// Car acting weird? · Set D · Coach chat: tap what you feel, see likely causes, videos and posts.
import { router } from 'expo-router';
import { useRef, useState } from 'react';
import { Linking, Platform, ScrollView, StyleSheet, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

import { BackIcon, CoachIcon } from '@/components/icons';
import { Body, Btn, Chip, Label, SquareBtn, tap } from '@/components/ui';
import { SYMPTOMS } from '@/data/symptoms';
import { useSaved } from '@/state/saved';
import { calm, C, F, PAD, themed } from '@/theme';
import { sheet, SkyHeader } from '@/components/sky';
import { Pressable, Text } from '@/components/t';

const CHANCE = { 'Most likely': 90, Maybe: 55, 'Less likely': 25 };
const URGENT = () => ({ 'Stop driving': C.red, 'Fix soon': '#F2A900', 'Can wait': C.green });
const mapsSearch = (q: string) =>
  Platform.OS === 'ios' ? `http://maps.apple.com/?q=${encodeURIComponent(q)}` : `https://www.google.com/maps/search/${encodeURIComponent(q)}`;

function Bubble({ me, children }: { me?: boolean; children: React.ReactNode }) {
  return (
    <View style={[s.bub, me ? s.me : s.them]}>
      <Text style={me ? s.meText : s.themText}>{children}</Text>
    </View>
  );
}
function LinkRow({ title, where, url }: { title: string; where: string; url: string }) {
  return (
    <Pressable onPress={() => { tap(); Linking.openURL(url); }} accessibilityRole="link" style={s.linkRow}>
      <View style={{ flex: 1 }}>
        <Body bold style={{ fontSize: 14 }}>{title}</Body>
        <Body style={{ fontSize: 12, color: C.muted }}>{where}</Body>
      </View>
      <View style={s.open}><Label style={{ fontSize: 10.5 }}>Open</Label></View>
    </Pressable>
  );
}

export default function Weird() {
  const { myCar } = useSaved();
  const [id, setId] = useState<string | null>(null);
  const scroll = useRef<ScrollView>(null);
  const sym = SYMPTOMS.find((x) => x.id === id);
  const carText = myCar ? `${myCar.year} ${myCar.make} ${myCar.model}` : '';
  const q = sym ? `${carText} ${sym.search}`.trim() : '';

  return (
    <SafeAreaView edges={calm ? [] : ['top']} style={{ flex: 1, backgroundColor: C.bg }}>
      {calm ? <SkyHeader title="Car acting weird?" back={() => router.back()} /> : (
        <View style={s.top}>
          <SquareBtn label="Back" onPress={() => router.back()}><BackIcon /></SquareBtn>
          <View style={{ flexDirection: 'row', alignItems: 'center', gap: 6 }}><CoachIcon size={18} /><Label>Car acting weird?</Label></View>
          <View style={{ width: 44 }} />
        </View>
      )}
      <View style={calm ? sheet.page : { flex: 1 }}>
      <ScrollView ref={scroll} contentContainerStyle={{ paddingHorizontal: PAD, paddingBottom: 40, gap: 8 }}>
        <Pressable onPress={() => { tap(); router.push({ pathname: '/light-help', params: { kind: 'ask', id: 'start' } }); }} accessibilityRole="button" style={askLink.box}>
          <Text style={askLink.t}>Not sure which one? Ask in your own words or send a photo ›</Text>
        </Pressable>
        <Bubble me>My car is acting weird.</Bubble>
        <Bubble>I can help. Tap what you feel, hear or smell.{carText ? ` I’ll look for help for your ${carText}.` : ''}</Bubble>
        <View style={s.chips}>
          {SYMPTOMS.map((x) => (
            <Chip key={x.id} label={x.name} on={id === x.id}
              onPress={() => { setId(x.id); setTimeout(() => scroll.current?.scrollToEnd({ animated: true }), 80); }} />
          ))}
        </View>

        {sym && (
          <>
            <Bubble me>{sym.name}.</Bubble>
            <Bubble>Here’s what it might be, best guess first.</Bubble>
            {sym.causes.map((c, i) => (
              <View key={c.name} style={[s.cause, i === 0 && { backgroundColor: C.accentSoft, borderColor: C.yellow }]}>
                <View style={{ flexDirection: 'row', justifyContent: 'space-between', gap: 8, alignItems: 'center' }}>
                  <Body bold style={{ flex: 1, fontSize: 15 }}>{c.name}</Body>
                  <View style={[s.pill, { backgroundColor: URGENT()[c.urgency] }]}><Label style={{ fontSize: 10, color: c.urgency === 'Fix soon' ? '#14161A' : '#FFFFFF' }}>{c.urgency}</Label></View>
                </View>
                <View style={{ flexDirection: 'row', alignItems: 'center', gap: 8, marginTop: 6 }}>
                  <View style={{ flex: 1, height: 6, backgroundColor: i === 0 ? 'rgba(0,0,0,.15)' : C.grey }}>
                    <View style={{ width: `${CHANCE[c.chance]}%`, height: '100%', backgroundColor: i === 0 ? C.ink : C.yellow }} />
                  </View>
                  <Label style={{ fontSize: 10.5 }}>{c.chance}</Label>
                </View>
              </View>
            ))}
            {!!sym.safety && <View style={s.danger}><Body bold style={{ color: C.ink }}>Safety first: {sym.safety}</Body></View>}
            <Body style={{ fontSize: 11.5, color: C.muted }}>This is a best guess, not a mechanic. A shop can tell you for sure.</Body>
            {/* Step-by-step help for this problem (free account), like the warning lights. */}
            <Btn kind="yellow" label="Talk it through, step by step" onPress={() => { tap(); router.push({ pathname: '/light-help', params: { kind: 'weird', id: sym.id } }); }} />

            <Bubble me>Can I see what other people did?</Bubble>
            <Bubble>Yes. Here are videos and posts about the same problem.</Bubble>
            <LinkRow title={`Videos: “${sym.search}”`} where="YouTube" url={`https://www.youtube.com/results?search_query=${encodeURIComponent(q)}`} />
            <LinkRow title="People with the same problem" where="Reddit · r/MechanicAdvice" url={`https://www.reddit.com/r/MechanicAdvice/search/?q=${encodeURIComponent(q)}`} />
            {myCar && <LinkRow title={`Owner complaints for the ${carText}`} where="NHTSA.gov · official" url="https://www.nhtsa.gov/recalls" />}
            <Btn label="Find a repair shop near me" style={{ marginTop: 6 }} onPress={() => Linking.openURL(mapsSearch('auto repair shop'))} />
          </>
        )}
      </ScrollView>
      </View>
    </SafeAreaView>
  );
}

const s = themed(() => StyleSheet.create({
  top: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', paddingHorizontal: PAD, paddingTop: 10, paddingBottom: 8 },
  bub: { maxWidth: '86%', paddingHorizontal: 13, paddingVertical: 10 },
  them: { alignSelf: 'flex-start', backgroundColor: C.grey },
  me: { alignSelf: 'flex-end', backgroundColor: C.hero },
  themText: { fontFamily: F.body, fontSize: 15, lineHeight: 21, color: C.ink },
  meText: { fontFamily: F.bodyBold, fontSize: 15, lineHeight: 21, color: C.yellow },
  chips: { flexDirection: 'row', flexWrap: 'wrap', gap: 6 },
  cause: { borderWidth: 1, borderColor: C.line, borderRadius: 12, padding: 12 },
  pill: { paddingHorizontal: 8, paddingVertical: 3 },
  danger: { backgroundColor: C.red, padding: 12 },
  linkRow: { flexDirection: 'row', alignItems: 'center', gap: 10, paddingVertical: 10, borderBottomWidth: 2, borderBottomColor: C.grey },
  open: { borderWidth: 1, borderColor: C.line, borderRadius: 12, paddingHorizontal: 8, paddingVertical: 3 },
}));

// Link to the open chat, "Ask about my car" (Oct 20, 2026).
const askLink = themed(() => StyleSheet.create({
  box: { backgroundColor: C.fill, borderRadius: 14, paddingHorizontal: 14, paddingVertical: 11, marginTop: 4 },
  t: { fontFamily: F.bodyBold, fontSize: 14, color: C.onAccent },
}));
