// "How far will you drive?" slider (picture 64 B, picked Oct 15, 2026): 10 to 60 minutes in steps
// of 5. Drag or tap the track; screen readers can swipe up and down to change it.
import { useEffect, useState } from 'react';
import { PanResponder, StyleSheet, View } from 'react-native';

import { tap } from '@/components/ui';
import { C, F, themed } from '@/theme';
import { Text } from '@/components/t';

const LO = 10;
const HI = 60;
const STEP = 5;
const MARKS = [10, 20, 30, 40, 50, 60];

export function DriveSlider({ value, onChange }: { value: number; onChange: (v: number) => void }) {
  const [w, setW] = useState(1);
  // Where the finger is on the track: where it first touched + how far it moved.
  const [touch, setTouch] = useState<{ base: number; dx: number } | null>(null);
  const [pan] = useState(() => PanResponder.create({
    onStartShouldSetPanResponder: () => true,
    onMoveShouldSetPanResponder: () => true,
    onPanResponderTerminationRequest: () => false,
    onPanResponderGrant: (e) => setTouch({ base: e.nativeEvent.locationX, dx: 0 }),
    onPanResponderMove: (_e, g) => setTouch((t) => (t ? { ...t, dx: g.dx } : t)),
  }));
  useEffect(() => {
    if (!touch) return;
    const next = Math.max(LO, Math.min(HI, LO + Math.round((((touch.base + touch.dx) / w) * (HI - LO)) / STEP) * STEP));
    if (next !== value) { tap(); onChange(next); }
  }, [touch]); // eslint-disable-line react-hooks/exhaustive-deps
  const pct = (value - LO) / (HI - LO);
  return (
    <View>
      <View accessible accessibilityRole="adjustable" accessibilityLabel="How far will you drive?"
        accessibilityValue={{ min: LO, max: HI, now: value, text: `${value} minutes` }}
        accessibilityActions={[{ name: 'increment' }, { name: 'decrement' }]}
        onAccessibilityAction={(e) => onChange(Math.max(LO, Math.min(HI, value + (e.nativeEvent.actionName === 'increment' ? STEP : -STEP))))}
        onLayout={(e) => setW(Math.max(1, e.nativeEvent.layout.width))} style={s.hit} {...pan.panHandlers}>
        <View pointerEvents="none" style={s.track} />
        <View pointerEvents="none" style={[s.fill, { width: `${pct * 100}%` }]} />
        <View pointerEvents="none" style={[s.thumb, { left: pct * w - 13 }]} />
      </View>
      <View style={s.marks} pointerEvents="none">
        {MARKS.map((m) => <Text key={m} style={[s.mark, m === value && { color: C.yellow, fontFamily: F.bodyBold }]}>{m === HI ? `${m} min` : String(m)}</Text>)}
      </View>
    </View>
  );
}

const s = themed(() => StyleSheet.create({
  hit: { height: 36, justifyContent: 'center' },
  track: { height: 6, borderRadius: 6, backgroundColor: C.line },
  fill: { position: 'absolute', left: 0, height: 6, borderRadius: 6, backgroundColor: C.yellow },
  thumb: { position: 'absolute', width: 26, height: 26, borderRadius: 13, backgroundColor: C.card, borderWidth: 3, borderColor: C.yellow,
    shadowColor: '#000', shadowOpacity: 0.2, shadowRadius: 4, shadowOffset: { width: 0, height: 2 }, elevation: 3 },
  marks: { flexDirection: 'row', justifyContent: 'space-between', marginTop: -2 },
  mark: { fontFamily: F.body, fontSize: 11, color: C.muted },
}));
