import { Barlow_400Regular, Barlow_600SemiBold, Barlow_700Bold } from '@expo-google-fonts/barlow';
import { BarlowCondensed_700Bold, BarlowCondensed_800ExtraBold, BarlowCondensed_800ExtraBold_Italic } from '@expo-google-fonts/barlow-condensed';
import { Manrope_500Medium, Manrope_600SemiBold, Manrope_700Bold, Manrope_800ExtraBold } from '@expo-google-fonts/manrope';
import { Michroma_400Regular } from '@expo-google-fonts/michroma';
import { useFonts } from 'expo-font';
import { Stack } from 'expo-router';
import * as SplashScreen from 'expo-splash-screen';
import { StatusBar } from 'expo-status-bar';
import { useEffect } from 'react';
import { View } from 'react-native';
import { useDayLook } from '@/components/sky';

import { FeedbackPrompt } from '@/components/feedback';
import { Toast } from '@/components/toast';
import { WidgetSync } from '@/widgets/sync';
import { Presence } from '@/lib/presence';
import { FrameRoute } from '@/components/frame-route';
import { AnswersProvider } from '@/state/answers';
import { AlertsProvider } from '@/state/alerts';
import { AuthProvider } from '@/state/auth';
import { NewsProvider } from '@/state/news';
import { RecallsProvider } from '@/state/recalls';
import { SavedProvider, useSaved } from '@/state/saved';
import { applyLang, phoneLang } from '@/i18n';
import { applyTheme, C, DEFAULT_LOOK, isDarkLook, lookNow, pageOf } from '@/theme';

SplashScreen.preventAutoHideAsync();

// Picks the look (White, Trust Blue, Midnight or Navy) and the language saved on this phone, then draws the app.
// Switching either redraws everything (the key changes) so every screen picks it up.
function Looks() {
  'use no memo'; // must redraw on every look change
  const { prefs, setPrefs, ready } = useSaved();
  const dayLook = useDayLook();
  // Clean (picture 82 style) became the app's look on Oct 18, 2026: light looks move to it, dark looks to its
  // night version, once. The older looks stay on Me for anyone who wants them back.
  // Design 5 (picture 200, Nov 6, 2026): everyone moves once to the Light Showroom, which follows the day
  // (dark showroom at night). The other looks stay on Me › Look.
  const moved = ready && prefs.lookV !== 4;
  useEffect(() => {
    if (moved) setPrefs({ ...prefs, theme: 'showroom', lookV: 4 });
  }, [moved]); // eslint-disable-line react-hooks/exhaustive-deps
  if (!ready || moved) return null;
  // "Follow the day" (picture 133; on unless turned off, saved as autoNight): Clean, Sunset Calm, Sunset Calm night and
  // Clean night take turns by the sun where they are. White, Midnight, Trust Blue and Navy stay as picked.
  const picked = prefs.theme ?? DEFAULT_LOOK;
  const look = lookNow(picked, prefs.autoNight !== false, dayLook);
  applyTheme(look);
  // Language: what they picked, or the phone's language the first time (picture 50 B).
  const lng = prefs.lang ?? phoneLang();
  applyLang(lng);
  return (
    <View key={`${look}-${lng}`} style={{ flex: 1, backgroundColor: pageOf(look) }}>
      <StatusBar style={isDarkLook(look) ? 'light' : 'dark'} />
      <Stack screenOptions={{ headerShown: false, contentStyle: { backgroundColor: C.bg } }} />
      <FeedbackPrompt />
      <Toast />
      <WidgetSync />
      <Presence />
      <FrameRoute />
    </View>
  );
}

export default function RootLayout() {
  const [loaded] = useFonts({
    Barlow_400Regular, Barlow_600SemiBold, Barlow_700Bold,
    BarlowCondensed_700Bold, BarlowCondensed_800ExtraBold, BarlowCondensed_800ExtraBold_Italic,
    Michroma_400Regular,
    Manrope_500Medium, Manrope_600SemiBold, Manrope_700Bold, Manrope_800ExtraBold,
  });
  useEffect(() => { if (loaded) SplashScreen.hideAsync(); }, [loaded]);
  if (!loaded) return null;

  return (
    <SavedProvider>
    <AnswersProvider>
    <AuthProvider>
    <RecallsProvider>
    <AlertsProvider>
    <NewsProvider>
      <Looks />
    </NewsProvider>
    </AlertsProvider>
    </RecallsProvider>
    </AuthProvider>
    </AnswersProvider>
    </SavedProvider>
  );
}
