// Me: your free account (picture 106, set 2 "soft rainbow", day and night; Loudjier picked it Oct 18, 2026).
// Members see tiles for what they keep; guests see what a free account adds. Settings for everyone.
import { router } from 'expo-router';
import * as WebBrowser from 'expo-web-browser';
import { useEffect, useState } from 'react';
import { ScrollView, StyleSheet, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

import { ProfilePic } from '@/components/profile-pic';
import { Avatar, BigBtn, Card, IconBox, Row, Sec, ToggleRow, type Tint } from '@/components/account-ui';
import { IdeaSheet } from '@/components/feedback';
import { BellIcon, BriefcaseIcon, BulbIcon, CarIcon, GlobeIcon, HeartIcon, InfoIcon, LockIcon, PinIcon, SoundIcon, SpeakerIcon, StarIcon, SunIcon, TagIcon, WrenchIcon } from '@/components/icons';
import { notify } from '@/components/notify';
import { tap } from '@/components/ui';
import { supabase } from '@/lib/supabase';
import { useAlerts } from '@/state/alerts';
import { useAuth } from '@/state/auth';
import { lightDarkOf } from '@/components/look-picker';
import { useSaved } from '@/state/saved';
import { carStatus, planAlerts } from '@/data/car-plan';
import { C, F, famOf, isDarkLook, look, PAD, themed } from '@/theme';
import { tr } from '@/i18n';
import { Pressable, Text } from '@/components/t';

const COLOR_NAME: Record<string, string> = { gold: 'Gold', blue: 'Blue', green: 'Green', navy: 'Navy & Gold' };

function Tile({ t, icon, label, sub, onPress, wide }: { t: Tint; icon: (c: string) => React.ReactNode; label: string; sub: string; onPress: () => void; wide?: boolean }) {
  return (
    <Pressable onPress={() => { tap(); onPress(); }} accessibilityRole="button" accessibilityLabel={`${label}. ${sub}`}
      style={({ pressed }) => [s.tile, wide && s.wide, pressed && { opacity: 0.85 }]}>
      <IconBox t={t}>{icon}</IconBox>
      <View style={wide ? { flex: 1 } : undefined}>
        <Text style={[s.tileT, wide && { marginTop: 0 }]}>{label}</Text>
        <Text style={s.tileS} numberOfLines={1}>{sub}</Text>
      </View>
    </Pressable>
  );
}

export default function Me() {
  const { prefs: phone, setPrefs, saved, myCar, myCars } = useSaved();
  const { session, name, memberSince, signOut, openSignIn, prefs } = useAuth();
  const { alertsOn } = useAlerts();
  const [feedback, setFeedback] = useState(false);
  const [reviews, setReviews] = useState<{ uid: string; n: number } | null>(null);
  const uid = session?.user.id;
  useEffect(() => {
    if (!uid) return;
    let live = true;
    supabase.from('reviews').select('id', { count: 'exact', head: true }).eq('user_id', uid)
      .then(({ count }) => { if (live) setReviews({ uid, n: count ?? 0 }); }, () => {});
    return () => { live = false; };
  }, [uid]);
  const nReviews = reviews?.uid === uid ? reviews?.n ?? 0 : 0;
  const plan = planAlerts(myCars);
  const nAlerts = (alertsOn ? 1 : 0) + (['upkeep', 'price', 'nearby', 'rates'] as const).filter((k) => prefs[k]).length + [plan.pay, plan.miles, plan.value].filter(Boolean).length;
  // My car tile: the car and what matters now ("2018 Trax · Paid off · Oil due soon").
  const [now] = useState(() => Date.now());
  const carSub = myCars.length > 1 ? `${myCars.length} cars` : myCar ? [`${myCar.year} ${myCar.model}`, ...carStatus(myCar, now)].join(' · ') : 'Add your car';

  return (
    <SafeAreaView edges={['top']} style={{ flex: 1, backgroundColor: C.bg }}>
      <Text style={s.top} accessibilityRole="header">Me</Text>
      <ScrollView contentContainerStyle={{ paddingHorizontal: PAD - 6, paddingBottom: 30 }}>
        {session ? (
          <>
            <View style={s.head}>
              <ProfilePic name={name} size={56} />
              <View style={{ flex: 1 }}>
                <Text style={s.name}>{name}</Text>
                <Text style={s.since}>{memberSince ? `Free member since ${memberSince}` : 'Free member'}</Text>
              </View>
              <Pressable onPress={() => { tap(); router.push('/profile'); }} accessibilityRole="button" hitSlop={10}><Text style={s.edit}>Edit</Text></Pressable>
            </View>
            <View style={s.grid}>
              <Tile t="blue" icon={(c) => <BellIcon size={18} color={c} />} label="Alerts" sub={`${nAlerts} on`} onPress={() => router.push('/alerts')} />
              <Tile t="green" icon={(c) => <CarIcon size={18} color={c} />} label="My car" sub={carSub} onPress={() => router.navigate('/my-car')} />
              <Tile t="red" icon={(c) => <HeartIcon size={18} color={c} />} label="Saved cars" sub={`${saved.length} car${saved.length === 1 ? '' : 's'}`} onPress={() => router.navigate('/garage')} />
              <Tile t="amber" icon={(c) => <PinIcon size={18} color={c} />} label="My dealer" sub={myCar?.dealer ? `${myCar.dealer.miles} mi` : 'Not set'} onPress={() => router.navigate('/my-car')} />
              <Tile wide t="purple" icon={(c) => <StarIcon size={18} color={c} />} label="My reviews" sub={nReviews ? `${nReviews} review${nReviews === 1 ? '' : 's'} · thank you!` : 'Write one on any car page'}
                onPress={() => notify('My reviews', 'Your reviews show on each car’s page, with your first name.')} />
            </View>
          </>
        ) : (
          <View style={s.guest}>
            <View style={{ alignItems: 'center' }}><Avatar name="?" size={60} /></View>
            <Text style={[s.name, { textAlign: 'center', marginTop: 10 }]}>Make it yours. Free.</Text>
            <Text style={s.guestSub}>Searching and safety info stay open. A free account adds:</Text>
            {[['Recall alerts for your car', 'blue', BellIcon], ['Oil and registration reminders', 'green', WrenchIcon], ['Price drops on saved cars', 'red', TagIcon], ['Your car, dealer and saves on any phone', 'amber', CarIcon]].map(([t, tn, I]) => {
              const Icon = I as typeof BellIcon;
              return (
                <View key={t as string} style={s.perk}>
                  <IconBox t={tn as Tint}>{(c) => <Icon size={16} color={c} />}</IconBox>
                  <Text style={s.perkT}>{t as string}</Text>
                </View>
              );
            })}
            <BigBtn label="Create free account" onPress={() => router.push('/join')} />
            <Pressable onPress={() => { tap(); openSignIn(undefined, 'login'); }} accessibilityRole="button" style={{ alignItems: 'center', paddingTop: 12 }}>
              <Text style={s.login}>I have an account · Log in</Text>
            </Pressable>
          </View>
        )}

        <Sec>Settings</Sec>
        <Card>
          <Row icon={(c) => <SunIcon size={18} color={c} />} label="Look" value={`${tr(COLOR_NAME[famOf(look)])} · ${tr(lightDarkOf(phone.theme, phone.autoNight) === 'auto' ? 'Auto' : isDarkLook(look) ? 'Dark' : 'Light')}`} onPress={() => router.push('/look')} />
          <Row t="green" icon={(c) => <GlobeIcon size={18} color={c} />} label="Language" value={(phone.lang ?? 'en') === 'es' ? 'Español' : 'English'} onPress={() => router.push('/look')} />
          <ToggleRow t="amber" icon={(c) => <SpeakerIcon size={18} color={c} on={phone.sound !== false} />} label="App sounds" sub="The start-up sound and the scan ding" on={phone.sound !== false} onChange={(v) => setPrefs({ ...phone, sound: v })} />
          <ToggleRow last t="purple" icon={(c) => <SoundIcon size={18} color={c} />} label="Read out loud" sub="The coach speaks every answer" on={phone.readAloud} onChange={(v) => setPrefs({ ...phone, readAloud: v })} />
        </Card>

        <Sec>Account</Sec>
        <Card>
          {session && <Row icon={(c) => <LockIcon size={18} color={c} />} label="Account & privacy" onPress={() => router.push('/account')} />}
          <Row t="amber" icon={(c) => <InfoIcon size={18} color={c} />} label="About & legal" onPress={() => router.push('/about')} />
          <Row t="green" icon={(c) => <BulbIcon size={18} color={c} />} label="Send us an idea" onPress={() => setFeedback(true)} />
          <Row last t="purple" icon={(c) => <BriefcaseIcon size={18} color={c} />} label="For businesses" sub="Dealers, shops, lenders: work with us" onPress={() => { tap(); WebBrowser.openBrowserAsync('https://carvessa.app/partners/').catch(() => {}); }} />
        </Card>
        {session && (
          <Pressable onPress={() => { tap(); signOut(); }} accessibilityRole="button" style={{ alignItems: 'center', paddingVertical: 16 }}>
            <Text style={s.out}>Sign out</Text>
          </Pressable>
        )}
      </ScrollView>
      {feedback && <IdeaSheet screen="/me" onClose={() => setFeedback(false)} />}
    </SafeAreaView>
  );
}

const s = themed(() => StyleSheet.create({
  top: { fontFamily: F.bodyBold, fontSize: 17, color: C.ink, textAlign: 'center', paddingVertical: 12 },
  head: { flexDirection: 'row', alignItems: 'center', gap: 12, paddingHorizontal: 4, paddingVertical: 8 },
  name: { fontFamily: F.head, fontSize: 21, color: C.ink },
  since: { fontFamily: F.body, fontSize: 13, color: C.muted },
  edit: { fontFamily: F.bodyBold, fontSize: 14, color: C.onAccent },
  grid: { flexDirection: 'row', flexWrap: 'wrap', gap: 10, marginTop: 8 },
  tile: { flexBasis: '47%', flexGrow: 1, backgroundColor: C.card, borderRadius: 18, padding: 13, borderWidth: 1, borderColor: C.line },
  wide: { flexBasis: '100%', flexDirection: 'row', alignItems: 'center', gap: 12 },
  tileT: { fontFamily: F.bodyBold, fontSize: 15, color: C.ink, marginTop: 8 },
  tileS: { fontFamily: F.body, fontSize: 12.5, color: C.muted },
  guest: { backgroundColor: C.fill, borderRadius: 22, padding: 18, alignItems: 'stretch', marginTop: 4 },
  guestSub: { fontFamily: F.body, fontSize: 14, color: C.ink, textAlign: 'center', marginTop: 4, marginBottom: 8 },
  perk: { flexDirection: 'row', alignItems: 'center', gap: 10, paddingVertical: 5 },
  perkT: { fontFamily: F.bodyBold, fontSize: 14.5, color: C.ink, flex: 1 },
  login: { fontFamily: F.bodyBold, fontSize: 14.5, color: C.onAccent },
  out: { fontFamily: F.bodyBold, fontSize: 15, color: C.muted },
}));
