// Pick a paint color (Color picker 1: dark showroom, picked Oct 9, 2026).
// Our own car is shown in each paint, so there are no photo rights issues.
import { LinearGradient } from 'expo-linear-gradient';
import { router, useLocalSearchParams } from 'expo-router';
import { useState } from 'react';
import { Image, ScrollView, StyleSheet, useWindowDimensions, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import Svg, { Circle, Path } from 'react-native-svg';

import { BackIcon } from '@/components/icons';
import { Body, Btn, Logo, SquareBtn, tap } from '@/components/ui';
import { FEATURE_TILES, PAINT_GROUPS, PAINTS } from '@/data/features';
import { useAnswers } from '@/state/answers';
import { C, F, PAD, themed } from '@/theme';
import { Pressable, Text } from '@/components/t';

export default function ColorPicker() {
  const { from, at } = useLocalSearchParams<{ from?: string; at?: string }>();
  const { answers, setAnswers, chat, setChat } = useAnswers();
  const { width } = useWindowDimensions();
  const w = Math.min(width, 520);
  const [group, setGroup] = useState<(typeof PAINT_GROUPS)[number]>('All');
  const [name, setName] = useState(answers.color ?? 'Midnight Blue');
  const pick = PAINTS.find((p) => p.name === name) ?? PAINTS[0];
  const carW = w - 20;

  const finish = (color?: string) => {
    const a = { ...answers, color };
    setAnswers(a);
    // From the coach: answer its "features" question with what they picked. `at` is where that
    // question is in the chat (3rd, or 4th when they're upgrading and the coach asked for their car).
    if (from === 'coach' && chat.length === Number(at ?? 2)) {
      const names = (keys: string[] = []) => FEATURE_TILES.filter((t) => t.keys.some((k) => keys.includes(k))).map((t) => t.label).join(', ');
      const parts = [a.mustHaves.length && `Must have: ${names(a.mustHaves)}`, a.wants?.length && `Nice to have: ${names(a.wants)}`, `Color: ${color ?? 'any'}`];
      setChat([...chat, parts.filter(Boolean).join(' · ')]);
      router.navigate('/coach');
    } else if (from === 'coach') router.navigate('/coach'); // never loop back to the features screen
    else router.back();
  };

  return (
    <View style={{ flex: 1, backgroundColor: '#05080F' }}>
      <LinearGradient colors={['#1E2A40', '#0B1220', '#05080F']} locations={[0, 0.45, 1]} style={StyleSheet.absoluteFill} />
      <SafeAreaView edges={['top']} style={{ flex: 1 }}>
        <View style={s.top}>
          <SquareBtn dark label="Back" onPress={() => router.back()}><BackIcon color="#FFFFFF" /></SquareBtn>
          <Logo size={14} dark />
          <View style={{ width: 44 }} />
        </View>
        <ScrollView contentContainerStyle={{ paddingBottom: 40 }}>
          <View style={{ alignItems: 'center', marginTop: 14, paddingHorizontal: PAD }}>
            <Text style={s.kicker}>Paint</Text>
            <Text style={s.name} accessibilityRole="header">{pick.name}</Text>
            <Text style={s.note}>{pick.note}</Text>
          </View>
          <View style={{ height: carW * (179 / 600) + 40, marginTop: 14, alignItems: 'center' }}>
            <View style={[s.shadow, { width: carW - 40, top: carW * (179 / 600) - 8 }]} />
            <Image source={pick.img} accessibilityLabel={`Our car in ${pick.name}`} style={{ width: carW, height: carW * (179 / 600) }} resizeMode="contain" />
          </View>

          <View style={{ paddingHorizontal: 20, gap: 14 }}>
            <View style={{ flexDirection: 'row', gap: 6, justifyContent: 'center' }}>
              {PAINT_GROUPS.map((g) => (
                <Pressable key={g} onPress={() => { tap(); setGroup(g); }} accessibilityRole="button" accessibilityState={{ selected: group === g }}
                  style={[s.group, group === g && { backgroundColor: C.fill }]}>
                  <Text style={[s.groupText, group === g && { color: C.onAccent }]}>{g}</Text>
                </Pressable>
              ))}
            </View>
            <View style={s.grid}>
              {PAINTS.filter((p) => group === 'All' || p.group === group).map((p) => {
                const on = p.name === pick.name;
                return (
                  <Pressable key={p.name} onPress={() => { tap(); setName(p.name); }} accessibilityRole="button" accessibilityState={{ selected: on }}
                    accessibilityLabel={p.name} style={{ width: (w - 40 - 30) / 6, alignItems: 'center', gap: 5 }}>
                    <View style={[s.ring, on && { borderColor: C.yellow }]}>
                      <View style={[s.dot, { backgroundColor: p.hex }]} />
                    </View>
                    <Text style={[s.short, on && { color: C.yellow }]} numberOfLines={1}>{p.short}</Text>
                  </Pressable>
                );
              })}
            </View>
            <View style={s.info}>
              <Svg width={20} height={20} viewBox="0 0 24 24" fill="none" stroke={C.yellow} strokeWidth={2} strokeLinecap="round"><Circle cx="12" cy="12" r="9" /><Path d="M12 8v5M12 16v.5" /></Svg>
              <Body style={{ flex: 1, fontSize: 12.5, lineHeight: 17, color: '#C9D1DD' }}>Bold colors can be harder to find on lots. The dealer can check which colors they have.</Body>
            </View>
            <Btn kind="yellow" label="Use this color" onPress={() => finish(pick.name)} />
            <Pressable onPress={() => { tap(); finish(undefined); }} accessibilityRole="button" hitSlop={8} style={{ alignSelf: 'center' }}>
              <Body bold style={{ color: '#C9D1DD', textDecorationLine: 'underline', fontSize: 13.5 }}>Any color is fine</Body>
            </Pressable>
          </View>
        </ScrollView>
      </SafeAreaView>
    </View>
  );
}

const s = themed(() => StyleSheet.create({
  top: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', paddingHorizontal: PAD, paddingTop: 10 },
  kicker: { fontFamily: F.bodySemi, fontSize: 12, letterSpacing: 3, textTransform: 'uppercase', color: '#9FB0CC' },
  name: { fontFamily: F.head, fontSize: 40, lineHeight: 42, textTransform: 'uppercase', color: '#FFFFFF', textAlign: 'center' },
  note: { fontFamily: F.body, fontSize: 13.5, color: '#C9D1DD', textAlign: 'center' },
  shadow: { position: 'absolute', height: 16, borderRadius: 100, backgroundColor: 'rgba(0,0,0,0.55)' },
  group: { borderRadius: 20, paddingHorizontal: 12, paddingVertical: 6, backgroundColor: 'rgba(255,255,255,0.08)' },
  groupText: { fontFamily: F.bodyBold, fontSize: 13, color: '#FFFFFF' },
  grid: { flexDirection: 'row', flexWrap: 'wrap', rowGap: 12, columnGap: 6 },
  ring: { width: 48, height: 48, borderRadius: 24, borderWidth: 2, borderColor: 'transparent', alignItems: 'center', justifyContent: 'center' },
  dot: { width: 40, height: 40, borderRadius: 20, borderWidth: 1, borderColor: 'rgba(255,255,255,0.25)' },
  short: { fontFamily: F.bodyBold, fontSize: 10.5, color: '#C9D1DD' },
  info: { flexDirection: 'row', gap: 8, alignItems: 'center', backgroundColor: 'rgba(255,255,255,0.06)', borderWidth: 1, borderColor: 'rgba(255,255,255,0.12)', borderRadius: 14, padding: 12 },
}));
