// My car reminders (picture 221 A, Loudjier Nov 13, 2026: "build it all"). Insurance, car payment (only when the car is
// financed or leased), oil change, service, tag renewal, emissions test, car wash or their own. They pick the next due
// day, how often, how many days before and the time. The phone reminds them itself, even with no internet. Free account.
import { router } from 'expo-router';
import { useState } from 'react';
import { KeyboardAvoidingView, Platform, ScrollView, StyleSheet, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

import { BigBtn, Card } from '@/components/account-ui';
import { BellIcon } from '@/components/icons';
import { notify } from '@/components/notify';
import { sheet, SkyHeader } from '@/components/sky';
import { Pressable, Text, TextInput } from '@/components/t';
import { Body, Chip, Label, tap } from '@/components/ui';
import { howPaid, shortDate } from '@/data/car-plan';
import { BEFORE, type CarReminder, daysLeft, EVERY, kindsFor, markDone, newId, remDue, REM_KINDS, remName, sortReminders, TIMES } from '@/data/car-reminders';
import { carName } from '@/data/my-cars';
import { tr } from '@/i18n';
import { canRemind } from '@/lib/reminders';
import { useAuth } from '@/state/auth';
import { useSaved } from '@/state/saved';
import { C, calm, F, PAD, themed } from '@/theme';

const pad = (n: number) => String(n).padStart(2, '0');
const mdy = (t: number) => { const d = new Date(t); return `${pad(d.getMonth() + 1)}/${pad(d.getDate())}/${d.getFullYear()}`; };
const parseDay = (t: string) => {
  const m = t.trim().match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (!m) return null;
  const d = new Date(Number(m[3]), Number(m[1]) - 1, Number(m[2]), 12);
  return isNaN(d.getTime()) || d.getMonth() !== Number(m[1]) - 1 ? null : d.getTime();
};
const timeLabel = (t: string) => { const [h, m] = t.split(':').map(Number); return `${h % 12 || 12}${m ? `:${pad(m)}` : ''} ${h < 12 ? 'AM' : 'PM'}`; };
const everyLabel = (e: CarReminder['every']) => EVERY.find((x) => x.every === e)!.label;
const beforeLabel = (b: CarReminder['before']) => BEFORE.find((x) => x.before === b)!.label;
export const remLine = (r: CarReminder) => [r.amount ? `$${r.amount.toLocaleString('en-US')}` : '', tr(everyLabel(r.every)), tr(beforeLabel(r.before))].filter(Boolean).join(' · ');
const dueText = (r: CarReminder, now: number) => {
  if (r.off) return tr('Off');
  const n = daysLeft(r, now);
  return n < 0 ? tr('Past due') : n === 0 ? tr('Today') : n === 1 ? tr('Tomorrow') : shortDate(new Date(remDue(r, now)));
};

export function Editor({ start, kinds, onSave, onCancel, onDone, onDelete }: {
  start: CarReminder; kinds: ReturnType<typeof kindsFor>; onSave: (r: CarReminder) => void; onCancel: () => void; onDone?: () => void; onDelete?: () => void;
}) {
  const [r, setR] = useState(start);
  const [due, setDue] = useState(mdy(start.due));
  const [amount, setAmount] = useState(start.amount ? String(start.amount) : '');
  const [sure, setSure] = useState(false);
  const pick = (kind: CarReminder['kind']) => { const k = REM_KINDS.find((x) => x.kind === kind)!; setR({ ...r, kind, every: onDelete ? r.every : k.every, before: onDelete ? r.before : k.before }); };
  const save = () => {
    const d = parseDay(due);
    if (!d) return notify('Check the date', 'Use month/day/year, like 11/20/2026.');
    if (r.kind === 'custom' && !r.label?.trim()) return notify('What should we remind you about?', 'Write a short name, like “Registration sticker”.');
    const n = Number(amount.replace(/[^\d.]/g, ''));
    onSave({ ...r, due: d, amount: n > 0 ? Math.round(n * 100) / 100 : undefined, off: false });
  };
  if (sure) return (
    <Card style={{ paddingVertical: 16 }}>
      <Body bold>{`${tr('Delete')} “${tr(remName(r))}”?`}</Body>
      <Body style={s.small}>You won’t get this reminder anymore.</Body>
      <View style={{ gap: 8, marginTop: 14 }}>
        <BigBtn label="Keep it" onPress={() => { tap(); onCancel(); }} />
        <BigBtn label="Edit instead" kind="soft" onPress={() => { tap(); setSure(false); }} />
        <BigBtn label="Delete" kind="danger" onPress={() => { tap(); onDelete?.(); }} />
      </View>
    </Card>
  );
  return (
    <Card style={{ paddingVertical: 14 }}>
      <Body bold>{onDelete ? 'Change reminder' : 'New reminder'}</Body>
      <Label style={s.fl}>WHAT</Label>
      <View style={s.chips}>{kinds.map((k) => <Chip key={k.kind} label={k.label} on={r.kind === k.kind} onPress={() => pick(k.kind)} />)}</View>
      {r.kind === 'custom' && (
        <TextInput value={r.label ?? ''} onChangeText={(t) => setR({ ...r, label: t })} placeholder="Registration sticker" placeholderTextColor={C.muted}
          accessibilityLabel="Reminder name" style={[s.input, { marginTop: 8 }]} />
      )}
      <View style={s.two}>
        <View style={{ flex: 1 }}>
          <Label style={s.fl}>AMOUNT (OPTIONAL)</Label>
          <TextInput value={amount} onChangeText={setAmount} placeholder="$142" placeholderTextColor={C.muted} keyboardType="decimal-pad" accessibilityLabel="Amount" style={s.input} />
        </View>
        <View style={{ flex: 1.2 }}>
          <Label style={s.fl}>NEXT DUE</Label>
          <TextInput value={due} onChangeText={setDue} placeholder="11/20/2026" placeholderTextColor={C.muted} accessibilityLabel="Next due date, month/day/year" style={s.input} />
        </View>
      </View>
      <Label style={s.fl}>HOW OFTEN</Label>
      <View style={s.chips}>{EVERY.map((x) => <Chip key={x.every} label={x.label} on={r.every === x.every} onPress={() => setR({ ...r, every: x.every })} />)}</View>
      <Label style={s.fl}>REMIND ME</Label>
      <View style={s.chips}>{BEFORE.map((x) => <Chip key={x.before} label={x.label} on={r.before === x.before} onPress={() => setR({ ...r, before: x.before })} />)}</View>
      <Label style={s.fl}>AT</Label>
      <View style={s.chips}>{TIMES.map((t) => <Chip key={t} label={timeLabel(t)} on={r.time === t} onPress={() => setR({ ...r, time: t })} />)}</View>
      <View style={{ gap: 8, marginTop: 14 }}>
        <BigBtn label="Save reminder" onPress={save} />
        {onDone && <BigBtn label={r.kind === 'insurance' || r.kind === 'payment' ? 'Mark paid' : 'Mark done'} kind="soft" onPress={() => { tap(); onDone(); }} />}
        {onDelete && <BigBtn label="Delete" kind="plain" onPress={() => { tap(); setSure(true); }} />}
        <BigBtn label="Cancel" kind="plain" onPress={() => { tap(); onCancel(); }} />
      </View>
    </Card>
  );
}

export default function RemindersScreen() {
  const { myCar, setMyCar } = useSaved();
  const { session, askAccount } = useAuth();
  const [now] = useState(() => Date.now());
  const [editing, setEditing] = useState<CarReminder | null>(null);
  const [isNew, setIsNew] = useState(false);
  const back = () => router.navigate('/garage');
  const list = sortReminders(myCar?.reminders ?? [], now);
  const kinds = kindsFor(myCar ? howPaid(myCar) : null);

  const start = () => {
    tap();
    if (!session) return askAccount('Never miss a car bill', 'A free account saves your reminders and brings them back on a new phone. No spam, never sold.');
    const k = REM_KINDS[0];
    const d = new Date(now);
    setEditing({ id: newId(), kind: k.kind, every: k.every, before: k.before, time: '09:00', due: new Date(d.getFullYear(), d.getMonth() + 1, d.getDate(), 12).getTime() });
    setIsNew(true);
  };
  const put = async (r: CarReminder) => {
    if (!myCar) return;
    if (!session) return askAccount('Never miss a car bill', 'A free account saves your reminders and brings them back on a new phone. No spam, never sold.');
    tap();
    const rest = (myCar.reminders ?? []).filter((x) => x.id !== r.id);
    setMyCar({ ...myCar, reminders: [...rest, r] });
    setEditing(null);
    if (Platform.OS !== 'web' && !(await canRemind(true))) notify('Reminders are off', 'Alerts are off for Carvessa in your phone settings. Turn them on there so this reminder can show.');
  };
  const remove = (id: string) => { if (myCar) setMyCar({ ...myCar, reminders: (myCar.reminders ?? []).filter((x) => x.id !== id) }); setEditing(null); };

  return (
    <SafeAreaView edges={calm ? [] : ['top']} style={{ flex: 1, backgroundColor: C.bg }}>
      <SkyHeader title="Reminders" sub={myCar ? carName(myCar) : undefined} back={back} />
      <KeyboardAvoidingView behavior={Platform.OS === 'ios' ? 'padding' : undefined} style={calm ? sheet.page : { flex: 1 }}>
        <ScrollView contentContainerStyle={{ paddingHorizontal: PAD, paddingBottom: 40, paddingTop: 6 }} keyboardShouldPersistTaps="handled">
          {!myCar ? (
            <Card style={{ paddingVertical: 16 }}>
              <Body bold>Add your car first</Body>
              <View style={{ marginTop: 12 }}><BigBtn label="Go to My Garage" onPress={back} /></View>
            </Card>
          ) : editing ? (
            <Editor start={editing} kinds={kinds} onSave={put} onCancel={() => setEditing(null)}
              onDone={isNew ? undefined : () => put(markDone(editing, now))} onDelete={isNew ? undefined : () => remove(editing.id)} />
          ) : (<>
            {!session && (
              <Card style={{ paddingVertical: 14, marginBottom: 12 }}>
                <Body bold>Never miss a car bill</Body>
                <Body style={s.small}>Insurance, car payment, tag renewal, oil change… you pick when. A free account keeps them safe.</Body>
                <View style={{ marginTop: 12 }}><BigBtn label="Create a free account" onPress={() => askAccount('Never miss a car bill', 'A free account saves your reminders and brings them back on a new phone. No spam, never sold.')} /></View>
              </Card>
            )}
            {list.length > 0 && (<>
              <Label style={s.k}>COMING UP</Label>
              <Card>
                {list.map((r, i) => {
                  const n = r.off ? 99 : daysLeft(r, now);
                  return (
                    <Pressable key={r.id} onPress={() => { tap(); setEditing(r); setIsNew(false); }} accessibilityRole="button"
                      accessibilityLabel={`${tr(remName(r))}, ${dueText(r, now)}, ${remLine(r)}`} style={[s.row, i < list.length - 1 && s.line, r.off && { opacity: 0.55 }]}>
                      <View style={s.ic}><BellIcon size={18} color={C.onAccent} /></View>
                      <View style={{ flex: 1 }}>
                        <Text style={s.what}>{remName(r)}</Text>
                        <Text style={s.sub}>{remLine(r)}</Text>
                      </View>
                      <View style={[s.due, n <= 3 && { backgroundColor: C.red }]}><Text style={[s.dueT, n <= 3 && { color: '#FFFFFF' }]}>{dueText(r, now)}</Text></View>
                    </Pressable>
                  );
                })}
              </Card>
            </>)}
            <View style={{ marginTop: 12 }}><BigBtn label="+ Add a reminder" kind={list.length ? 'soft' : 'solid'} onPress={start} /></View>
            <Body style={[s.small, { marginTop: 12 }]}>Reminders come on this phone, even with no internet. Tap one to change it, mark it paid or done, or delete it.</Body>
          </>)}
        </ScrollView>
      </KeyboardAvoidingView>
    </SafeAreaView>
  );
}

const s = themed(() => StyleSheet.create({
  fl: { fontSize: 10.5, color: C.muted, marginBottom: 4, marginTop: 12 },
  k: { fontSize: 11, color: C.muted, marginBottom: 8 },
  input: { height: 48, borderWidth: 1.5, borderColor: C.line, borderRadius: 12, paddingHorizontal: 12, fontFamily: F.bodyBold, fontSize: 15, color: C.ink, backgroundColor: C.card },
  two: { flexDirection: 'row', gap: 8 },
  chips: { flexDirection: 'row', flexWrap: 'wrap', gap: 6, marginTop: 4 },
  small: { fontSize: 12, color: C.muted, marginTop: 6, lineHeight: 17 },
  row: { flexDirection: 'row', alignItems: 'center', gap: 12, paddingVertical: 12 },
  line: { borderBottomWidth: 1, borderBottomColor: C.line },
  ic: { width: 36, height: 36, borderRadius: 11, backgroundColor: C.fill, alignItems: 'center', justifyContent: 'center' },
  what: { fontFamily: F.bodyBold, fontSize: 14.5, color: C.ink },
  sub: { fontFamily: F.body, fontSize: 12, color: C.muted, marginTop: 2 },
  due: { borderRadius: 999, paddingHorizontal: 10, paddingVertical: 5, backgroundColor: C.fill },
  dueT: { fontFamily: F.bodyBold, fontSize: 12, color: C.onAccent },
}));
