// Hustle Mode · Set D · Coach chat: pick a hustle, see the right vehicle and kit, then does it pay?
import { router } from 'expo-router';
import { useState } from 'react';
import { ScrollView, StyleSheet, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

import { CarPhoto } from '@/components/car-photo';
import { BackIcon, CoachIcon } from '@/components/icons';
import { Body, Btn, Chip, H, Label, SquareBtn, tap } from '@/components/ui';
import { CARS, Car, carName, yearsOf } from '@/data/cars';
import { fiveYearCost, round } from '@/data/costs';
import { costsFor } from '@/data/state-costs';
import { HUSTLES, Hustle } from '@/data/hustles';
import { money, priceFor, priceLine } from '@/data/prices';
import { useFacts } from '@/data/use-facts';
import { calm, C, F, PAD, themed } from '@/theme';
import { sheet, SkyHeader } from '@/components/sky';
import { Pressable, Text, TextInput } from '@/components/t';
import { LATEST_MODEL_YEAR, ageOf } from '@/data/year';

function Bubble({ me, children }: { me?: boolean; children: React.ReactNode }) {
  return (
    <View style={[s.bub, me ? s.me : s.them]}>
      <Text style={me ? s.meText : s.themText}>{children}</Text>
    </View>
  );
}

// Monthly cost to own a car: payment, gas, insurance, upkeep (5-year average).
function useMonthly(car: Car, year: number) {
  const { facts } = useFacts(car.id, year);
  const p = priceFor(car, year);
  if (!p) return null;
  return fiveYearCost({ price: p.amount, isNew: p.isNew, ageYears: ageOf(year), mpg: facts?.mpg?.combined,
    electric: facts?.mpg?.fuel === 'EV', milesPerYear: 20000, gasPrice: 3.3, kwhPrice: 0.17, down: 2000, apr: p.isNew ? 8 : 10, months: 60, taxPct: costsFor().tax }).perMonth;
}

function Meter({ car, year, hustle }: { car: Car; year: number; hustle: Hustle }) {
  const monthly = useMonthly(car, year);
  const [per, setPer] = useState(String(hustle.perJob));
  const [jobs, setJobs] = useState('8');
  if (!monthly) return null;
  const perJob = Number(per) || 0;
  const n = Number(jobs) || 0;
  const need = perJob ? Math.ceil(monthly / perJob) : 0;
  const earned = perJob * n;
  const extra = earned - monthly;
  return (
    <View>
      <View style={s.meter}>
        <Label style={{ color: C.yellow }}>Pays for itself after</Label>
        <View style={{ flexDirection: 'row', alignItems: 'baseline', gap: 8 }}>
          <H size={56} style={{ color: C.yellow }}>{need}</H>
          <H size={22} style={{ color: C.ink }}>{hustle.jobWord}s a month</H>
        </View>
        <Body style={{ color: C.muted, fontSize: 12.5 }}>The car costs about {money(round(monthly))} a month to own (payment, gas, insurance, upkeep).</Body>
        <View style={s.track}><View style={{ width: `${Math.min(100, need ? (n / need) * 100 : 0)}%`, height: '100%', backgroundColor: C.yellow }} /></View>
        <Body style={{ color: C.ink, fontSize: 13, marginTop: 6 }}>
          With {n} {hustle.jobWord}s you’d {extra >= 0 ? `keep about ${money(round(extra))} extra` : `be ${money(round(-extra))} short`} each month.
        </Body>
      </View>
      <View style={{ flexDirection: 'row', gap: 8, marginTop: 8 }}>
        <View style={{ flex: 1 }}>
          <Label style={s.inLabel}>You keep per {hustle.jobWord}</Label>
          <View style={s.numBox}><Body bold>$</Body><TextInput value={per} onChangeText={(t) => setPer(t.replace(/\D/g, ''))} keyboardType="number-pad" style={s.num} accessibilityLabel={`Money kept per ${hustle.jobWord}`} /></View>
        </View>
        <View style={{ flex: 1 }}>
          <Label style={s.inLabel}>{hustle.jobWord}s a month</Label>
          <View style={s.numBox}><TextInput value={jobs} onChangeText={(t) => setJobs(t.replace(/\D/g, ''))} keyboardType="number-pad" style={s.num} accessibilityLabel={`${hustle.jobWord}s per month`} /></View>
        </View>
      </View>
      <Body style={{ fontSize: 11.5, color: C.muted, marginTop: 6 }}>
        Example numbers. What you keep changes a lot by city and how much you work. Type your own.
      </Body>
    </View>
  );
}

export default function HustleMode() {
  const [hid, setHid] = useState<string | null>(null);
  const [pick, setPick] = useState(0);
  const hustle = HUSTLES.find((h) => h.id === hid);
  const cars = (hustle?.cars ?? []).map((id) => CARS.find((c) => c.id === id)!).filter(Boolean);
  const car = cars[pick];
  // A newer used year keeps the cost down for a hustle car.
  const year = car ? (yearsOf(car).find((y) => y <= 2024) ?? yearsOf(car)[0]) : LATEST_MODEL_YEAR;

  return (
    <SafeAreaView edges={calm ? [] : ['top']} style={{ flex: 1, backgroundColor: C.bg }}>
      {calm ? <SkyHeader title="Hustle Mode" back={() => router.navigate('/home')} /> : (
        <View style={s.top}>
          <SquareBtn label="Back" onPress={() => router.navigate('/home')}><BackIcon /></SquareBtn>
          <View style={{ flexDirection: 'row', alignItems: 'center', gap: 6 }}><CoachIcon size={18} /><Label>Hustle Mode</Label></View>
          <View style={{ width: 44 }} />
        </View>
      )}
      <View style={calm ? sheet.page : { flex: 1 }}>
      <ScrollView contentContainerStyle={{ paddingHorizontal: PAD, paddingBottom: 40, gap: 8 }}>
        <Bubble me>I want a car that makes me money.</Bubble>
        <Bubble>Love it! Which hustle sounds good?</Bubble>
        {HUSTLES.map((h) => (
          <Pressable key={h.id} onPress={() => { tap(); setHid(h.id); setPick(0); }} accessibilityRole="button" accessibilityState={{ selected: hid === h.id }}
            style={[s.opt, hid === h.id && { backgroundColor: C.accentSoft, borderColor: C.yellow }]}>
            <H size={20}>{h.name}</H>
            <Body style={{ fontSize: 13 }}>{h.line}</Body>
          </Pressable>
        ))}

        {hustle && car && (
          <>
            <View style={{ height: 8 }} />
            <Bubble me>{hustle.name}</Bubble>
            <Bubble>Great pick. Here’s the vehicle I’d start with, and what you need.</Bubble>
            <CarPhoto id={car.id} label={carName(car, year)} style={{ height: 190 }} />
            <H size={26}>{carName(car, year)}</H>
            <Body bold>{priceLine(priceFor(car, year))}</Body>
            <View style={s.chips}>
              {cars.map((c, i) => <Chip key={c.id} label={`${c.make} ${c.model}`} on={i === pick} onPress={() => setPick(i)} />)}
            </View>
            <Label style={{ marginTop: 6 }}>Starter kit</Label>
            {hustle.kit.map((k) => <Body key={k} style={s.li}>✓ {k}</Body>)}

            <View style={{ height: 8 }} />
            <Bubble me>Will it pay for itself?</Bubble>
            <Bubble>Let’s see. Change the numbers to match your plan.</Bubble>
            <>
              <Meter key={`${hustle.id}-${car.id}`} car={car} year={year} hustle={hustle} />
            </>

            <Label style={{ marginTop: 10 }}>Your first steps</Label>
            {hustle.firstSteps.map((t, i) => (
              <View key={t} style={s.tip}><View style={s.tipN}><H size={15} style={{ color: C.onAccent }}>{i + 1}</H></View><Body bold style={{ flex: 1, fontSize: 14 }}>{t}</Body></View>
            ))}
            <Btn label="See this car" style={{ marginTop: 12 }} onPress={() => router.push({ pathname: '/car/[id]', params: { id: car.id, year: String(year) } })} />
          </>
        )}
      </ScrollView>
      </View>
    </SafeAreaView>
  );
}

const s = themed(() => StyleSheet.create({
  top: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', paddingHorizontal: PAD, paddingTop: 10, paddingBottom: 8 },
  bub: { maxWidth: '86%', paddingHorizontal: 13, paddingVertical: 10 },
  them: { alignSelf: 'flex-start', backgroundColor: C.grey },
  me: { alignSelf: 'flex-end', backgroundColor: C.hero },
  themText: { fontFamily: F.body, fontSize: 15, lineHeight: 21, color: C.ink },
  meText: { fontFamily: F.bodyBold, fontSize: 15, lineHeight: 21, color: C.yellow },
  opt: { borderWidth: 1, borderColor: C.line, borderRadius: 12, padding: 12 },
  chips: { flexDirection: 'row', flexWrap: 'wrap', gap: 6 },
  li: { fontSize: 14.5, paddingVertical: 4 },
  meter: { backgroundColor: C.hero, padding: 14 },
  track: { height: 10, backgroundColor: '#333', marginTop: 10 },
  inLabel: { fontSize: 10.5, color: C.muted, marginBottom: 4 },
  numBox: { flexDirection: 'row', alignItems: 'center', gap: 2, borderWidth: 1, borderColor: C.line, borderRadius: 12, height: 48, paddingHorizontal: 10 },
  num: { flex: 1, fontFamily: F.bodyBold, fontSize: 16, color: C.ink, minWidth: 0 },
  tip: { flexDirection: 'row', gap: 10, alignItems: 'center', paddingVertical: 8, borderBottomWidth: 2, borderBottomColor: C.grey },
  tipN: { width: 26, height: 26, backgroundColor: C.fill, alignItems: 'center', justifyContent: 'center' },
}));
