// "Use my location" (picture 125, Loudjier Oct 21, 2026: "1 and 3 together"): a button where we ask for a ZIP,
// then the phone's own question. One-time and only when they tap: never in the background, never tracking.
// We keep the ZIP code (in the coach answers); the exact spot stays in memory for this visit only.
// Needs the Android build made Oct 21, 2026 or later (expo-location); older test apps hide the button.
// The web test site uses the browser's location.
import { requireOptionalNativeModule } from 'expo';
import { Platform } from 'react-native';

export const canLocate = Platform.OS === 'web'
  ? typeof navigator !== 'undefined' && !!navigator.geolocation
  : !!requireOptionalNativeModule('ExpoLocation');

export type Spot = { lat: number; lon: number; zip: string | null };
export type Located = { ok: true; spot: Spot } | { ok: false; why: 'denied' | 'off' | 'fail' };

let last: Spot | null = null;
/** Where they were when they last tapped "Use my location" in this visit (never saved). */
export const lastSpot = () => last;

const zip5 = (z?: string | null) => (z ?? '').match(/\b\d{5}\b/)?.[0] ?? null;
const timeout = <T,>(p: Promise<T>, ms: number) =>
  Promise.race([p, new Promise<never>((_, no) => setTimeout(() => no(new Error('timeout')), ms))]);

// OpenStreetMap's free address lookup, only when the phone can't tell us the ZIP (and on the web).
async function zipFromSpot(lat: number, lon: number) {
  try {
    const r = await timeout(fetch(`https://nominatim.openstreetmap.org/reverse?format=jsonv2&zoom=16&addressdetails=1&lat=${lat.toFixed(3)}&lon=${lon.toFixed(3)}`, { headers: { Accept: 'application/json' } }), 8000);
    const j = await r.json();
    return j?.address?.country_code === 'us' ? zip5(j.address.postcode) : null;
  } catch {
    return null;
  }
}

type Loc = typeof import('expo-location');
function native(): Loc | null {
  try {
    return require('expo-location') as Loc; // eslint-disable-line @typescript-eslint/no-require-imports
  } catch {
    return null;
  }
}

/** Ask once (the phone asks the person), find about where they are, and the ZIP code there. */
export async function locate(): Promise<Located> {
  if (!canLocate) return { ok: false, why: 'fail' };
  try {
    let lat: number, lon: number, zip: string | null = null;
    if (Platform.OS === 'web') {
      const pos = await new Promise<GeolocationPosition>((yes, no) =>
        navigator.geolocation.getCurrentPosition(yes, no, { enableHighAccuracy: false, timeout: 15000, maximumAge: 600000 }));
      ({ latitude: lat, longitude: lon } = pos.coords);
    } else {
      const L = native();
      if (!L) return { ok: false, why: 'fail' };
      const perm = await L.requestForegroundPermissionsAsync();
      if (!perm.granted) return { ok: false, why: 'denied' };
      if (!(await L.hasServicesEnabledAsync())) return { ok: false, why: 'off' };
      const pos = (await L.getLastKnownPositionAsync({ maxAge: 10 * 60000 }))
        ?? (await timeout(L.getCurrentPositionAsync({ accuracy: L.Accuracy.Low }), 15000));
      ({ latitude: lat, longitude: lon } = pos.coords);
      try { zip = zip5((await L.reverseGeocodeAsync({ latitude: lat, longitude: lon }))[0]?.postalCode); } catch { zip = null; }
    }
    if (!zip) zip = await zipFromSpot(lat, lon);
    last = { lat, lon, zip };
    return { ok: true, spot: last };
  } catch (e) {
    const code = (e as { code?: number })?.code;
    return { ok: false, why: code === 1 ? 'denied' : 'fail' };
  }
}

export type Exact = { ok: true; lat: number; lon: number; acc: number } | { ok: false; why: 'denied' | 'off' | 'fail' };
/** A fresh, careful reading of where they are right now (for "I parked here"). acc = how sure, in meters. Only when they tap. */
export async function locateExact(): Promise<Exact> {
  if (!canLocate) return { ok: false, why: 'fail' };
  try {
    if (Platform.OS === 'web') {
      const pos = await new Promise<GeolocationPosition>((yes, no) =>
        navigator.geolocation.getCurrentPosition(yes, no, { enableHighAccuracy: true, timeout: 20000, maximumAge: 0 }));
      return { ok: true, lat: pos.coords.latitude, lon: pos.coords.longitude, acc: pos.coords.accuracy ?? 999 };
    }
    const L = native();
    if (!L) return { ok: false, why: 'fail' };
    const perm = await L.requestForegroundPermissionsAsync();
    if (!perm.granted) return { ok: false, why: 'denied' };
    if (!(await L.hasServicesEnabledAsync())) return { ok: false, why: 'off' };
    const pos = await timeout(L.getCurrentPositionAsync({ accuracy: L.Accuracy.High }), 20000);
    last = { lat: pos.coords.latitude, lon: pos.coords.longitude, zip: last?.zip ?? null };
    return { ok: true, lat: pos.coords.latitude, lon: pos.coords.longitude, acc: pos.coords.accuracy ?? 999 };
  } catch (e) {
    const code = (e as { code?: number })?.code;
    return { ok: false, why: code === 1 ? 'denied' : 'fail' };
  }
}
