// What can I afford? (picked Oct 10, 2026: input C = tap cards; results 1 = three groups + 3 = goal-car plan).
// Everything is an estimate. Income and score stay on the phone. We never check credit.
import { router } from 'expo-router';
import { useState } from 'react';
import { ScrollView, StyleSheet, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import Svg, { Path } from 'react-native-svg';

import { CarPhoto } from '@/components/car-photo';
import { BackIcon } from '@/components/icons';
import { Body, Btn, H, Label, SquareBtn, tap } from '@/components/ui';
import { affordFor, INCOMES, Pick, planFor, safeRange, Tier, TIERS, usd } from '@/data/afford';
import { tr } from '@/i18n';
import { useAnswers } from '@/state/answers';
import { calm, C, F, PAD, themed } from '@/theme';
import { sheet, SkyHeader } from '@/components/sky';
import { Pressable, Text } from '@/components/t';

type Group = 'fits' | 'stretch' | 'save';

function Card({ label, sub, on, onPress }: { label: string; sub: string; on: boolean; onPress: () => void }) {
  return (
    <Pressable onPress={() => { tap(); onPress(); }} accessibilityRole="button" accessibilityState={{ selected: on }} accessibilityLabel={`${label}, ${sub}`}
      style={({ pressed }) => [s.pick, on && s.pickOn, pressed && { opacity: 0.8 }]}>
      <Text style={[s.pickLabel, tr(label).length > 11 && { fontSize: 14 }]} numberOfLines={1}>{label}</Text>
      <Text style={s.pickSub}>{sub}</Text>
    </Pressable>
  );
}

function CarRow({ p, onPress, good }: { p: Pick; onPress: () => void; good?: boolean }) {
  return (
    <Pressable onPress={() => { tap(); onPress(); }} accessibilityRole="button" accessibilityLabel={`${p.name}, about ${usd(p.pay)} a month`}
      style={({ pressed }) => [s.row, pressed && { opacity: 0.85 }]}>
      <CarPhoto id={p.car.id} label={p.name} style={{ width: 118, height: 96 }} />
      <View style={{ flex: 1, paddingVertical: 10, paddingRight: 10, gap: 4 }}>
        <Body bold style={{ fontSize: 15 }}>{p.name}</Body>
        <Body style={{ fontSize: 12.5, color: C.muted }}>{p.isNew ? `New from about ${usd(p.price)}` : `About ${usd(p.price)} used`}</Body>
        <View style={[s.payChip, !good && { backgroundColor: C.accentSoft }]}>
          <Text style={[s.payText, !good && { color: C.yellow }]}>About {usd(p.pay)} / mo</Text>
        </View>
      </View>
    </Pressable>
  );
}

export default function Afford() {
  const { answers, setAnswers } = useAnswers();
  const [income, setIncome] = useState<number | undefined>(answers.income);
  const [tier, setTier] = useState<Tier | undefined>(answers.credit);
  const [unknown, setUnknown] = useState(false);
  const [showing, setShowing] = useState(!!(answers.income && answers.credit));
  const [group, setGroup] = useState<Group>('fits');
  const [goalId, setGoalId] = useState<string | null>(null);

  const ready = !!income && !!tier;
  const res = ready ? affordFor(income, tier) : null;
  const goal = res ? (res.goals.find((g) => `${g.car.id}:${g.year}` === goalId) ?? res.goals[0]) : undefined;
  const plan = goal && income && tier ? planFor(goal, income, tier) : null;
  const open = (p: Pick) => router.push({ pathname: '/car/[id]', params: { id: p.car.id, year: String(p.year) } });

  const show = () => { if (!ready) return; setAnswers({ ...answers, income, credit: tier }); setShowing(true); setGroup('fits'); };

  if (!showing || !res) {
    return (
      <SafeAreaView edges={calm ? [] : ['top']} style={{ flex: 1, backgroundColor: C.bg }}>
        {calm ? <SkyHeader title="What can I afford?" sub="2 quick taps" back={() => router.back()} /> : (
          <View style={s.top}>
            <SquareBtn label="Back" onPress={() => router.back()}><BackIcon /></SquareBtn>
            <Label>2 quick taps</Label>
            <View style={{ width: 44 }} />
          </View>
        )}
        <View style={calm ? sheet.page : { flex: 1 }}>
        <ScrollView contentContainerStyle={{ paddingHorizontal: PAD, paddingBottom: 40, gap: 10 }}>
          {!calm && <H size={34}>What can I afford?</H>}
          <Label style={calm ? { marginTop: 6 } : undefined}>1 · Your yearly income</Label>
          <View style={s.grid}>
            {INCOMES.map((i) => <View key={i.label} style={{ width: '31.8%' }}><Card label={i.label} sub={i.sub} on={income === i.amount} onPress={() => setIncome(i.amount)} /></View>)}
          </View>
          <Label style={{ marginTop: 6 }}>2 · Your credit score (about)</Label>
          <View style={s.grid}>
            {TIERS.map((t) => <View key={t.tier} style={{ width: '48.6%' }}><Card label={t.tier} sub={t.sub} on={tier === t.tier} onPress={() => { setTier(t.tier); setUnknown(false); }} /></View>)}
          </View>
          <Pressable onPress={() => { tap(); setTier('Fair'); setUnknown(true); }} accessibilityRole="button" hitSlop={8} style={{ alignSelf: 'center' }}>
            <Body style={{ color: unknown ? C.yellow : C.muted, textDecorationLine: 'underline', fontSize: 13.5 }}>{unknown ? 'Using “Fair” for now. You can change it.' : 'I don’t know my score'}</Body>
          </Pressable>
          <View style={s.hero}>
            <Label style={{ color: C.yellow }}>Safe car payment for you</Label>
            <H size={32} style={{ marginTop: 2 }}>{income ? `${usd(safeRange(income).low)} to ${usd(safeRange(income).high)} / mo` : 'Tap your income'}</H>
            <Body style={{ fontSize: 12, color: C.muted }}>Estimate: 10% to 15% of your monthly pay. Updates as you tap.</Body>
          </View>
          <Btn kind="yellow" label="Show my cars" onPress={show} style={!ready ? { opacity: 0.5 } : undefined} />
          <Body style={{ fontSize: 11.5, color: C.muted, textAlign: 'center' }}>Stays on your phone. We never check your credit.</Body>
        </ScrollView>
        </View>
      </SafeAreaView>
    );
  }

  const groups: { key: Group; label: string; sub: string }[] = [
    { key: 'fits', label: 'Fits now', sub: `${res.fits.length} car${res.fits.length === 1 ? '' : 's'}` },
    { key: 'stretch', label: 'A stretch', sub: `${res.stretch.length} car${res.stretch.length === 1 ? '' : 's'}` },
    { key: 'save', label: 'Save for it', sub: res.goals.length ? '1 plan' : 'None needed' },
  ];
  const incomeLabel = INCOMES.find((i) => i.amount === income)?.label ?? usd(income ?? 0);

  return (
    <SafeAreaView edges={calm ? [] : ['top']} style={{ flex: 1, backgroundColor: C.bg }}>
      {calm ? <SkyHeader title="What can I afford?" back={() => router.back()} /> : (
        <View style={s.top}>
          <SquareBtn label="Back" onPress={() => router.back()}><BackIcon /></SquareBtn>
          <Label>What can I afford?</Label>
          <View style={{ width: 44 }} />
        </View>
      )}
      <View style={calm ? sheet.page : { flex: 1 }}>
      <ScrollView contentContainerStyle={{ paddingHorizontal: PAD, paddingBottom: 40, gap: 10 }}>
        <View style={s.hero}>
          <Label style={{ color: C.yellow }}>Your safe car payment · estimate</Label>
          <H size={32} style={{ marginTop: 2 }}>{usd(res.range.low)} to {usd(res.range.high)} / month</H>
          <View style={{ flexDirection: 'row', gap: 6, marginTop: 8, flexWrap: 'wrap' }}>
            <View style={s.tag}><Text style={s.tagText}>{incomeLabel} a year</Text></View>
            <View style={s.tag}><Text style={s.tagText}>{res.tier.tier} credit · about {res.tier.apr}% new, {res.tier.used}% used</Text></View>
            <Pressable onPress={() => { tap(); setShowing(false); }} accessibilityRole="button" style={[s.tag, { borderColor: C.yellow }]}><Text style={[s.tagText, { color: C.yellow }]}>Edit</Text></Pressable>
          </View>
        </View>

        <View style={s.tabs}>
          {groups.map((g) => (
            <Pressable key={g.key} onPress={() => { tap(); setGroup(g.key); }} accessibilityRole="tab" accessibilityState={{ selected: group === g.key }}
              style={[s.tab, group === g.key && { backgroundColor: C.fill }]}>
              <Text style={[s.tabLabel, group === g.key && { color: C.onAccent }]}>{g.label}</Text>
              <Text style={[s.tabSub, group === g.key && { color: C.onAccent }]}>{g.sub}</Text>
            </Pressable>
          ))}
        </View>

        {group === 'fits' && (
          <>
            {res.fits.length ? res.fits.map((p) => <CarRow key={p.car.id} p={p} good onPress={() => open(p)} />)
              : <Body style={{ color: C.muted }}>No cars fit this budget yet. Check “A stretch” or “Save for it”.</Body>}
            {res.drop > 0 && (
              <View style={s.tip}>
                <View style={s.tipIcon}><Svg width={18} height={18} viewBox="0 0 24 24" fill="none" stroke={C.onAccent} strokeWidth={2.4} strokeLinecap="round" strokeLinejoin="round"><Path d="M4 17l6-6 4 4 6-8M15 7h5v5" /></Svg></View>
                <Body style={{ flex: 1, fontSize: 13.5 }}><Body bold style={{ fontSize: 13.5 }}>Raise your score to {res.tier.score}+</Body> and these drop about {usd(res.drop)} a month.</Body>
              </View>
            )}
          </>
        )}
        {group === 'stretch' && (
          res.stretch.length ? (
            <>
              <Body style={{ color: C.muted, fontSize: 13.5 }}>These fit, but leave less room for gas, insurance and bills.</Body>
              {res.stretch.map((p) => <CarRow key={p.car.id} p={p} onPress={() => open(p)} />)}
            </>
          ) : <Body style={{ color: C.muted }}>Nothing in between for this budget. See “Fits now”.</Body>
        )}
        {group === 'save' && (goal && plan ? (
          <>
            <Pressable onPress={() => open(goal)} accessibilityRole="button" style={s.goalCard}>
              <CarPhoto id={goal.car.id} label={goal.name} style={{ height: 130 }} />
              <View style={{ padding: 12 }}>
                <Label style={{ color: C.yellow }}>Your goal car</Label>
                <H size={26} style={{ marginTop: 2 }}>{goal.name}</H>
                <Body style={{ fontSize: 13, color: C.muted }}>New from about {usd(goal.price)}</Body>
              </View>
            </Pressable>
            <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={{ gap: 6 }}>
              {res.goals.map((g) => {
                const on = g === goal;
                return (
                  <Pressable key={g.car.id} onPress={() => { tap(); setGoalId(`${g.car.id}:${g.year}`); }} accessibilityRole="button" accessibilityState={{ selected: on }}
                    style={[s.goalChip, on && { backgroundColor: C.fill, borderColor: C.fill }]}>
                    <Text style={[s.goalChipText, on && { color: C.onAccent }]}>{g.car.make} {g.car.model}</Text>
                  </Pressable>
                );
              })}
            </ScrollView>
            <>
            <View style={{ gap: 8 }}>
            <View style={{ flexDirection: 'row', gap: 8 }}>
              <View style={[s.box, { flex: 1 }]}><Body style={{ fontSize: 12, color: C.muted, textAlign: 'center' }}>Today</Body><H size={24} style={{ color: C.red, textAlign: 'center' }}>{usd(plan.today)}/mo</H></View>
              <View style={[s.box, { flex: 1, borderColor: C.green }]}><Body style={{ fontSize: 12, color: C.muted, textAlign: 'center' }}>After your plan</Body><H size={24} style={{ color: C.green, textAlign: 'center' }}>{usd(plan.after)}/mo</H></View>
            </View>
            <Label style={{ marginTop: 4 }}>Your plan{plan.months ? ` · about ${plan.months < 24 ? `${plan.months} months` : `${Math.round(plan.months / 12 * 2) / 2} years`}` : ''}</Label>
            {plan.down > 0 && (
              <View style={s.box}>
                <Body bold>1 · Save {usd(plan.save)} a month</Body>
                <Body style={{ fontSize: 12.5, color: C.muted }}>Goal: {usd(plan.down)} for the down payment ({plan.months} months)</Body>
              </View>
            )}
            {plan.better && (
              <View style={s.box}>
                <Body bold>{plan.down > 0 ? '2' : '1'} · Raise your score to {res.tier.score}+</Body>
                <Body style={{ fontSize: 12.5, color: C.muted }}>Pay every bill on time and keep cards under 30% used. That alone saves about {usd(plan.savesScore)} a month on this car.</Body>
              </View>
            )}
            <View style={[s.box, { borderColor: C.green }]}>
              <Body bold>Then your {goal.car.model} fits</Body>
              <Body style={{ fontSize: 12.5, color: C.muted }}>About {usd(plan.after)} a month with {usd(plan.down)} down and a {plan.next.tier.toLowerCase()} score.</Body>
            </View>
            </View>
            </>
          </>
        ) : <Body style={{ color: C.muted }}>Good news: every car we know already fits or is a stretch for you.</Body>)}

        <Body style={{ fontSize: 11.5, color: C.muted, textAlign: 'center', marginTop: 4 }}>
          Estimates, not a loan offer. 6-year loan, $0 down, tax and fees included. Your lender sets the real rate.
        </Body>
      </ScrollView>
      </View>
    </SafeAreaView>
  );
}

const s = themed(() => StyleSheet.create({
  top: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', paddingHorizontal: PAD, paddingTop: 10, paddingBottom: 10 },
  grid: { flexDirection: 'row', flexWrap: 'wrap', justifyContent: 'space-between', rowGap: 7 },
  pick: { borderRadius: 14, borderWidth: 1, borderColor: C.line, backgroundColor: C.card, paddingHorizontal: 12, paddingVertical: 10 },
  pickOn: { borderColor: C.yellow, backgroundColor: C.accentSoft },
  pickLabel: { fontFamily: F.bodyBold, fontSize: 16, color: C.ink },
  pickSub: { fontFamily: F.body, fontSize: 12, color: C.muted },
  hero: { backgroundColor: C.hero, borderRadius: 16, padding: 14 },
  tag: { borderRadius: 20, borderWidth: 1, borderColor: C.line, paddingHorizontal: 10, paddingVertical: 4 },
  tagText: { fontFamily: F.bodyBold, fontSize: 12, color: C.ink },
  tabs: { flexDirection: 'row', gap: 4, backgroundColor: C.card, borderRadius: 14, padding: 4 },
  tab: { flex: 1, alignItems: 'center', borderRadius: 10, paddingVertical: 8 },
  tabLabel: { fontFamily: F.bodyBold, fontSize: 14, color: C.ink },
  tabSub: { fontFamily: F.body, fontSize: 11.5, color: C.muted },
  row: { flexDirection: 'row', gap: 12, borderRadius: 16, overflow: 'hidden', backgroundColor: C.card, borderWidth: 1, borderColor: C.line },
  payChip: { alignSelf: 'flex-start', borderRadius: 20, paddingHorizontal: 10, paddingVertical: 3, backgroundColor: C.goodBg },
  payText: { fontFamily: F.bodyBold, fontSize: 13, color: C.goodInk },
  tip: { flexDirection: 'row', gap: 10, alignItems: 'center', borderRadius: 16, padding: 12, backgroundColor: C.card, borderWidth: 1, borderColor: C.line },
  tipIcon: { width: 34, height: 34, borderRadius: 17, backgroundColor: C.fill, alignItems: 'center', justifyContent: 'center' },
  goalCard: { borderRadius: 16, overflow: 'hidden', backgroundColor: C.card, borderWidth: 1, borderColor: C.line },
  goalChip: { borderRadius: 20, borderWidth: 1, borderColor: C.line, backgroundColor: C.card, paddingHorizontal: 12, paddingVertical: 7 },
  goalChipText: { fontFamily: F.bodyBold, fontSize: 13, color: C.ink },
  box: { borderRadius: 14, borderWidth: 1, borderColor: C.line, backgroundColor: C.card, padding: 12, gap: 2 },
}));
