// "Same car at other dealers" on Check a car (picture 147, Oct 25, 2026): the same model for sale nearby,
// sorted by Top choice, price, miles or distance. Top choice = the best mix of price for its miles (half),
// miles (a quarter) and drive time (a quarter). Plain math here so it can be tested.
import { listingTag } from '@/data/fair-price';
import type { Listing } from '@/data/listings';

export type Sort = 'top' | 'price' | 'miles' | 'distance';
export type Ranked = Listing & { score: number; top: boolean; why: string[] }; // why: short pieces, each translated on its own

// The car we want at other dealers: same model, same year ±1, not the one you're looking at.
// 'Chevy' (our name) and 'Chevrolet' (the listing's) are the same brand.
const BRAND: Record<string, string> = { chevy: 'chevrolet', vw: 'volkswagen', mercedes: 'mercedes-benz' };
const brand = (m: string) => BRAND[m.trim().toLowerCase()] ?? m.trim().toLowerCase();

export function sameCars(cars: Listing[], c: { year: number; make: string; model: string; vin?: string }, allYears = false): Listing[] {
  const mk = brand(c.make), md = c.model.toLowerCase();
  return cars.filter((l) => l.vin !== c.vin && brand(l.make) === mk
    && (l.model.toLowerCase() === md || l.model.toLowerCase().startsWith(md + ' ') || md.startsWith(l.model.toLowerCase() + ' '))
    && (allYears || Math.abs(l.year - c.year) <= 1));
}

// 0 = worst in the group, 1 = best. Everyone the same = 1.
const spread = (v: number, lo: number, hi: number, lowIsGood = true) => (hi === lo ? 1 : lowIsGood ? (hi - v) / (hi - lo) : (v - lo) / (hi - lo));

export function rank(cars: Listing[]): Ranked[] {
  if (!cars.length) return [];
  // Price for its miles: how far under (or over) our fair middle. Without our estimate, compare with the group's middle price.
  const prices = cars.map((l) => l.price).sort((a, b) => a - b);
  const groupMid = prices[Math.floor(prices.length / 2)];
  const value = cars.map((l) => { const t = listingTag(l); const mid = t ? (t.range[0] + t.range[1]) / 2 : groupMid; return (mid - l.price) / mid; });
  const miles = cars.map((l) => l.miles ?? Math.max(...cars.map((x) => x.miles ?? 0)));
  const vLo = Math.min(...value), vHi = Math.max(...value);
  const mLo = Math.min(...miles), mHi = Math.max(...miles);
  const dLo = Math.min(...cars.map((l) => l.min)), dHi = Math.max(...cars.map((l) => l.min));
  const parts = cars.map((l, i) => ({ p: spread(value[i], vLo, vHi, false), m: spread(miles[i], mLo, mHi), d: spread(l.min, dLo, dHi) }));
  const scores = parts.map((x) => 0.5 * x.p + 0.25 * x.m + 0.25 * x.d);
  const best = scores.indexOf(Math.max(...scores));
  return cars.map((l, i) => {
    const x = parts[i];
    const why = [x.p === 1 && value[i] > 0 ? 'Best price for its miles' : value[i] > 0 ? 'Good price for its miles' : null,
      x.m === 1 && cars.length > 1 ? 'Fewest miles' : null, x.d >= 0.6 ? 'Close by' : null].filter((w): w is string => !!w).slice(0, 2);
    return { ...l, score: scores[i], top: cars.length > 1 && i === best, why: why.length ? why : ['Best mix of price, miles and distance'] };
  });
}

export function sortCars(cars: Ranked[], by: Sort): Ranked[] {
  const key: Record<Sort, (l: Ranked) => number> = { top: (l) => -l.score, price: (l) => l.price, miles: (l) => l.miles ?? Infinity, distance: (l) => l.min };
  return [...cars].sort((a, b) => key[by](a) - key[by](b));
}

// ["$1,600 less", "2,850 fewer miles"] compared with the car you're looking at.
export function versus(l: Listing, asking?: number, miles?: number): { parts: string[]; better: boolean } | null {
  const parts: string[] = [];
  let better = false;
  const n = (v: number) => Math.abs(v).toLocaleString('en-US');
  if (asking) { const d = asking - l.price; if (Math.abs(d) >= 100) { parts.push(`$${n(d)} ${d > 0 ? 'less' : 'more'}`); better = d > 0; } else parts.push('Same price'); }
  if (miles && l.miles != null) { const d = miles - l.miles; if (Math.abs(d) >= 100) parts.push(`${n(d)} ${d > 0 ? 'fewer' : 'more'} miles`); }
  return parts.length ? { parts, better } : null;
}
