// Popular in Atlanta (pictures 253 A + 256 A + 257 + 258, Loudjier Nov 17, 2026).
// The app adds 1 to a car for the shopper's area when they open its page, save it or compare it.
// We send only: the ZIP (turned into an area on the server), the car, the kind of action and a random id
// made on this phone (so one phone counts once per car per day). No names, no exact location.
// Until an area has 20 different shoppers in 2 weeks we show the U.S. best sellers instead (honest start).
import AsyncStorage from '@react-native-async-storage/async-storage';
import { supabase } from '@/lib/supabase';
import { popularZip } from './popular-zip';

export type Kind = 'view' | 'save' | 'compare';
export type PopRow = { car_id: string; score: number; views: number; saves: number; compares: number; rank_now: number; rank_before: number | null; shoppers: number; metro: string };
export type Why = 'saved' | 'compared' | 'looked';
export type PopCar = { id: string; rank: number; move: 'up' | 'down' | 'same' | 'new'; by: number; why: Why | null };
export type PopList = { local: boolean; area: string; cars: PopCar[] };

/** Areas need this many different phones in the last 14 days before we show their own list. */
export const MIN_SHOPPERS = 20;

/** 2025 U.S. new-vehicle sales order (automaker full-year reports; Ford F-Series 828,832 #1), only cars we have
 * pictures for. GMC Sierra and Tesla Model Y are left out (no good picture yet). */
export const US_BEST_SELLERS = ['f150', 'silverado', 'rav4', 'crv', 'ram1500', 'camry', 'tacoma', 'equinox'];

export { setPopularZip, popularZip } from './popular-zip';

/** ZIP → area name we show. Same rule as the server (metro_of). */
export function areaOf(z: string): { key: string; name: string } {
  const p = z.slice(0, 3);
  return ['300', '301', '302', '303', '311', '399'].includes(p) ? { key: 'atlanta', name: 'Atlanta' } : { key: `z${p}`, name: 'your area' };
}

const ID_KEY = 'carvessa:shopper:v1';
let shopperId: string | null = null;
async function shopper(): Promise<string> {
  if (shopperId) return shopperId;
  try { shopperId = await AsyncStorage.getItem(ID_KEY); } catch { /* storage can be off */ }
  if (!shopperId) {
    const hex = () => Math.floor(Math.random() * 0x100000000).toString(16).padStart(8, '0');
    shopperId = `${hex()}${hex()}${hex()}${hex()}`;
    try { await AsyncStorage.setItem(ID_KEY, shopperId); } catch { /* fine */ }
  }
  return shopperId;
}

// One count per car + kind per visit is plenty (the server also keeps one per phone per day).
const sent = new Set<string>();
/** Fire and forget: never slows the app, never shows an error. */
export function countCar(carId: string, kind: Kind) {
  const zip = popularZip();
  if (!zip || !carId) return;
  const key = `${carId}:${kind}`;
  if (sent.has(key)) return;
  sent.add(key);
  shopper().then((s) => supabase.rpc('bump_car_interest', { p_zip: zip, p_car: carId, p_kind: kind, p_shopper: s })).then(() => {}, () => { sent.delete(key); });
}

/** Turns the server rows into our list, or the U.S. best sellers when the area is still too new. */
export function toList(rows: PopRow[], z: string, known: (id: string) => boolean): PopList {
  const area = areaOf(z || '30303');
  const shoppers = rows[0]?.shoppers ?? 0;
  const mine = rows.filter((r) => known(r.car_id));
  if (shoppers >= MIN_SHOPPERS && mine.length >= 3) {
    return {
      local: true, area: area.name,
      cars: mine.slice(0, 10).map((r, i) => {
        const rank = i + 1;
        const move: PopCar['move'] = r.rank_before == null ? 'new' : r.rank_before > rank ? 'up' : r.rank_before < rank ? 'down' : 'same';
        const parts: [Why, number][] = [['saved', r.saves * 3], ['compared', r.compares * 2], ['looked', r.views]];
        parts.sort((a, b) => b[1] - a[1]);
        return { id: r.car_id, rank, move, by: r.rank_before == null ? 0 : Math.abs(r.rank_before - rank), why: parts[0][1] > 0 ? parts[0][0] : null };
      }),
    };
  }
  return { local: false, area: area.name, cars: US_BEST_SELLERS.filter(known).map((id, i) => ({ id, rank: i + 1, move: 'same', by: 0, why: null })) };
}

let cache: { zip: string; at: number; rows: PopRow[] } | null = null;
/** The area's top 10 (cached 30 minutes). Any problem → empty, which shows the U.S. best sellers. */
export async function fetchPopular(z: string): Promise<PopRow[]> {
  if (!/^\d{5}$/.test(z)) return [];
  if (cache && cache.zip === z && Date.now() - cache.at < 30 * 60 * 1000) return cache.rows;
  try {
    const { data, error } = await supabase.rpc('popular_cars', { p_zip: z, p_days: 7 });
    if (error || !Array.isArray(data)) return [];
    cache = { zip: z, at: Date.now(), rows: data as PopRow[] };
    return cache.rows;
  } catch { return []; }
}

/** Monday of this week, for the "New week · Nov 16" ribbon. */
export function weekStart(now = new Date()): Date {
  const d = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  d.setDate(d.getDate() - ((d.getDay() + 6) % 7));
  return d;
}
