import AsyncStorage from '@react-native-async-storage/async-storage';
import { createContext, useContext, useEffect, useMemo, useState } from 'react';

import { TIERS, aprOf, outTheDoor, payFor } from '@/data/afford';
import { monthlyPayment } from '@/data/costs';
import { setHomeState, stateFromZip } from '@/data/state-costs';
import { setPopularZip } from '@/data/popular-zip';
import { BUDGETS, CARS, Car, Goal, Kind, MUST_HAVES, Year, carIsKind, featureAt, yearsOf } from '@/data/cars';
import { bandOf, priceFor } from '@/data/prices';
import { LATEST_MODEL_YEAR } from '@/data/year';
import { ALL_KINDS, BOTH, UPGRADE, applyAnswer, hasCar, likeMine, walk } from '@/data/coach';

export type Answers = {
  goal?: string;
  budget?: string;
  mustHaves: string[];
  wants?: string[]; // nice to have (picked in the features grid, not starred)
  color?: string; // paint color picked in the showroom
  income?: number; // "What can I afford?": yearly pay, stays on the phone
  credit?: 'Rebuilding' | 'Fair' | 'Good' | 'Great';
  current?: string; // upgrade / similar / new
  myCar?: string;
  myCarMiles?: number; // picture 185: their car's miles (about)
  myCarKind?: string; // their car's kind as a coach answer ('SUV (3 rows)', 'Sedan'…), from data/car-kind.ts
  myCarSeats?: number;
  kindCheck?: string; // picked smaller than their car: 'Yes, sedans' / 'Show both' / 'SUVs like mine'
  riders?: string;
  zip?: string;
  // Smarter coach (picture 69, Oct 16, 2026)
  kind?: string; // SUV, Sedan… or "Not sure, show me all"
  newUsed?: string; // New only / Either / Used only
  pay?: string; // Cash / Car loan / Lease / Not sure yet
  monthly?: string; // "About $400"
  down?: string; // "$1,000 – $2,500"
  apps?: string; // "Uber, DoorDash"
  trade?: string; // "Yes, trade it in" / "No, …"
  firstCar?: string; // Yes / No
  when?: string; // Just looking / This month / In 1–3 months / Later
  more?: More; // optional "Tell me more" after the top 3
  pre?: PreApproval; // "You're pre-approved" (picture 167 screen 15): what their lender gave them
};
// What the lender told them: rate (APR %), up to $, months, good until (MM/DD/YYYY). Typed in by them, never a lender's data feed.
export type PreApproval = { apr: number; upTo: number; months: number; until?: string; lender?: string };
const untilOk = (u?: string) => {
  const m = u?.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  return !m || new Date(Number(m[3]), Number(m[1]) - 1, Number(m[2]), 23, 59).getTime() >= Date.now();
};
/** A pre-approval that hasn't run out. */
export const preOf = (a: Answers) => (a.pre && a.pre.apr >= 0 && a.pre.months > 0 && untilOk(a.pre.until) ? a.pre : undefined);
/** Their shopping number: the monthly payment if they borrow all of the pre-approval (an ESTIMATE). */
export const shoppingNumber = (p: PreApproval) => Math.round(monthlyPayment(p.upTo, p.apr, p.months));
/** Fits the pre-approval: what they'd borrow (out the door, minus money down) is at or under "up to". */
export const fitsPre = (a: Answers, price: number) => { const p = preOf(a); return p ? outTheDoor(price) - (DOWN[a.down ?? ''] ?? 0) <= p.upTo : undefined; };
export type More = { daily?: string; fuel?: string; skip?: string[]; accidents?: string; parking?: string; snow?: string };

export const KIND_LABEL: Record<string, Kind> = { SUV: 'SUV', 'SUV (3 rows)': 'SUV', Sedan: 'Sedan', Truck: 'Truck', Minivan: 'Minivan', Hatchback: 'Hatchback', 'Sports car': 'Sports', Electric: 'Electric', Hybrid: 'Hybrid' };
export const DOWN: Record<string, number> = { '$0': 0, 'Under $1,000': 500, '$1,000 – $2,500': 1750, '$2,500 – $5,000': 3750, '$5,000+': 6000 };
/** The monthly payment they picked, as a number ("About $600+" → 600), or undefined. */
export const monthlyCap = (a: Answers) => (a.pay === 'Car loan' ? Number((a.monthly ?? '').replace(/[^\d]/g, '')) || undefined : undefined);
/** Our payment ESTIMATE for this price with their loan answers (72 months, their credit, their money
 * down). Used-car rate unless we know it's new: most of our shoppers buy used. */
export function paymentFor(a: Answers, price: number, isNew = a.newUsed === 'New only') {
  // Pre-approved: their real rate and loan length beat our credit-level guess.
  const p = preOf(a);
  if (p) return Math.round(monthlyPayment(Math.max(0, outTheDoor(price) - (DOWN[a.down ?? ''] ?? 0)), p.apr, p.months));
  const t = TIERS.find((x) => x.tier === a.credit) ?? TIERS[2];
  return payFor(price, aprOf(t, isNew), DOWN[a.down ?? ''] ?? 0);
}

/** One coach chat kept on the phone (picture 185 History): up to 3, newest first. */
export type ChatRec = { id: string; at: number; chat: string[]; answers: Answers; done: boolean };
export const MAX_CHATS = 3;
/** Put this chat first (replacing its older copy) and keep the newest 3. */
export function upsertChat(list: ChatRec[], rec: ChatRec): ChatRec[] {
  return [rec, ...list.filter((c) => c.id !== rec.id)].slice(0, MAX_CHATS);
}
/** A new chat keeps what other screens saved (ZIP, pay, pre-approval), not the old chat's answers. */
export const freshAnswers = (a: Answers): Answers => ({ mustHaves: [], zip: a.zip, income: a.income, pre: a.pre });
const newId = () => `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`;

type Ctx = {
  answers: Answers;
  setAnswers: (a: Answers) => void;
  chat: string[]; // the coach chat answers, in order
  setChat: (c: string[]) => void;
  // Start a NEW coach chat (the old one stays in History), optionally with a goal picked. For "Upgrade my
  // car", pass the car they already saved (carAnswer text + its kind) so the coach skips asking for it.
  // likeMine: also answer "What kind of car?" with their car's kind (one-tap Upgrade from Home, Nov 17, 2026).
  startChat: (goal?: string, car?: { text: string; info?: Partial<Answers> }, likeMine?: boolean) => void;
  history: ChatRec[]; // up to 3 chats, newest first (includes this one once it has an answer)
  chatId: string;
  openChat: (id: string) => void; // continue / change answers / see picks of an old chat
  deleteChat: (id: string) => void;
};
const AnswersCtx = createContext<Ctx | null>(null);
const KEY = 'carvessa:answers:v1';

export function AnswersProvider({ children }: { children: React.ReactNode }) {
  const [answers, setAnswers] = useState<Answers>({ mustHaves: [] });
  // The coach starts fresh every time the app opens (picture 185); old chats wait in History.
  const [chat, setChat] = useState<string[]>([]);
  const [chatId, setChatId] = useState(newId);
  const [stored, setHistory] = useState<ChatRec[]>([]); // History without the open chat's newest words
  // Kept on this phone so the coach remembers you after the app closes (reset plan, Oct 16, 2026).
  const [loaded, setLoaded] = useState(false);
  useEffect(() => {
    AsyncStorage.getItem(KEY)
      .then((raw) => {
        if (!raw) return;
        const d = JSON.parse(raw);
        if (d?.answers && Array.isArray(d.answers.mustHaves)) setAnswers(d.answers);
        if (Array.isArray(d?.history)) setHistory(d.history.filter((c: ChatRec) => c && Array.isArray(c.chat) && c.answers && Array.isArray(c.answers.mustHaves)).slice(0, MAX_CHATS));
        else if (Array.isArray(d?.chat) && d.chat.length && d?.answers) {
          // Older app: one chat, no history. It becomes the first History chat.
          const old = d.chat.filter((x: unknown) => typeof x === 'string');
          setHistory([{ id: 'old', at: Date.now(), chat: old, answers: d.answers, done: walk(old, d.answers).step === null }]);
        }
      })
      .catch(() => {})
      .finally(() => setLoaded(true));
  }, []);
  // This chat goes into History as soon as it has an answer, and stays up to date.
  const [at, setAt] = useState(0);
  const history = useMemo(() => (chat.length ? upsertChat(stored, { id: chatId, at: at || stored.find((c) => c.id === chatId)?.at || 0, chat, answers, done: walk(chat, answers).step === null }) : stored),
    [stored, chat, answers, chatId, at]);
  const setChatNow = (c: string[]) => { setChat(c); setAt(Date.now()); };
  useEffect(() => {
    if (loaded) AsyncStorage.setItem(KEY, JSON.stringify({ answers, history })).catch(() => {});
  }, [answers, history, loaded]);
  // Out-the-door math uses the state of their ZIP code (data/state-costs.ts).
  setHomeState(stateFromZip(answers.zip));
  setPopularZip(answers.zip);
  const value = useMemo(() => ({
    answers, setAnswers, chat, setChat: setChatNow, history, chatId,
    startChat: (goal?: string, car?: { text: string; info?: Partial<Answers> }, likeMine?: boolean) => {
      setHistory(history); setChatId(newId());
      let a = freshAnswers(answers);
      const next: string[] = [];
      if (goal) { next.push(goal); a = applyAnswer(a, 'goal', goal); }
      if (goal === UPGRADE && car?.text) { next.push(car.text); a = applyAnswer(a, 'myCar', car.text, car.info); }
      if (goal === UPGRADE && car?.text && likeMine && a.myCarKind) { next.push(a.myCarKind); a = applyAnswer(a, 'kind', a.myCarKind); }
      setChatNow(next); setAnswers(a);
    },
    openChat: (id: string) => {
      const c = history.find((x) => x.id === id);
      if (!c) return;
      setHistory(history); setChatId(c.id); setChat(c.chat); setAt(c.at); setAnswers({ ...c.answers, zip: c.answers.zip ?? answers.zip });
    },
    deleteChat: (id: string) => {
      setHistory(history.filter((x) => x.id !== id));
      if (id === chatId) { setChatId(newId()); setChat([]); }
    },
  }), [answers, chat, history, chatId]); // eslint-disable-line react-hooks/exhaustive-deps
  return <AnswersCtx.Provider value={value}>{children}</AnswersCtx.Provider>;
}

export function useAnswers() {
  const c = useContext(AnswersCtx);
  if (!c) throw new Error('useAnswers must be inside AnswersProvider');
  return c;
}

export type Match = { car: Car; year: Year; fit: number; used: boolean };

// Simple example matcher. The real coach will use live prices and the Claude API on the server.
// For each car it picks the newest model year that fits the budget (older years cost less).
// With a car loan and a monthly payment, "fits" means our payment estimate is at or under it.
export function topMatches(a: Answers, n = 3): Match[] {
  const out = score(a, true);
  // Too strict (for example "New only" under $15K)? Loosen kind and new/used rather than show nothing.
  return (out.length >= n ? out : score(a, false)).slice(0, n);
}

/** "More good matches" under the top 3 (picture 70 A): the next ones that still fit the answers. */
export function moreMatches(a: Answers, n = 9): Match[] {
  const strict = score(a, true);
  const list = strict.length >= 3 ? strict : score(a, false);
  return list.slice(3, 3 + n).filter((m) => m.fit >= 60);
}

// A car clearly under their plan: payment at most 85% of their monthly cap, or a lower price band than their budget.
function wellUnder(a: Answers, car: Car, year: Year) {
  const p = priceFor(car, year);
  if (!p) return false;
  const cap = monthlyCap(a);
  if (cap) return paymentFor(a, p.amount, p.isNew) <= cap * 0.85;
  const budget = BUDGETS.indexOf(a.budget ?? '');
  return budget >= 0 && bandOf(p.amount) < budget;
}

export type Reason = { ok: boolean; text: string };
/** Why a car fits (or misses) their "Tell me more" answers (picture 123 A). Only facts from our car data; max 3. */
export function moreReasons(a: Answers, car: Car, year: Year): Reason[] {
  const m = a.more ?? {};
  const out: Reason[] = [];
  if (m.fuel === 'Hybrid') out.push(car.green === 'hybrid' ? { ok: true, text: 'Hybrid' } : car.green === 'ev' ? { ok: true, text: 'Electric' } : { ok: false, text: 'Not a hybrid' });
  if (m.fuel === 'Electric') out.push(car.green === 'ev' ? { ok: true, text: 'Electric' } : { ok: false, text: 'Not electric' });
  if (m.snow === 'Yes') {
    const awd = car.features['4x4 / AWD'];
    out.push(awd === 'inc' ? { ok: true, text: 'AWD for snow' } : awd === 'trim' || awd === 'plan' ? { ok: true, text: 'AWD on some versions' } : { ok: false, text: 'No AWD' });
  }
  if (m.parking === 'Yes') {
    if (['Sedan', 'Hatchback'].includes(car.body)) out.push({ ok: true, text: 'Easy to park' });
    else if (['Truck', 'Minivan'].includes(car.body)) out.push({ ok: false, text: 'Big to park' });
  }
  if (m.daily === 'Over 50 miles' && car.green) out.push({ ok: true, text: 'Saves gas on long drives' });
  if (m.daily === 'Under 20 miles' && wellUnder(a, car, year)) out.push({ ok: true, text: 'Lower price for short drives' });
  return out.slice(0, 3);
}

/** Their "Tell me more" answers as short words for the "Picks updated" card. */
export function moreSummary(m: More = {}): string[] {
  return [
    m.fuel && m.fuel !== 'Any' ? m.fuel : '',
    m.daily ? `${m.daily} a day` : '',
    m.snow === 'Yes' ? 'Snow' : '',
    m.parking === 'Yes' ? 'Tight parking' : '',
    m.accidents === 'No accidents' ? 'No accidents' : m.accidents ? 'Fixed accident OK' : '',
    m.skip?.length ? `Skip: ${m.skip.join(', ')}` : '',
  ].filter(Boolean);
}

/** The kinds they want, after the smaller-pick check ('Show both' = theirs too; 'SUVs like mine' = theirs). */
export function wantedKinds(a: Answers): string[] {
  const k = a.kind;
  if (!k || k === ALL_KINDS || !KIND_LABEL[k]) return [];
  const mine = a.myCarKind && KIND_LABEL[a.myCarKind] ? a.myCarKind : undefined;
  if (mine && a.kindCheck === likeMine(a)) return [mine];
  if (mine && a.kindCheck === BOTH) return [k, mine];
  return [k];
}

function score(a: Answers, strict: boolean): Match[] {
  const budget = BUDGETS.indexOf(a.budget ?? '');
  const upgrading = hasCar(a) && !!a.myCar;
  const likeTrax = upgrading && /trax/i.test(a.myCar ?? '');
  const needSeats = a.riders === '6 or more' ? 6 : 1;
  const kinds = wantedKinds(a);
  const kind = kinds.length > 0;
  const isWanted = (car: Car) => kinds.some((k) => carIsKind(car, KIND_LABEL[k]) && (k !== 'SUV (3 rows)' || car.seats >= 7));
  const mySeats = a.myCarSeats ?? 0;
  const myModel = (a.myCar ?? '').toLowerCase();
  const cap = monthlyCap(a);
  const more = a.more ?? {};
  const skipMakes = (more.skip ?? []).map((m) => m.toLowerCase());
  const scored = CARS.map((car) => {
    if (skipMakes.some((m) => car.make.toLowerCase().includes(m))) return null;
    if (strict && kind && !isWanted(car)) return null;
    // Upgrading: only show years newer than the car they have now.
    const myYear = Number((a.myCar ?? '').match(/\b(19|20)\d\d\b/)?.[0]) || 0;
    const all = yearsOf(car);
    let years = (a.current ?? '').startsWith('Yes') && myYear ? all.filter((y) => y > myYear) : all;
    if (strict && a.newUsed === 'New only') years = years.filter((y) => priceFor(car, y)?.isNew);
    if (strict && a.newUsed === 'Used only') years = years.filter((y) => !priceFor(car, y)?.isNew);
    if (!years.length) return null;
    // Budget band for each year, from its price.
    const bandFor = (y: Year) => { const p = priceFor(car, y); return p ? bandOf(p.amount) : BUDGETS.length - 1; };
    const payOf = (y: Year) => { const p = priceFor(car, y); return paymentFor(a, p?.amount ?? 0, p?.isNew ?? false); };
    const fits = (y: Year) => (cap ? payOf(y) <= cap : budget >= 0 ? bandFor(y) <= budget : true);
    let year = years[0];
    if (cap || budget >= 0) {
      const ok = years.filter(fits);
      // newest year that fits; if none fit, the cheapest year
      year = ok.length ? ok[0] : years.reduce((p, y) => ((priceFor(car, y)?.amount ?? bandFor(y)) < (priceFor(car, p)?.amount ?? bandFor(p)) ? y : p), years[0]);
    }
    const band = bandFor(year);
    let s = 60;
    if (a.goal && car.goals.includes(a.goal as Goal)) s += 14;
    if (cap) { const pay = payOf(year); s += pay <= cap ? 12 : -Math.min(30, Math.round(((pay - cap) / cap) * 60)); }
    else if (budget >= 0) s += band === budget ? 12 : band === budget - 1 ? 7 : band < budget ? 0 : -10 * (band - budget);
    if (kind) s += isWanted(car) ? 15 : -30;
    // Upgrading (picture 185): a real step up from THEIR car, not just a newer year.
    if (upgrading && a.myCarKind && !kind) {
      const mine = KIND_LABEL[a.myCarKind];
      if (mine && carIsKind(car, mine) && (a.myCarKind !== 'SUV (3 rows)' || car.seats >= 7)) s += 10;
      if (mySeats && car.seats < mySeats) s -= 12;
    }
    if (upgrading && myModel.includes(car.model.toLowerCase())) s += 4; // same car, newer
    if (car.popular) s += 3;
    // Only count features we have data for. Others are saved, and the dealer checks them.
    for (const m of a.mustHaves) if (MUST_HAVES.includes(m)) s += featureAt(car, year, m) === 'inc' ? 3 : featureAt(car, year, m) ? 1 : -3;
    for (const m of a.wants ?? []) if (featureAt(car, year, m) === 'inc') s += 1;
    if (car.seats < needSeats) s -= 20;
    if (likeTrax && car.likeTrax) s += car.likeTrax;
    // "Tell me more" answers
    if (more.fuel === 'Electric') s += car.green === 'ev' ? 12 : -8;
    if (more.fuel === 'Hybrid') s += car.green === 'hybrid' ? 8 : 0;
    if (more.parking === 'Yes') s += ['Sedan', 'Hatchback'].includes(car.body) ? 4 : ['Truck', 'Minivan'].includes(car.body) ? -6 : 0;
    if (more.snow === 'Yes') s += car.features['4x4 / AWD'] ? 5 : -2;
    if (more.daily === 'Over 50 miles') s += car.green ? 4 : 0;
    // Short drives: gas savings are small, so a lower price matters more than a hybrid or electric.
    if (more.daily === 'Under 20 miles') {
      if (car.green) s -= 3;
      if (wellUnder(a, car, year)) s += 3;
    }
    if (year < LATEST_MODEL_YEAR) s -= 2 * (LATEST_MODEL_YEAR - year); // a newer car is a little better when both fit
    return { car, year, score: s };
  }).filter((x): x is { car: Car; year: Year; score: number } => x !== null);
  scored.sort((x, y) => y.score - x.score);
  if (!scored.length) return [];
  // The best car shows 95%; the others show how far behind it they are.
  const best = scored[0].score;
  return scored.map(({ car, year, score: v }) => ({ car, year, used: !(priceFor(car, year)?.isNew ?? year === LATEST_MODEL_YEAR), fit: Math.max(40, Math.round(95 - (best - v))) }));
}
