// The Home scene: our silver sedan drives through a city.
// The city moves past, the wheels turn, and the sky follows the weather
// (day or night, clear, cloudy, rain, snow or fog). "Reduce motion" keeps it still.
import { LinearGradient } from 'expo-linear-gradient';
import { useEffect, useState } from 'react';
import { AccessibilityInfo, Animated, Easing, Image, StyleSheet, useWindowDimensions, View } from 'react-native';
import Svg, { Defs, Ellipse, LinearGradient as SvgGradient, Polygon, RadialGradient, Stop } from 'react-native-svg';

import { themed } from '@/theme';

import type { Weather } from '@/data/weather';

const SEDAN = require('../../assets/car/sedan.png');
const WHEEL_REAR = require('../../assets/car/wheel-rear.png');
const WHEEL_FRONT = require('../../assets/car/wheel-front.png');

type Look = {
  sky: [string, string, string];
  orb: string | null; orbGlow: string; stars: boolean;
  cloud: string | null; far: string; mids: string[]; tree: string; win: string;
  road: string; curb: string; dash: string; beam: boolean; fall: 'rain' | 'snow' | null; fog: boolean; dim: number;
};

const NIGHT_CITY = { far: '#141B2E', mids: ['#10172A', '#172035', '#131A2D', '#182036'], tree: '#0D1A14', win: 'rgba(227,195,90,0.65)', road: '#14161B', curb: '#2A2D35', dash: '#8A8A8A' };
const DAY_CITY = { far: '#9DB4C8', mids: ['#5E7385', '#4F6476', '#6A7F90', '#56697B'], tree: '#3E7A4A', win: 'rgba(255,255,255,0.35)', road: '#3A3D42', curb: '#B9BEC4', dash: '#FFFFFF' };
const GREY_CITY = { far: '#5A6474', mids: ['#3B4452', '#333B48', '#404958', '#384150'], tree: '#2E4436', win: 'rgba(255,230,150,0.4)', road: '#2B2E33', curb: '#555B64', dash: '#D9D9D9' };

export function lookFor(w: Weather): Look {
  const wet = w.sky === 'rain' || w.sky === 'storm';
  const grey = wet || w.sky === 'cloudy' || w.sky === 'snow' || w.sky === 'fog';
  if (!w.isDay) {
    return {
      sky: grey ? ['#0A0F1C', '#1A2236', '#28324A'] : ['#060A16', '#121C36', '#1E2A4A'],
      orb: grey ? null : '#F4F1DE', orbGlow: 'rgba(244,241,222,0.35)', stars: !grey,
      cloud: grey ? 'rgba(70,82,110,0.8)' : null, ...NIGHT_CITY,
      beam: true, fall: wet ? 'rain' : w.sky === 'snow' ? 'snow' : null, fog: w.sky === 'fog', dim: 0.85,
    };
  }
  if (grey) {
    return {
      sky: wet ? ['#3B4453', '#66707F', '#8C939E'] : ['#6B7A8F', '#9AA7B8', '#C9D2DC'],
      orb: null, orbGlow: '', stars: false, cloud: wet ? 'rgba(52,60,74,0.9)' : 'rgba(235,240,245,0.85)', ...GREY_CITY,
      beam: wet, fall: wet ? 'rain' : w.sky === 'snow' ? 'snow' : null, fog: w.sky === 'fog', dim: 0.95,
    };
  }
  return {
    sky: ['#4E9BDB', '#A9D4F2', '#E6F2FA'], orb: '#FFE680', orbGlow: 'rgba(255,236,150,0.7)', stars: false,
    cloud: 'rgba(255,255,255,0.9)', ...DAY_CITY, beam: false, fall: null, fog: false, dim: 1,
  };
}

// Buildings: [width, height, color index or -1 for a tree]
const FAR = [[30, 56], [22, 96], [38, 70], [18, 106], [44, 62], [26, 84], [34, 48], [24, 100], [40, 60], [28, 78], [38, 52], [20, 88]];
const MID = [[52, 64, 0], [36, 78, 1], [60, 44, 2], [22, 32, -1], [46, 68, 3], [22, 28, -1], [52, 54, 0]];
const DROPS = Array.from({ length: 36 }, (_, k) => ({ x: (k * 53) % 400, y: (k * 37) % 300 }));

function useLoop(ms: number, still: boolean) {
  const [v] = useState(() => new Animated.Value(0));
  useEffect(() => {
    if (still) return;
    const a = Animated.loop(Animated.timing(v, { toValue: 1, duration: ms, easing: Easing.linear, useNativeDriver: true }));
    a.start();
    return () => a.stop();
  }, [v, ms, still]);
  return v;
}

function Building({ w, h, color, win, tree }: { w: number; h: number; color: string; win: string; tree?: boolean }) {
  if (tree) return <View style={{ width: w, height: h, borderTopLeftRadius: 12, borderTopRightRadius: 12, backgroundColor: color }} />;
  const rows = Math.floor((h - 8) / 12);
  const cols = Math.max(1, Math.floor((w - 6) / 10));
  return (
    <View style={{ width: w, height: h, backgroundColor: color, paddingTop: 8, paddingHorizontal: 4, gap: 6 }}>
      {Array.from({ length: rows }, (_, r) => (
        <View key={r} style={{ flexDirection: 'row', gap: 6 }}>
          {Array.from({ length: cols }, (__, c) => <View key={c} style={{ width: 4, height: 6, backgroundColor: win }} />)}
        </View>
      ))}
    </View>
  );
}

export function CityScene({ weather, height = 300, carWidth = 300, children }: { weather: Weather; height?: number; carWidth?: number; children?: React.ReactNode }) {
  const { width } = useWindowDimensions();
  const [still, setStill] = useState(false);
  useEffect(() => { AccessibilityInfo.isReduceMotionEnabled().then(setStill).catch(() => {}); }, []);
  const L = lookFor(weather);
  const far = useLoop(48000, still);
  const mid = useLoop(18000, still);
  const dash = useLoop(380, still);
  const wheel = useLoop(420, still);
  const poles = useLoop(1300, still);
  const bob = useLoop(700, still);
  const fall = useLoop(L.fall === 'snow' ? 2400 : 450, still || !L.fall);
  const cloud = useLoop(80000, still);

  const farW = FAR.reduce((n, b) => n + b[0] + 4, 0);
  const midW = MID.reduce((n, b) => n + b[0] + 10, 0);
  const copies = (unit: number) => Math.ceil(width / unit) + 1;
  const slide = (v: Animated.Value, unit: number) => ({ transform: [{ translateX: v.interpolate({ inputRange: [0, 1], outputRange: [0, -unit] }) }] });
  const spin = { transform: [{ rotate: wheel.interpolate({ inputRange: [0, 1], outputRange: ['0deg', '360deg'] }) }] };
  const carW = Math.min(carWidth, width * 0.74);
  const carH = carW * (179 / 600);
  const carLeft = (width - carW) / 2 - 10;
  const night = L.beam;
  // Headlight position (front of the car, as a share of the car picture).
  const hx = carLeft + carW * 0.974;
  const hy = 12 + carH * 0.5;
  const bobY = { transform: [{ translateY: bob.interpolate({ inputRange: [0, 0.5, 1], outputRange: [0, -1.2, 0] }) }] };
  const pole = night ? '#2E3440' : '#59626E';

  return (
    <View style={{ height, overflow: 'hidden' }}>
      <LinearGradient colors={L.sky} style={StyleSheet.absoluteFill} />
      {!!L.orb && <View style={[s.orb, { backgroundColor: L.orb, shadowColor: L.orb }]} />}
      {L.stars && [[30, 112], [100, 122], [170, 106], [230, 132], [56, 146], [290, 118]].map(([x, y], k) => <View key={k} style={[s.star, { left: x, top: y }]} />)}
      {!!L.cloud && (
        <Animated.View style={[s.row, { top: 108 }, slide(cloud, 400)]}>
          {Array.from({ length: copies(400) }, (_, k) => (
            <View key={k} style={{ width: 400, height: 40 }}>
              <View style={[s.cloud, { left: 20, top: 8, width: 150, height: 30, backgroundColor: L.cloud ?? undefined }]} />
              <View style={[s.cloud, { left: 60, top: -4, width: 70, height: 32, backgroundColor: L.cloud ?? undefined }]} />
              <View style={[s.cloud, { left: 240, top: 18, width: 120, height: 22, backgroundColor: L.cloud ?? undefined }]} />
            </View>
          ))}
        </Animated.View>
      )}
      <Animated.View style={[s.row, { bottom: 62, alignItems: 'flex-end' }, slide(far, farW)]}>
        {Array.from({ length: copies(farW) }, (_, k) => (
          <View key={k} style={{ flexDirection: 'row', alignItems: 'flex-end', gap: 4, paddingRight: 4 }}>
            {FAR.map(([w, h], j) => <View key={j} style={{ width: w, height: h, backgroundColor: L.far }} />)}
          </View>
        ))}
      </Animated.View>
      <Animated.View style={[s.row, { bottom: 62, alignItems: 'flex-end' }, slide(mid, midW)]}>
        {Array.from({ length: copies(midW) }, (_, k) => (
          <View key={k} style={{ flexDirection: 'row', alignItems: 'flex-end', gap: 10, paddingRight: 10 }}>
            {MID.map(([w, h, c], j) => <Building key={j} w={w} h={h} tree={c < 0} color={c < 0 ? L.tree : L.mids[c]} win={L.win} />)}
          </View>
        ))}
      </Animated.View>
      <View style={[s.road, { backgroundColor: L.road }]} />
      <View style={[s.curb, { backgroundColor: L.curb }]} />
      <Animated.View pointerEvents="none" style={[s.row, { bottom: 60, alignItems: 'flex-end' }, slide(poles, 150)]}>
        {Array.from({ length: Math.ceil(width / 150) + 2 }, (_, k) => (
          <View key={k} style={{ width: 150, height: 92 }}>
            <View style={{ position: 'absolute', left: 30, bottom: 0, width: 3, height: 84, backgroundColor: pole }} />
            <View style={{ position: 'absolute', left: 30, top: 6, width: 22, height: 3, backgroundColor: pole }} />
            <View style={{ position: 'absolute', left: 46, top: 7, width: 12, height: 5, borderRadius: 3, backgroundColor: night ? '#FFE9A8' : '#C9CED6' }} />
            {night && <View style={{ position: 'absolute', left: 36, top: 8, width: 32, height: 32, borderRadius: 16, backgroundColor: 'rgba(255,200,90,0.22)' }} />}
          </View>
        ))}
      </Animated.View>
      <Animated.View style={[s.row, { bottom: 20 }, slide(dash, 60)]}>
        {Array.from({ length: Math.ceil(width / 60) + 2 }, (_, k) => <View key={k} style={{ width: 30, height: 3, marginRight: 30, backgroundColor: L.dash }} />)}
      </Animated.View>
      {night && (
        <Svg pointerEvents="none" width={220} height={90} style={{ position: 'absolute', left: hx - 6, bottom: hy - 52 }}>
          <Defs>
            <SvgGradient id="beam" x1="0" y1="0" x2="1" y2="0">
              <Stop offset="0" stopColor="#EAF4FF" stopOpacity="0.75" />
              <Stop offset="1" stopColor="#EAF4FF" stopOpacity="0" />
            </SvgGradient>
            <RadialGradient id="pool" cx="0.5" cy="0.5" r="0.5">
              <Stop offset="0" stopColor="#EAF4FF" stopOpacity="0.35" />
              <Stop offset="1" stopColor="#EAF4FF" stopOpacity="0" />
            </RadialGradient>
          </Defs>
          <Ellipse cx={120} cy={80} rx={95} ry={9} fill="url(#pool)" />
          <Polygon points="0,49 0,55 220,90 220,30" fill="url(#beam)" />
        </Svg>
      )}
      {/* Soft shadow and a faint road reflection so the car sits on the road (picked Oct 10: fix B). */}
      <Svg pointerEvents="none" width={carW} height={30} style={{ position: 'absolute', left: carLeft, bottom: 2 }}>
        <Defs>
          <RadialGradient id="shadow" cx="0.5" cy="0.5" r="0.5">
            <Stop offset="0" stopColor="#000000" stopOpacity="0.6" />
            <Stop offset="1" stopColor="#000000" stopOpacity="0" />
          </RadialGradient>
        </Defs>
        <Ellipse cx={carW * 0.5} cy={15} rx={carW * 0.5} ry={11} fill="url(#shadow)" />
      </Svg>
      <Image source={SEDAN} style={{ position: 'absolute', left: carLeft, bottom: 12 - carH + 2, width: carW, height: carH, opacity: night ? 0.1 : 0.07, transform: [{ scaleY: -1 }] }} />
      <View pointerEvents="none" style={[s.road, { height: 12, bottom: 0, backgroundColor: L.road, opacity: 0.55 }]} />
      {!night && (
        <Svg pointerEvents="none" width={90} height={50} style={{ position: 'absolute', left: hx - 40, bottom: hy - 25 }}>
          <Defs>
            <RadialGradient id="glow" cx="0.5" cy="0.5" r="0.5">
              <Stop offset="0" stopColor="#FFF4D6" stopOpacity="0.45" />
              <Stop offset="1" stopColor="#FFF4D6" stopOpacity="0" />
            </RadialGradient>
          </Defs>
          <Ellipse cx={45} cy={25} rx={45} ry={22} fill="url(#glow)" />
        </Svg>
      )}
      <Animated.View style={[{ position: 'absolute', left: carLeft, bottom: 12, width: carW, height: carH, opacity: L.dim }, bobY]} accessible accessibilityLabel="Our silver electric car driving through the city">
        <Image source={SEDAN} style={{ position: 'absolute', width: carW, height: carH }} />
        <View style={[s.light, { left: carW * 0.8853, top: carH * 0.4825, width: carW * 0.098, opacity: night ? 1 : 0.7 }]} />
        {night && <View style={[s.tail, { left: carW * 0.0262, top: carH * 0.3569, width: carW * 0.0735 }]} />}
        <Animated.Image source={WHEEL_REAR} style={[{ position: 'absolute', left: carW * 0.1276, top: carH * 0.4678, width: carW * 0.1551, height: carW * 0.1551 }, spin]} />
        <Animated.Image source={WHEEL_FRONT} style={[{ position: 'absolute', left: carW * 0.7389, top: carH * 0.4678, width: carW * 0.1551, height: carW * 0.1551 }, spin]} />
      </Animated.View>
      {!!L.fall && (
        <Animated.View pointerEvents="none" style={[StyleSheet.absoluteFill, { transform: [{ translateY: fall.interpolate({ inputRange: [0, 1], outputRange: [-60, 0] }) }] }]}>
          {DROPS.filter((d) => d.x < width).map((d, k) => (
            <View key={k} style={L.fall === 'snow'
              ? { position: 'absolute', left: d.x, top: d.y, width: 4, height: 4, borderRadius: 2, backgroundColor: 'rgba(255,255,255,0.9)' }
              : { position: 'absolute', left: d.x, top: d.y, width: 1.5, height: 16, backgroundColor: 'rgba(220,230,240,0.6)', transform: [{ rotate: '15deg' }] }} />
          ))}
        </Animated.View>
      )}
      {L.fog && <View pointerEvents="none" style={[StyleSheet.absoluteFill, { backgroundColor: 'rgba(230,233,238,0.35)' }]} />}
      {children}
    </View>
  );
}

const s = themed(() => StyleSheet.create({
  row: { position: 'absolute', left: 0, flexDirection: 'row' },
  orb: { position: 'absolute', right: 50, top: 104, width: 30, height: 30, borderRadius: 15, shadowOpacity: 0.9, shadowRadius: 16, shadowOffset: { width: 0, height: 0 } },
  star: { position: 'absolute', width: 2, height: 2, backgroundColor: '#FFFFFF', opacity: 0.8 },
  cloud: { position: 'absolute', borderRadius: 30 },
  road: { position: 'absolute', left: 0, right: 0, bottom: 0, height: 62 },
  light: { position: 'absolute', height: 3, borderRadius: 2, backgroundColor: '#F2F8FF', shadowColor: '#BFE0FF', shadowOpacity: 1, shadowRadius: 6, shadowOffset: { width: 0, height: 0 } },
  tail: { position: 'absolute', height: 2.5, borderRadius: 2, backgroundColor: '#FF4A3A', shadowColor: '#FF2A1A', shadowOpacity: 1, shadowRadius: 6, shadowOffset: { width: 0, height: 0 } },
  curb: { position: 'absolute', left: 0, right: 0, bottom: 60, height: 3 },
}));
