// The second set of home screen widgets (pictures 190–192, Loudjier Nov 5–6, 2026: 'I like them all' + 'Yes').
// Small pieces of data kept on the phone: where you parked, this week's 3 checks, trip miles,
// plus the health score, VIN barcode and countdown math. Nothing here leaves the phone.
import AsyncStorage from '@react-native-async-storage/async-storage';

import type { WidgetCar } from './data';

export const PARK_KEY = 'carvessa:parking:v1';
export const WEEK_KEY = 'carvessa:week-check:v1';
export const TRIPS_KEY = 'carvessa:trips:v1';

const DAY = 86_400_000;

async function readJson<T>(key: string): Promise<T | null> {
  try {
    const raw = await AsyncStorage.getItem(key);
    return raw ? (JSON.parse(raw) as T) : null;
  } catch {
    return null;
  }
}
const writeJson = (key: string, v: unknown) => (v === null ? AsyncStorage.removeItem(key) : AsyncStorage.setItem(key, JSON.stringify(v))).catch(() => {});

// ---- Where did I park? (picture 192) ----
/** acc = how sure the phone was, in meters (big = weak GPS, e.g. in a garage). meterEnd = when the meter runs out. */
export type ParkSpot = { lat: number; lon: number; at: number; acc?: number; note?: string; photo?: string; meterEnd?: number };
export const readPark = () => readJson<ParkSpot>(PARK_KEY);
export const writePark = (p: ParkSpot | null) => writeJson(PARK_KEY, p);
/** GPS this unsure (meters) gets a 'weak signal, add a note' message. */
export const WEAK_GPS = 50;

/** Straight-line miles between two spots. */
export function milesBetween(a: { lat: number; lon: number }, b: { lat: number; lon: number }): number {
  const R = 3958.8, toR = Math.PI / 180;
  const dLat = (b.lat - a.lat) * toR, dLon = (b.lon - a.lon) * toR;
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(a.lat * toR) * Math.cos(b.lat * toR) * Math.sin(dLon / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(h));
}
/** Walking minutes (about): streets add ~30% to a straight line, 3 mph. */
export const walkMinutes = (miles: number) => Math.max(1, Math.round(((miles * 1.3) / 3) * 60));

export type Travel = 'walk' | 'drive' | 'transit';
export type MapApp = 'google' | 'waze' | 'apple' | 'other';
/** The link that opens a map app with directions to the car. Waze only drives. */
export function directionsUrl(app: MapApp, travel: Travel, to: { lat: number; lon: number }): string {
  const ll = `${to.lat.toFixed(6)},${to.lon.toFixed(6)}`;
  if (app === 'waze') return `https://waze.com/ul?ll=${ll}&navigate=yes`;
  if (app === 'apple') return `http://maps.apple.com/?daddr=${ll}&dirflg=${travel === 'walk' ? 'w' : travel === 'transit' ? 'r' : 'd'}`;
  if (app === 'other') return `geo:${ll}?q=${ll}(My%20car)`;
  const mode = travel === 'walk' ? 'walking' : travel === 'transit' ? 'transit' : 'driving';
  return `https://www.google.com/maps/dir/?api=1&destination=${ll}&travelmode=${mode}`;
}

/** "2 h ago", "Just now". */
export function agoText(at: number, now: number): string {
  const m = Math.max(0, Math.round((now - at) / 60000));
  if (m < 2) return 'Just now';
  if (m < 60) return `${m} min ago`;
  const h = Math.round(m / 60);
  if (h < 24) return `${h} h ago`;
  const d = Math.round(h / 24);
  return d === 1 ? 'Yesterday' : `${d} days ago`;
}
/** "18 min" left on the meter, "Ended" or null when there's no meter. */
export function meterText(p: ParkSpot | null, now: number): string | null {
  if (!p?.meterEnd) return null;
  const m = Math.ceil((p.meterEnd - now) / 60000);
  if (m <= 0) return 'Meter ended';
  return m >= 60 ? `Meter ends in ${Math.floor(m / 60)} h ${m % 60} min` : `Meter ends in ${m} min`;
}

// ---- 2-minute weekly check (X) ----
export type Week = { week: string; ticks: boolean[]; streak: number; lastDone?: string };
export const WEEK_CHECKS = ['Tire pressure', 'Lights and signals', 'Washer fluid'];
/** Monday-based week name, e.g. "2026-11-02". */
export function weekOf(now: number): string {
  const d = new Date(now);
  const day = (d.getDay() + 6) % 7;
  const mon = new Date(d.getFullYear(), d.getMonth(), d.getDate() - day);
  return `${mon.getFullYear()}-${String(mon.getMonth() + 1).padStart(2, '0')}-${String(mon.getDate()).padStart(2, '0')}`;
}
const prevWeek = (w: string) => { const [y, m, d] = w.split('-').map(Number); return weekOf(new Date(y, m - 1, d - 7).getTime()); };
/** This week's state: a new week starts empty; the streak breaks if last week wasn't finished. */
export function weekNow(w: Week | null, now: number): Week {
  const wk = weekOf(now);
  if (w && w.week === wk) return w;
  const keep = w && (w.lastDone === prevWeek(wk) || w.lastDone === wk);
  return { week: wk, ticks: WEEK_CHECKS.map(() => false), streak: keep ? w!.streak : 0, lastDone: w?.lastDone };
}
/** Tick (or untick) one check. Finishing all three adds one week to the streak, once. */
export function tickWeek(w: Week | null, i: number, now: number): Week {
  const cur = weekNow(w, now);
  const ticks = cur.ticks.map((t, k) => (k === i ? !t : t));
  const done = ticks.every(Boolean);
  if (done && cur.lastDone !== cur.week) return { ...cur, ticks, streak: cur.streak + 1, lastDone: cur.week };
  return { ...cur, ticks };
}
export const readWeek = async (now: number) => weekNow(await readJson<Week>(WEEK_KEY), now);
export const writeWeek = (w: Week) => writeJson(WEEK_KEY, w);

// ---- App driver day (Y) ----
export type Trip = { at: number; miles: number; app?: string };
export const readTrips = async () => (await readJson<Trip[]>(TRIPS_KEY)) ?? [];
export const writeTrips = (t: Trip[]) => writeJson(TRIPS_KEY, t.slice(-500));
/** The IRS standard mileage rate we use for the write-off estimate (business use, 2025: 70¢ a mile). */
export const IRS_RATE = { year: 2025, perMile: 0.7 };
const sameDay = (a: number, b: number) => new Date(a).toDateString() === new Date(b).toDateString();
export function milesToday(trips: Trip[], now: number) {
  return Math.round(trips.filter((t) => sameDay(t.at, now)).reduce((n, t) => n + t.miles, 0) * 10) / 10;
}
export function milesThisMonth(trips: Trip[], now: number) {
  const d = new Date(now);
  return Math.round(trips.filter((t) => { const x = new Date(t.at); return x.getFullYear() === d.getFullYear() && x.getMonth() === d.getMonth(); })
    .reduce((n, t) => n + t.miles, 0) * 10) / 10;
}
export const writeOff = (miles: number) => Math.round(miles * IRS_RATE.perMile);

// ---- Car health score (L) ----
export type HealthItem = { text: string; tone: 'ok' | 'warn' | 'bad' };
/** Our own 0–100 score (not a mechanic's check): open recalls, oil, tag renewal, and cold weather tires. */
export function healthOf(car: WidgetCar, tempF?: number): { score: number; word: string; items: HealthItem[] } {
  let score = 100;
  const items: HealthItem[] = [];
  if (car.recalls === null) items.push({ text: 'Recalls: checking', tone: 'warn' });
  else if (car.recalls === 0) items.push({ text: 'No recalls', tone: 'ok' });
  else { score -= Math.min(40, 25 * car.recalls); items.push({ text: car.recalls === 1 ? '1 open recall' : `${car.recalls} open recalls`, tone: 'bad' }); }
  if (car.oilIn !== null) {
    if (car.oilIn < 100) { score -= 20; items.push({ text: 'Oil change due', tone: 'bad' }); }
    else if (car.oilIn <= 500) { score -= 8; items.push({ text: `Oil in ${car.oilIn.toLocaleString('en-US')} mi`, tone: 'warn' }); }
    else if (car.oilIn <= 1500) { score -= 3; items.push({ text: `Oil in ${car.oilIn.toLocaleString('en-US')} mi`, tone: 'warn' }); }
    else items.push({ text: 'Oil is fine', tone: 'ok' });
  }
  if (car.regDays !== undefined) {
    if (car.regDays < 0) { score -= 20; items.push({ text: 'Tag renewal late', tone: 'bad' }); }
    else if (car.regDays <= 30) { score -= 6; items.push({ text: `Tag in ${car.regDays} days`, tone: 'warn' }); }
    else items.push({ text: `Tag ${car.regDue}`, tone: 'ok' });
  }
  if (tempF !== undefined && tempF <= 40) { score -= 2; items.push({ text: 'Cold: check tires', tone: 'warn' }); }
  score = Math.max(0, Math.min(100, Math.round(score)));
  return { score, word: score >= 90 ? 'Looking good' : score >= 70 ? 'A few things' : 'Needs you', items: items.slice(0, 4) };
}

// ---- Car pass (Q): the VIN as a Code 39 barcode, the kind shops and parts stores scan ----
const C39: Record<string, string> = {
  '0': 'nnnwwnwnn', '1': 'wnnwnnnnw', '2': 'nnwwnnnnw', '3': 'wnwwnnnnn', '4': 'nnnwwnnnw', '5': 'wnnwwnnnn', '6': 'nnwwwnnnn', '7': 'nnnwnnwnw', '8': 'wnnwnnwnn', '9': 'nnwwnnwnn',
  A: 'wnnnnwnnw', B: 'nnwnnwnnw', C: 'wnwnnwnnn', D: 'nnnnwwnnw', E: 'wnnnwwnnn', F: 'nnwnwwnnn', G: 'nnnnnwwnw', H: 'wnnnnwwnn', I: 'nnwnnwwnn', J: 'nnnnwwwnn',
  K: 'wnnnnnnww', L: 'nnwnnnnww', M: 'wnwnnnnwn', N: 'nnnnwnnww', O: 'wnnnwnnwn', P: 'nnwnwnnwn', Q: 'nnnnnnwww', R: 'wnnnnnwwn', S: 'nnwnnnwwn', T: 'nnnnwnwwn',
  U: 'wwnnnnnnw', V: 'nwwnnnnnw', W: 'wwwnnnnnn', X: 'nwnnwnnnw', Y: 'wwnnwnnnn', Z: 'nwwnwnnnn', '-': 'nwnnnnwnw', '.': 'wwnnnnwnn', ' ': 'nwwnnnwnn', '*': 'nwnnwnwnn',
};
/** Bars and gaps for a Code 39 barcode: [width, isBar][], narrow = 1, wide = 3. Null for letters Code 39 can't hold. */
export function code39(text: string): [number, boolean][] | null {
  const s = `*${text.toUpperCase()}*`;
  const out: [number, boolean][] = [];
  for (let i = 0; i < s.length; i++) {
    const p = C39[s[i]];
    if (!p) return null;
    for (let k = 0; k < 9; k++) out.push([p[k] === 'w' ? 3 : 1, k % 2 === 0]);
    if (i < s.length - 1) out.push([1, false]);
  }
  return out;
}
/** The barcode as an svg string (black bars on white), for the widget and the Car pass screen. */
export function code39Svg(text: string, height = 40): string | null {
  const bars = code39(text);
  if (!bars) return null;
  const quiet = 10;
  let x = quiet, rects = '';
  for (const [w, bar] of bars) { if (bar) rects += `<rect x="${x}" y="0" width="${w}" height="${height}"/>`; x += w; }
  const W = x + quiet;
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${height}" preserveAspectRatio="none"><rect width="${W}" height="${height}" fill="#fff"/><g fill="#0F1A2A">${rects}</g></svg>`;
}
/** "3GNCJ…4821": first 5 and last 4 of a VIN. */
export const vinShort = (v?: string) => (v && v.length >= 11 ? `${v.slice(0, 5)}…${v.slice(-4)}` : v ?? '');

// ---- Countdowns (N) ----
/** "1/12/2027" (how My car keeps the tag date) → a Date, else null. */
export function parseUsDate(t?: string): Date | null {
  const m = t?.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (!m) return null;
  const d = new Date(Number(m[3]), Number(m[1]) - 1, Number(m[2]));
  return isNaN(d.getTime()) ? null : d;
}
/** Whole days from today to that date (0 = today, below 0 = late). */
export function daysUntil(d: Date, now: number): number {
  const a = new Date(now); const t = new Date(a.getFullYear(), a.getMonth(), a.getDate()).getTime();
  return Math.round((new Date(d.getFullYear(), d.getMonth(), d.getDate()).getTime() - t) / DAY);
}
/** "1.2K" for big counts, else the number. */
export const shortNum = (n: number) => (Math.abs(n) >= 1000 ? `${(Math.round(n / 100) / 10).toString()}K` : String(Math.round(n)));
