// Car trouble? (picture 191 U, Loudjier Nov 6, 2026: 'Yes'). The SOS widget's buttons open this screen:
// ?go=call (add your roadside number), share (send my spot), tow (tow trucks near me), steps (stay safe).
// Free for everyone, always. 911 comes first when anyone is hurt.
import { router, useLocalSearchParams } from 'expo-router';
import { useEffect, useRef, useState } from 'react';
import { Linking, Platform, ScrollView, Share, StyleSheet, TextInput, View } from 'react-native';

import { AccountTop, BigBtn, Card, Sec } from '@/components/account-ui';
import { Text } from '@/components/t';
import { Body } from '@/components/ui';
import { tr } from '@/i18n';
import { lastSpot, locateExact } from '@/lib/location';
import { useSaved } from '@/state/saved';
import { C, F, PAD, themed } from '@/theme';
import { readSnap } from '@/widgets/data';
import { redrawWidgets } from '@/widgets/sync';

const STEPS = [
  'Turn on your hazard lights.',
  'If the car still moves, get it off the road: a shoulder, a parking lot or a side street.',
  'On a busy road or highway, it’s usually safer to stay in the car with your seat belt on.',
  'If you must get out, use the side away from traffic and stand well off the road.',
  'Call roadside help. Call 911 if anyone is hurt, the car is in a dangerous spot, or you smell gas or see smoke.',
];

export const mapsNear = (q: string) => {
  const sp = lastSpot();
  if (Platform.OS === 'ios') return `http://maps.apple.com/?q=${encodeURIComponent(q)}${sp ? `&sll=${sp.lat},${sp.lon}` : ''}`;
  return sp ? `https://www.google.com/maps/search/${encodeURIComponent(q)}/@${sp.lat},${sp.lon},13z` : `https://www.google.com/maps/search/${encodeURIComponent(q)}`;
};
const telOf = (n: string) => `tel:${n.replace(/[^\d+]/g, '')}`;

export default function Sos() {
  const { go } = useLocalSearchParams<{ go?: string }>();
  const { myCar, setMyCar } = useSaved();
  const [num, setNum] = useState(myCar?.roadside ?? '');
  const [msg, setMsg] = useState('');
  const done = useRef('');

  async function shareSpot() {
    setMsg('Finding where you are…');
    const r = await locateExact();
    if (!r.ok) { setMsg(r.why === 'denied' ? 'Allow location for Carvessa in your phone settings to send your spot.' : 'We couldn’t find where you are. Try again.'); return; }
    setMsg('');
    Share.share({ message: `${tr('My car broke down. I’m here:')} https://www.google.com/maps/search/?api=1&query=${r.lat.toFixed(6)},${r.lon.toFixed(6)}` }).catch(() => {});
  }
  // The widget button they tapped happens right away (once per tap).
  useEffect(() => {
    if (!go || done.current === go) return;
    done.current = go;
    if (go === 'share') Promise.resolve().then(shareSpot);
    if (go === 'tow') Linking.openURL(mapsNear('tow truck')).catch(() => {});
  }, [go]); // eslint-disable-line react-hooks/exhaustive-deps

  const saveNum = () => {
    if (!myCar) return;
    setMyCar({ ...myCar, roadside: num.trim() || undefined });
    readSnap().then(redrawWidgets).catch(() => {});
    setMsg(num.trim() ? 'Saved. The widget’s “Call roadside” now calls this number.' : '');
  };
  const back = () => (router.canGoBack() ? router.back() : router.navigate('/garage'));

  return (
    <View style={{ flex: 1, backgroundColor: C.bg }}>
      <AccountTop title="Car trouble" back={back} />
      <ScrollView contentContainerStyle={{ paddingHorizontal: PAD - 6, paddingBottom: 40 }} keyboardShouldPersistTaps="handled">
        <Card style={s.hurt}>
          <Text style={s.hurtT}>{tr('Is anyone hurt, or are you in danger?')}</Text>
          <BigBtn kind="danger" label="Call 911" onPress={() => Linking.openURL('tel:911').catch(() => {})} />
        </Card>

        <Sec>Roadside help</Sec>
        <Card style={{ padding: 14, gap: 10 }}>
          {myCar?.roadside ? <BigBtn label={`${tr('Call roadside')} · ${myCar.roadside}`} onPress={() => Linking.openURL(telOf(myCar.roadside!)).catch(() => {})} /> : null}
          <Body style={{ color: C.muted }}>Your roadside number is on your insurance card or app (also on many car club cards).</Body>
          <TextInput value={num} onChangeText={setNum} onEndEditing={saveNum} keyboardType="phone-pad" placeholder={tr('Roadside phone number')} placeholderTextColor={C.muted}
            autoFocus={go === 'call' && !myCar?.roadside} style={s.input} accessibilityLabel={tr('Roadside phone number')} />
          {myCar ? <BigBtn kind="soft" label="Save number" onPress={saveNum} /> : <Body>Add your car in My Garage first.</Body>}
        </Card>

        <Sec>Get help here</Sec>
        <View style={{ gap: 10 }}>
          <BigBtn kind="soft" label="Send my spot to family" onPress={shareSpot} />
          <BigBtn kind="soft" label="Tow trucks near me" onPress={() => Linking.openURL(mapsNear('tow truck')).catch(() => {})} />
        </View>

        <Sec>Stay safe</Sec>
        <Card style={{ padding: 14, gap: 8 }}>
          {STEPS.map((t, i) => (
            <View key={i} style={{ flexDirection: 'row', gap: 10 }}>
              <Text style={s.num}>{i + 1}</Text>
              <Body style={{ flex: 1 }}>{t}</Body>
            </View>
          ))}
        </Card>
        {msg ? <Body style={{ marginTop: 12 }}>{tr(msg)}</Body> : null}
      </ScrollView>
    </View>
  );
}

const s = themed(() => StyleSheet.create({
  hurt: { padding: 14, gap: 10, marginTop: 10 },
  hurtT: { fontFamily: F.bodyBold, fontSize: 17, color: C.ink },
  input: { borderWidth: 1, borderColor: C.line, borderRadius: 14, paddingHorizontal: 12, paddingVertical: 10, fontFamily: F.body, fontSize: 16, color: C.ink, backgroundColor: C.bg },
  num: { fontFamily: F.bodyBold, fontSize: 15, color: C.onAccent, width: 18 },
}));
