// Versions (trims) from the car guide, so people can search for one and find it for sale
// (Loudjier Oct 21, 2026: "Make version choices available to search and to buy").
import { GUIDE } from '@/data/guide';

/** "Sport Touring · ST" → ["Sport Touring", "ST"]; "Hybrid (Blue · SEL · Limited)" → ["Hybrid", "Blue", "SEL", "Limited"]. */
export const trimParts = (name: string) => name.split(/[·(),/]/).map((p) => p.trim()).filter(Boolean);
export const trimNames = (carId: string) => (GUIDE[carId]?.trims ?? []).map((t) => t.name);

const words = (s: string) => ` ${s.toLowerCase().replace(/[^a-z0-9.+-]+/g, ' ').trim()} `;
/** Does a dealer's trim ("XLE Premium AWD") match a guide version ("XLE · XLE Premium")? Whole words only. */
// "Hybrid (LE · XLE · SE)" needs the word Hybrid too, so a gas LE doesn't count.
export function trimMatches(listingTrim: string | null | undefined, name: string) {
  const t = words(listingTrim ?? '');
  const has = (p: string) => t.includes(words(p));
  const group = name.match(/^(.+?)\s*\((.+)\)$/);
  if (group) return has(group[1]) && trimParts(group[2]).some(has);
  return trimParts(name).some(has);
}
