// made up; safety first; when it depends on the car we point to the owner's manual, the door sticker or a shop;
// costs say estimate; it ends with "We can be wrong. Check with a mechanic."
// An answer can jump to another chat: next '@weird:<id>' or '@light:<id>'.
import type { Recall } from '@/data/gov';
import type { Flow } from '@/data/light-help';

// Which real NHTSA recalls (on their model year) belong to each problem. parts = NHTSA main part, words = details,
// risk = the recall's own "consequence" text (e.g. a fire risk for a burning smell).
type Rule = { parts?: string[]; words?: RegExp; risk?: RegExp };
export const SYMPTOM_RECALLS: Record<string, Rule> = {
  // Brake noise and shaking come from pads, rotors and calipers; a brake booster ('POWER ASSIST') recall is not about them.
  'shake-brake': { words: /ROTOR|DISC|CALIPER|PAD|LINING|FOUNDATION/ },
  'shake-speed': { parts: ['TIRES', 'WHEELS'], words: /AXLE|DRIVESHAFT|HALF SHAFT/ },
  squeak: { words: /ROTOR|DISC|CALIPER|PAD|LINING|FOUNDATION/ },
  grind: { words: /ROTOR|DISC|CALIPER|PAD|LINING|FOUNDATION/ },
  pull: { parts: ['TIRES', 'WHEELS'], words: /ALIGNMENT|TIE ROD|CONTROL ARM|BALL JOINT|LINKAGE/ },
  'wont-start': { words: /STARTER|BATTERY|IGNITION SWITCH|FUEL PUMP/ },
  burning: { risk: /\bFIRE\b/ },
  sweet: { words: /COOLANT|COOLING SYSTEM|RADIATOR|HEATER CORE|WATER PUMP/ },
  leak: { words: /LEAK|FUEL TANK|FUEL LINE|COOLANT|OIL PAN|DRAIN PLUG/, risk: /\bLEAK/ },
  clunk: { parts: ['SUSPENSION'], words: /TIE ROD|BALL JOINT|LINKAGE|STABILIZER|SWAY BAR/ },
  hot: { words: /COOLANT|COOLING SYSTEM|RADIATOR|WATER PUMP|THERMOSTAT|COOLING FAN/ },
  'noise-turn': { words: /AXLE|CV JOINT|DRIVESHAFT|HALF SHAFT/ },
  gascap: { words: /FUEL (FILLER|DOOR|CAP)|FILLER (CAP|NECK|DOOR)|EVAP|PURGE/ },
};
export function symptomRecall(id: string, r: Pick<Recall, 'part' | 'risk'>): boolean {
  const rule = SYMPTOM_RECALLS[id];
  if (!rule) return false;
  const up = r.part.toUpperCase();
  const main = up.split(':')[0].trim();
  const detail = up.split(':').slice(1).join(':');
  return (rule.parts ?? []).some((p) => main === p || main.startsWith(`${p},`) || main.startsWith(`${p} (`))
    || !!rule.words?.test(detail) || !!rule.risk?.test(r.risk.toUpperCase());
}

