// Owner reviews on the car page (picture 9, Oct 10, 2026): stars summary, sorting, reviews,
// "Helpful", "Report", and "Write a review" for members. Guests are asked to join first.
import { useCallback, useEffect, useState } from 'react';
import { ActivityIndicator, Modal, StyleSheet, View } from 'react-native';

import { notify } from '@/components/notify';
import { Body, Btn, H, Label, tap } from '@/components/ui';
import { ago, deleteMyReview, getReviews, postReview, reportReview, Review, REVIEW_TAGS, Sort, summary, voteHelpful } from '@/data/reviews';
import { useAuth } from '@/state/auth';
import { C, F, themed } from '@/theme';
import { KeyboardSheet } from '@/components/keyboard-sheet';
import { Pressable, Text, TextInput } from '@/components/t';

const SORTS: { key: Sort; label: string }[] = [{ key: 'helpful', label: 'Most helpful' }, { key: 'newest', label: 'Newest' }, { key: 'lowest', label: 'Lowest' }];
const stars = (n: number) => '★★★★★'.slice(0, Math.round(n)) + '☆☆☆☆☆'.slice(0, 5 - Math.round(n));

function Pill({ label, on, onPress }: { label: string; on: boolean; onPress: () => void }) {
  return (
    <Pressable onPress={() => { tap(); onPress(); }} accessibilityRole="button" accessibilityState={{ selected: on }}
      style={[s.pill, on && { backgroundColor: C.fill, borderColor: C.fill }]}>
      <Text style={[s.pillText, on && { color: C.onAccent }]}>{label}</Text>
    </Pressable>
  );
}

function WriteSheet({ carId, carName, years, onClose, onPosted }: { carId: string; carName: string; years: number[]; onClose: () => void; onPosted: () => void }) {
  const { name } = useAuth();
  const [n, setN] = useState(0);
  const [year, setYear] = useState<number | null>(null);
  const [tags, setTags] = useState<string[]>([]);
  const [body, setBody] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const post = async () => {
    setError(null);
    if (!n) return setError('Tap the stars to rate it.');
    if (body.trim().length < 10) return setError('Write at least a short sentence (10 letters or more).');
    setBusy(true);
    const err = await postReview({ car_id: carId, display_name: name || 'Member', stars: n, owned_year: year, tags, body: body.trim() });
    setBusy(false);
    if (err) return setError(err);
    notify('Thank you!', 'Your review is posted. It helps other drivers.');
    onPosted(); onClose();
  };
  return (
    <Modal transparent animationType="slide" visible onRequestClose={onClose}>
      <KeyboardSheet onClose={onClose} backStyle={s.back} sheetStyle={[s.sheet, { gap: 10, paddingBottom: 30 }]}>
          <View style={s.grab} />
          <H size={26}>Review your {carName}</H>
          <Body style={{ fontSize: 13, color: C.muted }}>Members only. Be kind and honest. Posting as {name || 'Member'}.</Body>
          <View style={{ flexDirection: 'row', gap: 6 }} accessibilityRole="adjustable" accessibilityLabel={`${n} of 5 stars`}>
            {[1, 2, 3, 4, 5].map((k) => (
              <Pressable key={k} onPress={() => { tap(); setN(k); }} accessibilityRole="button" accessibilityLabel={`${k} star${k === 1 ? '' : 's'}`} hitSlop={4}>
                <Text style={{ fontSize: 38, color: k <= n ? C.yellow : C.line }}>★</Text>
              </Pressable>
            ))}
          </View>
          <Label>Which year do you own?</Label>
          <View style={s.wrap}>
            {years.slice(0, 4).map((y) => <Pill key={y} label={String(y)} on={year === y} onPress={() => setYear(year === y ? null : y)} />)}
            <Pill label="Older" on={year === 0} onPress={() => setYear(year === 0 ? null : 0)} />
          </View>
          <Label>Quick tags</Label>
          <View style={s.wrap}>
            {REVIEW_TAGS.map((t) => <Pill key={t} label={t} on={tags.includes(t)} onPress={() => setTags(tags.includes(t) ? tags.filter((x) => x !== t) : [...tags, t])} />)}
          </View>
          <TextInput value={body} onChangeText={setBody} multiline maxLength={1500} placeholder="Tell others what you like and don’t like…" placeholderTextColor={C.muted}
            style={s.text} accessibilityLabel="Your review" />
          {!!error && <Text style={s.error}>{error}</Text>}
          {busy ? <ActivityIndicator color={C.yellow} style={{ height: 56 }} /> : <Btn kind="yellow" label="Post review" onPress={post} />}
      </KeyboardSheet>
    </Modal>
  );
}

export function OwnerReviews({ carId, carName, years }: { carId: string; carName: string; years: number[] }) {
  const { session, openSignIn } = useAuth();
  const [sort, setSort] = useState<Sort>('helpful');
  const [list, setList] = useState<Review[] | null>(null);
  const [failed, setFailed] = useState(false);
  const [writing, setWriting] = useState(false);
  const [tick, setTick] = useState(0);
  const reload = useCallback(() => setTick((t) => t + 1), []);

  useEffect(() => {
    let on = true;
    getReviews(carId, sort).then((r) => { if (on) { setList(r); setFailed(false); } }).catch(() => { if (on) setFailed(true); });
    return () => { on = false; };
  }, [carId, sort, tick]);

  const needAccount = (why: string, then: () => void) => (session ? then() : openSignIn(why));
  const sum = summary(list ?? []);
  const mine = list?.find((r) => r.user_id === session?.user.id);

  return (
    <View style={{ marginTop: 16, gap: 10 }}>
      <H size={26}>Owner reviews</H>
      {failed ? <Body style={{ color: C.muted }}>Can’t load reviews right now. Check your internet.</Body>
        : !list ? <ActivityIndicator color={C.yellow} style={{ alignSelf: 'flex-start' }} />
        : (
          <>
            {sum.n > 0 ? (
              <View style={s.hero}>
                <View style={{ alignItems: 'center' }}>
                  <H size={46}>{sum.avg.toFixed(1)}</H>
                  <Text style={s.stars}>{stars(sum.avg)}</Text>
                  <Body style={{ fontSize: 12, color: C.muted }}>{sum.n} owner{sum.n === 1 ? '' : 's'}</Body>
                </View>
                <View style={{ flex: 1, gap: 5 }}>
                  {sum.by.map((b) => (
                    <View key={b.k} style={{ flexDirection: 'row', alignItems: 'center', gap: 6 }}>
                      <Body style={{ fontSize: 12, width: 10 }}>{b.k}</Body>
                      <View style={s.bar}><View style={{ width: `${b.pct}%`, height: '100%', backgroundColor: C.yellow }} /></View>
                    </View>
                  ))}
                </View>
              </View>
            ) : <Body style={{ color: C.muted }}>No reviews yet. Own one? Be the first to help other drivers.</Body>}
            {sum.n > 1 && <View style={s.wrap}>{SORTS.map((x) => <Pill key={x.key} label={x.label} on={sort === x.key} onPress={() => setSort(x.key)} />)}</View>}
            {list.map((r) => (
              <View key={r.id} style={s.card}>
                <View style={{ flexDirection: 'row', justifyContent: 'space-between' }}>
                  <Body bold>{r.display_name}</Body>
                  <Text style={s.stars}>{stars(r.stars)}</Text>
                </View>
                <Body style={{ fontSize: 12, color: C.muted }}>
                  {r.owned_year ? `Owns a ${r.owned_year} · ` : r.owned_year === 0 ? 'Owns an older one · ' : ''}{ago(r.created_at)}
                </Body>
                {r.tags.length > 0 && <View style={[s.wrap, { marginTop: 2 }]}>{r.tags.map((t) => <View key={t} style={s.tag}><Text style={s.tagText}>{t}</Text></View>)}</View>}
                <Body style={{ fontSize: 14.5, marginTop: 2 }}>{r.body}</Body>
                <View style={{ flexDirection: 'row', gap: 16, marginTop: 4 }}>
                  <Pressable hitSlop={8} accessibilityRole="button" onPress={() => needAccount('Join free to vote on reviews.', async () => { if (await voteHelpful(r.id)) reload(); })}>
                    <Body style={{ fontSize: 12.5, color: C.muted }}>Helpful ({r.helpful})</Body>
                  </Pressable>
                  {r.user_id === session?.user.id ? (
                    <Pressable hitSlop={8} accessibilityRole="button" onPress={async () => { await deleteMyReview(r.id); reload(); }}>
                      <Body style={{ fontSize: 12.5, color: C.muted, textDecorationLine: 'underline' }}>Delete my review</Body>
                    </Pressable>
                  ) : (
                    <Pressable hitSlop={8} accessibilityRole="button" onPress={() => needAccount('Join free to report a review.', async () => { await reportReview(r.id); notify('Thanks for telling us', 'We’ll take a look at this review.'); })}>
                      <Body style={{ fontSize: 12.5, color: C.muted, textDecorationLine: 'underline' }}>Report</Body>
                    </Pressable>
                  )}
                </View>
              </View>
            ))}
            {!mine && <Btn kind="yellow" label="Write a review" onPress={() => needAccount('Join free to write a review. It takes 30 seconds.', () => setWriting(true))} />}
          </>
        )}
      <View style={s.soon}>
        <Label style={{ color: C.yellow }}>Expert reviews</Label>
        <Body style={{ fontSize: 13, color: C.muted }}>Short quotes from car experts are coming soon.</Body>
      </View>
      {writing && <WriteSheet carId={carId} carName={carName} years={years} onClose={() => setWriting(false)} onPosted={reload} />}
    </View>
  );
}

const s = themed(() => StyleSheet.create({
  hero: { flexDirection: 'row', gap: 16, alignItems: 'center', backgroundColor: C.hero, borderRadius: 16, padding: 14 },
  stars: { color: C.yellow, fontSize: 15, letterSpacing: 1 },
  bar: { flex: 1, height: 6, borderRadius: 3, backgroundColor: C.line, overflow: 'hidden' },
  wrap: { flexDirection: 'row', flexWrap: 'wrap', gap: 6 },
  pill: { borderRadius: 20, borderWidth: 1, borderColor: C.line, backgroundColor: C.card, paddingHorizontal: 12, paddingVertical: 7 },
  pillText: { fontFamily: F.bodyBold, fontSize: 13, color: C.ink },
  card: { backgroundColor: C.card, borderWidth: 1, borderColor: C.line, borderRadius: 16, padding: 14, gap: 3 },
  tag: { borderRadius: 12, backgroundColor: C.accentSoft, paddingHorizontal: 8, paddingVertical: 2 },
  tagText: { fontFamily: F.bodyBold, fontSize: 11.5, color: C.yellow },
  soon: { borderRadius: 14, borderWidth: 1, borderStyle: 'dashed', borderColor: C.line, padding: 12, marginTop: 4 },
  back: { flex: 1, backgroundColor: 'rgba(0,0,0,0.6)' },
  sheet: { maxHeight: '88%', backgroundColor: C.card, borderTopLeftRadius: 22, borderTopRightRadius: 22, borderTopWidth: 1, borderColor: C.line, padding: 20 },
  grab: { width: 40, height: 5, borderRadius: 3, backgroundColor: C.line, alignSelf: 'center' },
  text: { minHeight: 110, borderRadius: 12, borderWidth: 1, borderColor: C.line, backgroundColor: C.bg, padding: 12, fontFamily: F.body, fontSize: 15.5, color: C.ink, textAlignVertical: 'top' },
  error: { fontFamily: F.bodyBold, fontSize: 13.5, color: C.red },
}));
