// Popular in Atlanta, the full Top 10 (pictures 256 A + 257 + 258, Loudjier Nov 17, 2026). The spotlight stage on
// top, the rest of the list below, and the filters floating at the bottom where the thumb reaches (picture 255).
import { LinearGradient } from 'expo-linear-gradient';
import { router } from 'expo-router';
import { useMemo, useState } from 'react';
import { ScrollView, StyleSheet, useWindowDimensions, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

import { BackIcon } from '@/components/icons';
import { LOOKS, PopularRow, PopularStage, payOf, usePopular, useStageMode } from '@/components/popular-stage';
import { Pressable, Text } from '@/components/t';
import { tap } from '@/components/ui';
import { CARS, type Car } from '@/data/cars';
import { monthlyCap, useAnswers } from '@/state/answers';

type F = 'all' | 'plan' | 'suv' | 'hybrid' | 'apps';
const carOf = (id: string) => CARS.find((c) => c.id === id) as Car;

export default function Popular() {
  const { width } = useWindowDimensions();
  const { answers } = useAnswers();
  const list = usePopular();
  const { mode } = useStageMode();
  const L = LOOKS[mode];
  const cap = monthlyCap(answers);
  const [f, setF] = useState<F>('all');
  const shown = useMemo(() => list.cars.filter((p) => {
    const c = carOf(p.id);
    if (f === 'plan') return !!cap && payOf(answers, c).pay <= cap;
    if (f === 'suv') return c.body === 'SUV';
    if (f === 'hybrid') return !!c.green;
    if (f === 'apps') return c.goals.includes('Drive for apps');
    return true;
  }), [list, f, cap, answers]);
  const chips: [F, string][] = [['all', 'All'], ...(cap ? [['plan', 'Fits my plan'] as [F, string]] : []), ['suv', 'SUV'], ['hybrid', 'Hybrid'], ['apps', 'App drivers']];
  const night = mode === 'night';
  return (
    <View style={{ flex: 1, backgroundColor: L.bg[2] }}>
      <LinearGradient colors={L.bg} style={StyleSheet.absoluteFill} />
      <SafeAreaView edges={['top']} style={{ flex: 1 }}>
        <View style={s.top}>
          <Pressable onPress={() => { tap(); if (router.canGoBack()) router.back(); else router.navigate('/home'); }} accessibilityRole="button" accessibilityLabel="Back"
            style={[s.back, { backgroundColor: L.chipBg }]}><BackIcon color={night ? '#FFFFFF' : '#10151B'} /></Pressable>
        </View>
        <ScrollView contentContainerStyle={{ paddingBottom: 120 }}>
          <PopularStage width={width} full list={{ ...list, cars: shown }} />
          <View style={{ paddingHorizontal: 18, marginTop: 4 }}>
            {shown.slice(1).map((p) => <PopularRow key={p.id} p={p} mode={mode} answers={answers} />)}
            {!shown.length ? <Text style={[s.empty, { color: L.sub }]}>No car in this list matches that. Try All.</Text> : null}
            <Text style={[s.fine, { color: L.sub }]}>Payments are estimates, not a loan offer. This list is never paid for: no ads, no sponsored cars.</Text>
          </View>
        </ScrollView>
        <View style={[s.dock, { backgroundColor: night ? '#16224A' : '#FFFFFF', borderColor: night ? 'rgba(255,255,255,0.1)' : '#E1E7F0' }]}>
          <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={{ gap: 6, paddingHorizontal: 6 }}>
            {chips.map(([k, t]) => {
              const on = f === k;
              return (
                <Pressable key={k} onPress={() => { tap(); setF(k); }} accessibilityRole="button" accessibilityState={{ selected: on }}
                  style={[s.chip, { backgroundColor: on ? (night ? '#F4C24E' : '#1F5FBF') : night ? 'rgba(255,255,255,0.08)' : '#F1F4F9' }]}>
                  <Text style={[s.chipT, { color: on ? (night ? '#2B1F05' : '#FFFFFF') : night ? '#DCE5F5' : '#2A3442' }]}>{t}</Text>
                </Pressable>
              );
            })}
          </ScrollView>
        </View>
      </SafeAreaView>
    </View>
  );
}

const s = StyleSheet.create({
  top: { paddingHorizontal: 14, paddingTop: 4, paddingBottom: 2 },
  back: { width: 40, height: 40, borderRadius: 20, alignItems: 'center', justifyContent: 'center' },
  dock: { position: 'absolute', left: 12, right: 12, bottom: 24, borderRadius: 22, borderWidth: 1, paddingVertical: 7 },
  chip: { borderRadius: 99, paddingHorizontal: 13, paddingVertical: 9 },
  chipT: { fontSize: 12.5, fontWeight: '800' },
  empty: { fontSize: 13, textAlign: 'center', marginVertical: 18 },
  fine: { fontSize: 11, lineHeight: 16, textAlign: 'center', marginTop: 12 },
});
