// Recall alerts in the app (picture 25, option A, picked Oct 10, 2026).
// Every time the app opens we check NHTSA for recalls on each saved car. Recalls the person
// hasn't opened yet count as "new": they show at the top of My Garage and as a red number on
// the Garage tab. Opening the recall (or closing the alert) marks it as seen, on this phone.
import AsyncStorage from '@react-native-async-storage/async-storage';
import { createContext, useCallback, useContext, useEffect, useMemo, useState } from 'react';

import { getFacts, type Recall } from '@/data/gov';
import { useSaved } from '@/state/saved';
import { useRefreshTick } from '@/lib/refresh';

const KEY = 'carvessa:recalls-seen:v1';
export type CarRecalls = { key: string; id: string; year: number; recalls: Recall[]; fresh: Recall[] };

type Ctx = {
  byCar: Record<string, CarRecalls>; // key = "carId-year"
  fresh: CarRecalls[]; // saved cars with recalls not seen yet
  freshCount: number;
  markSeen: (key: string) => void;
};
const RecallsCtx = createContext<Ctx>({ byCar: {}, fresh: [], freshCount: 0, markSeen: () => {} });

export function RecallsProvider({ children }: { children: React.ReactNode }) {
  const { saved, ready } = useSaved();
  const [seen, setSeen] = useState<Record<string, string[]> | null>(null);
  const [found, setFound] = useState<Record<string, Recall[]>>({});

  useEffect(() => {
    AsyncStorage.getItem(KEY).then((raw) => setSeen(raw ? JSON.parse(raw) : {})).catch(() => setSeen({}));
  }, []);

  // Check each saved car (getFacts is cached, so this is cheap after the first time).
  const keys = saved.map((x) => `${x.id}-${x.year}`).join(',');
  const tick = useRefreshTick();
  useEffect(() => {
    if (!ready) return;
    let live = true;
    saved.forEach((x) => {
      getFacts(x.id, x.year).then((f) => {
        if (live && f.recalls) setFound((old) => ({ ...old, [`${x.id}-${x.year}`]: f.recalls! }));
      }).catch(() => {});
    });
    return () => { live = false; };
  }, [ready, keys, tick]); // eslint-disable-line react-hooks/exhaustive-deps

  const markSeen = useCallback((key: string) => {
    setSeen((old) => {
      const next = { ...(old ?? {}), [key]: (found[key] ?? []).map((r) => r.id) };
      AsyncStorage.setItem(KEY, JSON.stringify(next)).catch(() => {});
      return next;
    });
  }, [found]);

  const value = useMemo(() => {
    const byCar: Record<string, CarRecalls> = {};
    for (const x of saved) {
      const key = `${x.id}-${x.year}`;
      const recalls = found[key];
      if (!recalls) continue;
      const old = new Set(seen?.[key] ?? []);
      byCar[key] = { key, id: x.id, year: x.year, recalls, fresh: seen ? recalls.filter((r) => !old.has(r.id)) : [] };
    }
    const fresh = Object.values(byCar).filter((c) => c.fresh.length);
    return { byCar, fresh, freshCount: fresh.reduce((n, c) => n + c.fresh.length, 0), markSeen };
  }, [saved, found, seen, markSeen]);

  return <RecallsCtx.Provider value={value}>{children}</RecallsCtx.Provider>;
}

export const useRecalls = () => useContext(RecallsCtx);
