const STATUS = (): Record<FeatureStatus, { label: string; bg: string; fg: string }> => ({
  inc: { label: 'Included', bg: C.fill, fg: C.onAccent },
  trim: { label: 'Higher trim', bg: C.hero, fg: C.ink },
  plan: { label: 'App plan', bg: C.hero, fg: C.yellow },
  check: { label: 'Check trim', bg: C.card, fg: C.ink },
});
function LinkCard({ kicker, text, onPress }: { kicker: string; text: string; onPress: () => void }) {
  return (
    <Pressable onPress={() => { tap(); onPress(); }} accessibilityRole="button" style={s.link}>
      <View style={{ flex: 1 }}>
        <Label style={{ color: C.yellow }}>{kicker}</Label>
        <Body bold style={{ color: C.ink }}>{text}</Body>
      </View>
      <ArrowIcon color={C.yellow} />
    </Pressable>
  );
}

// Clean look year picker (picture 93 B, Oct 18, 2026): each year is a small card with its typical price,
// so shoppers see right away what an older year saves. Opens scrolled to the picked year.
// Clean look (picture 103 A, Oct 18, 2026): soft chips. Green = good, amber = good to know, red = recalls.
function SoftPros({ pros, cons }: { pros: string[]; cons: string[] }) {
  const night = isDarkLook(look);
  const tone = (kind: 'good' | 'know' | 'recall') => kind === 'good'
    ? { bg: night ? 'rgba(127,220,164,0.14)' : '#E3F1E8', fg: night ? '#8FE0B0' : '#1C6B40' }
    : kind === 'know' ? { bg: night ? 'rgba(242,196,107,0.14)' : '#FFF1D6', fg: night ? '#F2C46B' : '#7A5000' }
      : { bg: night ? 'rgba(240,140,120,0.16)' : '#FBE6E3', fg: night ? '#F2A39A' : '#A3382A' };
  const chip = (text: string, kind: 'good' | 'know' | 'recall') => {
    const t = tone(kind);
    return (
      <View key={text} style={[s.softChip, { backgroundColor: t.bg }]}>
        {kind === 'good' ? <CheckIcon size={15} color={t.fg} /> : <AlertIcon size={15} color={t.fg} />}
        <Text style={[s.softChipT, { color: t.fg }]}>{text}</Text>
      </View>
    );
  };
  return (
    <View style={s.softBox}>
      <Text style={s.softH}>Why people love it</Text>
      <View style={s.softWrap}>{pros.map((p) => chip(p, 'good'))}</View>
      {cons.length > 0 && <>
        <Text style={[s.softH, { marginTop: 10 }]}>Good to know</Text>
        <View style={s.softWrap}>{cons.map((p) => chip(p, /recall/i.test(p) ? 'recall' : 'know'))}</View>
      </>}
    </View>
  );
}

function YearCards({ car, year }: { car: Car; year: number }) {
  const years = yearsOf(car);
  const ref = useRef<ScrollView>(null);
  const at = Math.max(0, years.indexOf(year));
  return (
    <ScrollView ref={ref} horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={{ gap: 8, marginTop: 12, paddingVertical: 4, paddingRight: 4 }}
      onLayout={() => ref.current?.scrollTo({ x: Math.max(0, at * 104 - 104), animated: false })}>
      {years.map((yy) => {
        const p = priceFor(car, yy);
        const on = yy === year;
        return (
          <Pressable key={yy} onPress={() => { tap(); router.setParams({ year: String(yy) }); }} accessibilityRole="button" accessibilityState={{ selected: on }}
            accessibilityLabel={`${yy}${p ? `, ${money(p.amount)}${p.isNew ? ' new' : ' used, estimate'}` : ''}`}
            style={[s.yearCard, on && s.yearOn]}>
            <Text style={[s.yearY, on && { color: C.yellow }]}>{String(yy)}</Text>
            <Text style={s.yearP}>{p ? money(p.amount) : '–'}</Text>
            <Text style={s.yearS}>{p ? (p.isNew ? 'new' : 'used · est.') : ''}</Text>
          </Pressable>
        );
      })}
    </ScrollView>
  );
}

// Design C: name and price on one line, the fair-price range, then plan tags.
function CalmTop({ car, year, name, fit }: { car: Car; year: number; name: string; fit?: string }) {
  const p = priceFor(car, year);
  const range = p && !p.isNew ? fairRange(car, year) : null;
  const k = (n: number) => `$${Math.round(n / 1000)}K`;
  return (
    <View style={{ marginTop: 6 }}>
      <View style={{ flexDirection: 'row', alignItems: 'baseline', gap: 10 }}>
        <Text style={s.name} accessibilityRole="header">{name}</Text>
        {p ? <Text style={s.price}>{money(p.amount)}</Text> : null}
      </View>
      <Text style={s.k}>{`${p && !p.isNew ? 'Used ' : ''}${car.body} · estimate${range ? ` · fair price ${k(range[0])}–${k(range[1])}` : ''}${fit ? ` · ${fit}% match` : ''}`}</Text>
    </View>
  );
}

// Design C ring card: the payment next to your plan, out the door and the 5-year cost a month, then 4 tiles.
function CalmMoney({ car, year }: { car: Car; year: number }) {
  const { answers } = useAnswers();
  const { facts } = useFacts(car.id, year);
  const p = priceFor(car, year);
  if (!p) return null;
  const pay = paymentFor(answers, p.amount, p.isNew);
  const cap = monthlyCap(answers);
  const st = homeState();
  const five = quickFiveYear(p.amount, p.isNew, ageOf(year), facts?.mpg?.combined, facts?.mpg?.fuel === 'EV', costsFor().tax);
  const range = p.isNew ? null : fairRange(car, year);
  const recalls = facts?.recalls?.length;
  const tiles: [string, string][] = [
    [facts?.mpg ? String(facts.mpg.combined) : '–', facts?.mpg?.fuel === 'EV' ? 'MPGe' : 'MPG'],
    [facts?.stars ? `${facts.stars}★` : '–', 'Safety'],
    [String(car.seats), 'Seats'],
    [recalls == null ? '–' : String(recalls), 'Recalls'],
  ];
  return (
    <View>
      <View style={s.card}>
        <Ring pct={cap ? pay / cap : 0.75} big={money(pay)} small="a month" over={!!cap && pay > cap} size={88} />
        <View style={{ flex: 1 }}>
          {cap ? <View style={s.line}><Text style={s.k}>Your plan</Text><Body bold style={{ flexShrink: 0 }}>{`$${cap}`}</Body></View> : null}
          <View style={s.line}><Text style={s.k}>{st ? `Out the door · ${st}` : 'Out the door'}</Text><Body bold style={{ flexShrink: 0 }}>{money(outTheDoor(p.amount))}</Body></View>
          <View style={s.line}><Text style={s.k}>5-yr cost / mo</Text><Body bold style={{ flexShrink: 0 }}>{`≈ ${money(round(five.perMonth))}`}</Body></View>
        </View>
      </View>
      <View style={{ flexDirection: 'row', gap: 7, marginTop: 8 }}>
        {tiles.map(([a, b]) => (
          <View key={b} style={s.tile}><Text style={s.tileBig}>{a}</Text><Text style={[s.k, { fontSize: 10.5 }]}>{b}</Text></View>
        ))}
      </View>
      {range ? <View style={{ marginTop: 12 }}><FairBar range={range} at={p.amount} /></View> : null}
      <OtdLine price={p.amount} />
    </View>
  );
}

// Save button on the Sunset Calm sky (white circle, dark heart; filled green when saved).
function SkySave({ id, year }: { id: string; year: number }) {
  const { isSaved } = useSaved();
  const saveToggle = useSaveToggle();
  const on = isSaved(id, year);
  return (
    <SkyBtn label={on ? 'Remove from saved cars' : 'Save this car'} onPress={() => { tap(); saveToggle(id, year); }}>
      <HeartIcon size={19} color={on ? '#1F6E4E' : '#1D2B24'} />
    </SkyBtn>
  );
}

export default function CarDetails() {
  const pull = usePullRefresh();
  const { id, fit, year: y } = useLocalSearchParams<{ id: string; fit?: string; year?: string }>();
  const year = Number(y) || LATEST_MODEL_YEAR;
  const { answers } = useAnswers();
  const car = CARS.find((c) => c.id === id);
  const { facts } = useFacts(car?.id, year);
  const [forSale, setForSale] = useState(0);
  const onCount = useCallback((n: number) => setForSale(n), []);
  const { addRecent } = useSaved();
  useEffect(() => { if (car) addRecent(car.id, year); }, [car, year, addRecent]);
  if (!car) return null;
  const name = carName(car, year);
  const list = answers.mustHaves.length ? answers.mustHaves : MUST_HAVES.slice(0, 5);
  const price = priceFor(car, year);
  const included = list.filter((m) => featureAt(car, year, m) === 'inc').length;
  const { pros, cons } = prosCons(car.id, facts);
  const about = ABOUT[car.id];

  return (
    <SafeAreaView edges={calm ? [] : ['top']} style={{ flex: 1, backgroundColor: C.bg }}>
      {!calm && (
        <View style={s.top}>
          <SquareBtn label="Back" onPress={() => router.back()}><BackIcon /></SquareBtn>
          <Label>Car details</Label>
          <SaveHeart id={car.id} year={year} />
        </View>
      )}
      <ScrollView refreshControl={pull} contentContainerStyle={calm ? { paddingBottom: 110 } : { paddingHorizontal: PAD, paddingBottom: 110 }}>
        {/* Design C: the sky scrolls with the page and the car floats over it. */}
        {calm && (
          <SkyHeader title="Car details" height={215} skyline={70}
            left={<SkyBtn label="Back" onPress={() => router.back()}><BackIcon color="#1D2B24" /></SkyBtn>}
            right={<SkySave id={car.id} year={year} />} />
        )}
        <View style={calm ? s.flow : null}>
        {calm && skyLook ? <CarCutout id={car.id} year={year} label={name} height={175} style={{ marginTop: -128, marginHorizontal: 18 }} />
          : calm ? <View style={{ marginTop: 4 }}><CarGallery key={`${car.id}-${year}`} id={car.id} year={year} label={name} height={200} /></View>
          : <CarPhoto id={car.id} label={name} style={s.photo} />}
        {!(calm && !skyLook) && <PhotoCredit id={car.id} year={year} cut={calm} />}
        {calm ? <CalmTop car={car} year={year} name={name} fit={fit} /> : (<>
        <H size={32} style={{ marginTop: 12 }}>{name}</H>
        <View style={{ marginTop: 6, flexDirection: 'row', gap: 6, flexWrap: 'wrap' }}>
          <Tag label={car.tag} />{price && !price.isNew && <Tag label="Used" dark />}{fit ? <Tag label={`${fit}% match`} /> : null}
        </View>
        </>)}
        {yearsOf(car).length > 1 && calm && !skyLook && <YearCards car={car} year={year} />}
        {yearsOf(car).length > 1 && !(calm && !skyLook) && (
          <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={{ gap: 6, marginTop: 10 }}>
            {yearsOf(car).map((yy) => (
              <Chip key={yy} label={String(yy)} on={yy === year} onPress={() => router.setParams({ year: String(yy) })} />
            ))}
          </ScrollView>
        )}

        {calm ? <CalmMoney car={car} year={year} /> : <PriceBox car={car} year={year} answers={answers} />}
        {isShowroom() && <CarInfo car={car} year={year} facts={facts ?? null} />}
        <ForSaleRow car={car} onCount={onCount} />

        {!isShowroom() && !!facts?.recalls?.length && (
          <View style={s.recallBanner}>
            <AlertIcon size={22} color={C.red} />
            <Body style={{ flex: 1, fontSize: 14 }}>{`${facts.recalls.length} recall${facts.recalls.length === 1 ? '' : 's'} for this year. Fixes are free at any dealer. Details below.`}</Body>
          </View>
        )}

        <Label style={s.sec}>Why buy it</Label>
        <Body style={{ fontSize: 16 }}>{car.why}</Body>
        {calm && !skyLook ? <SoftPros pros={pros} cons={cons} /> : <View style={s.pcRow}>
          <View style={[s.pc, { borderColor: C.green }]}>
            <Label style={{ color: C.green }}>Good</Label>
            {pros.map((p) => <Body key={p} style={s.pcItem}>+ {p}</Body>)}
          </View>
          <View style={[s.pc, { borderColor: C.red }]}>
            <Label style={{ color: C.red }}>Watch out</Label>
            {cons.map((p) => <Body key={p} style={s.pcItem}>– {p}</Body>)}
          </View>
        </View>}

        <Label style={s.sec}>Your must-haves · {included} of {list.length} included</Label>
        {list.map((m) => {
          const st = STATUS()[featureAt(car, year, m) ?? 'check'];
          return (
            <View key={m} style={s.row}>
              <Body bold>{m}</Body>
              <View style={[s.pill, { backgroundColor: st.bg }]}><Label style={{ fontSize: 10, color: st.fg }}>{st.label}</Label></View>
            </View>
          );
        })}

        <View style={{ height: 8 }} />
        <RealFacts carId={car.id} year={year} recallsOpen />
        <OwnerProblems make={car.make} model={car.model} year={year} carId={car.id} recalls={facts?.recalls} />

        {about && (
          <>
            <Label style={s.sec}>About this car</Label>
            <Body style={{ fontSize: 15.5, lineHeight: 23 }}>{about.about}</Body>
            <Label style={[s.sec, { marginTop: 14 }]}>Great for</Label>
            <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: 6 }}>
              {about.goodFor.map((g) => <View key={g} style={s.forChip}><Body bold style={{ fontSize: 13, color: C.yellow }}>{g}</Body></View>)}
            </View>
          </>
        )}
        <CarGuide car={car} year={year} />
        <Label style={[s.sec, { marginTop: 14 }]}>Quick facts</Label>
        <View style={s.facts}>
          {[
            ['Type', car.body],
            ['Seats', String(car.seats)],
            ['Engine', car.green === 'ev' ? 'Electric' : car.green === 'hybrid' ? 'Hybrid' : 'Gas'],
            ...(facts?.mpg ? [['Gas mileage', `${facts.mpg.combined} ${facts.mpg.fuel === 'EV' ? 'MPGe' : 'MPG'} (EPA)`]] : []),
            ['All-wheel drive', car.features['4x4 / AWD'] === 'inc' ? 'Yes' : car.features['4x4 / AWD'] ? 'Some trims' : 'No'],
            ['Years we show', yearsOf(car).length > 1 ? `${yearsOf(car)[yearsOf(car).length - 1]}–${yearsOf(car)[0]}` : String(yearsOf(car)[0])],
          ].map(([k, v], i) => (
            <View key={k} style={[s.factRow, i > 0 && { borderTopWidth: 1, borderTopColor: C.line }]}>
              <Body style={{ color: C.muted, fontSize: 14 }}>{k}</Body>
              <Body bold style={{ fontSize: 14 }}>{v}</Body>
            </View>
          ))}
        </View>
        {about && (
          <View style={s.tip}>
            <Label style={{ color: C.yellow }}>Buying tip</Label>
            <Body style={{ fontSize: 14.5, marginTop: 4 }}>{about.tip}</Body>
          </View>
        )}

        <OwnerReviews carId={car.id} carName={`${car.make} ${car.model}`} years={yearsOf(car)} />

        <LinkCard kicker="Cost to own" text="Your payment and the 5-year cost, your way" onPress={() => router.push({ pathname: '/cost/[id]', params: { id: car.id, year: String(year) } })} />
        <LinkCard kicker="Watch it drive" text="Test-drive videos on YouTube"
          onPress={() => Linking.openURL(`https://www.youtube.com/results?search_query=${encodeURIComponent(`${name} test drive review`)}`)} />

        <DealersNear carId={car.id} />

        <Body style={s.small}>Prices, payments and out-the-door are estimates. Features are example info; check the trim at the dealer. “About”, pros and cons and tips are Carvessa’s notes. Crash stars and recalls are from NHTSA; gas mileage from the EPA.</Body>
        </View>
      </ScrollView>
      <View style={s.dock}>
        <Btn kind="yellow" label={forSale ? `See all ${forSale} for sale` : 'Cars for sale near you'} iconRight={<ArrowIcon color={C.onAccent} />} onPress={() => openShop(car)} />
      </View>
    </SafeAreaView>
  );
}

