// "2015 Camry deleted · Undo" (picture 209): a small dark bar for a few seconds after deleting, so a wrong tap is easy to fix.
import { useEffect } from 'react';
import { AccessibilityInfo, StyleSheet, View } from 'react-native';

import { CheckIcon } from '@/components/icons';
import { Pressable, Text } from '@/components/t';
import { tap } from '@/components/ui';
import { tr } from '@/i18n';
import { F } from '@/theme';

export function UndoBar({ text, onUndo, onDone, seconds = 6 }: { text: string; onUndo: () => void; onDone: () => void; seconds?: number }) {
  useEffect(() => {
    AccessibilityInfo.announceForAccessibility?.(`${tr(text)}. ${tr('Undo')}`);
    const t = setTimeout(onDone, seconds * 1000);
    return () => clearTimeout(t);
  }, [text]); // eslint-disable-line react-hooks/exhaustive-deps
  return (
    <View style={s.bar} accessibilityLiveRegion="polite">
      <CheckIcon size={20} color="#7FD6A0" />
      <Text style={s.t} numberOfLines={1}>{text}</Text>
      <Pressable onPress={() => { tap(); onUndo(); }} accessibilityRole="button" hitSlop={10} style={s.btn}>
        <Text style={s.undo}>Undo</Text>
      </Pressable>
    </View>
  );
}

const s = StyleSheet.create({
  bar: { position: 'absolute', left: 16, right: 16, bottom: 96, backgroundColor: '#111318', borderRadius: 16, paddingHorizontal: 16, minHeight: 52,
    flexDirection: 'row', alignItems: 'center', gap: 10, shadowColor: '#000', shadowOpacity: 0.25, shadowRadius: 12, shadowOffset: { width: 0, height: 6 }, elevation: 8 },
  t: { flex: 1, fontFamily: F.bodyBold, fontSize: 15, color: '#FFFFFF' },
  btn: { minHeight: 44, justifyContent: 'center', paddingHorizontal: 4 },
  undo: { fontFamily: F.bodyBold, fontSize: 15, color: '#E2C27E' },
});
