// ---- I · Full garage (4×4) ----
function Garage({ s, p, pick }: { s: WidgetSnap | null; p: Pal; pick: number }) {
  if (!s || !s.cars.length) return <AddCar p={p} />;
  const i = ((pick % s.cars.length) + s.cars.length) % s.cars.length;
  const car = s.cars[i];
  const r = recallLine(car, p);
  const tile = (label: string, value: string, color: ColorProp = p.ink) => (
    <FlexWidget style={{ flex: 1, backgroundColor: p.bg, borderRadius: 14, padding: 9 }}>
      <TextWidget text={tr(label)} style={{ fontSize: 11, fontFamily: B, color: p.sub }} maxLines={1} />
      <TextWidget text={value} style={{ fontSize: 14, fontFamily: XB, color }} maxLines={1} truncate="END" />
    </FlexWidget>
  );
  const pay = car.payDate ? `${car.payDate}${car.payAmount ? ` · ${money(car.payAmount)}` : ''}` : tr(car.recalls === null ? 'Not set' : 'None');
  return (
    <FlexWidget style={card(p, { backgroundColor: p.tile, padding: 14 })}>
      <FlexWidget style={{ flexDirection: 'row', width: 'match_parent', alignItems: 'center' }}>
        <FlexWidget {...open(LINK.garage)} style={{ flex: 1 }}>
          <Kicker text="My Garage" color={p.blue} />
          <TextWidget text={car.name} style={{ fontSize: 16, fontFamily: XB, color: p.ink }} maxLines={1} truncate="END" />
        </FlexWidget>
        {s.cars.length > 1 ? (
          <FlexWidget clickAction="NEXT_CAR" style={{ backgroundColor: p.fill, borderRadius: 12, paddingHorizontal: 10, paddingVertical: 6 }}>
            <TextWidget text={tr('{a} of {b} cars ›').replace('{a}', String(i + 1)).replace('{b}', String(s.cars.length))} style={{ fontSize: 12, fontFamily: XB, color: p.blue }} />
          </FlexWidget>
        ) : null}
      </FlexWidget>
      <FlexWidget {...open(LINK.garage)} style={{ flex: 1, width: 'match_parent', alignItems: 'center', justifyContent: 'center' }}>
        {SZ.h - 238 >= 30 ? <CarPic car={car} w={Math.round(clamp(SZ.w - 28, 80, 300))} h={Math.round(clamp(SZ.h - 238, 30, 140))} /> : null}
      </FlexWidget>
      <FlexWidget style={{ flexDirection: 'row', width: 'match_parent', flexGap: 8 }}>
        {tile('Recalls', car.recalls === null ? tr('Checking') : car.recalls === 0 ? tr('None open') : plural(car.recalls, '{n} open', '{n} open'), r.bad ? p.red : car.recalls === 0 ? p.green : p.ink)}
        {tile('Oil change', car.oilIn === null ? tr('Add miles') : car.oilIn < 100 ? tr('Due now') : `~${miles(car.oilIn)} mi`, car.oilIn !== null && car.oilIn < 100 ? p.red : p.ink)}
      </FlexWidget>
      <FlexWidget style={{ flexDirection: 'row', width: 'match_parent', flexGap: 8, marginTop: 8 }}>
        {tile('Payment', pay)}
        {tile('Worth (est.)', car.worth ? `${money(car.worth[0])}–${money(car.worth[1])}` : tr('Not known'))}
      </FlexWidget>
      <FlexWidget style={{ flexDirection: 'row', width: 'match_parent', flexGap: 8, marginTop: 10 }}>
        <Btn label="Light on?" uri={LINK.light} p={p} />
        <Btn label="Ask" uri={LINK.ask} p={p} />
        <Btn label="Check a car" uri={LINK.scan} p={p} />
      </FlexWidget>
    </FlexWidget>
  );
}

// ---- J · Tip of the day (4×2) ----
export const tipIndex = (tips: number, day: number, extra: number) => (tips ? (((day + extra) % tips) + tips) % tips : 0);
function Tip({ s, extra, day }: { s: WidgetSnap | null; extra: number; day: number }) {
  const car = activeOf(s);
  const tips = s?.tips ?? [];
  const tip = tips.length ? tips[tipIndex(tips.length, day, extra)] : tr('Cold mornings lower tire pressure. About 1 PSI for every 10°F colder. Check before a morning drive.');
  const cut = tip.search(/[.:]\s/);
  const head = cut > 0 ? tip.slice(0, cut + 1) : tip;
  const rest = cut > 0 ? [tip.slice(cut + 2)] : [];
  return (
    <FlexWidget {...open(LINK.garage)} style={{ height: 'match_parent', width: 'match_parent', borderRadius: 24, padding: 16, backgroundGradient: { from: '#E26A4A', to: '#B8472A', orientation: 'TL_BR' } }}>
      <FlexWidget style={{ flexDirection: 'row', width: 'match_parent' }}>
        <FlexWidget style={{ flex: 1 }}><Kicker text="Did you know?" color="#FFE3D8" /></FlexWidget>
        {car ? <TextWidget text={tr('Your {car}').replace('{car}', car.short).toUpperCase()} style={{ fontSize: 11, fontFamily: XB, color: '#FFE3D8', letterSpacing: 0.08 }} maxLines={1} /> : null}
      </FlexWidget>
      <TextWidget text={head} style={{ fontSize: SZ.h < 150 ? 15 : 17, fontFamily: XB, color: '#FFFFFF', marginTop: 6 }} maxLines={SZ.h < 150 ? 2 : 3} truncate="END" />
      {rest.length && SZ.h >= 150 ? <TextWidget text={rest.join(' ')} style={{ fontSize: 12.5, fontFamily: B, color: '#FFF4EF', marginTop: 4 }} maxLines={2} truncate="END" /> : null}
      <FlexWidget style={{ flex: 1 }} />
      <FlexWidget clickAction="NEXT_TIP" style={{ backgroundColor: '#FFFFFF', borderRadius: 12, paddingHorizontal: 12, paddingVertical: 7 }}>
        <TextWidget text={tr('Another tip ›')} style={{ fontSize: 12.5, fontFamily: XB, color: '#A63A20' }} />
      </FlexWidget>
    </FlexWidget>
  );
}

