// ================= Second set (pictures 190–192, Nov 6, 2026) =================

export type Extra = { park?: ParkSpot | null; week?: Week; trips?: Trip[]; now?: number };
const nowOf = (x?: Extra) => x?.now ?? Date.now();

// ---- L · Car health score ----
function healthRing(score: number) {
  const r = 42, c = 2 * Math.PI * r, f = Math.max(0.02, score / 100);
  const [a, b] = score >= 90 ? ['#00E5FF', '#39FF88'] : score >= 70 ? ['#FFD36E', '#FFB020'] : ['#FF8A7A', '#FF3B30'];
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><defs><linearGradient id="g" x1="0" x2="1"><stop offset="0" stop-color="${a}"/><stop offset="1" stop-color="${b}"/></linearGradient></defs><circle cx="50" cy="50" r="${r}" fill="none" stroke="#18241E" stroke-width="9"/><circle cx="50" cy="50" r="${r}" fill="none" stroke="url(#g)" stroke-width="9" stroke-linecap="round" stroke-dasharray="${(c * f).toFixed(1)} ${c.toFixed(1)}" transform="rotate(-90 50 50)"/></svg>`;
}
const TONE = { ok: '#39FF88', warn: '#FFB020', bad: '#FF6B5E' } as const;
function Health({ s }: { s: WidgetSnap | null }) {
  const car = activeOf(s);
  if (!car) return <AddCar p={NIGHT} small />;
  const h = healthOf(car, s?.weather?.tempF);
  const R = Math.round(clamp(SZ.h - 50, 70, 130));
  const color = h.score >= 90 ? '#39FF88' : h.score >= 70 ? '#FFB020' : '#FF6B5E';
  return (
    <FlexWidget {...open(LINK.myCar)} style={{ height: 'match_parent', width: 'match_parent', borderRadius: 24, padding: 14, backgroundGradient: { from: '#12201A', to: '#05070A', orientation: 'TOP_BOTTOM' } }}>
      <FlexWidget style={{ flexDirection: 'row', width: 'match_parent' }}>
        <FlexWidget style={{ flex: 1 }}><Kicker text="Car health" color={color as ColorProp} /></FlexWidget>
        <TextWidget text={`${car.year} ${car.short}`.toUpperCase()} style={{ fontSize: 11, fontFamily: XB, color: '#7C8A99', letterSpacing: 0.08 }} maxLines={1} />
      </FlexWidget>
      <FlexWidget style={{ flexDirection: 'row', flex: 1, width: 'match_parent', alignItems: 'center', flexGap: 14 }}>
        <OverlapWidget style={{ width: R, height: R }}>
          <Svg xml={healthRing(h.score)} w={R} h={R} />
          <FlexWidget style={{ width: R, height: R, alignItems: 'center', justifyContent: 'center' }}>
            <TextWidget text={String(h.score)} style={{ fontSize: Math.round(R * 0.32), fontFamily: XB, color: '#FFFFFF' }} />
            <TextWidget text={tr(h.word)} style={{ fontSize: 10.5, fontFamily: B, color: '#9FB3A8' }} maxLines={1} />
          </FlexWidget>
        </OverlapWidget>
        <FlexWidget style={{ flex: 1, flexGap: 7 }}>
          {h.items.map((it, i) => (
            <FlexWidget key={i} style={{ flexDirection: 'row', alignItems: 'center', flexGap: 7 }}>
              <Dot color={TONE[it.tone]} />
              <TextWidget text={tr(it.text)} style={{ fontSize: 12.5, fontFamily: B, color: '#FFFFFF' }} maxLines={1} truncate="END" />
            </FlexWidget>
          ))}
        </FlexWidget>
      </FlexWidget>
      <TextWidget text={tr('Our score, not a mechanic’s check')} style={{ fontSize: 10, fontFamily: B, color: '#5E6E66' }} maxLines={1} />
    </FlexWidget>
  );
}

// ---- P · Light on? Tap the one you see ----
