const SHORT_LIGHT: Record<string, string> = { engine: 'Check engine', oil: 'Oil', temp: 'Engine hot', battery: 'Battery', tire: 'Tire', brake: 'Brakes' };

// ---- N · Countdowns ----
function Countdown({ s, p }: { s: WidgetSnap | null; p: Pal }) {
  const car = activeOf(s);
  if (!car) return <AddCar p={p} small />;
  const col = (big: string, unit: string, what: string, color: ColorProp = p.ink, first = false) => (
    <FlexWidget style={{ flex: 1, paddingLeft: first ? 0 : 10, borderLeftWidth: first ? 0 : 1, borderColor: p.fill }}>
      <TextWidget text={big} style={{ fontSize: big.length > 4 ? 24 : 32, fontFamily: XB, color }} maxLines={1} />
      <TextWidget text={tr(unit).toUpperCase()} style={{ fontSize: 10, fontFamily: XB, color: p.sub, letterSpacing: 0.06 }} maxLines={1} />
      <TextWidget text={what} style={{ fontSize: 12, fontFamily: B, color: p.ink, marginTop: 2 }} maxLines={2} />
    </FlexWidget>
  );
  const pay = car.payDays !== undefined ? col(String(Math.max(0, car.payDays)), car.payDays === 1 ? 'day' : 'days', car.payAmount ? `${tr('Payment')} ${money(car.payAmount)}` : tr('Payment'), p.ink, true)
    : col('–', 'no loan', tr('Payment'), p.sub, true);
  const oil = car.oilIn === null ? col('–', 'add miles', tr('Oil change'), p.sub) : car.oilIn < 100 ? col(tr('Now'), 'due', tr('Oil change'), p.red) : col(shortNum(car.oilIn), 'miles', tr('Oil change'), car.oilIn <= 1500 ? p.amber : p.ink);
  const tag = car.regDays === undefined ? col('–', 'add date', tr('Tag renewal'), p.sub) : car.regDays < 0 ? col(tr('Late'), 'renew now', tr('Tag renewal'), p.red) : col(String(car.regDays), car.regDays === 1 ? 'day' : 'days', tr('Tag renewal'), car.regDays <= 30 ? p.amber : p.ink);
  const f = car.paid ? car.paid[0] / car.paid[1] : 0;
  return (
    <FlexWidget {...open(LINK.myCar)} style={card(p)}>
      <FlexWidget style={{ flexDirection: 'row', width: 'match_parent' }}>
        <FlexWidget style={{ flex: 1 }}><Kicker raw text={`${tr('Coming up')} · ${car.short}`} color={p.blue} /></FlexWidget>
      </FlexWidget>
      <FlexWidget style={{ flexDirection: 'row', width: 'match_parent', marginTop: 8, flex: 1 }}>{pay}{oil}{tag}</FlexWidget>
      {car.paid && SZ.h >= 150 ? (
        <FlexWidget style={{ width: 'match_parent', marginTop: 6 }}>
          <FlexWidget style={{ flexDirection: 'row', width: 'match_parent' }}>
            <FlexWidget style={{ flex: 1 }}><TextWidget text={tr('Car paid off')} style={{ fontSize: 11, fontFamily: B, color: p.sub }} /></FlexWidget>
            <TextWidget text={tr('{a} of {b} payments').replace('{a}', String(car.paid[0])).replace('{b}', String(car.paid[1]))} style={{ fontSize: 11, fontFamily: B, color: p.sub }} />
          </FlexWidget>
          <FlexWidget style={{ width: 'match_parent', height: 8, borderRadius: 4, backgroundColor: p.fill, marginTop: 4, flexDirection: 'row' }}>
            <FlexWidget style={{ width: Math.max(4, Math.round((SZ.w - 28) * f)), height: 8, borderRadius: 4, backgroundGradient: { from: '#1F5FBF', to: '#3D8BFF', orientation: 'LEFT_RIGHT' } }} />
          </FlexWidget>
        </FlexWidget>
      ) : null}
    </FlexWidget>
  );
}

