// ---- S · Drive alert ----
/** What the weather means for driving right now. Loud only when it matters. */
export function driveAlert(w?: WidgetWeather): { level: 'bad' | 'ok'; title: string; text: string } | null {
  if (!w) return null;
  if (w.tempF <= 34 && (w.sky === 'rain' || w.sky === 'snow' || w.sky === 'fog')) return { level: 'bad', title: 'Ice possible on the roads', text: 'Leave 10 minutes early. Clear every window. Cold air can turn on the tire light.' };
  if (w.sky === 'snow') return { level: 'bad', title: 'Snow on the roads', text: 'Go slow and leave extra room to stop. Clear every window before you drive.' };
  if (w.sky === 'storm') return { level: 'bad', title: 'Storms around', text: 'Heavy rain and wind. If you can’t see, pull over somewhere safe and wait.' };
  if (w.sky === 'rain') return { level: 'bad', title: 'Wet roads', text: 'Leave more room to stop, and turn your headlights on.' };
  if (w.sky === 'fog') return { level: 'bad', title: 'Fog', text: 'Low beams on, slow down, and leave lots of room.' };
  if (w.tempF <= 34) return { level: 'bad', title: 'Freezing out', text: 'Watch for ice on bridges. Cold air can turn on the tire light.' };
  if (w.tempF >= 95) return { level: 'bad', title: 'Big heat today', text: 'Never leave kids or pets in the car. Heat is hard on batteries.' };
  return { level: 'ok', title: 'Good driving weather', text: 'Nothing to watch for right now.' };
}
const HAZARD = (w: number) => `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${w} 10">${Array.from({ length: Math.ceil(w / 24) + 1 }, (_, i) => `<path d="M${i * 24} 10 L${i * 24 + 10} 0 L${i * 24 + 22} 0 L${i * 24 + 12} 10 Z" fill="#FFB020"/>`).join('')}</svg>`;
function DriveAlert({ s }: { s: WidgetSnap | null }) {
  const w = s?.weather;
  const a = driveAlert(w);
  const bad = a?.level === 'bad';
  const W = Math.round(SZ.w);
  return (
    <FlexWidget {...open(LINK.myCar)} style={{ height: 'match_parent', width: 'match_parent', borderRadius: 24, backgroundColor: bad ? '#1B1206' : '#0E1A12', overflow: 'hidden' }}>
      {bad ? <Svg xml={HAZARD(W)} w={W} h={10} /> : <FlexWidget style={{ height: 10 }} />}
      <FlexWidget style={{ padding: 14, paddingTop: 10, flex: 1, width: 'match_parent' }}>
        <FlexWidget style={{ flexDirection: 'row', width: 'match_parent', alignItems: 'center' }}>
          <FlexWidget style={{ flex: 1 }}><Kicker raw text={`${tr('Now')}${s?.spot?.place ? ` · ${s.spot.place}` : ''}`} color={bad ? '#FFB020' : '#5ED08F'} /></FlexWidget>
          {w ? <TextWidget text={`${Math.round(w.tempF)}°`} style={{ fontSize: 22, fontFamily: XB, color: '#FFFFFF' }} /> : null}
        </FlexWidget>
        <TextWidget text={a ? `${tr(a.title)}${bad ? '' : ' ✓'}` : tr('Open Carvessa to load the weather')} style={{ fontSize: 18, fontFamily: XB, color: '#FFFFFF', marginTop: 4 }} maxLines={2} />
        {a ? <TextWidget text={tr(a.text)} style={{ fontSize: 12.5, fontFamily: B, color: bad ? '#E9D9BF' : '#B5CDBE', marginTop: 4 }} maxLines={SZ.h < 150 ? 1 : 3} truncate="END" /> : null}
      </FlexWidget>
    </FlexWidget>
  );
}

