// ---- AB · What my car costs this month ----
function costRing(parts: number[], size: number) {
  const r = 40, c = 2 * Math.PI * r, total = parts.reduce((a, b) => a + b, 0) || 1;
  const colors = ['#1F5FBF', '#3D8BFF', '#7BB0FF', '#C9DCFA'];
  let off = 0;
  const segs = parts.map((v, i) => {
    const len = (v / total) * c;
    const seg = len > 0.5 ? `<circle cx="50" cy="50" r="${r}" fill="none" stroke="${colors[i]}" stroke-width="13" stroke-dasharray="${len.toFixed(1)} ${c.toFixed(1)}" stroke-dashoffset="${(-off).toFixed(1)}" transform="rotate(-90 50 50)"/>` : '';
    off += len;
    return seg;
  }).join('');
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100" width="${size}" height="${size}"><circle cx="50" cy="50" r="${r}" fill="none" stroke="#EEF2F7" stroke-width="13"/>${segs}</svg>`;
}
const MONTHS_LONG = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
function MonthCost({ s, p, x }: { s: WidgetSnap | null; p: Pal; x?: Extra }) {
  const car = activeOf(s);
  if (!car) return <AddCar p={p} small />;
  const c = car.cost;
  if (!c) {
    return (
      <FlexWidget {...open(LINK.myCar)} style={card(p, { justifyContent: 'center' })}>
        <Kicker text="What my car costs" color={p.blue} />
        <TextWidget text={tr('Add your miles in My Garage')} style={{ fontSize: 14, fontFamily: XB, color: p.ink, marginTop: 6 }} />
      </FlexWidget>
    );
  }
  const parts = [c.pay, c.gas, c.ins, c.upkeep];
  const total = parts.reduce((a, b) => a + b, 0);
  const R = Math.round(clamp(SZ.h - 60, 70, 120));
  const colors = ['#1F5FBF', '#3D8BFF', '#7BB0FF', '#C9DCFA'] as ColorProp[];
  const rows: [string, number][] = [['Payment', c.pay], ['Gas', c.gas], ['Insurance', c.ins], ['Upkeep', c.upkeep]];
  return (
    <FlexWidget {...open(LINK.myCar)} style={card(p)}>
      <Kicker raw text={`${tr(MONTHS_LONG[new Date(nowOf(x)).getMonth()])} · ${car.short}`} color={p.blue} />
      <FlexWidget style={{ flexDirection: 'row', flex: 1, width: 'match_parent', alignItems: 'center', flexGap: 14 }}>
        <OverlapWidget style={{ width: R, height: R }}>
          <Svg xml={costRing(parts, R)} w={R} h={R} />
          <FlexWidget style={{ width: R, height: R, alignItems: 'center', justifyContent: 'center' }}>
            <TextWidget text={money(total)} style={{ fontSize: 16, fontFamily: XB, color: p.ink }} />
            <TextWidget text={tr('est.')} style={{ fontSize: 10, fontFamily: B, color: p.sub }} />
          </FlexWidget>
        </OverlapWidget>
        <FlexWidget style={{ flex: 1, flexGap: 5 }}>
          {rows.map(([label, v], i) => (v || i > 0 ? (
            <FlexWidget key={label} style={{ flexDirection: 'row', alignItems: 'center', flexGap: 7 }}>
              <FlexWidget style={{ width: 10, height: 10, borderRadius: 3, backgroundColor: colors[i] }} />
              <TextWidget text={`${tr(label)} ${i ? '~' : ''}${money(v)}`} style={{ fontSize: 12.5, fontFamily: B, color: p.ink }} maxLines={1} />
            </FlexWidget>
          ) : null))}
        </FlexWidget>
      </FlexWidget>
      <TextWidget text={tr('Estimates from your miles, EPA gas use and our cost guide')} style={{ fontSize: 10, fontFamily: B, color: p.sub }} maxLines={1} truncate="END" />
    </FlexWidget>
  );
}

export type Size = { w: number; h: number };
export function drawWidget(name: string, s: WidgetSnap | null, dark: boolean, pick = 0, day = 0, size?: Size, x?: Extra): React.JSX.Element {
  const p = dark ? NIGHT : DAY;
  SZ = size && size.w > 0 && size.h > 0 ? size : DEFAULT_SIZE[name as WidgetName] ?? { w: 250, h: 180 };
  switch (name as WidgetName) {
    case 'MyCar': return <MyCar s={s} p={p} />;
    case 'MyCarButtons': return <MyCarButtons s={s} p={p} />;
    case 'Gauge': return <Gauge s={s} />;
    case 'CarBig': return <CarBig s={s} p={p} dark={dark} />;
    case 'NavyGold': return <NavyGold s={s} />;
    case 'Weather': return <Weather s={s} dark={dark} />;
    case 'OneLine': return <OneLine s={s} p={p} />;
    case 'Garage': return <Garage s={s} p={p} pick={pick} />;
    case 'Tip': return <Tip s={s} extra={pick} day={day} />;
    case 'Quick': return <Quick />;
    case 'Health': return <Health s={s} />;
    case 'Lights': return <Lights />;
    case 'Countdown': return <Countdown s={s} p={p} />;
    case 'Odometer': return <Odometer s={s} />;
    case 'Value': return <Value s={s} />;
    case 'CarPass': return <CarPass s={s} />;
    case 'NightGlow': return <NightGlow s={s} x={x} />;
    case 'DriveAlert': return <DriveAlert s={s} />;
    case 'Parking': return <Parking x={x} p={p} />;
    case 'Sos': return <Sos s={s} />;
    case 'Radar': return <Radar s={s} x={x} />;
    case 'NextCar': return <NextCarW s={s} p={p} />;
    case 'WeekCheck': return <WeekCheck x={x} p={p} />;
    case 'Driver': return <Driver x={x} />;
    case 'MonthCost': return <MonthCost s={s} p={p} x={x} />;
    default: return <MyCar s={s} p={p} />;
  }
}

/** A plain card with no pictures or fonts: drawn first, so a widget is never an empty box (and if only this
 * shows, the full drawing failed). `note` shows an error in small words, to help us fix it. */
export function plainCard(title: string, line: string, note?: string) {
  const one = (dark: boolean) => (
    <FlexWidget {...open(LINK.garage)} style={{ height: 'match_parent', width: 'match_parent', backgroundColor: dark ? '#141B26' : '#FFFFFF', borderRadius: 24, padding: 14, justifyContent: 'center' }}>
      <TextWidget text={title} style={{ fontSize: 15, color: dark ? '#FFFFFF' : '#0F1A2A' }} maxLines={1} />
      <TextWidget text={line} style={{ fontSize: 12, color: dark ? '#9AA6B8' : '#556274' }} maxLines={2} />
      {note ? <TextWidget text={note} style={{ fontSize: 10, color: dark ? '#FFB4A8' : '#8E2A1B' }} maxLines={3} /> : null}
    </FlexWidget>
  );
  return { light: one(false), dark: one(true) };
}

/** Both versions, for renderWidget({ light, dark }). */
export const bothLooks = (name: string, s: WidgetSnap | null, pick = 0, day = 0, size?: Size, x?: Extra) => ({
  light: drawWidget(name, s, false, pick, day, size, x),
  dark: drawWidget(name, s, true, pick, day, size, x),
});
