// Recall alerts on the phone for members (picture 25, option C, picked Oct 10, 2026).
// - Members' saved cars are copied to Supabase (table saved_cars) so our daily server check
//   (supabase/functions/recall-check) knows which recalls to look for.
// - Turning on "Recall alerts" in Me asks the phone for permission and saves the phone's
//   Expo push token (table push_tokens). Turning it off keeps the token but stops alerts.
// Guests still get the in-app alerts in My Garage (state/recalls.tsx).
import { withoutReceipts } from '@/data/car-log';
import Constants from 'expo-constants';
import * as Device from 'expo-device';
import * as Notifications from 'expo-notifications';
import { router } from 'expo-router';
import { createContext, useCallback, useContext, useEffect, useMemo, useRef, useState } from 'react';
import { Platform } from 'react-native';

import { GOV_NAMES } from '@/data/gov';
import { syncReminders } from '@/lib/reminders';
import { supabase } from '@/lib/supabase';
import { useAuth } from '@/state/auth';
import { type MyCar, useSaved } from '@/state/saved';
import { LATEST_MODEL_YEAR } from '@/data/year';
import { goFromAlert } from '@/lib/alert-route';

// Alert taps already handled (by notification id), so a tap is never opened twice.
const handled = new Set<string>();

// Show alerts even while the app is open.
if (Platform.OS !== 'web') {
  Notifications.setNotificationHandler({
    handleNotification: async () => ({ shouldShowBanner: true, shouldShowList: true, shouldPlaySound: true, shouldSetBadge: false }),
  });
}

type Ctx = {
  alertsOn: boolean;
  busy: boolean;
  setAlertsOn: (on: boolean) => Promise<string | null>; // returns a message to show if it didn't work
};
const AlertsCtx = createContext<Ctx>({ alertsOn: false, busy: false, setAlertsOn: async () => null });

async function phoneToken(): Promise<{ token?: string; error?: string }> {
  if (Platform.OS === 'web') return { error: 'Phone alerts work in the phone app, not on the web.' };
  if (!Device.isDevice) return { error: 'Phone alerts need a real phone.' };
  if (Platform.OS === 'android') {
    await Notifications.setNotificationChannelAsync('recalls', { name: 'Recall alerts', importance: Notifications.AndroidImportance.HIGH });
  }
  let { status } = await Notifications.getPermissionsAsync();
  if (status !== 'granted') status = (await Notifications.requestPermissionsAsync()).status;
  if (status !== 'granted') return { error: 'Alerts are off for Carvessa in your phone settings. Turn them on there, then try again.' };
  const projectId = (Constants.expoConfig?.extra as { eas?: { projectId?: string } } | undefined)?.eas?.projectId;
  try {
    const t = await Notifications.getExpoPushTokenAsync(projectId ? { projectId } : undefined);
    return { token: t.data };
  } catch {
    return { error: 'This test app can’t get phone alerts yet. They will work in the real Carvessa app.' };
  }
}

export function AlertsProvider({ children }: { children: React.ReactNode }) {
  const { session, prefs } = useAuth();
  const { saved, addSaved, myCars, setMyCars, pickCar, ready } = useSaved();
  const [st, setSt] = useState<{ uid?: string; on: boolean }>({ on: false });
  const [busy, setBusy] = useState(false);
  const uid = session?.user.id;
  const [synced, setSynced] = useState<string | null>(null); // the member whose account copy we've already brought back
  const alertsOn = !!uid && st.uid === uid && st.on;
  const setOn = useCallback((on: boolean) => setSt({ uid, on }), [uid]);

  // Read the current setting for this member.
  useEffect(() => {
    if (!uid) return;
    let live = true;
    supabase.from('push_tokens').select('enabled').eq('user_id', uid).eq('enabled', true).limit(1)
      .then(({ data }) => { if (live) setSt({ uid, on: !!data?.length }); });
    return () => { live = false; };
  }, [uid]);

  // Keep the member's saved cars in Supabase in step with the phone.
  const keys = saved.map((x) => `${x.id}-${x.year}`).sort().join(',');
  useEffect(() => {
    // Wait until the account copy is brought back first, so a new (empty) phone never wipes it.
    if (!uid || synced !== uid) return;
    const rows = saved.filter((x) => GOV_NAMES[x.id]).map((x) => ({ user_id: uid, car_id: x.id, year: x.year, make: GOV_NAMES[x.id].make, models: GOV_NAMES[x.id].recall }));
    (async () => {
      const { data } = await supabase.from('saved_cars').select('car_id,year').eq('user_id', uid);
      const want = new Set(rows.map((r) => `${r.car_id}-${r.year}`));
      const gone = (data ?? []).filter((r) => !want.has(`${r.car_id}-${r.year}`));
      for (const g of gone) await supabase.from('saved_cars').delete().eq('user_id', uid).eq('car_id', g.car_id).eq('year', g.year);
      if (rows.length) await supabase.from('saved_cars').upsert(rows, { onConflict: 'user_id,car_id,year', ignoreDuplicates: true });
    })().catch(() => {});
  }, [uid, keys, synced]); // eslint-disable-line react-hooks/exhaustive-deps

  // Free account (Oct 18, 2026): your car + dealer and saved cars follow you to a new phone.
  // On sign-in, bring them back if this phone has none; after that, keep the account copy of "My car" up to date.
  useEffect(() => {
    if (!uid || !ready || synced === uid) return;
    (async () => {
      // my_cars = every car (Oct 23, 2026); older app versions only wrote my_car (one car).
      const meta = session?.user.user_metadata as { my_car?: MyCar | null; my_cars?: MyCar[] } | undefined;
      if (!myCars.length) {
        if (meta?.my_cars?.length) setMyCars(meta.my_cars);
        else if (meta?.my_car) setMyCars([meta.my_car]);
      }
      if (!saved.length) {
        const { data } = await supabase.from('saved_cars').select('car_id,year').eq('user_id', uid);
        if (data?.length) addSaved(data.map((r) => ({ id: r.car_id as string, year: r.year as number })));
      }
    })().catch(() => {}).finally(() => setSynced(uid));
  }, [uid, ready]); // eslint-disable-line react-hooks/exhaustive-deps
  const carKey = JSON.stringify(myCars);
  useEffect(() => {
    if (!uid || synced !== uid) return;
    const meta = session?.user.user_metadata as { my_cars?: unknown } | undefined;
    // Receipt photos are files on this phone (picture 221 option 1), so they stay out of the account copy.
    const cloud = myCars.map((c) => withoutReceipts(c));
    if (JSON.stringify(meta?.my_cars ?? []) === JSON.stringify(cloud)) return;
    // my_car stays = car #1 so older app versions still find a car.
    supabase.auth.updateUser({ data: { my_cars: cloud, my_car: cloud[0] ?? null } }).catch(() => {});
  }, [uid, synced, carKey]); // eslint-disable-line react-hooks/exhaustive-deps

  // Payment, miles and oil reminders made on the phone (My car plan, Oct 30, 2026): free account, like every reminder.
  useEffect(() => {
    if (!ready) return;
    syncReminders(myCars, { upkeep: prefs.upkeep, allowed: !!uid });
  }, [ready, carKey, uid, prefs.upkeep]); // eslint-disable-line react-hooks/exhaustive-deps

  // Tapping an alert opens that car's Safety tab, or, for a car in My Garage (Oct 26, 2026), that car's My car page.
  const carsRef = useRef(myCars);
  useEffect(() => { carsRef.current = myCars; }, [myCars]);
  useEffect(() => {
    if (Platform.OS === 'web') return;
    // A tap can open the app (cold start) before this listener exists, so also read the last tap once; each tap is
    // handled once (by its notification id), and only after the opening animation (lib/alert-route.ts).
    const handle = (r: Notifications.NotificationResponse | null) => {
      if (!r || handled.has(r.notification.request.identifier)) return;
      handled.add(r.notification.request.identifier);
      // Forget it, so a normal app start later never reopens an old alert. Guarded for older installed apps.
      Promise.resolve().then(() => Notifications.clearLastNotificationResponseAsync?.()).catch(() => {});
      goFromAlert(() => open(r));
    };
    const open = (r: Notifications.NotificationResponse) => {
      const d = r.notification.request.content.data as { carId?: string; year?: number; mine?: boolean; make?: string; model?: string; screen?: 'loan' | 'miles' | 'value' | 'insure' | 'reminders' };
      if (d?.mine) {
        const i = carsRef.current.findIndex((c) => c.year === d.year && c.make === d.make && c.model === d.model);
        if (i >= 0) pickCar(i);
        if (d.screen === 'loan') router.push('/loan');
        else if (d.screen === 'value') router.push('/value');
        else if (d.screen === 'insure') router.push('/insure');
        else if (d.screen === 'reminders') router.push('/reminders');
        else if (d.screen === 'miles') router.push({ pathname: '/garage', params: { miles: '1' } });
        else router.push('/my-car');
      } else if (d?.carId) router.push({ pathname: '/car/[id]', params: { id: d.carId, year: String(d.year ?? LATEST_MODEL_YEAR), tab: 'Safety' } });
    };
    Notifications.getLastNotificationResponseAsync().then(handle).catch(() => {});
    const sub = Notifications.addNotificationResponseReceivedListener(handle);
    return () => sub.remove();
  }, [pickCar]);

  const setAlertsOn = useCallback(async (on: boolean) => {
    if (!uid) return 'Join free to get phone alerts.';
    setBusy(true);
    try {
      if (!on) {
        await supabase.from('push_tokens').update({ enabled: false }).eq('user_id', uid);
        setOn(false);
        return null;
      }
      const { token, error } = await phoneToken();
      if (!token) return error ?? 'Couldn’t turn on alerts.';
      const { error: dbErr } = await supabase.from('push_tokens').upsert({ token, user_id: uid, enabled: true, platform: Platform.OS === 'ios' ? 'ios' : 'android', updated_at: new Date().toISOString() });
      if (dbErr) return 'Couldn’t save your alert setting. Check your internet and try again.';
      setOn(true);
      return null;
    } finally {
      setBusy(false);
    }
  }, [uid, setOn]);

  const value = useMemo(() => ({ alertsOn, busy, setAlertsOn }), [alertsOn, busy, setAlertsOn]);
  return <AlertsCtx.Provider value={value}>{children}</AlertsCtx.Provider>;
}

export const useAlerts = () => useContext(AlertsCtx);
