// Free government car data, fetched on the phone:
//  - NHTSA (nhtsa.gov): recalls and crash-test star ratings
//  - EPA (fueleconomy.gov): miles per gallon
// Safety stars and MPG try the newest model year first, then the year before,
// because new models are often rated months after they go on sale.
// Recalls are only for the exact model year shown.

import snapshot from './facts-snapshot.json';
import { onPullClear } from '@/lib/refresh';
import { LATEST_MODEL_YEAR } from '@/data/year';

export type Recall = { id: string; part: string; summary: string; risk: string; fix: string; date: string };
export type Facts = {
  year?: number;
  stars?: number | null; // 1–5, null = not rated yet
  mpg?: { city: number; hwy: number; combined: number; fuel: string } | null;
  recalls?: Recall[] | null;
  source: { safety?: number; mpg?: number; recalls?: number }; // model year each fact came from
  saved?: string; // set when shown from the copy saved in the app (no internet)
};

// How each car is named in the government data. NHTSA uses different
