const SNAPSHOT = snapshot as unknown as { saved: string; cars: Record<string, Facts> };
const NHTSA = 'https://api.nhtsa.gov';
const EPA = 'https://www.fueleconomy.gov/ws/rest';

async function getJson(url: string): Promise<any> {
  const ctrl = new AbortController();
  const t = setTimeout(() => ctrl.abort(), 12000);
  try {
    const r = await fetch(url, { headers: { Accept: 'application/json' }, signal: ctrl.signal });
    // NHTSA answers "no recalls" with status 400 but a normal empty list, so read the body first.
    const j = await r.json().catch(() => null);
    if (!r.ok && !(j && (Array.isArray(j.results) || Array.isArray(j.Results)))) throw new Error(`HTTP ${r.status}`);
    return j;
  } finally {
    clearTimeout(t);
  }
}
const list = <T,>(x: T | T[] | undefined | null): T[] => (x == null ? [] : Array.isArray(x) ? x : [x]);
const enc = encodeURIComponent;

// ---- parsers (kept separate so they can be tested without the internet) ----
export function parseRecalls(j: any): Recall[] {
  return list(j?.results ?? j?.Results).map((r: any) => ({
    id: String(r.NHTSACampaignNumber ?? ''),
    part: String(r.Component ?? 'Part not listed'),
    summary: String(r.Summary ?? ''),
    risk: String(r.Consequence ?? ''),
    fix: String(r.Remedy ?? ''),
    date: String(r.ReportReceivedDate ?? ''),
  }));
}
export function parseStars(j: any): number | null {
  const v = Number(list(j?.Results)[0]?.OverallRating);
  return v >= 1 && v <= 5 ? v : null;
}
export function pickEpaModel(j: any, re: RegExp): string | undefined {
  return list<any>(j?.menuItem).map((m) => String(m.value ?? m.text)).find((m) => re.test(m));
}
export function parseMpg(j: any) {
  const city = Number(j?.city08), hwy = Number(j?.highway08), combined = Number(j?.comb08);
  if (!combined) return null;
  return { city, hwy, combined, fuel: String(j?.atvType && j.atvType !== 'null' ? j.atvType : j?.fuelType1 ?? 'Gas') };
}

// ---- lookups ----
async function recalls(n: Names, year: number) {
  const all = await Promise.all(n.recall.map((m) =>
    getJson(`${NHTSA}/recalls/recallsByVehicle?make=${enc(n.make)}&model=${enc(m)}&modelYear=${year}`).then(parseRecalls)));
  const seen = new Set<string>();
  return all.flat().filter((r) => !seen.has(r.id) && seen.add(r.id));
}
async function stars(n: Names, year: number) {
  let tested = false;
  for (const m of n.safety) {
    const v = list<any>((await getJson(`${NHTSA}/SafetyRatings/modelyear/${year}/make/${enc(n.make)}/model/${enc(m)}`))?.Results);
    if (!v.length) continue;
    tested = true;
    const ratings = await Promise.all(v.slice(0, 3).map((x) => getJson(`${NHTSA}/SafetyRatings/VehicleId/${x.VehicleId}`).then(parseStars).catch(() => null)));
    const best = ratings.filter((r): r is number => r != null);
    if (best.length) return Math.max(...best);
  }
  return tested ? null : undefined; // null = tested but no overall rating; undefined = not tested this year
}
async function mpg(n: Names, year: number) {
  const models = await getJson(`${EPA}/vehicle/menu/model?year=${year}&make=${enc(n.epaMake)}`);
  const model = pickEpaModel(models, n.epaModel);
  if (!model) return undefined;
  const opts = list<any>((await getJson(`${EPA}/vehicle/menu/options?year=${year}&make=${enc(n.epaMake)}&model=${enc(model)}`))?.menuItem);
  if (!opts.length) return undefined;
  // Prefer the regular gas or hybrid engine over diesel or plug-in versions.
  const pick = opts.find((o) => !/diesel|phev|plug-in/i.test(String(o.text))) ?? opts[0];
  return parseMpg(await getJson(`${EPA}/vehicle/${pick.value}`));
}

async function firstYear<T>(years: number[], fn: (year: number) => Promise<T | undefined>): Promise<{ v: T; year: number } | null> {
  for (const y of years) {
    try {
      const v = await fn(y);
      if (v !== undefined) return { v, year: y };
    } catch {
      // try the next year
    }
  }
  return null;
}

const cache = new Map<string, Promise<Facts>>();
onPullClear(() => cache.clear());
export function getFacts(carId: string, year = LATEST_MODEL_YEAR): Promise<Facts> {
  const key = `${carId}-${year}`;
  const years = [year, year - 1];
  const n = GOV_NAMES[carId];
  if (!n) return Promise.resolve({ source: {} });
  if (!cache.has(key)) {
    const p = (async () => {
      const [s, m, r] = await Promise.all([firstYear(years, (y) => stars(n, y)), firstYear(years, (y) => mpg(n, y)), recalls(n, year).then((v) => ({ v, year })).catch(() => null)]);
      if (!s && !m && !r) {
        // No internet (or the services are down): use the copy saved in the app.
        const snap = SNAPSHOT.cars[key];
        if (snap) return { ...snap, saved: SNAPSHOT.saved } as Facts;
      }
      return {
        stars: s ? s.v : undefined,
        mpg: m ? m.v : undefined,
        recalls: r ? r.v : undefined,
        source: { safety: s?.year, mpg: m?.year, recalls: r?.year },
      } as Facts;
    })();
    p.catch(() => cache.delete(key));
    cache.set(key, p);
  }
  return cache.get(key)!;
}

// Recalls for any car the user owns (typed by them), e.g. "2020 Chevy Trax".
const MAKE_ALIAS: Record<string, string> = { chevy: 'CHEVROLET', vw: 'VOLKSWAGEN', mercedes: 'MERCEDES-BENZ', benz: 'MERCEDES-BENZ', 'land rover': 'LAND ROVER', landrover: 'LAND ROVER' };
export async function recallsForMyCar(make: string, model: string, year: number): Promise<Recall[]> {
  const mk = MAKE_ALIAS[make.trim().toLowerCase()] ?? make.trim().toUpperCase();
  const md = model.trim().toUpperCase();
  return parseRecalls(await getJson(`${NHTSA}/recalls/recallsByVehicle?make=${enc(mk)}&model=${enc(md)}&modelYear=${year}`));
}

// All models a brand sells in a year, from NHTSA vPIC (free, no key). Big work trucks and
// bare chassis are left out. Saved in memory so we ask only once.
const VPIC = 'https://vpic.nhtsa.dot.gov/api/vehicles';
const modelCache = new Map<string, string[]>();
const WORK_TRUCK = /^\d|\b(HD|HG|XD|XG|Chassis|Cutaway|Stripped|Cab Forward|BrightDrop|Express|Savana|Transit|ProMaster|Sprinter|LCF|Low Cab)\b/i;
export async function modelsFor(make: string, year: number): Promise<string[]> {
  const key = `${make}|${year}`;
  if (modelCache.has(key)) return modelCache.get(key)!;
  const j = await getJson(`${VPIC}/GetModelsForMakeYear/make/${enc(make)}/modelyear/${year}?format=json`);
  const names = [...new Set(list<{ Model_Name: string }>(j?.Results).map((r) => r.Model_Name.trim()))]
    .filter((n) => n && !WORK_TRUCK.test(n)).sort((a, b) => a.localeCompare(b));
  modelCache.set(key, names);
  return names;
}

/** Saved crash stars, mileage and recalls for a car, the closest year we have, without going online (Home rows). */
export function savedFacts(carId: string, year: number): Facts | undefined {
  const keys = Object.keys(SNAPSHOT.cars).filter((k) => k.startsWith(`${carId}-`));
  if (!keys.length) return undefined;
  const best = keys.reduce((a, b) => (Math.abs(Number(b.split('-').pop()) - year) < Math.abs(Number(a.split('-').pop()) - year) ? b : a));
  return SNAPSHOT.cars[best];
}

/** What kind of vehicle a model is, from NHTSA's free list (coach picture 185): 'mpv' = SUV or van,
 * 'car' = sedan/hatchback/coupe, 'truck' = pickup. null when NHTSA doesn't know it or can't be reached. */
export async function vpicTypeOf(make: string, year: number, model: string): Promise<'mpv' | 'car' | 'truck' | null> {
  const want = model.trim().toLowerCase();
  const types: [string, 'mpv' | 'car' | 'truck'][] = [['Multipurpose Passenger Vehicle (MPV)', 'mpv'], ['Passenger Car', 'car'], ['Truck', 'truck']];
  for (const [t, k] of types) {
    const j = await getJson(`${VPIC}/GetModelsForMakeYear/make/${enc(make)}/modelyear/${year}/vehicletype/${enc(t)}?format=json`).catch(() => null);
    if (list<{ Model_Name: string }>(j?.Results).some((r) => r.Model_Name.trim().toLowerCase() === want)) return k;
  }
  return null;
}
