// Last mileage reported (picture 150 · 3, Oct 26, 2026): miles people type in the VIN scanner, shared with no name
// (Supabase table vin_miles, migration 015, used only through two functions). Any error = nothing shown.
import { supabase } from '@/lib/supabase';

// maxReporters = how many different members reported the highest miles (Nov 4, 2026; older server: undefined).
export type MilesReport = { lastMiles: number; lastAt: string; maxMiles: number; maxAt: string; maxReporters?: number };

export async function lastMiles(vin: string): Promise<MilesReport | null> {
  const { data, error } = await supabase.rpc('vin_miles_last', { p_vin: vin });
  const r = !error && Array.isArray(data) ? data[0] : null;
  return r && r.last_miles != null ? { lastMiles: r.last_miles, lastAt: r.last_at, maxMiles: r.max_miles, maxAt: r.max_at, maxReporters: r.max_reporters ?? undefined } : null;
}

// Only signed-in members can report (Nov 4, 2026): the server ignores anyone else, so we don't even try.
export async function reportMiles(vin: string, miles: number): Promise<void> {
  const { data } = await supabase.auth.getSession().catch(() => ({ data: { session: null } }));
  if (!data.session) return;
  await supabase.rpc('vin_miles_report', { p_vin: vin, p_miles: Math.round(miles) }).then(() => {}, () => {});
}

/** Odometers don't go back: a number clearly under the highest report (more than 500 miles) gets a heads-up, but only
 *  when 2+ different members reported those higher miles, so one wrong or fake reading can't flag an honest car. */
export function milesWentDown(now: number | null | undefined, r: MilesReport | null): boolean {
  return !!r && now != null && now > 0 && r.maxMiles - now > 500 && (r.maxReporters ?? 0) >= 2;
}

export const shortDate = (iso: string) => new Date(iso).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
