// Picture 237 (Nov 13, 2026, Loudjier: "Build" after 1B + 2C + 3B): "Which version to get" is one switch.
// Tap a version: its photo stage, our checked note, the estimates, and two buttons: Compare versions
// (face to face) and Buy this version (the road to your car). Version notes come from data/guide*.ts
// (our own checked words); we never make up features per version.
import { router } from 'expo-router';
import { useState } from 'react';
import { ScrollView, StyleSheet, View } from 'react-native';
import Svg, { Polygon } from 'react-native-svg';

import { CarCutout } from '@/components/car-photo';
import { Pressable, Text } from '@/components/t';
import { tap } from '@/components/ui';
import type { Car } from '@/data/cars';
import type { Guide } from '@/data/guide';
import { priceFor } from '@/data/prices';
import { loanOf } from '@/data/search-budget';
import { paymentFor, useAnswers } from '@/state/answers';
import { C, F, isDarkLook, look, themed } from '@/theme';

export const money = (n: number) => `$${Math.round(n).toLocaleString('en-US')}`;

/** The version people should look at first: our "best value" one, else the first. */
export const firstVersion = (g: Guide) => Math.max(0, g.trims.findIndex((t) => t.best));

export function VStage({ id, year, height, label }: { id: string; year: number; height: number; label: string }) {
  const night = isDarkLook(look);
  return (
    <View style={[s.stage, { height }]}>
      <Svg viewBox="0 0 100 92" style={s.v} pointerEvents="none">
        <Polygon fill={night ? '#E8CFA4' : '#E3CFA2'} opacity={night ? 0.22 : 0.6} points="0,0 27,0 52,70 40,92" />
        <Polygon fill={night ? '#E8CFA4' : '#E3CFA2'} opacity={night ? 0.22 : 0.6} points="100,0 73,0 48,70 60,92" />
      </Svg>
      <View style={{ position: 'absolute', left: 0, right: 0, bottom: 8, alignItems: 'center' }}>
        <CarCutout id={id} year={year} label={label} height={height - 30} style={{ width: '88%' }} flat />
      </View>
    </View>
  );
}

export function VersionTabs({ car, year, guide }: { car: Car; year: number; guide: Guide }) {
  const { answers } = useAnswers();
  const [i, setI] = useState(firstVersion(guide));
  const t = guide.trims[i] ?? guide.trims[0];
  const p = priceFor(car, year);
  const pay = p ? paymentFor(loanOf(answers), p.amount, p.isNew) : undefined;
  const other = guide.trims.findIndex((_, k) => k !== i);
  const night = isDarkLook(look);
  return (
    <View>
      <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={s.seg}>
        {guide.trims.map((x, k) => (
          <Pressable key={x.name} onPress={() => { tap(); setI(k); }} accessibilityRole="tab" accessibilityState={{ selected: k === i }}
            style={[s.segBtn, k === i && s.segOn]}>
            <Text style={[s.segT, k === i && s.segTOn]} numberOfLines={1}>{x.name}</Text>
          </Pressable>
        ))}
      </ScrollView>
      <View style={{ marginTop: 10 }}>
        <VStage id={car.id} year={year} height={170} label={`${car.make} ${car.model} ${t.name}`} />
        <Text style={s.yr}>{`${year} · ${t.name}`.toUpperCase()}</Text>
      </View>
      <View style={s.head}>
        <Text style={s.name}>{t.name}</Text>
        {t.best && <View style={[s.best, { backgroundColor: night ? '#9CC0F7' : '#1F5FBF' }]}><Text style={[s.bestT, { color: night ? '#0D1626' : '#fff' }]}>Best value</Text></View>}
      </View>
      <Text style={s.note}>{t.text[0]}</Text>
      {p && (
        <View style={s.prc}>
          <View style={s.box}><Text style={s.small}>{p.isNew ? 'Starting price, new' : 'Used price, est.'}</Text><Text style={s.big}>{money(p.amount)}</Text></View>
          {pay != null && <View style={s.box}><Text style={s.small}>Monthly, est.</Text><Text style={[s.big, { color: C.goodInk }]}>{`≈ ${money(pay)}`}</Text></View>}
        </View>
      )}
      <Text style={s.foot}>Prices are for the car, not this version. The dealer has the full list of what each version includes.</Text>
      <View style={s.btns}>
        {other >= 0 && (
          <Pressable onPress={() => { tap(); router.push({ pathname: '/versions', params: { id: car.id, year: String(year), a: t.name, b: guide.trims[other === i ? 0 : other].name } }); }}
            accessibilityRole="button" style={[s.btn, s.sec]}>
            <Text style={[s.btnT, { color: C.onAccent }]} numberOfLines={1}>Compare versions</Text>
          </Pressable>
        )}
        <Pressable onPress={() => { tap(); router.push({ pathname: '/buy-road', params: { id: car.id, year: String(year), trim: t.name } }); }}
          accessibilityRole="button" style={[s.btn, s.pri]}>
          <Text style={[s.btnT, { color: night ? '#0D1626' : '#fff' }]} numberOfLines={1}>Buy this version</Text>
        </Pressable>
      </View>
    </View>
  );
}

const s = themed(() => StyleSheet.create({
  seg: { gap: 6, backgroundColor: C.grey, borderRadius: 14, padding: 4 },
  segBtn: { paddingHorizontal: 14, paddingVertical: 9, borderRadius: 11, minWidth: 70, alignItems: 'center' },
  segOn: { backgroundColor: C.fill, shadowColor: '#000', shadowOpacity: 0.06, shadowRadius: 4, shadowOffset: { width: 0, height: 2 }, elevation: 1 },
  segT: { fontFamily: F.bodyBold, fontSize: 14, color: C.muted },
  segTOn: { color: C.onAccent },
  stage: { borderRadius: 22, overflow: 'hidden', backgroundColor: isDarkLook(look) ? '#1D1C1A' : '#F4EFE4' },
  v: { position: 'absolute', left: '28%', top: 6, width: '44%', aspectRatio: 100 / 92 },
  yr: { position: 'absolute', top: 10, left: 12, fontFamily: F.logo, fontSize: 10.5, letterSpacing: 1.2, color: isDarkLook(look) ? '#E8CFA4' : '#86652B' },
  head: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', gap: 8, marginTop: 12 },
  name: { flex: 1, fontFamily: F.head, fontSize: 20, color: C.ink },
  best: { borderRadius: 999, paddingHorizontal: 10, paddingVertical: 3 },
  bestT: { fontFamily: F.bodyBold, fontSize: 11.5 },
  note: { fontFamily: F.body, fontSize: 15, lineHeight: 21, color: C.ink, marginTop: 4 },
  prc: { flexDirection: 'row', gap: 10, marginTop: 12 },
  box: { flex: 1, backgroundColor: C.card, borderRadius: 14, padding: 10, borderWidth: 1, borderColor: C.line },
  small: { fontFamily: F.body, fontSize: 11.5, color: C.muted },
  big: { fontFamily: F.head, fontSize: 17, color: C.ink, marginTop: 2 },
  foot: { fontFamily: F.body, fontSize: 11.5, lineHeight: 16, color: C.muted, marginTop: 8 },
  btns: { flexDirection: 'row', gap: 8, marginTop: 12 },
  btn: { flex: 1, borderRadius: 999, paddingVertical: 12, alignItems: 'center', justifyContent: 'center' },
  sec: { backgroundColor: C.fill },
  pri: { backgroundColor: isDarkLook(look) ? '#9CC0F7' : '#1F5FBF' },
  btnT: { fontFamily: F.bodyBold, fontSize: 14 },
}));
