// Delete my account (picture 29, steps 3 and 4, picked Oct 12, 2026). Apple requires it.
// Step 3: "Are you sure?" lists what goes away; the person types DELETE so nobody does it by mistake.
// Step 4: "Your account is deleted". Saved cars stay on this phone and the app keeps working as a guest.
import { router } from 'expo-router';
import { useState } from 'react';
import { ActivityIndicator, Modal, StyleSheet, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

import { CheckIcon } from '@/components/icons';
import { Body, Btn, H, tap } from '@/components/ui';
import { useAuth } from '@/state/auth';
import { C, F, PAD, themed } from '@/theme';
import { KeyboardSheet } from '@/components/keyboard-sheet';
import { Pressable, Text } from '@/components/t';

const GOES = ['Your account, email and name', 'Your reviews', 'Your saved cars on our server', 'Your phone alerts'];

export function DeleteAccount({ onClose }: { onClose: () => void }) {
  const { deleteAccount } = useAuth();
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [done, setDone] = useState(false);
  const ok = true;

  const go = async () => {
    if (!ok || busy) return;
    tap();
    setBusy(true);
    setError(null);
    const err = await deleteAccount();
    setBusy(false);
    if (err) return setError(err);
    setDone(true);
  };

  if (done) {
    return (
      <Modal visible animationType="fade" onRequestClose={() => { onClose(); router.navigate('/home'); }}>
        <SafeAreaView style={s.done}>
          <View style={s.check}><CheckIcon size={38} color={C.goodInk} /></View>
          <H size={32} style={{ textAlign: 'center' }}>Your account is deleted</H>
          <Body style={{ color: C.muted, textAlign: 'center', marginTop: 10, lineHeight: 22 }}>
            Thanks for trying Carvessa. Your saved cars stay on this phone. You can keep using the app as a guest.
          </Body>
          <Btn kind="yellow" label="Back to Home" style={{ marginTop: 24, alignSelf: 'stretch' }} onPress={() => { onClose(); router.navigate('/home'); }} />
        </SafeAreaView>
      </Modal>
    );
  }

  return (
    <Modal transparent visible animationType="slide" onRequestClose={onClose}>
      <KeyboardSheet onClose={onClose} backStyle={s.back} sheetStyle={s.sheet}>
          <View style={s.grab} />
          <H size={30}>Delete your account?</H>
          <Body style={{ marginTop: 2 }}>This can’t be undone. We will delete:</Body>
          {GOES.map((g) => (
            <View key={g} style={s.li}><Text style={s.x}>✕</Text><Body style={{ flex: 1 }}>{g}</Body></View>
          ))}
          <Pressable onPress={() => { tap(); onClose(); }} style={s.keepDark} accessibilityRole="button"><Text style={s.keepDarkT}>Keep my account</Text></Pressable>
          <Btn kind="outline" label="✎ Edit my profile instead" onPress={() => { onClose(); router.push('/profile'); }} />
          {!!error && <Text style={s.error} accessibilityLiveRegion="polite">{error}</Text>}
          {busy ? <ActivityIndicator color={C.red} style={{ height: 52 }} /> : (
            <Pressable onPress={go} style={s.redOutline} accessibilityRole="button">
              <Text style={s.redOutlineT}>Yes, delete my account</Text>
            </Pressable>
          )}
        </KeyboardSheet>
    </Modal>
  );
}

const s = themed(() => StyleSheet.create({
  back: { flex: 1, backgroundColor: 'rgba(0,0,0,0.55)' },
  keepDark: { backgroundColor: C.ink, borderRadius: 16, minHeight: 52, alignItems: 'center', justifyContent: 'center', marginTop: 8 },
  keepDarkT: { fontFamily: F.bodyBold, fontSize: 16, color: C.bg },
  redOutline: { borderWidth: 1.5, borderColor: C.red, borderRadius: 16, minHeight: 52, alignItems: 'center', justifyContent: 'center' },
  redOutlineT: { fontFamily: F.bodyBold, fontSize: 16, color: C.red },
  sheet: { backgroundColor: C.card, borderTopLeftRadius: 22, borderTopRightRadius: 22, borderTopWidth: 1, borderColor: C.line, padding: 20, paddingBottom: 30, gap: 8 },
  grab: { width: 40, height: 5, borderRadius: 3, backgroundColor: C.line, alignSelf: 'center', marginBottom: 6 },
  li: { flexDirection: 'row', gap: 8, alignItems: 'center' },
  x: { fontFamily: F.bodyBold, color: C.red, fontSize: 15, width: 16 },
  input: { height: 52, borderRadius: 12, borderWidth: 1.5, borderColor: C.line, backgroundColor: C.bg, paddingHorizontal: 14, fontFamily: F.bodyBold, fontSize: 16, color: C.ink, letterSpacing: 1 },
  error: { fontFamily: F.bodyBold, fontSize: 13.5, color: C.red },
  red: { height: 54, borderRadius: 14, backgroundColor: C.red, alignItems: 'center', justifyContent: 'center', marginTop: 4 },
  redText: { fontFamily: F.bodyBold, fontSize: 16, color: '#FFFFFF' },
  done: { flex: 1, backgroundColor: C.bg, alignItems: 'center', justifyContent: 'center', paddingHorizontal: PAD + 8 },
  check: { width: 76, height: 76, borderRadius: 38, backgroundColor: C.goodBg, alignItems: 'center', justifyContent: 'center', marginBottom: 18 },
}));
