// One "Sort" button that opens the choices in a small sheet (Loudjier, Nov 13, 2026: "Create a sort button with
// the options"). Replaces a row of sort chips. The button shows the sort that's on now.
import { useState } from 'react';
import { Modal, StyleSheet, View } from 'react-native';
import Svg, { Path } from 'react-native-svg';

import { Pressable, Text } from '@/components/t';
import { tap } from '@/components/ui';
import { tr } from '@/i18n';
import { C, F, isDarkLook, look, themed } from '@/theme';

export function SortButton<T extends string>({ options, value, onChange }: { options: readonly T[]; value: T; onChange: (v: T) => void }) {
  const [open, setOpen] = useState(false);
  const pick = (v: T) => { tap(); onChange(v); setOpen(false); };
  return (
    <>
      <Pressable onPress={() => { tap(); setOpen(true); }} accessibilityRole="button" accessibilityLabel={`${tr('Sort')}: ${tr(value)}`} style={s.btn}>
        <Svg width={16} height={16} viewBox="0 0 24 24" fill="none" stroke={C.ink} strokeWidth={2.2} strokeLinecap="round" strokeLinejoin="round">
          <Path d="M7 4v16M7 20l-3-3M7 20l3-3M17 20V4M17 4l-3 3M17 4l3 3" />
        </Svg>
        <Text style={s.btnL}>Sort:</Text>
        <Text style={s.btnV} numberOfLines={1}>{value}</Text>
        <Svg width={14} height={14} viewBox="0 0 24 24" fill="none" stroke={C.muted} strokeWidth={2.4} strokeLinecap="round" strokeLinejoin="round"><Path d="M6 9l6 6 6-6" /></Svg>
      </Pressable>
      <Modal visible={open} transparent animationType="fade" onRequestClose={() => setOpen(false)}>
        <Pressable style={s.dim} onPress={() => setOpen(false)} accessibilityLabel={tr('Close')} />
        <View style={s.sheet} accessibilityViewIsModal>
          <View style={s.grab} />
          <Text style={s.title} accessibilityRole="header">Sort by</Text>
          {options.map((o) => {
            const on = o === value;
            return (
              <Pressable key={o} onPress={() => pick(o)} accessibilityRole="radio" accessibilityState={{ checked: on }} style={[s.row, on && s.rowOn]}>
                <Text style={[s.rowT, on && { color: C.onAccent }]}>{o}</Text>
                <View style={[s.radio, on && { borderColor: C.onAccent }]}>{on && <View style={[s.dot, { backgroundColor: C.onAccent }]} />}</View>
              </Pressable>
            );
          })}
        </View>
      </Modal>
    </>
  );
}

const s = themed(() => StyleSheet.create({
  btn: { flexDirection: 'row', alignItems: 'center', gap: 6, alignSelf: 'flex-start', backgroundColor: C.card, borderRadius: 999, paddingHorizontal: 14, paddingVertical: 9, borderWidth: 1, borderColor: C.line, maxWidth: '100%' },
  btnL: { fontFamily: F.body, fontSize: 14, color: C.muted },
  btnV: { fontFamily: F.bodyBold, fontSize: 14, color: C.ink, flexShrink: 1 },
  dim: { position: 'absolute', top: 0, left: 0, right: 0, bottom: 0, backgroundColor: 'rgba(10,15,25,0.45)' },
  sheet: { position: 'absolute', left: 0, right: 0, bottom: 0, backgroundColor: isDarkLook(look) ? '#16171C' : C.card, borderTopLeftRadius: 24, borderTopRightRadius: 24, padding: 18, paddingBottom: 34 },
  grab: { alignSelf: 'center', width: 44, height: 5, borderRadius: 3, backgroundColor: C.line, marginBottom: 12 },
  title: { fontFamily: F.head, fontSize: 19, color: C.ink, marginBottom: 8 },
  row: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', paddingVertical: 14, paddingHorizontal: 14, borderRadius: 14, marginTop: 4 },
  rowOn: { backgroundColor: C.fill },
  rowT: { fontFamily: F.bodyBold, fontSize: 16, color: C.ink },
  radio: { width: 22, height: 22, borderRadius: 11, borderWidth: 2, borderColor: C.line, alignItems: 'center', justifyContent: 'center' },
  dot: { width: 11, height: 11, borderRadius: 6 },
}));
