// A simple map we draw ourselves from OpenStreetMap tiles (Oct 15, 2026, real cars step 1), so it
// works on phones and the web without a new app build. Drag to move, + and − to zoom.
// Test use only: OpenStreetMap's own tile servers are for light use. Before the public launch,
// point TILE at a tile service with a plan (for example MapTiler or Stadia). Keep the credit.
import { useEffect, useState, type ReactNode } from 'react';
import { Image, Linking, PanResponder, StyleSheet, View } from 'react-native';

import { tap } from '@/components/ui';
import { C, F, theme } from '@/theme';
import { Pressable, Text } from '@/components/t';

const SIZE = 256;
// Oct 24, 2026: OpenStreetMap started blocking the app ("Access blocked" tiles on Android). Geoapify's free
// plan allows apps (with its credit). Its map key is made for apps; Loudjier adds it as the Expo
// environment variable EXPO_PUBLIC_GEOAPIFY_KEY (never in git). Until then we fall back to OpenStreetMap.
const GEO_KEY = process.env.EXPO_PUBLIC_GEOAPIFY_KEY;
const TILE = (z: number, x: number, y: number) => GEO_KEY
  ? `https://maps.geoapify.com/v1/tile/osm-bright/${z}/${x}/${y}.png?apiKey=${GEO_KEY}`
  : `https://tile.openstreetmap.org/${z}/${x}/${y}.png`;
const HEADERS = { 'User-Agent': 'Carvessa/1.0 (carvessa.app)' };
export const MIN_Z = 7;
export const MAX_Z = 14;

export type LatLon = { lat: number; lon: number };
export type Proj = (lat: number, lon: number) => { x: number; y: number };

export function ll2px(lat: number, lon: number, z: number) {
  const n = SIZE * 2 ** z;
  const s = Math.sin((lat * Math.PI) / 180);
  return { x: ((lon + 180) / 360) * n, y: (0.5 - Math.log((1 + s) / (1 - s)) / (4 * Math.PI)) * n };
}
export function px2ll(x: number, y: number, z: number): LatLon {
  const n = SIZE * 2 ** z;
  const lon = (x / n) * 360 - 180;
  const lat = (Math.atan(Math.sinh(Math.PI * (1 - (2 * y) / n))) * 180) / Math.PI;
  return { lat, lon };
}
// Pixels for this many miles going north from a spot (for drive-time circles).
export function milesToPx(miles: number, at: LatLon, z: number) {
  const a = ll2px(at.lat, at.lon, z);
  const b = ll2px(at.lat + miles / 69, at.lon, z);
  return Math.abs(a.y - b.y);
}

type Props = {
  width: number;
  height: number;
  center: LatLon;
  zoom: number;
  // Called after the person drags or zooms, with the new middle of the map.
  onMoved?: (center: LatLon, zoom: number) => void;
  children?: (proj: Proj, zoom: number) => ReactNode;
  controlsTop?: number;
};

export function TileMap({ width, height, center, zoom, onMoved, children, controlsTop = 70 }: Props) {
  const dark = theme === 'midnight';
  const [z, setZ] = useState(zoom);
  const [mid, setMid] = useState(() => ll2px(center.lat, center.lon, zoom));
  const [drag, setDrag] = useState({ dx: 0, dy: 0 });
  // The parent moves the map (a new search): follow it.
  const [given, setGiven] = useState(`${center.lat},${center.lon},${zoom}`);
  const now = `${center.lat},${center.lon},${zoom}`;
  if (now !== given) {
    setGiven(now);
    setZ(zoom);
    setMid(ll2px(center.lat, center.lon, zoom));
  }

  // The drag handler is made once, so it only uses state setters. After a drag ends, `done`
  // changes and the effect below tells the parent where the map is now.
  const [done, setDone] = useState(0);
  const [pan] = useState(() => PanResponder.create({
    onMoveShouldSetPanResponder: (_e, g) => Math.abs(g.dx) + Math.abs(g.dy) > 6,
    onPanResponderMove: (_e, g) => setDrag({ dx: g.dx, dy: g.dy }),
    onPanResponderRelease: (_e, g) => {
      setMid((m) => ({ x: m.x - g.dx, y: m.y - g.dy }));
      setDrag({ dx: 0, dy: 0 });
      setDone((n) => n + 1);
    },
    onPanResponderTerminate: () => setDrag({ dx: 0, dy: 0 }),
  }));
  useEffect(() => {
    if (done) onMoved?.(px2ll(mid.x, mid.y, z), z);
  }, [done]); // eslint-disable-line react-hooks/exhaustive-deps

  const zoomBy = (d: number) => {
    const nz = Math.max(MIN_Z, Math.min(MAX_Z, z + d));
    if (nz === z) return;
    tap();
    const k = 2 ** (nz - z);
    const next = { x: mid.x * k, y: mid.y * k };
    setZ(nz);
    setMid(next);
    onMoved?.(px2ll(next.x, next.y, nz), nz);
  };

  const ox = mid.x - width / 2 - drag.dx;
  const oy = mid.y - height / 2 - drag.dy;
  const n = 2 ** z;
  const tiles: ReactNode[] = [];
  for (let tx = Math.floor(ox / SIZE); tx <= Math.floor((ox + width) / SIZE); tx++) {
    for (let ty = Math.floor(oy / SIZE); ty <= Math.floor((oy + height) / SIZE); ty++) {
      if (ty < 0 || ty >= n) continue;
      const wx = ((tx % n) + n) % n;
      tiles.push(<Image key={`${z}/${tx}/${ty}`} source={{ uri: TILE(z, wx, ty), headers: HEADERS }} fadeDuration={0}
        style={{ position: 'absolute', left: tx * SIZE - ox, top: ty * SIZE - oy, width: SIZE, height: SIZE }} />);
    }
  }
  const proj: Proj = (lat, lon) => { const p = ll2px(lat, lon, z); return { x: p.x - ox, y: p.y - oy }; };

  return (
    <View style={{ width, height, overflow: 'hidden', backgroundColor: dark ? '#0F131A' : '#E8E6E1' }} {...pan.panHandlers}>
      {tiles}
      {/* Softens the map so prices stand out; darker in Midnight. */}
      <View pointerEvents="none" style={[StyleSheet.absoluteFill, { backgroundColor: dark ? 'rgba(10,14,21,0.58)' : 'rgba(246,245,242,0.32)' }]} />
      {children?.(proj, z)}
      <View style={[s.zoom, { top: controlsTop, backgroundColor: C.card, borderColor: C.line }]}>
        <Pressable onPress={() => zoomBy(1)} accessibilityRole="button" accessibilityLabel="Zoom in" style={s.zBtn}><Text style={[s.zTxt, { color: C.ink }]}>+</Text></Pressable>
        <View style={{ height: 1, backgroundColor: C.line }} />
        <Pressable onPress={() => zoomBy(-1)} accessibilityRole="button" accessibilityLabel="Zoom out" style={s.zBtn}><Text style={[s.zTxt, { color: C.ink }]}>−</Text></Pressable>
      </View>
      <Pressable onPress={() => Linking.openURL('https://www.openstreetmap.org/copyright').catch(() => {})} accessibilityRole="link"
        style={[s.credit, { backgroundColor: dark ? 'rgba(10,14,21,0.7)' : 'rgba(255,255,255,0.8)' }]}>
        <Text style={{ fontFamily: F.body, fontSize: 10, color: C.muted }}>{GEO_KEY ? 'Powered by Geoapify · © OpenStreetMap' : '© OpenStreetMap'}</Text>
      </Pressable>
    </View>
  );
}

const s = StyleSheet.create({
  zoom: { position: 'absolute', right: 10, width: 40, borderRadius: 12, borderWidth: 1, overflow: 'hidden' },
  zBtn: { height: 40, alignItems: 'center', justifyContent: 'center' },
  zTxt: { fontFamily: F.bodyBold, fontSize: 22, lineHeight: 26 },
  credit: { position: 'absolute', right: 0, bottom: 0, paddingHorizontal: 6, paddingVertical: 2, borderTopLeftRadius: 6 },
});
