// The Sunset Calm sky (design C, Oct 17–18, 2026): a sky with the Atlanta skyline on top of the main screens.
// It follows the time of day where the person lives (sunrise and sunset from their ZIP, Atlanta until we
// know it): morning, day, evening (the sunset) and night with stars and lit windows. Me › Sky can keep
// it on the sunset all the time. The gold V sun only shows on the Welcome screen (Loudjier, Oct 17).
import { LinearGradient } from 'expo-linear-gradient';
import { useEffect, useState } from 'react';
import { AppState, StyleSheet, useWindowDimensions, View, type ViewStyle } from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import Svg, { Circle, Defs, LinearGradient as SvgGradient, Polygon, RadialGradient, Rect, Stop } from 'react-native-svg';

import { V_LEFT, V_RIGHT } from '@/components/brand';
import { BackIcon } from '@/components/icons';
import { zipToPlace } from '@/data/dealers';
import { ATLANTA, dayLookAt, type DayLook, isDarkAt, phaseAt, type SkyPhase } from '@/data/sun';
import { lastSpot } from '@/lib/location';
import { useAnswers } from '@/state/answers';
import { useSaved } from '@/state/saved';
import { C, F, PAD, skyLook, themed } from '@/theme';
import { Pressable, Text } from '@/components/t';

type SkyLook = { colors: [string, string, string, string]; city: string; ink: string; soft: string };
export const SKIES: Record<SkyPhase, SkyLook> = {
  morning: { colors: ['#8CC9D9', '#BFE3D9', '#FFE3C2', '#FFD3A8'], city: '#2F5E57', ink: '#1D2B24', soft: '#1F6E4E' },
  day: { colors: ['#6FB8E0', '#A9DAEE', '#DDF1EE', '#EEF7EE'], city: '#3E6E66', ink: '#1D2B24', soft: '#1F6E4E' },
  evening: { colors: ['#6F4BA8', '#C46A8E', '#FF9B7A', '#FFC896'], city: '#3A2346', ink: '#FFFFFF', soft: '#D7F2E1' },
  night: { colors: ['#0B1026', '#1C1F4A', '#3A2F63', '#5A3D6E'], city: '#05060F', ink: '#FFFFFF', soft: '#D7F2E1' },
};
const STOPS = [0, 0.42, 0.75, 1] as const;

// Where the person is, for sunrise and sunset. Looked up once per ZIP.
const places = new Map<string, { lat: number; lon: number }>();

/** Where they are for sunrise and sunset: their last 'Use my location' spot, else their ZIP, else Atlanta. Re-checks every minute. */
export function useSunPlace() {
  const { answers } = useAnswers();
  const zip = answers.zip && /^\d{5}$/.test(answers.zip) ? answers.zip : '';
  const [, setFound] = useState(0);
  const [now, setNow] = useState(() => new Date());
  useEffect(() => {
    const t = setInterval(() => setNow(new Date()), 60_000);
    // Opening the app again (e.g. in the morning) checks the clock right away, not up to a minute later.
    const sub = AppState.addEventListener('change', (st) => { if (st === 'active') setNow(new Date()); });
    return () => { clearInterval(t); sub.remove(); };
  }, []);
  useEffect(() => {
    if (!zip || places.has(zip)) return;
    let on = true;
    zipToPlace(zip).then((p) => { places.set(zip, { lat: p.lat, lon: p.lon }); if (on) setFound((n) => n + 1); }).catch(() => {});
    return () => { on = false; };
  }, [zip]);
  return { now, spot: lastSpot() ?? ((zip && places.get(zip)) || ATLANTA) };
}

/** Follow the day: which of the four looks it is now where they are (picture 133). Re-checks every minute. */
export function useDayLook(): DayLook {
  const { now, spot } = useSunPlace();
  return dayLookAt(now, spot.lat, spot.lon);
}

/** True when it's dark where they are (Loudjier, Oct 22, 2026: Clean turns to Clean night by the user's location). */
export function useSunDark() {
  const { now, spot } = useSunPlace();
  return isDarkAt(now, spot.lat, spot.lon);
}

/** The sky phase to draw now, and its text colors. Re-checks every minute. */
export function useSky() {
  const { prefs } = useSaved();
  const { now, spot } = useSunPlace();
  const phase: SkyPhase = prefs.sky === 'sunset' ? 'evening' : phaseAt(now, spot.lat, spot.lon);
  return { phase, ...SKIES[phase], light: phase === 'morning' || phase === 'day' };
}

// Buildings [x, width, height] in a 330-wide strip, plus two tall towers (the Atlanta look of design 6).
const BUILDINGS = [[0, 22, 27], [24, 24, 21], [50, 14, 52], [66, 15, 41], [83, 13, 50], [98, 18, 20], [118, 14, 45], [134, 25, 22], [161, 19, 23], [182, 25, 21], [209, 15, 32], [226, 13, 43], [241, 13, 32], [256, 13, 26], [271, 21, 44], [294, 16, 52], [312, 15, 37]];
// Lit windows at night: [x, height above the ground].
const WINDOWS = Array.from({ length: 46 }, (_, k) => [(k * 67 + 11) % 326, 6 + ((k * 29) % 40)]);
const STARS = Array.from({ length: 34 }, (_, k) => ({ x: ((k * 97) % 100) / 100, y: ((k * 61) % 70) / 100, r: k % 3 === 0 ? 1.5 : 1, o: [0.5, 0.8, 1][k % 3] }));

function Skyline({ width, height, color, lit }: { width: number; height: number; color: string; lit: boolean }) {
  const h = height;
  return (
    <Svg width={width} height={h} viewBox={`0 0 330 ${h}`} preserveAspectRatio="none" style={{ position: 'absolute', left: 0, bottom: 0 }}>
      {BUILDINGS.map(([x, w, bh]) => <Rect key={x} x={x} y={h - bh} width={w} height={bh} fill={color} />)}
      <Rect x={200} y={h - 66} width={18} height={66} fill={color} />
      <Polygon points={`200,${h - 66} 209,${h - 82} 218,${h - 66}`} fill={color} />
      <Rect x={208} y={h - 90} width={2} height={10} fill={color} />
      <Rect x={96} y={h - 58} width={16} height={58} fill={color} />
      <Rect x={99} y={h - 64} width={10} height={6} fill={color} />
      {lit && WINDOWS.map(([x, y], k) => <Rect key={k} x={x} y={h - y} width={2} height={3} fill="#FFD27A" opacity={0.85} />)}
    </Svg>
  );
}

/** The glowing gold V (logo shape), used as the sun on the Welcome screen only. */
export function GoldV({ size }: { size: number }) {
  const glow = size * 2.2;
  return (
    <View style={{ width: glow, height: glow, alignItems: 'center', justifyContent: 'center' }} pointerEvents="none">
      <Svg width={glow} height={glow} style={StyleSheet.absoluteFill}>
        <Defs>
          <RadialGradient id="vglow" cx="50%" cy="50%" r="50%">
            <Stop offset="0" stopColor="#FFD696" stopOpacity={0.8} />
            <Stop offset="0.65" stopColor="#FFD696" stopOpacity={0} />
          </RadialGradient>
        </Defs>
        <Circle cx={glow / 2} cy={glow / 2} r={glow / 2} fill="url(#vglow)" />
      </Svg>
      <Svg width={size} height={(size * 92) / 100} viewBox="0 0 100 92">
        <Defs>
          <SvgGradient id="vgold" x1="0" y1="0" x2="0" y2="1">
            <Stop offset="0" stopColor="#F6DFA0" />
            <Stop offset="0.55" stopColor="#D9B562" />
            <Stop offset="1" stopColor="#A9822F" />
          </SvgGradient>
        </Defs>
        <Polygon points={V_LEFT} fill="url(#vgold)" />
        <Polygon points={V_RIGHT} fill="url(#vgold)" />
      </Svg>
    </View>
  );
}

/**
 * The sky with the skyline at its bottom. Children are drawn on top (logo, titles, buttons).
 * sun: where the gold V sits (Welcome only).
 */
export function Sky({ height, phase, skyline = 80, sun, children, style }: { height: number; phase: SkyPhase; skyline?: number; sun?: { top: number; size: number }; children?: React.ReactNode; style?: ViewStyle }) {
  const width = useWindowDimensions().width;
  const look = SKIES[phase];
  return (
    <View style={[{ height, overflow: 'hidden' }, style]}>
      <LinearGradient colors={look.colors} locations={STOPS as unknown as [number, number, ...number[]]} style={StyleSheet.absoluteFill} />
      {phase === 'night' && STARS.map((s, k) => (
        <View key={k} style={{ position: 'absolute', left: s.x * width, top: 20 + s.y * (height - skyline - 20), width: s.r * 2, height: s.r * 2, borderRadius: s.r, backgroundColor: '#FFFFFF', opacity: s.o }} />
      ))}
      {sun && <View style={{ position: 'absolute', top: sun.top - sun.size * 0.6, left: 0, right: 0, alignItems: 'center' }}><GoldV size={sun.size} /></View>}
      {skyline > 0 && <Skyline width={width} height={skyline} color={look.city} lit={phase === 'night'} />}
      {children}
    </View>
  );
}

/** A round button on the sky (back, save): white circle so the dark icon reads on every sky. */
export function SkyBtn({ label, onPress, children }: { label: string; onPress: () => void; children: React.ReactNode }) {
  return (
    <Pressable onPress={onPress} accessibilityRole="button" accessibilityLabel={label} hitSlop={6}
      style={({ pressed }) => [hs.btn, pressed && { opacity: 0.8 }]}>
      {children}
    </Pressable>
  );
}

/**
 * The sky on top of an inner screen (car page, Cars that fit you, Coach, Garage): left button, title, right
 * button, and optional extra lines under them. The screen's page then starts with `sheet` (round top corners).
 */
export function SkyHeader({ title, sub, left, right, back, icon, height = 110, skyline = 60, children }: { title?: string; sub?: string; left?: React.ReactNode; right?: React.ReactNode; back?: () => void; icon?: React.ReactNode; height?: number; skyline?: number; children?: React.ReactNode }) {
  const sky = useSky();
  const insets = useSafeAreaInsets();
  // Clean look (picture 82): a plain header on the page color, dark title, round white buttons.
  if (!skyLook) {
    return (
      <View style={[hs.row, { paddingTop: insets.top + 10, paddingBottom: 6, backgroundColor: C.bg }]}>
        <View style={hs.side}>{back ? <SkyBtn label="Back" onPress={back}><BackIcon color="#1D2B24" /></SkyBtn> : left}</View>
        <View style={{ flex: 1, flexDirection: 'row', alignItems: 'center', justifyContent: 'center', gap: 10 }}>
          {icon}
          <View style={{ alignItems: icon ? 'flex-start' : 'center', flexShrink: 1 }}>
            {title ? <Text style={[hs.title, { color: C.ink }]} numberOfLines={1} accessibilityRole="header">{title}</Text> : null}
            {sub ? <Text style={[hs.sub, { color: C.muted }]} numberOfLines={1}>{sub}</Text> : null}
          </View>
        </View>
        <View style={[hs.side, { alignItems: 'flex-end' }]}>{right}</View>
      </View>
    );
  }
  return (
    <Sky height={height + insets.top} phase={sky.phase} skyline={skyline}>
      <View style={[hs.row, { paddingTop: insets.top + 8 }]}>
        <View style={hs.side}>{back ? <SkyBtn label="Back" onPress={back}><BackIcon color="#1D2B24" /></SkyBtn> : left}</View>
        <View style={{ flex: 1, flexDirection: 'row', alignItems: 'center', justifyContent: 'center', gap: 10 }}>
          {icon}
          <View style={{ alignItems: icon ? 'flex-start' : 'center', flexShrink: 1 }}>
            {title ? <Text style={[hs.title, { color: sky.ink }]} numberOfLines={1} accessibilityRole="header">{title}</Text> : null}
            {sub ? <Text style={[hs.sub, { color: sky.ink }]} numberOfLines={1}>{sub}</Text> : null}
          </View>
        </View>
        <View style={[hs.side, { alignItems: 'flex-end' }]}>{right}</View>
      </View>
      {children}
    </Sky>
  );
}

const hs = themed(() => StyleSheet.create({
  row: { flexDirection: 'row', alignItems: 'center', gap: 8, paddingHorizontal: PAD - 4 },
  side: { minWidth: 44 },
  btn: skyLook
    ? { width: 42, height: 42, borderRadius: 21, backgroundColor: 'rgba(255,255,255,0.88)', alignItems: 'center', justifyContent: 'center' }
    : { width: 42, height: 42, borderRadius: 21, backgroundColor: '#FFFFFF', alignItems: 'center', justifyContent: 'center', shadowColor: '#0F1A2A', shadowOpacity: 0.1, shadowRadius: 10, shadowOffset: { width: 0, height: 3 }, elevation: 3 },
  title: { fontFamily: F.head, fontSize: 17 },
  sub: { fontFamily: F.bodySemi, fontSize: 12, opacity: 0.92, marginTop: 1 },
}));

/** The page under a sky: round top corners that tuck over the bottom of the sky. */
export const sheet = themed(() => StyleSheet.create({
  page: skyLook
    ? { flex: 1, marginTop: -28, paddingTop: 10, borderTopLeftRadius: 28, borderTopRightRadius: 28, backgroundColor: C.bg, overflow: 'hidden' }
    : { flex: 1, backgroundColor: C.bg },
}));
