// Alerts (picture 106, set 2): what a member wants to hear about. Recall phone alerts work now
// (state/alerts.tsx + the daily recall-check). Car plan reminders (Oct 30, 2026) are made on the phone
// (lib/reminders.ts): oil, car payments, the monthly mileage check and value checks. The rest start soon.
import { router } from 'expo-router';
import { Platform, ScrollView, View } from 'react-native';

import { AccountTop, Card, Sec, ToggleRow } from '@/components/account-ui';
import { BellIcon, CarIcon, CashIcon, PinIcon, TagIcon, WrenchIcon } from '@/components/icons';
import { Pressable, Text } from '@/components/t';
import { planAlerts } from '@/data/car-plan';
import { canRemind } from '@/lib/reminders';
import { notify } from '@/components/notify';
import { Body } from '@/components/ui';
import { useAlerts } from '@/state/alerts';
import { type AlertPrefs, useAuth } from '@/state/auth';
import { useSaved } from '@/state/saved';
import { C, F, PAD } from '@/theme';

export default function Alerts() {
  const { session, prefs, setPref, askAccount } = useAuth();
  const { alertsOn, busy, setAlertsOn } = useAlerts();
  const { myCar, saved, myCars, setMyCars, activeCar, pickCar } = useSaved();
  const plan = planAlerts(myCars);
  const ask = () => askAccount('Turn on alerts with a free account', 'We tell you the day a new recall comes out, and when it’s time for an oil change. No spam, never sold.');
  // A car plan switch here turns it on or off for every car in My Garage.
  const setPlan = async (v: boolean, change: (c: (typeof myCars)[number]) => (typeof myCars)[number]) => {
    if (!session) return ask();
    if (v && Platform.OS !== 'web' && !(await canRemind(true))) return notify('Reminders are off', 'Alerts are off for Carvessa in your phone settings. Turn them on there, then try again.');
    setMyCars(myCars.map(change));
    pickCar(activeCar); // keep the same car open in My Garage
  };
  const flip = (k: keyof AlertPrefs) => (v: boolean) => (session ? setPref(k, v) : ask());
  const what = [myCar ? `${myCar.year} ${myCar.model}` : '', saved.length ? `${saved.length} saved car${saved.length === 1 ? '' : 's'}` : ''].filter(Boolean).join(' + ') || 'Your car and saved cars';
  return (
    <View style={{ flex: 1, backgroundColor: C.bg }}>
      <AccountTop title="Alerts" />
      <ScrollView contentContainerStyle={{ paddingHorizontal: PAD - 6, paddingBottom: 30 }}>
        <Body style={{ color: C.muted, marginHorizontal: 4 }}>Pick what we tell you about. You can change it any time.</Body>
        <Sec>Your car</Sec>
        <Card>
          <ToggleRow icon={(c) => <BellIcon size={18} color={c} />} label="Recall alerts" sub={what} on={!!session && alertsOn} disabled={busy}
            onChange={async (v) => { if (!session) return ask(); const msg = await setAlertsOn(v); if (msg) notify('Recall alerts', msg); }} />
          <ToggleRow last t="green" icon={(c) => <WrenchIcon size={18} color={c} />} label="Maintenance reminders" sub="Oil change coming up, from your miles" on={!!session && prefs.upkeep} onChange={flip('upkeep')} />
        </Card>
        <Sec>My car plan</Sec>
        {myCars.length ? (
          <Card>
            {plan.pay === null && myCars.every((c) => c.owned) ? (
              <View style={{ paddingVertical: 12, borderBottomWidth: 1, borderBottomColor: C.line }}>
                <Text style={{ fontFamily: F.bodyBold, fontSize: 15, color: C.ink }}>Car payments</Text>
                <Text style={{ fontFamily: F.body, fontSize: 12.5, color: C.green, marginTop: 2 }}>✓ Paid off: no payments to remind you about</Text>
              </View>
            ) : plan.pay === null ? (
              <Pressable onPress={() => router.push('/loan')} accessibilityRole="button" style={{ paddingVertical: 12 }}>
                <Text style={{ fontFamily: F.bodyBold, fontSize: 15, color: C.ink }}>Car payments</Text>
                <Text style={{ fontFamily: F.body, fontSize: 12.5, color: C.muted, marginTop: 2 }}>Add your loan in My Garage to get payment reminders ›</Text>
              </Pressable>
            ) : (
              <ToggleRow t="purple" icon={(c) => <CashIcon size={18} color={c} />} label="Car payments" sub="3 days before, and the morning it’s due" on={!!session && plan.pay}
                onChange={(v) => setPlan(v, (c) => (c.loan?.left ? { ...c, loan: { ...c.loan, remind: v } } : c))} />
            )}
            <ToggleRow t="blue" icon={(c) => <CarIcon size={18} color={c} />} label="Monthly mileage check" sub="“Is your mileage about …?” once a month" on={!!session && plan.miles}
              onChange={(v) => setPlan(v, (c) => ({ ...c, checkMiles: v }))} />
            <ToggleRow last t="amber" icon={(c) => <TagIcon size={18} color={c} />} label="Value check every 3 months" sub="What your car is worth now" on={!!session && plan.value}
              onChange={(v) => setPlan(v, (c) => ({ ...c, valueTips: v }))} />
          </Card>
        ) : (
          <Card>
            <Pressable onPress={() => router.navigate('/garage')} accessibilityRole="button" style={{ paddingVertical: 12 }}>
              <Text style={{ fontFamily: F.bodyBold, fontSize: 15, color: C.ink }}>Add your car first</Text>
              <Text style={{ fontFamily: F.body, fontSize: 12.5, color: C.muted, marginTop: 2 }}>Payment, mileage and value reminders come with your car in My Garage ›</Text>
            </Pressable>
          </Card>
        )}
        <Sec>Shopping</Sec>
        <Card>
          <ToggleRow t="red" icon={(c) => <TagIcon size={18} color={c} />} label="Price drops" sub="On your saved cars" on={!!session && prefs.price} onChange={flip('price')} />
          <ToggleRow t="amber" icon={(c) => <PinIcon size={18} color={c} />} label="New cars for sale near you" sub="That fit your plan" on={!!session && prefs.nearby} onChange={flip('nearby')} />
          <ToggleRow last t="purple" icon={(c) => <CashIcon size={18} color={c} />} label="Loan rate changes" sub="When car loan rates move" on={!!session && prefs.rates} onChange={flip('rates')} />
        </Card>
        <Sec>How we tell you</Sec>
        <Card>
          <ToggleRow last icon={(c) => <BellIcon size={18} color={c} />} label="Also by email" sub="Phone alerts come first" on={!!session && prefs.email} onChange={flip('email')} />
        </Card>
        <Body style={{ fontSize: 12.5, color: C.muted, marginTop: 12, marginHorizontal: 4 }}>Safety recalls always show in the app, even with alerts off.</Body>
        <Body style={{ fontSize: 12.5, color: C.muted, marginTop: 4, marginHorizontal: 4 }}>Recall alerts, maintenance and your car plan reminders work now in the phone app. Price drops, new cars near you, loan rate changes and email start soon; we save your choices for then.</Body>
      </ScrollView>
    </View>
  );
}
