// Questions · Set D · Coach chat. Smarter questions from picture 69 (approved Oct 15, 2026): kind of
// car, new or used, how you pay (+ payment, money down, credit for a loan), which apps for app drivers,
// trade-in, first car, when you're buying. Every question keeps Skip.
import * as Speech from 'expo-speech';
import { router } from 'expo-router';
import { useEffect, useMemo, useRef, useState } from 'react';
import { ScrollView, StyleSheet, useWindowDimensions, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

import { BodyGrid, KINDS } from '@/components/body-tiles';
import { CarNowSheet, type CarNow } from '@/components/car-now-sheet';
import { ChatHistory } from '@/components/chat-history';
import { FeatureGrid, mustTiles, picksFrom, picksToAnswers, wantTiles, type Picks } from '@/components/feature-grid';
import { ArrowIcon, BackIcon, ClockIcon, CoachIcon, SpeakerIcon } from '@/components/icons';
import { sheet, SkyBtn, SkyHeader } from '@/components/sky';
import { Btn, Chip, H, Label, SquareBtn, tap } from '@/components/ui';
import { kindFromName, type CarKind } from '@/data/car-kind';
import { applyAnswer, carAnswer, modelOf, optionsOf, walk } from '@/data/coach';
import { freshAnswers, useAnswers, type Answers } from '@/state/answers';
import { useSaved } from '@/state/saved';
import { C, calm, F, PAD, skyLook, themed } from '@/theme';
import { Pressable, Text, TextInput } from '@/components/t';
import { useKeyboardLift } from '@/lib/keyboard-lift';
import Animated from 'react-native-reanimated';
import { speechLang, tr } from '@/i18n';
import { UseMyLocation } from '@/components/use-location';

export default function Coach() {
  const { answers, setAnswers, chat: done, setChat: setDone, history, chatId, openChat, deleteChat, startChat } = useAnswers();
  const { prefs, myCars, addCar } = useSaved();
  const [picked, setPicked] = useState<string[]>([]);
  const [picks, setPicks] = useState<Picks>(() => picksFrom(answers));
  const { width, height } = useWindowDimensions();
  const [text, setText] = useState('');
  const [voiceSet, setVoice] = useState<boolean | null>(null); // null = follow the Me setting
  const voice = voiceSet ?? prefs.readAloud;
  const scroll = useRef<ScrollView>(null);
  const [showHistory, setShowHistory] = useState(false);
  const [hiddenAt, setHiddenAt] = useState<number | null>(null); // the car pop-up was closed at this step
  // Keeps the answer box above the keyboard (Android draws behind it now).
  const [kbRef, kbStyle, kbMeasure] = useKeyboardLift(() => setTimeout(() => scroll.current?.scrollToEnd({ animated: true }), 50));

  // Walk the steps, skipping ones that don't apply, to build the chat.
  const { msgs, step, stepNo, total } = useMemo(() => walk(done, answers), [done]); // eslint-disable-line react-hooks/exhaustive-deps
  // An unfinished chat from before (picture 185): offer to continue it on a fresh start.
  const unfinished = done.length === 0 ? history.find((c) => !c.done && c.id !== chatId) : undefined;

  const last = msgs[msgs.length - 1];
  useEffect(() => {
    setTimeout(() => scroll.current?.scrollToEnd({ animated: true }), 50);
    if (voice && last.from === 'coach') { Speech.stop(); Speech.speak(tr(last.text), { language: speechLang() }); }
  }, [msgs.length]); // eslint-disable-line react-hooks/exhaustive-deps
  // The "car you have now" question opens its pop-up by itself (until they close it).
  const carSheet = !!step?.carNow && hiddenAt !== stepNo;

  const answer = (v: string, info?: Partial<Answers>) => {
    if (!step) return;
    const next = [...done, v];
    // The first answer of a new chat starts from fresh answers (ZIP, pay and pre-approval stay).
    const base = done.length === 0 ? freshAnswers(answers) : answers;
    const a = applyAnswer(base, step.key, v, info);
    if (step.key === 'credit' && !['Rebuilding', 'Fair', 'Good', 'Great'].includes(v)) a.credit = base.credit;
    setAnswers(a);
    setDone(next); setPicked([]); setText('');
  };
  // Picked in the pop-up: answer with the car + miles, its kind, and save it to My Garage if asked.
  const pickCarNow = (car: CarNow, kind: CarKind | undefined, save: boolean) => {
    if (save) addCar({ year: car.year, make: car.make, model: car.model, miles: car.miles });
    answer(carAnswer(`${car.year} ${car.make} ${car.model}`, car.miles), { myCarKind: kind?.kind, myCarSeats: kind?.seats });
  };
  // Typed instead ("2019 Nissan Pathfinder"): our list knows most kinds without the internet.
  const typedCar = (v: string) => {
    const words = v.replace(/^\s*(19|20)\d\d\s+/, '').split(/\s+/);
    const k = kindFromName(words.slice(1).join(' ')) ?? kindFromName(words.join(' '));
    answer(v, { myCarKind: k?.kind, myCarSeats: k?.seats });
  };
  const back = () => { if (done.length === 0) router.navigate('/home'); else { setDone(done.slice(0, -1)); setPicked([]); } };
  // The features grid: Done answers with what they picked (stars = must have, the rest = nice to have).
  const featuresDone = () => {
    const names = (t: { label: string }[]) => t.map((x) => x.label).join(', ');
    const musts = mustTiles(picks), wants = wantTiles(picks);
    answer([musts.length && `Must have: ${names(musts)}`, wants.length && `Nice to have: ${names(wants)}`].filter(Boolean).join(' · '), picksToAnswers(picks));
  };
  // "Also pick a color": save the picks, then the Color screen answers this question (with the color).
  const pickColor = () => {
    tap();
    setAnswers({ ...answers, ...picksToAnswers(picks) });
    router.push({ pathname: '/color', params: { from: 'coach', at: String(done.length) } });
  };
  const send = () => {
    const v = text.trim();
    if (step?.multi) answer([...picked, ...(v ? [v] : [])].join(', '));
    else if (v && step?.carNow) typedCar(v);
    else if (v) answer(v);
  };
  // Tap one of your answers to change it: the chat goes back to that question.
  const changeAt = (at: number) => { tap(); setDone(done.slice(0, at)); setPicked([]); };
  const options = step ? optionsOf(step, answers) : [];

  return (
    <SafeAreaView edges={calm ? ['bottom'] : undefined} style={{ flex: 1, backgroundColor: C.bg }}>
      <View style={{ flex: 1 }}>
        {calm ? (
          <SkyHeader height={100} skyline={0} title="Your coach" sub={`No pressure · Habla español · Step ${Math.min(stepNo, total)} of ${total}`}
            icon={<View style={s.avatar}><CoachIcon size={22} color={skyLook ? '#1F6E4E' : C.yellow} /></View>}
            left={<SkyBtn label="Back" onPress={back}><BackIcon color="#1D2B24" /></SkyBtn>}
            right={<SkyBtn label={voice ? 'Stop reading out loud' : 'Read answers out loud'} onPress={() => { if (voice) Speech.stop(); setVoice(!voice); }}><SpeakerIcon on={voice} color="#1D2B24" /></SkyBtn>} />
        ) : null}
        <View style={calm ? [sheet.page, { flex: 1 }] : { flex: 1 }}>
        {calm ? (
          <View style={[s.top, { paddingTop: 18 }]}>
            <Pressable onPress={() => { tap(); setShowHistory(true); }} accessibilityRole="button" accessibilityLabel={`History, ${history.length} chats`} style={s.hist}>
              <ClockIcon size={15} color={C.onAccent} />
              <Text style={s.histT}>{history.length ? `History · ${history.length}` : 'History'}</Text>
            </Pressable>
            <View style={[s.bar, { flex: 1, marginHorizontal: 0, marginTop: 0, borderRadius: 3, overflow: 'hidden', backgroundColor: C.hero }]}>
              <View style={{ width: `${(Math.min(stepNo - (step ? 1 : 0), total) / total) * 100}%`, height: '100%', backgroundColor: C.yellow, borderRadius: 3 }} />
            </View>
            {step ? (
              <Pressable onPress={() => answer('')} accessibilityRole="button" hitSlop={10} style={{ marginLeft: 14 }}><Label style={{ color: C.yellow, textDecorationLine: 'underline' }}>Skip</Label></Pressable>
            ) : null}
          </View>
        ) : (<>
        <View style={s.top}>
          <SquareBtn label="Back" onPress={back}><BackIcon /></SquareBtn>
          <Label>Step {Math.min(stepNo, total)} of {total}</Label>
          {step ? (
            <Pressable onPress={() => answer('')} accessibilityRole="button" hitSlop={10}><Label style={{ textDecorationLine: 'underline' }}>Skip</Label></Pressable>
          ) : <View style={{ width: 30 }} />}
        </View>
        <View style={s.bar}><View style={{ width: `${(Math.min(stepNo - (step ? 1 : 0), total) / total) * 100}%`, height: '100%', backgroundColor: C.yellow }} /></View>

        <View style={s.coachRow}>
          <View style={s.coachIcon}><CoachIcon size={22} color={C.onAccent} /></View>
          <View style={{ flex: 1 }}>
            <H size={20}>Your Carvessa coach</H>
            <Text style={{ fontFamily: F.bodyBold, fontSize: 12, color: C.green }}>● Online</Text>
          </View>
          <SquareBtn label={voice ? 'Stop reading out loud' : 'Read answers out loud'} onPress={() => { if (voice) Speech.stop(); setVoice(!voice); }}>
            <SpeakerIcon on={voice} />
          </SquareBtn>
        </View>
        </>)}

        <ScrollView ref={scroll} style={{ flex: 1 }} contentContainerStyle={{ padding: PAD, gap: 8 }}>
          {msgs.map((m, k) => (
            <View key={k} style={{ gap: 8 }}>
              {m.from === 'me' && m.at !== undefined ? (
                <Pressable onPress={() => changeAt(m.at!)} accessibilityRole="button" accessibilityHint="Change this answer" style={[s.bub, s.me]}>
                  <Text style={s.meText}>{m.text}</Text>
                </Pressable>
              ) : (
                <View style={[s.bub, m.from === 'me' ? s.me : s.them]}>
                  <Text style={m.from === 'me' ? s.meText : s.themText}>{m.text}</Text>
                </View>
              )}
              {k === 0 && unfinished && (
                <Pressable onPress={() => { tap(); openChat(unfinished.id); }} accessibilityRole="button" style={[s.bub, s.them, s.cont]}>
                  <Text style={s.contT}>You have an unfinished chat from before. <Text style={s.contLink}>Continue it ›</Text></Text>
                </Pressable>
              )}
            </View>
          ))}
          {!step && <Text style={s.tapHint}>Tap any of your answers to change it.</Text>}
        </ScrollView>

        <Animated.View ref={kbRef} onLayout={kbMeasure} style={[s.dock, kbStyle]}>
          {step ? (
            <>
              {step.carNow && <Btn small kind="yellow" label={myCars.length ? 'Pick my car' : 'Pick the car'} onPress={() => setHiddenAt(null)} style={{ marginBottom: 10 }} />}
              {step.tiles && (
                <View style={{ marginBottom: 8 }}>
                  {!!answers.myCarKind && answers.myCar && (
                    <Pressable onPress={() => { tap(); answer(answers.myCarKind!); }} accessibilityRole="button" style={s.like}>
                      <Text style={s.likeT}>✓ Like my {modelOf(answers.myCar)} · {answers.myCarKind}</Text>
                    </Pressable>
                  )}
                  <BodyGrid cols={4} h={50} value={null} kinds={KINDS.map((k) => k.kind)}
                    onChange={(k) => { if (k) answer(KINDS.find((x) => x.kind === k)!.label); }} />
                </View>
              )}
              {!!options.length && (
                <View style={s.chips}>
                  {options.map((o) => (
                    <Chip key={o} label={o} on={picked.includes(o)}
                      onPress={() => (step.multi ? setPicked(picked.includes(o) ? picked.filter((x) => x !== o) : [...picked, o]) : answer(o))} />
                  ))}
                </View>
              )}
              {step.grid && (
                <>
                  <ScrollView style={{ maxHeight: height * 0.42 }} contentContainerStyle={{ paddingBottom: 4 }}>
                    <FeatureGrid small picks={picks} onChange={setPicks} width={Math.min(width, 520) - PAD * 2} />
                  </ScrollView>
                  {(() => {
                    const n = mustTiles(picks).length + wantTiles(picks).length;
                    return <Btn kind="yellow" label={n ? `Done · ${n} picked` : 'Done'} onPress={() => { tap(); featuresDone(); }} style={{ marginTop: 10 }} />;
                  })()}
                  <Pressable onPress={pickColor} accessibilityRole="button" style={{ alignSelf: 'center', padding: 8 }}>
                    <Text style={s.colorLink}>Also pick a color (optional)</Text>
                  </Pressable>
                </>
              )}
              {step.multi && <Btn small label={picked.length ? `Done · ${picked.length} picked` : 'Done'} onPress={send} style={{ marginBottom: 8 }} />}
              {step.key === 'zip' && <UseMyLocation needZip style={{ marginBottom: 8 }} onSpot={(sp) => answer(sp.zip!)} />}
              {!step.grid && <View style={s.inputRow}>
                <TextInput value={text} onChangeText={setText} onSubmitEditing={send} returnKeyType="send"
                  placeholder={step.placeholder ?? 'Or type your answer'} placeholderTextColor="#999"
                  keyboardType={step.key === 'zip' ? 'number-pad' : 'default'} accessibilityLabel="Type your answer" style={s.input} />
                <Pressable onPress={() => { tap(); send(); }} style={[s.send, calm && s.sendCalm]} accessibilityRole="button" accessibilityLabel="Send">
                  {calm ? <ArrowIcon color={C.onAccent} size={20} /> : <Text style={{ fontFamily: F.head, fontSize: 16, letterSpacing: 1, color: C.yellow }}>SEND</Text>}
                </Pressable>
              </View>}
            </>
          ) : (
            <Btn label="See my top 3" iconRight={<ArrowIcon color={C.yellow} />} onPress={() => router.push({ pathname: '/results', params: { upgrade: '0' } })} />
          )}
        </Animated.View>
        </View>
      </View>
      {carSheet && <CarNowSheet garage={myCars} onUse={pickCarNow} onClose={() => setHiddenAt(stepNo)} />}
      {showHistory && (
        <ChatHistory history={history} openId={chatId} onClose={() => setShowHistory(false)}
          onContinue={(id) => { openChat(id); setShowHistory(false); }}
          onChange={(id) => { openChat(id); setShowHistory(false); }}
          onPicks={(id) => { openChat(id); setShowHistory(false); router.push({ pathname: '/results', params: { upgrade: '0' } }); }}
          onDelete={deleteChat}
          onNew={() => { startChat(); setShowHistory(false); }} />
      )}
    </SafeAreaView>
  );
}

const s = themed(() => StyleSheet.create({
  top: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', paddingHorizontal: PAD, paddingTop: 10 },
  bar: { height: 6, backgroundColor: C.grey, marginHorizontal: PAD, marginTop: 14 },
  coachRow: { flexDirection: 'row', alignItems: 'center', gap: 10, paddingHorizontal: PAD, paddingTop: 16 },
  coachIcon: { width: 40, height: 40, backgroundColor: C.fill, alignItems: 'center', justifyContent: 'center' },
  bub: { maxWidth: '86%', paddingHorizontal: 13, paddingVertical: 10, borderRadius: calm ? 18 : 0 },
  them: { alignSelf: 'flex-start', backgroundColor: C.grey },
  // Sunset Calm: your answers in green bubbles with white text.
  me: { alignSelf: 'flex-end', backgroundColor: calm ? C.fill : C.hero },
  themText: { fontFamily: F.body, fontSize: 15.5, lineHeight: 21, color: C.ink },
  meText: { fontFamily: F.bodyBold, fontSize: 15.5, lineHeight: 21, color: calm ? C.onAccent : C.yellow },
  dock: { borderTopWidth: calm ? 0 : 1, borderTopColor: C.line, padding: PAD, paddingTop: 14, paddingBottom: 12 },
  chips: { flexDirection: 'row', flexWrap: 'wrap', gap: 6, marginBottom: 10 },
  colorLink: { fontFamily: F.bodyBold, fontSize: 14, color: C.yellow, textDecorationLine: 'underline' },
  inputRow: { flexDirection: 'row', gap: 6 },
  input: { flex: 1, height: 50, borderWidth: 1, borderColor: C.line, borderRadius: calm ? 999 : 12, backgroundColor: calm ? C.card : undefined, paddingHorizontal: 12, fontFamily: F.body, fontSize: 15.5, color: C.ink },
  sendCalm: { width: 50, backgroundColor: C.fill },
  hist: { flexDirection: 'row', alignItems: 'center', gap: 5, backgroundColor: C.fill, borderRadius: 999, paddingHorizontal: 10, paddingVertical: 6, marginRight: 12 },
  histT: { fontFamily: F.bodyBold, fontSize: 12.5, color: C.onAccent },
  cont: { backgroundColor: C.fill },
  contT: { fontFamily: F.body, fontSize: 14, lineHeight: 20, color: C.onAccent },
  contLink: { fontFamily: F.bodyBold, color: C.onAccent, textDecorationLine: 'underline' },
  tapHint: { fontFamily: F.body, fontSize: 13, color: C.muted, textAlign: 'center', marginTop: 4 },
  like: { borderRadius: 14, borderWidth: 2, borderColor: C.yellow, backgroundColor: C.fill, paddingVertical: 12, paddingHorizontal: 14, marginBottom: 2 },
  likeT: { fontFamily: F.bodyBold, fontSize: 15, color: C.onAccent },
  avatar: { width: 40, height: 40, borderRadius: 20, backgroundColor: skyLook ? 'rgba(255,255,255,0.88)' : C.hero, alignItems: 'center', justifyContent: 'center' },
  send: { width: 72, height: 50, backgroundColor: C.hero, alignItems: 'center', justifyContent: 'center', borderRadius: calm ? 999 : 0 },
}));
