// Opening a screen from a tapped alert (Nov 4, 2026 fix). When the app was closed, the tap starts the app on the
// opening animation, which then sends people to Home and used to hide the screen the alert wanted. Now a tap that
// comes in during the opening waits here, and the opening runs it right after it moves on.
let openingDone = false;
let waiting: (() => void) | null = null;

/** Run `go` now, or right after the opening if it is still playing. */
export function goFromAlert(go: () => void) {
  if (openingDone) go();
  else waiting = go;
}

/** Called by the opening screen once it has moved on (to Home, Login or back where they were). */
export function openingFinished() {
  openingDone = true;
  const go = waiting;
  waiting = null;
  if (go) setTimeout(go, 0);
}
