// Account & privacy (picture 106, set 2): how you sign in, what we keep, sign out and delete — always easy to find.
import { router } from 'expo-router';
import { useState } from 'react';
import { ScrollView, StyleSheet, View } from 'react-native';

import { AccountTop, BigBtn, Card, Row, Sec } from '@/components/account-ui';
import { DeleteAccount } from '@/components/delete-account';
import { GlobeIcon, InfoIcon, LockIcon, MailIcon } from '@/components/icons';
import { notify } from '@/components/notify';
import { useAuth } from '@/state/auth';
import { C, F, PAD, themed } from '@/theme';
import { Text, TextInput } from '@/components/t';

export default function Account() {
  const { session, withGoogle, signOut, changePassword } = useAuth();
  const [pw, setPw] = useState<string | null>(null);
  const [deleting, setDeleting] = useState(false);
  if (!session) return (
    <View style={{ flex: 1, backgroundColor: C.bg }}><AccountTop title="Account & privacy" /><Text style={[s.keep, { margin: PAD }]}>You’re not signed in.</Text></View>
  );
  const savePw = async () => {
    const err = await changePassword(pw ?? '');
    if (err) return notify('Change password', err);
    setPw(null);
    notify('Password changed', 'Use your new password next time you log in.');
  };
  return (
    <View style={{ flex: 1, backgroundColor: C.bg }}>
      <AccountTop title="Account & privacy" />
      <ScrollView contentContainerStyle={{ paddingHorizontal: PAD - 6, paddingBottom: 30 }} keyboardShouldPersistTaps="handled">
        <Sec>Sign-in</Sec>
        <Card>
          <Row icon={(c) => <MailIcon size={18} color={c} />} label="Email" value={session.user.email ?? ''} />
          {withGoogle
            ? <Row last t="green" icon={(c) => <GlobeIcon size={18} color={c} />} label="Signed in with" value="Google" />
            : <Row last t="amber" icon={(c) => <LockIcon size={18} color={c} />} label="Change password" onPress={() => setPw(pw === null ? '' : null)} />}
        </Card>
        {pw !== null && (
          <View style={{ marginTop: 8 }}>
            <TextInput value={pw} onChangeText={setPw} secureTextEntry placeholder="New password · 8+ letters" placeholderTextColor={C.muted} style={s.in} accessibilityLabel="New password" autoComplete="new-password" />
            <BigBtn label="Save new password" onPress={savePw} />
          </View>
        )}
        <Sec>What we keep</Sec>
        <Card style={{ paddingVertical: 12 }}>
          <Text style={s.keep}>✓ Your first name, email and ZIP</Text>
          <Text style={s.keep}>✓ Your car, saved cars and dealer</Text>
          <Text style={s.keep}>✓ Your alert choices and reviews</Text>
          <Text style={[s.keep, { color: C.muted }]}>✗ We never sell your info · no ad tracking</Text>
        </Card>
        <Card style={{ marginTop: 10 }}>
          <Row icon={(c) => <InfoIcon size={18} color={c} />} label="Privacy Policy" onPress={() => router.push({ pathname: '/legal', params: { tab: 'privacy' } })} />
          <Row last icon={(c) => <InfoIcon size={18} color={c} />} label="Terms of Use" onPress={() => router.push({ pathname: '/legal', params: { tab: 'terms' } })} />
        </Card>
        <View style={{ height: 8 }} />
        <BigBtn label="Sign out" kind="soft" onPress={() => { signOut(); router.navigate('/me'); }} />
        <BigBtn label="Delete my account" kind="danger" onPress={() => setDeleting(true)} />
        <Text style={s.fine}>Deletes your account, saved cars and reviews. It can’t be undone.</Text>
      </ScrollView>
      {deleting && <DeleteAccount onClose={() => setDeleting(false)} />}
    </View>
  );
}

const s = themed(() => StyleSheet.create({
  keep: { fontFamily: F.body, fontSize: 14, lineHeight: 24, color: C.ink },
  fine: { fontFamily: F.body, fontSize: 12, color: C.muted, textAlign: 'center', marginTop: 8 },
  in: { backgroundColor: C.card, borderWidth: 1, borderColor: C.line, borderRadius: 14, paddingHorizontal: 14, paddingVertical: 12, fontFamily: F.bodyBold, fontSize: 16, color: C.ink },
}));
