// One-tap Upgrade (Nov 17, 2026, Loudjier: "If I hit upgrade it should go automatically to similar newer SUV like mine…
// it should not go to the second question page… There should be a little edit to change or update preferences").
// With a saved car we know the kind of: start the upgrade chat with their car and "like mine", then open the results
// in upgrade mode. Without a car (or a car we can't place), the coach asks for it as before.
import { router } from 'expo-router';
import { carNowOf, UPGRADE } from '@/data/coach';
import { useAnswers } from '@/state/answers';
import { useSaved } from '@/state/saved';

export function useQuickUpgrade() {
  const { startChat } = useAnswers();
  const { myCar } = useSaved();
  return () => {
    const now = myCar ? carNowOf(myCar) : undefined;
    if (now && now.info.myCarKind) {
      startChat(UPGRADE, now, true);
      router.navigate({ pathname: '/results', params: { upgrade: '1' } });
      return;
    }
    startChat(UPGRADE, now);
    router.navigate('/coach');
  };
}
