// "What can I afford?" math. All ESTIMATES: not a loan offer, and we never check credit.
// Safe car payment = 10% to 15% of monthly pay before taxes.
// Fits now = up to 12%. A stretch = 12% to 15%. Save for it = above 15%.
// Loans are 6 years (72 months), $0 down, used cars at a higher rate. Out-the-door price = price + the state's car tax + fees (state-costs.ts).
import { CARS, Car, carName, yearsOf } from '@/data/cars';
import { monthlyPayment } from '@/data/costs';
import { priceFor } from '@/data/prices';
import { homeState, outTheDoorIn } from '@/data/state-costs';

export const INCOMES = [
  { label: '$30K', sub: 'or less', amount: 30000 },
  { label: '$40K', sub: '$30K–$50K', amount: 40000 },
  { label: '$60K', sub: '$50K–$75K', amount: 60000 },
  { label: '$85K', sub: '$75K–$100K', amount: 85000 },
  { label: '$125K', sub: '$100K–$150K', amount: 125000 },
  { label: '$150K+', sub: 'and up', amount: 175000 },
];

export type Tier = 'Rebuilding' | 'Fair' | 'Good' | 'Great';
// Loan rates are ESTIMATES. `apr` = new car, `used` = used car. Used rates follow Experian's
// Q1 2026 averages by credit level (used average about 11.4%), rounded up a little so we never
// promise a payment that's too low (Oct 16, 2026).
export const TIERS: { tier: Tier; sub: string; apr: number; used: number; score: number }[] = [
  { tier: 'Rebuilding', sub: 'Below 600', apr: 17, used: 20, score: 600 },
  { tier: 'Fair', sub: '600 to 669', apr: 12, used: 14.5, score: 670 },
  { tier: 'Good', sub: '670 to 739', apr: 8, used: 10, score: 740 },
  { tier: 'Great', sub: '740 and up', apr: 6, used: 7, score: 800 },
];
export type TierInfo = (typeof TIERS)[number];
/** The loan rate for this credit level: new or used car. */
export const aprOf = (t: TierInfo, isNew: boolean) => (isNew ? t.apr : t.used);
export const MONTHS = 72;

// Out-the-door price: price + the shopper's state car tax + dealer and title fees (data/state-costs.ts).
export const outTheDoor = (price: number, st?: string | null) => outTheDoorIn(price, st === undefined ? homeState() : st);
const factor = (apr: number) => monthlyPayment(1000, apr, MONTHS) / 1000;
export const payFor = (price: number, apr: number, down = 0) => Math.round(Math.max(0, outTheDoor(price) - down) * factor(apr));
const round = (n: number, to: number) => Math.round(n / to) * to;

export function safeRange(income: number) {
  const m = income / 12;
  return { low: round(m * 0.1, 5), fit: round(m * 0.12, 5), high: round(m * 0.15, 5), monthly: m };
}

export type Pick = { car: Car; year: number; price: number; pay: number; isNew: boolean; name: string };

// Every car and year we know, with its payment.
function allPicks(t: TierInfo): Pick[] {
  const out: Pick[] = [];
  for (const car of CARS) for (const year of yearsOf(car)) {
    const p = priceFor(car, year);
    if (p) out.push({ car, year, price: p.amount, pay: payFor(p.amount, aprOf(t, p.isNew)), isNew: p.isNew, name: carName(car, year) });
  }
  return out;
}
// One year per car: the newest year that lands in the group.
function onePerCar(list: Pick[]) {
  const seen = new Set<string>();
  return list.filter((p) => (seen.has(p.car.id) ? false : (seen.add(p.car.id), true)));
}

function spread(list: Pick[], top: number, n: number) {
  const out: Pick[] = [];
  for (let i = 0; i < n; i++) {
    const target = top * (1 - (0.45 * i) / (n - 1)); // 100%, 89%, 78%, 66%, 55% of the budget
    const ok = list.filter((p) => !out.some((o) => o.car.id === p.car.id || o.price === p.price));
    const freshBody = ok.filter((p) => !out.some((o) => o.car.body === p.car.body));
    const pool = freshBody.length ? freshBody : ok;
    // Closest to the step; a newer year wins when two are close.
    const best = pool.sort((a, b) => Math.abs(a.pay - target) - Math.abs(b.pay - target) + (b.year - a.year) * 8)[0];
    if (best) out.push(best);
  }
  return out;
}

export function affordFor(income: number, tier: Tier) {
  const t = TIERS.find((x) => x.tier === tier) ?? TIERS[1];
  const next = TIERS[Math.min(TIERS.indexOf(t) + 1, TIERS.length - 1)];
  const r = safeRange(income);
  const picks = allPicks(t).sort((a, b) => b.year - a.year || b.pay - a.pay);
  // Fits now: a real mix. Five price steps from the top of the budget down to about half,
  // one car per step, no repeat cars or prices, and different body types when we can.
  const fits = spread(picks.filter((p) => p.pay <= r.fit && p.pay >= r.fit * 0.45), r.fit, 5).sort((a, b) => b.pay - a.pay);
  const stretch = onePerCar(picks.filter((p) => p.pay > r.fit && p.pay <= r.high)).sort((a, b) => a.pay - b.pay).slice(0, 4);
  // Save for it: new cars just above the budget, cheapest first.
  const fitIds = new Set([...fits, ...stretch].map((p) => p.car.id));
  const goals = onePerCar(picks.filter((p) => p.isNew && p.pay > r.high && !fitIds.has(p.car.id))).sort((a, b) => a.pay - b.pay).slice(0, 6);
  // How much a better score would save on the "fits now" cars.
  const drop = fits.length && next !== t ? Math.round(fits.reduce((s, p) => s + p.pay - payFor(p.price, aprOf(next, p.isNew)), 0) / fits.length) : 0;
  return { range: r, tier: t, next, fits, stretch, goals, drop };
}

// Goal-car plan: save for a down payment, raise the score one level, then it fits.
export function planFor(goal: Pick, income: number, tier: Tier) {
  const t = TIERS.find((x) => x.tier === tier) ?? TIERS[1];
  const next = TIERS[Math.min(TIERS.indexOf(t) + 1, TIERS.length - 1)];
  const r = safeRange(income);
  const today = payFor(goal.price, aprOf(t, goal.isNew));
  const nextApr = aprOf(next, goal.isNew);
  const maxLoan = r.fit / factor(nextApr);
  const down = Math.max(0, Math.ceil((outTheDoor(goal.price) - maxLoan) / 500) * 500);
  const save = Math.max(50, round(r.monthly * 0.075, 50));
  const months = down ? Math.ceil(down / save) : 0;
  const after = payFor(goal.price, nextApr, down);
  return { today, after, down, save, months, next, better: next !== t, savesScore: today - payFor(goal.price, nextApr) };
}

export const usd = (n: number) => `$${Math.round(n).toLocaleString('en-US')}`;
