// Service history (picture 167 screen 5, Oct 30, 2026): what was done, when, at how many miles, where and the cost.
// Kept with the car (on the phone, and in the free account). "Share" sends a plain list, handy when you sell.
import { router } from 'expo-router';
import { useState } from 'react';
import { KeyboardAvoidingView, Platform, ScrollView, Share, StyleSheet, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

import { BigBtn, Card } from '@/components/account-ui';
import { notify } from '@/components/notify';
import { sheet, SkyHeader } from '@/components/sky';
import { Pressable, Text, TextInput } from '@/components/t';
import { Body, Chip, Label, tap } from '@/components/ui';
import { addService, estMiles, fullDate, type Service, SERVICES, spentThisYear } from '@/data/car-plan';
import { carName } from '@/data/my-cars';
import { tr } from '@/i18n';
import { useSaved } from '@/state/saved';
import { C, calm, F, PAD, themed } from '@/theme';

const day = (t: number) => fullDate(new Date(t));
const num = (t: string) => Number(t.replace(/[^\d.]/g, '')) || 0;
const parseDate = (t: string) => {
  const m = t.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (!m) return null;
  const d = new Date(Number(m[3]), Number(m[1]) - 1, Number(m[2]), 12);
  return isNaN(d.getTime()) || d.getTime() > Date.now() + 86400000 ? null : d.getTime();
};

function Field({ label, value, onChange, placeholder, numeric, flex = 1 }: { label: string; value: string; onChange: (v: string) => void; placeholder: string; numeric?: boolean; flex?: number }) {
  return (
    <View style={{ flex }}>
      <Label style={s.fl}>{label}</Label>
      <TextInput value={value} onChangeText={onChange} placeholder={placeholder} placeholderTextColor={C.muted} accessibilityLabel={label}
        keyboardType={numeric ? 'number-pad' : 'default'} style={s.input} autoCorrect={false} />
    </View>
  );
}

function AddService({ miles, onSave, onCancel }: { miles: number | null; onSave: (x: Service) => void; onCancel: () => void }) {
  const [what, setWhat] = useState('Oil change');
  const [other, setOther] = useState('');
  const [when, setWhen] = useState('');
  const [mi, setMi] = useState(miles ? String(Math.round(miles / 10) * 10) : '');
  const [where, setWhere] = useState('');
  const [cost, setCost] = useState('');
  const save = () => {
    const at = when.trim() ? parseDate(when.trim()) : Date.now();
    if (!at) return notify('Check the date', 'Use month/day/year, like 06/03/2026. Leave it empty for today.');
    const name = what === 'Other' ? other.trim() : what;
    if (!name) return notify('What was done?', 'Write what was done, like “New headlight”.');
    onSave({ what: name, at, miles: num(mi) || undefined, where: where.trim() || undefined, cost: num(cost) ? Math.round(num(cost)) : undefined });
  };
  return (
    <Card style={{ paddingVertical: 14 }}>
      <Body bold>Add a service</Body>
      <View style={s.chips}>{SERVICES.map((x) => <Chip key={x} label={x} on={what === x} onPress={() => setWhat(x)} />)}</View>
      {what === 'Other' && <Field label="WHAT WAS DONE" value={other} onChange={setOther} placeholder="New headlight" />}
      <View style={s.two}>
        <Field label="DATE (EMPTY = TODAY)" value={when} onChange={setWhen} placeholder="06/03/2026" />
        <Field label="MILES" value={mi} onChange={setMi} placeholder="18,920" numeric />
      </View>
      <View style={s.two}>
        <Field label="WHERE (OPTIONAL)" value={where} onChange={setWhere} placeholder="I did it" flex={1.4} />
        <Field label="COST $ (OPTIONAL)" value={cost} onChange={setCost} placeholder="64" numeric />
      </View>
      <View style={{ gap: 8, marginTop: 14 }}>
        <BigBtn label="Save" onPress={save} />
        <BigBtn label="Cancel" kind="plain" onPress={onCancel} />
      </View>
    </Card>
  );
}

export default function ServiceScreen() {
  const { myCar, setMyCar } = useSaved();
  const [adding, setAdding] = useState(false);
  const [now] = useState(() => Date.now());
  const back = () => router.navigate('/garage');
  const list = myCar?.services ?? [];
  const year = new Date(now).getFullYear();
  const spent = spentThisYear(list, year);

  const save = (x: Service) => {
    if (!myCar) return;
    tap();
    const services = addService(myCar.services, x);
    // Newer miles than we had: they become the car's miles. An oil change moves "what's due".
    const newer = x.miles && x.miles > (myCar.miles ?? 0) && x.at > (myCar.milesAt ?? 0) - 86400000;
    const lastOil = x.what === 'Oil change' && x.miles && x.miles >= (myCar.lastOil ?? 0) ? x.miles : myCar.lastOil;
    setMyCar({ ...myCar, services, lastOil, ...(newer ? { miles: x.miles } : {}) });
    setAdding(false);
  };
  const remove = (i: number) => myCar && setMyCar({ ...myCar, services: list.filter((_, k) => k !== i) });
  const share = () => {
    if (!myCar) return;
    const lines = list.map((x) => `• ${day(x.at)} · ${tr(x.what)}${x.miles ? ` · ${x.miles.toLocaleString('en-US')} mi` : ''}${x.where ? ` · ${x.where}` : ''}`);
    Share.share({ message: `${tr('Service history')} · ${carName(myCar)}\n${lines.join('\n')}\n\n${tr('From the Carvessa app. Typed in by the owner.')}` }).catch(() => {});
  };

  return (
    <SafeAreaView edges={calm ? [] : ['top']} style={{ flex: 1, backgroundColor: C.bg }}>
      <SkyHeader title="Service history" sub={myCar ? carName(myCar) : undefined} back={back} />
      <KeyboardAvoidingView behavior={Platform.OS === 'ios' ? 'padding' : undefined} style={calm ? sheet.page : { flex: 1 }}>
        <ScrollView contentContainerStyle={{ paddingHorizontal: PAD, paddingBottom: 40, paddingTop: 6 }} keyboardShouldPersistTaps="handled">
          {!myCar ? (
            <Card style={{ paddingVertical: 16 }}>
              <Body bold>Add your car first</Body>
              <View style={{ marginTop: 12 }}><BigBtn label="Go to My Garage" onPress={back} /></View>
            </Card>
          ) : adding ? (
            <AddService miles={estMiles(myCar, now)} onSave={save} onCancel={() => setAdding(false)} />
          ) : (<>
            <BigBtn label="+ Log a service I did" onPress={() => setAdding(true)} />
            {list.length ? (
              <Card style={{ marginTop: 12 }}>
                {list.map((x, i) => (
                  <View key={`${x.at}-${i}`} style={[s.row, i < list.length - 1 && s.line]}>
                    <View style={{ flex: 1 }}>
                      <Text style={s.what}>{x.what}</Text>
                      <Text style={s.sub}>{[day(x.at), x.miles ? `${x.miles.toLocaleString('en-US')} mi` : '', x.where ?? ''].filter(Boolean).join(' · ')}</Text>
                    </View>
                    {x.cost ? <Text style={s.cost}>{`$${x.cost.toLocaleString('en-US')}`}</Text> : null}
                    <Pressable onPress={() => { tap(); remove(i); }} accessibilityRole="button" accessibilityLabel={`Remove ${x.what}`} hitSlop={8} style={s.x}>
                      <Text style={s.xT}>✕</Text>
                    </Pressable>
                  </View>
                ))}
              </Card>
            ) : (
              <Card style={{ marginTop: 12, paddingVertical: 14 }}>
                <Body bold>Nothing logged yet</Body>
                <Body style={s.small}>Add oil changes, tires, brakes and more. Buyers like a car with records, and your next oil change gets more exact.</Body>
              </Card>
            )}
            {spent > 0 && (
              <Card style={{ marginTop: 10, paddingVertical: 12 }}>
                <Body bold>{`Spent on upkeep in ${year}: $${spent.toLocaleString('en-US')}`}</Body>
                <Body style={s.small}>From the costs you typed in.</Body>
              </Card>
            )}
            {list.length > 0 && <View style={{ marginTop: 12 }}><BigBtn label="Share my service history" kind="soft" onPress={share} /></View>}
            <Body style={[s.small, { marginTop: 14 }]}>Handy when you sell or trade in: buyers like a car with records.</Body>
          </>)}
        </ScrollView>
      </KeyboardAvoidingView>
    </SafeAreaView>
  );
}

const s = themed(() => StyleSheet.create({
  fl: { fontSize: 10.5, color: C.muted, marginBottom: 4, marginTop: 10 },
  input: { height: 48, borderWidth: 1.5, borderColor: C.line, borderRadius: 12, paddingHorizontal: 12, fontFamily: F.bodyBold, fontSize: 15, color: C.ink, backgroundColor: C.card },
  two: { flexDirection: 'row', gap: 8 },
  chips: { flexDirection: 'row', flexWrap: 'wrap', gap: 6, marginTop: 10 },
  small: { fontSize: 12, color: C.muted, marginTop: 6, lineHeight: 17 },
  row: { flexDirection: 'row', alignItems: 'center', gap: 10, paddingVertical: 12 },
  line: { borderBottomWidth: 1, borderBottomColor: C.line },
  what: { fontFamily: F.bodyBold, fontSize: 14.5, color: C.ink },
  sub: { fontFamily: F.body, fontSize: 12, color: C.muted, marginTop: 2 },
  cost: { fontFamily: F.bodyBold, fontSize: 14, color: C.ink },
  x: { width: 28, height: 28, borderRadius: 14, backgroundColor: C.fill, alignItems: 'center', justifyContent: 'center' },
  xT: { fontFamily: F.bodyBold, fontSize: 12, color: C.onAccent },
}));
