// The scanner's "take a photo" pieces (picture 145, Oct 25, 2026): the camera row at the bottom of the found
// card (a gold camera that clicks like a shutter so people know what it means) and the photo sheet
// (tips, a frame guide, Open the camera / Choose from my photos). Photos stay on the phone.
import { useEffect, useState } from 'react';
import { Animated, Easing, Modal, StyleSheet, View } from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import Svg, { Circle, Path, Rect } from 'react-native-svg';

import { Pressable, Text } from '@/components/t';
import { tap } from '@/components/ui';
import { canPhoto, pickPhoto } from '@/lib/photo';
import { F } from '@/theme';

const GOLD = '#E0B640';
const NAVY = '#0F1A2A';

const CameraGlyph = () => (
  <Svg width={22} height={22} viewBox="0 0 24 24" fill="none" stroke={NAVY} strokeWidth={2.2} strokeLinejoin="round">
    <Path d="M4 8h3l2-3h6l2 3h3v11H4z" /><Circle cx={12} cy={13} r={3.6} />
  </Svg>
);

/** The row under "Use this car". The camera squeezes, flashes and throws little rays every few seconds. */
export function CameraRow({ title, sub, still, onPress }: { title: string; sub: string; still: boolean; onPress: () => void }) {
  const [k] = useState(() => new Animated.Value(0));
  useEffect(() => {
    if (still) return;
    const loop = Animated.loop(Animated.sequence([
      Animated.delay(1400),
      Animated.timing(k, { toValue: 1, duration: 520, easing: Easing.linear, useNativeDriver: true }),
      Animated.timing(k, { toValue: 0, duration: 0, useNativeDriver: true }),
    ]));
    loop.start();
    return () => loop.stop();
  }, [still, k]);
  const scale = k.interpolate({ inputRange: [0, 0.2, 0.45, 0.7, 1], outputRange: [1, 0.86, 1.07, 1, 1] });
  const flash = k.interpolate({ inputRange: [0, 0.18, 0.3, 0.7, 1], outputRange: [0, 0, 0.95, 0, 0] });
  const rays = k.interpolate({ inputRange: [0, 0.25, 0.4, 0.8, 1], outputRange: [0, 0, 1, 0, 0] });
  return (
    <Pressable onPress={() => { tap(); onPress(); }} accessibilityRole="button" accessibilityLabel={`${title}. ${sub}`} style={s.row}>
      <View style={{ width: 40, height: 40 }}>
        <Animated.View style={[s.cam, { transform: [{ scale }] }]}>
          <CameraGlyph />
          <Animated.View style={[StyleSheet.absoluteFill, s.flash, { opacity: flash }]} />
        </Animated.View>
        {[{ left: -7, top: 3, r: '-40deg' }, { left: 18, top: -11, r: '0deg' }, { right: -7, top: 3, r: '40deg' }].map((p, i) => (
          <Animated.View key={i} style={[s.ray, { left: p.left, right: p.right, top: p.top, opacity: rays, transform: [{ rotate: p.r }] }]} />
        ))}
      </View>
      <View style={{ flex: 1, minWidth: 0 }}>
        <Text style={s.title} numberOfLines={1}>{title}</Text>
        <Text style={s.sub} numberOfLines={1}>{sub}</Text>
      </View>
      <Text style={s.chev}>›</Text>
    </Pressable>
  );
}

/** Bottom sheet: how to take a good photo, then the camera or the photo library. Returns a data: address. */
export function PhotoSheet({ onClose, onPhoto }: { onClose: () => void; onPhoto: (uri: string) => void }) {
  const insets = useSafeAreaInsets();
  const [busy, setBusy] = useState(false);
  const go = async (from: 'camera' | 'library') => {
    tap();
    setBusy(true);
    const p = await pickPhoto(from);
    setBusy(false);
    if (!p) return;
    onPhoto(p.base64 ? `data:${p.mime ?? 'image/jpeg'};base64,${p.base64}` : p.uri);
  };
  return (
    <Modal transparent animationType="slide" visible onRequestClose={onClose}>
      <Pressable style={s.back} onPress={onClose} accessibilityLabel="Close" />
      <View style={[s.sheet, { paddingBottom: insets.bottom + 16 }]} accessibilityViewIsModal>
        <View style={s.grab} />
        <Text style={s.h}>Take a photo of this car</Text>
        <Text style={s.p}>Step back so the whole car fits. The front corner works best. Only when you’re parked and safe.</Text>
        <View style={s.guide}>
          <Svg width="100%" height={110} viewBox="0 0 200 110">
            <Rect x={4} y={4} width={192} height={102} rx={12} fill="none" stroke={GOLD} strokeWidth={3} strokeDasharray="10 8" />
            <Path d="M38 78h124l-8-20-22-6-14-16H82L66 52H44l-6 12z" fill="none" stroke="#fff" strokeWidth={3} strokeLinejoin="round" />
            <Circle cx={66} cy={80} r={10} fill="none" stroke="#fff" strokeWidth={3} /><Circle cx={136} cy={80} r={10} fill="none" stroke="#fff" strokeWidth={3} />
          </Svg>
        </View>
        {canPhoto ? (
          <>
            <Pressable onPress={() => go('camera')} disabled={busy} accessibilityRole="button" style={[s.btn, busy && { opacity: 0.6 }]}><Text style={s.btnText}>Open the camera</Text></Pressable>
            <Pressable onPress={() => go('library')} disabled={busy} accessibilityRole="button" style={{ padding: 10, alignSelf: 'center' }}><Text style={s.link}>Choose from my photos</Text></Pressable>
          </>
        ) : <Text style={s.p}>Photos need the newest Carvessa app. Update it to add a photo.</Text>}
        <Text style={s.priv}>No faces or license plates up close. The photo stays on your phone.</Text>
      </View>
    </Modal>
  );
}

const s = StyleSheet.create({
  row: { flexDirection: 'row', alignItems: 'center', gap: 12, marginTop: 10, paddingVertical: 9, paddingHorizontal: 12, borderRadius: 16, backgroundColor: 'rgba(255,255,255,0.07)', borderWidth: 1, borderColor: 'rgba(224,182,64,0.35)' },
  cam: { width: 40, height: 40, borderRadius: 13, backgroundColor: GOLD, alignItems: 'center', justifyContent: 'center', overflow: 'hidden' },
  flash: { backgroundColor: '#FFFFFF', borderRadius: 13 },
  ray: { position: 'absolute', width: 3, height: 8, borderRadius: 2, backgroundColor: '#F3D27A' },
  title: { fontFamily: F.bodyBold, fontSize: 15, color: '#FFFFFF' },
  sub: { fontFamily: F.body, fontSize: 12.5, color: '#9AA7B8', marginTop: 1 },
  chev: { fontFamily: F.bodyBold, fontSize: 24, color: GOLD },
  back: { flex: 1, backgroundColor: 'rgba(0,0,0,0.55)' },
  sheet: { backgroundColor: NAVY, borderTopLeftRadius: 26, borderTopRightRadius: 26, paddingHorizontal: 20, paddingTop: 12, gap: 10 },
  grab: { width: 40, height: 5, borderRadius: 3, backgroundColor: '#3A4658', alignSelf: 'center' },
  h: { fontFamily: F.head, fontSize: 22, color: '#FFFFFF' },
  p: { fontFamily: F.body, fontSize: 14.5, lineHeight: 20, color: '#C3CCD8' },
  guide: { backgroundColor: '#1F2E52', borderRadius: 16, padding: 10 },
  btn: { height: 54, borderRadius: 16, backgroundColor: GOLD, alignItems: 'center', justifyContent: 'center' },
  btnText: { fontFamily: F.bodyBold, fontSize: 17, color: NAVY },
  link: { fontFamily: F.bodyBold, fontSize: 15, color: GOLD },
  priv: { fontFamily: F.body, fontSize: 12.5, color: '#8892A0', textAlign: 'center' },
});
