// My loan (picture 167 screens 1–3, Loudjier said go Oct 30, 2026): the driver types their own loan numbers,
// sees what's left and when it's paid off, marks payments paid and gets a reminder before each one.
// Their numbers only: never an account number, a login or a Social Security number. Totals are ESTIMATES.
// Finance | Lease | Own at the top (Loudjier, Oct 30, 2026): a lease is tracked like a loan (payments, reminders)
// plus the miles it allows; Own = paid off.
import { router } from 'expo-router';
import { useState } from 'react';
import { KeyboardAvoidingView, Platform, ScrollView, StyleSheet, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

import { BigBtn, Card, ToggleRow } from '@/components/account-ui';
import { BellIcon, CashIcon } from '@/components/icons';
import { notify } from '@/components/notify';
import { Ring } from '@/components/ring';
import { sheet, SkyHeader } from '@/components/sky';
import { Pressable, Text, TextInput } from '@/components/t';
import { Body, H, Label, tap } from '@/components/ui';
import { balanceLeft, daysUntil, type HowPaid, howPaid, leaseMiles, monthName, monthYear, shortDate, type Loan, loanChange, markPaid, nextDue, paidThisMonth, payoffDate, paymentAtRate } from '@/data/car-plan';
import { carName } from '@/data/my-cars';
import { canRemind } from '@/lib/reminders';
import { useAuth } from '@/state/auth';
import { useAnswers } from '@/state/answers';
import { useSaved } from '@/state/saved';
import { C, calm, F, PAD, themed } from '@/theme';

const usd = (n: number) => `$${Math.round(n).toLocaleString('en-US')}`;
const num = (t: string) => Number(t.replace(/[^\d.]/g, '')) || 0;

function Field({ label, value, onChange, placeholder, kind = 'number', flex = 1 }: { label: string; value: string; onChange: (v: string) => void; placeholder: string; kind?: 'number' | 'decimal' | 'text'; flex?: number }) {
  return (
    <View style={{ flex }}>
      <Label style={s.fl}>{label}</Label>
      <TextInput value={value} onChangeText={onChange} placeholder={placeholder} placeholderTextColor={C.muted} accessibilityLabel={label}
        keyboardType={kind === 'number' ? 'number-pad' : kind === 'decimal' ? 'decimal-pad' : 'default'} style={s.input} autoCorrect={false} />
    </View>
  );
}

function Tile({ label, big, small, good }: { label: string; big: string; small: string; good?: boolean }) {
  return (
    <View style={s.tile}>
      <Text style={s.tileL}>{label}</Text>
      <Text style={s.tileB}>{big}</Text>
      <Text style={[s.tileS, good && { color: C.green, fontFamily: F.bodyBold }]}>{small}</Text>
    </View>
  );
}

function EditLoan({ loan, isNew, lease, onSave, onCancel, onDelete }: { loan?: Loan; isNew?: boolean; lease?: boolean; onSave: (l: Loan) => void; onCancel: () => void; onDelete?: () => void }) {
  const [lender, setLender] = useState(loan?.lender ?? '');
  const [apr, setApr] = useState(loan ? String(loan.apr) : '');
  const [pay, setPay] = useState(loan?.payment ? String(loan.payment) : '');
  const [day, setDay] = useState(loan?.dueDay ? String(loan.dueDay) : '');
  const [left, setLeft] = useState(loan ? String(loan.left) : '');
  const [total, setTotal] = useState(loan?.total ? String(loan.total) : '');
  const [mpy, setMpy] = useState(loan?.milesPerYear ? String(loan.milesPerYear) : '');
  const [start, setStart] = useState(loan?.startMiles !== undefined ? String(loan.startMiles) : '');
  const d = Math.round(num(day));
  const base = num(pay) > 0 && d >= 1 && d <= 31 && num(left) >= 1 && num(left) <= 120;
  const ok = lease ? base && num(total) >= num(left) && num(total) <= 60 : base && num(apr) >= 0 && num(apr) < 40;
  const next: Loan = lease
    ? { ...loan, kind: 'lease', lender: lender.trim() || undefined, apr: 0, payment: Math.round(num(pay)), dueDay: d, left: Math.round(num(left)), total: Math.round(num(total)),
      milesPerYear: num(mpy) ? Math.round(num(mpy)) : undefined, startMiles: start.trim() ? Math.round(num(start)) : undefined, remind: loan?.remind, autopay: loan?.autopay }
    : { ...loan, kind: undefined, milesPerYear: undefined, startMiles: undefined, lender: lender.trim() || undefined, apr: num(apr), payment: Math.round(num(pay)), dueDay: d, left: Math.round(num(left)),
      total: num(total) >= num(left) ? Math.round(num(total)) : undefined, remind: loan?.remind, autopay: loan?.autopay };
  const change = loan && !isNew && !lease && ok ? loanChange(loan, next) : null;
  // They changed the rate but not the payment: show what the payment on what's left would be, so they can check with the lender.
  const rateOnly = loan && !isNew && !lease && ok && num(apr) !== loan.apr && Math.round(num(pay)) === loan.payment;
  return (
    <View>
      <Card style={{ paddingVertical: 14 }}>
        <Field label={lease ? 'LEASED THROUGH (OPTIONAL)' : 'LENDER (OPTIONAL)'} value={lender} onChange={setLender} placeholder={lease ? 'Toyota Financial' : 'My credit union'} kind="text" />
        <View style={s.two}>
          {!lease && <Field label="RATE (APR %)" value={apr} onChange={setApr} placeholder="6.4" kind="decimal" />}
          <Field label="MONTHLY PAYMENT" value={pay} onChange={setPay} placeholder={lease ? '329' : '392'} />
          {lease && <Field label="DUE EVERY MONTH ON DAY" value={day} onChange={setDay} placeholder="15" />}
        </View>
        <View style={s.two}>
          {!lease && <Field label="DUE EVERY MONTH ON DAY" value={day} onChange={setDay} placeholder="15" />}
          <Field label="PAYMENTS LEFT" value={left} onChange={setLeft} placeholder={lease ? '22' : '65'} />
          {lease && <Field label="LEASE LENGTH (MONTHS)" value={total} onChange={setTotal} placeholder="36" />}
        </View>
        {lease ? (
          <View style={s.two}>
            <Field label="MILES ALLOWED A YEAR" value={mpy} onChange={setMpy} placeholder="12,000" />
            <Field label="MILES WHEN IT STARTED" value={start} onChange={setStart} placeholder="15" />
          </View>
        ) : (
          <View style={s.two}>
            <Field label="LOAN LENGTH IN MONTHS (OPTIONAL)" value={total} onChange={setTotal} placeholder="72" />
          </View>
        )}
        <Body style={s.small}>{lease ? 'It’s all on your lease papers or the leasing company’s app. With your miles allowed, we tell you early if you’re heading over.' : 'It’s all on your loan statement or your lender’s app. We never ask for your account number or login.'}</Body>
      </Card>
      {change && (
        <View style={[s.note, change.month > 0 ? s.good : s.warn]}>
          <Text style={[s.noteB, { color: change.month > 0 ? C.green : C.ink }]}>
            {change.month > 0 ? `You’d pay ${usd(change.month)} less a month` : `You’d pay ${usd(-change.month)} more a month`}
          </Text>
          <Text style={s.noteT}>{`About ${usd(Math.abs(change.total))} ${change.month > 0 ? 'saved' : 'more'} over the rest of the loan (estimate).`}</Text>
        </View>
      )}
      {rateOnly && (
        <View style={[s.note, s.warn]}>
          <Text style={s.noteT}>{`At ${num(apr)}%, the payment on what’s left would be about ${usd(paymentAtRate(next, num(apr)))} (estimate). Your lender has the real number.`}</Text>
        </View>
      )}
      <View style={{ gap: 8, marginTop: 14 }}>
        <BigBtn label="Save" onPress={() => (ok ? onSave(next) : notify('Check your numbers', lease ? 'Add the payment, the day it’s due (1–31), how many payments are left and the lease length.' : 'Add the payment, the rate, the day it’s due (1–31) and how many payments are left.'))} />
        <BigBtn label="Cancel" kind="plain" onPress={onCancel} />
        {onDelete && <BigBtn label={lease ? 'Remove this lease' : 'Remove this loan'} kind="danger" onPress={onDelete} />}
      </View>
    </View>
  );
}

export default function LoanScreen() {
  const { myCar, setMyCar } = useSaved();
  const { session, askAccount } = useAuth();
  const [editing, setEditing] = useState(false);
  const [now] = useState(() => new Date());
  const loan = myCar?.loan;
  const how = myCar ? howPaid(myCar) : null;
  const [tab, setTab] = useState<HowPaid | null>(null);
  const show: HowPaid = tab ?? how ?? 'finance';
  // Bought with a pre-approval (screen 15): start from its rate, lender and length.
  const { answers } = useAnswers();
  const draft: Loan | undefined = how === 'finance' ? loan : answers.pre ? { apr: answers.pre.apr, lender: answers.pre.lender, total: answers.pre.months, left: answers.pre.months, payment: 0, dueDay: 0 } : undefined;
  const save = (l: Loan | undefined) => myCar && setMyCar({ ...myCar, loan: l, owned: l ? undefined : myCar.owned });
  const back = () => router.navigate('/garage');
  const pick = (h: HowPaid) => {
    tap(); setEditing(false); setTab(h);
    if (h === 'own' && myCar && !loan) setMyCar({ ...myCar, owned: true });
  };

  let body: React.ReactNode;
  if (!myCar) {
    body = (
      <Card style={{ paddingVertical: 16 }}>
        <Body bold>Add your car first</Body>
        <Body style={s.small}>Your loan or lease goes with your car in My Garage.</Body>
        <View style={{ marginTop: 12 }}><BigBtn label="Go to My Garage" onPress={back} /></View>
      </Card>
    );
  } else if (show === 'own') {
    body = how === 'own' ? (<>
      {/* Paid off (Loudjier, Oct 30, 2026: "I paid my car off"): no payments, the value is all theirs. */}
      <View style={s.own}>
        <Text style={s.ownB}>✓ You own your car</Text>
        <Text style={s.ownT}>{`Your ${carName(myCar)} is paid off. No car payments. Nice work!`}</Text>
      </View>
      <View style={{ gap: 8, marginTop: 12 }}><BigBtn label="See what it’s worth" kind="soft" onPress={() => router.push('/value')} /></View>
      <Body style={[s.small, { marginTop: 14 }]}>Owning your car outright is a strong spot: its full value can be your money down when you decide to upgrade. No rush.</Body>
    </>) : (
      <Card style={{ paddingVertical: 14 }}>
        <Body bold>{how === 'lease' ? 'Did you buy your leased car?' : 'Is your car paid off?'}</Body>
        <Body style={s.small}>{how === 'lease' ? 'Your lease numbers will be removed, and we’ll show your car as yours.' : 'Your loan numbers will be removed, and we’ll show your car as paid off.'}</Body>
        <View style={{ gap: 8, marginTop: 12 }}>
          <BigBtn label="Yes, I own it" onPress={() => { tap(); setMyCar({ ...myCar, loan: undefined, owned: true }); }} />
          <BigBtn label="Cancel" kind="plain" onPress={() => setTab(null)} />
        </View>
      </Card>
    );
  } else if (show !== how || editing) {
    const lease = show === 'lease';
    body = (<>
      {show !== how && (
        <View style={{ marginBottom: 12 }}>
          <H size={22}>{lease ? 'Track your lease' : 'Track your car loan'}</H>
          <Body style={[s.small, { fontSize: 14 }]}>{lease
            ? 'Your payment, a reminder before each one, when the lease ends, and an early heads-up if you’re heading over your miles.'
            : 'See what’s left, when it’s paid off, and get a reminder before each payment. Your numbers, on your phone.'}</Body>
        </View>
      )}
      <EditLoan key={`${show}-${how}`} loan={show === how ? loan : lease ? undefined : draft} isNew={show !== how} lease={lease}
        onCancel={() => (show !== how ? setTab(null) : setEditing(false))}
        onSave={(l) => { tap(); save(l); setEditing(false); setTab(null); }}
        onDelete={show === how ? () => { tap(); save(undefined); setEditing(false); } : undefined} />
    </>);
  } else if (loan) {
    const lease = loan.kind === 'lease';
    const due = nextDue(loan, now);
    const days = daysUntil(due, now);
    const paidNow = loan.total ? Math.max(0, loan.total - loan.left) : null;
    const end = payoffDate(loan, now);
    const when = days === 0 ? 'today' : days === 1 ? 'tomorrow' : `in ${days} days`;
    const lastPaid = loan.paid?.length ? loan.paid[loan.paid.length - 1] : null;
    const remindOn = !!session && !!loan.remind;
    const lm = lease ? leaseMiles(myCar, now.getTime()) : null;
    body = (<>
      <Card style={{ paddingVertical: 14 }}>
        <View style={{ flexDirection: 'row', gap: 14, alignItems: 'center' }}>
          {paidNow !== null
            ? <Ring pct={paidNow / loan.total!} big={`${paidNow}/${loan.total}`} small="paid" size={84} />
            : <Ring pct={0} big={String(loan.left)} small="left" size={84} />}
          <View style={{ flex: 1 }}>
            <Text style={s.big}>{`Next payment: ${shortDate(due)}`}</Text>
            <Text style={s.sub}>{`${usd(loan.payment)} · ${when}`}</Text>
            {lastPaid && <Text style={[s.sub, { color: C.green, fontFamily: F.bodyBold }]}>{`✓ Marked paid: ${monthName(Number(lastPaid.slice(5)) - 1)}`}</Text>}
          </View>
        </View>
        {loan.left > 0 && (
          <Pressable onPress={() => { tap(); save(markPaid(loan, now)); }} accessibilityRole="button" style={s.paid}>
            <Text style={s.paidT}>{`✓ I paid the ${monthName(due.getMonth())} payment`}</Text>
          </Pressable>
        )}
      </Card>
      {lease ? (
        <View style={s.tiles}>
          <Tile label="PAYMENT" big={usd(loan.payment)} small="a month" />
          <Tile label="PAYMENTS LEFT" big={String(loan.left)} small={`of ${loan.total}`} />
          <Tile label="LEASE ENDS" big={loan.left ? monthYear(end) : 'Done!'} small={loan.left ? 'last payment' : 'no payments left'} good={!loan.left} />
          <Tile label="MILES" big={lm ? (lm.over > 0 ? `≈ ${lm.over.toLocaleString('en-US')} over` : 'On track') : '—'} small={lm ? 'at this pace, est.' : 'add allowed miles'} good={!!lm && lm.over <= 0} />
        </View>
      ) : (
        <View style={s.tiles}>
          <Tile label="RATE" big={`${loan.apr}%`} small="you entered" />
          <Tile label="PAYMENT" big={usd(loan.payment)} small="a month" />
          <Tile label="LEFT TO PAY" big={`≈ ${usd(balanceLeft(loan))}`} small="estimate" />
          <Tile label="PAID OFF" big={loan.left ? monthYear(end) : 'Done!'} small={loan.left ? 'if you pay on time' : 'no payments left'} good={!loan.left} />
        </View>
      )}
      {lease && lm && (
        <View style={[s.note, lm.over > 0 ? s.warn : s.good]}>
          <Text style={[s.noteB, { color: lm.over > 0 ? C.ink : C.green }]}>{lm.over > 0 ? `Heading about ${lm.over.toLocaleString('en-US')} miles over` : 'On track with your miles'}</Text>
          <Text style={s.noteT}>{lm.over > 0
            ? `Your lease allows ${lm.allowed.toLocaleString('en-US')} miles. At this pace you’d finish about ${lm.over.toLocaleString('en-US')} over (estimate). Leases often charge for each mile over: check your contract.`
            : `Your lease allows ${lm.allowed.toLocaleString('en-US')} miles. At this pace you’d finish under that (estimate).`}</Text>
        </View>
      )}
      <Card style={{ marginTop: 10 }}>
        <ToggleRow icon={(c) => <BellIcon size={18} color={c} />} label="Remind me" sub={lease ? '3 days before each payment, and 3 months before the lease ends' : '3 days before, and the morning it’s due'} on={remindOn}
          onChange={async (v) => {
            if (!session) return askAccount('Get payment reminders', 'Free account. A reminder 3 days before each car payment. No spam, never sold.');
            if (v && Platform.OS !== 'web' && !(await canRemind(true))) return notify('Reminders are off', 'Alerts are off for Carvessa in your phone settings. Turn them on there, then try again.');
            if (v && Platform.OS === 'web') notify('Reminders', 'Payment reminders show up in the phone app.');
            save({ ...loan, remind: v });
          }} />
        <ToggleRow last t="green" icon={(c) => <CashIcon size={18} color={c} />} label="I use autopay" sub="Then we only send a heads-up" on={!!loan.autopay}
          onChange={(v) => save({ ...loan, autopay: v })} />
      </Card>
      <View style={{ marginTop: 12, gap: 8 }}>
        <BigBtn label={lease ? '✎ Edit my lease' : '✎ Edit my loan'} kind="soft" onPress={() => setEditing(true)} />
        {!lease && <BigBtn label="I paid it off" kind="plain" onPress={() => { tap(); setMyCar({ ...myCar, loan: undefined, owned: true }); }} />}
      </View>
      {paidThisMonth(loan, now) && <Body style={[s.small, { textAlign: 'center', color: C.green }]}>This month is paid. Nice.</Body>}
      <Body style={[s.small, { marginTop: 14 }]}>{lease
        ? 'At the end of a lease you can usually return the car, buy it, or trade up. Your lease papers have the final word; miles are our estimate.'
        : 'These are your numbers. Your lender’s statement has the final word. “Left to pay” is our estimate from your rate and payments.'}</Body>
    </>);
  }

  const seg = myCar ? (
    <View style={s.seg} accessibilityRole="tablist">
      {(['finance', 'lease', 'own'] as const).map((h) => {
        const on = show === h;
        return (
          <Pressable key={h} onPress={() => pick(h)} accessibilityRole="tab" accessibilityState={{ selected: on }} style={[s.segB, on && s.segOn]}>
            <Text style={[s.segT, on && { color: C.onAccent }]}>{h === 'finance' ? 'Finance' : h === 'lease' ? 'Lease' : 'Own'}</Text>
          </Pressable>
        );
      })}
    </View>
  ) : null;
  const title = !myCar ? 'Finance, lease or own' : show === 'lease' ? 'My lease' : show === 'own' ? (how === 'own' ? 'My car is paid off' : 'Own it') : 'My loan';
  return (
    <SafeAreaView edges={calm ? [] : ['top']} style={{ flex: 1, backgroundColor: C.bg }}>
      <SkyHeader title={title} sub={myCar ? `${carName(myCar)}${loan?.lender ? ` · ${loan.lender}` : ''}` : undefined} back={back} />
      <KeyboardAvoidingView behavior={Platform.OS === 'ios' ? 'padding' : undefined} style={calm ? sheet.page : { flex: 1 }}>
        <ScrollView contentContainerStyle={{ paddingHorizontal: PAD, paddingBottom: 40, paddingTop: 6 }} keyboardShouldPersistTaps="handled">
          {seg}
          {body}
        </ScrollView>
      </KeyboardAvoidingView>
    </SafeAreaView>
  );
}

const s = themed(() => StyleSheet.create({
  seg: { flexDirection: 'row', backgroundColor: C.card, borderRadius: 999, padding: 4, marginBottom: 14, borderWidth: 1, borderColor: C.line },
  segB: { flex: 1, paddingVertical: 10, borderRadius: 999, alignItems: 'center' },
  segOn: { backgroundColor: C.fill },
  segT: { fontFamily: F.bodyBold, fontSize: 14.5, color: C.muted },
  fl: { fontSize: 10.5, color: C.muted, marginBottom: 4, marginTop: 10 },
  input: { height: 48, borderWidth: 1.5, borderColor: C.line, borderRadius: 12, paddingHorizontal: 12, fontFamily: F.bodyBold, fontSize: 16, color: C.ink, backgroundColor: C.card },
  two: { flexDirection: 'row', gap: 8 },
  small: { fontSize: 12, color: C.muted, marginTop: 8, lineHeight: 17 },
  big: { fontFamily: F.bodyBold, fontSize: 16.5, color: C.ink },
  sub: { fontFamily: F.body, fontSize: 13, color: C.muted, marginTop: 2 },
  paid: { marginTop: 12, backgroundColor: C.fill, borderRadius: 999, paddingVertical: 11, alignItems: 'center' },
  paidT: { fontFamily: F.bodyBold, fontSize: 14, color: C.onAccent },
  tiles: { flexDirection: 'row', flexWrap: 'wrap', gap: 8, marginTop: 10 },
  tile: { flexBasis: '48%', flexGrow: 1, backgroundColor: C.card, borderRadius: 14, padding: 12, borderWidth: 1, borderColor: C.line },
  tileL: { fontFamily: F.bodyBold, fontSize: 10.5, letterSpacing: 0.5, color: C.muted },
  tileB: { fontFamily: F.head, fontSize: 19, color: C.ink, marginTop: 2 },
  tileS: { fontFamily: F.body, fontSize: 11.5, color: C.muted },
  note: { borderRadius: 14, padding: 12, marginTop: 10 },
  good: { backgroundColor: 'rgba(31,157,85,0.12)' },
  warn: { backgroundColor: C.fill },
  noteB: { fontFamily: F.bodyBold, fontSize: 14 },
  own: { backgroundColor: 'rgba(31,157,85,0.12)', borderRadius: 16, padding: 16 },
  ownB: { fontFamily: F.head, fontSize: 20, color: C.green },
  ownT: { fontFamily: F.body, fontSize: 14, color: C.ink, marginTop: 4, lineHeight: 20 },
  ownBtn: { marginTop: 12, borderWidth: 1.5, borderColor: C.green, borderRadius: 999, paddingVertical: 11, alignItems: 'center' },
  ownBtnT: { fontFamily: F.bodyBold, fontSize: 14, color: C.green },
  noteT: { fontFamily: F.body, fontSize: 12.5, color: C.ink, marginTop: 2, lineHeight: 18 },
}));
