// Logo D (picked Oct 12, 2026; the logo Carvessa keeps): "CAR" + a gold headlight V + "essa".
// The V is two headlight blades that meet at the bottom. It is exactly as tall as the capital
// letters (Michroma caps are 0.75 of the font size) and sits on the same line as the letters.
// Same shape as design/logo/carvessa-v-mark-*.svg.
import { View } from 'react-native';
import Svg, { Polygon } from 'react-native-svg';

import { F } from '@/theme';
import { Text } from '@/components/t';

export const V_LEFT = '0,0 27,0 52,70 40,92';
export const V_RIGHT = '100,0 73,0 48,70 60,92';

export function VMark({ height, color }: { height: number; color: string }) {
  return (
    <Svg width={(height * 100) / 92} height={height} viewBox="0 0 100 92">
      <Polygon points={V_LEFT} fill={color} />
      <Polygon points={V_RIGHT} fill={color} />
    </Svg>
  );
}

// ink = color of "CAR"; gold = color of the V and "essa".
export function Wordmark({ size, ink, gold, glow }: { size: number; ink: string; gold: string; glow?: boolean }) {
  // glow: a soft dark shadow so the logo reads on a picture (picture 67 B).
  const shadow = glow ? { textShadowColor: 'rgba(0,0,0,0.85)', textShadowOffset: { width: 0, height: 1 }, textShadowRadius: 8 } : null;
  const text = { fontFamily: F.logo, fontSize: size, letterSpacing: size * 0.06, ...shadow };
  return (
    <View style={{ flexDirection: 'row', alignItems: 'baseline' }} accessible accessibilityLabel="Carvessa">
      <Text style={[text, { color: ink }]}>CAR</Text>
      <View style={{ marginLeft: size * 0.12, marginRight: size * 0.07 }}>
        <VMark height={size * 0.75} color={gold} />
      </View>
      <Text style={[text, { color: gold }]}>essa</Text>
    </View>
  );
}
