import { useState } from 'react';
import { ActivityIndicator, Linking, StyleSheet, View } from 'react-native';

import { Body, H, Label, tap } from '@/components/ui';
import { Facts } from '@/data/gov';
import { useFacts } from '@/data/use-facts';
import { C, F, themed } from '@/theme';
import { Pressable } from '@/components/t';
import { LATEST_MODEL_YEAR } from '@/data/year';
import { AlertIcon } from '@/components/icons';

// NHTSA part names look like "STEERING:LINKAGES:KNUCKLE"; show the first, plainest part.
const partName = (p: string) => p.split(/[:/]/)[0].trim().toLowerCase().replace(/^\w/, (c) => c.toUpperCase());

const yearNote = (y: number | undefined, want = LATEST_MODEL_YEAR) => (y && y !== want ? ` · ${y} model` : '');

export function Stars({ n }: { n: number }) {
  return <H size={17} numberOfLines={1} accessibilityLabel={`${n} out of 5 stars`}>{'★'.repeat(n)}<H size={17} style={{ color: '#4A4F59' }}>{'★'.repeat(5 - n)}</H></H>;
}

function Tile({ label, children, note, hi }: { label: string; children: React.ReactNode; note: string; hi?: boolean }) {
  return (
    <View style={[s.tile, hi && { backgroundColor: C.accentSoft, borderColor: C.yellow }]}>
      <Label style={s.tileL}>{label}</Label>
      <View style={{ minHeight: 26, justifyContent: 'center' }}>{children}</View>
      <Body style={s.tileN}>{note}</Body>
    </View>
  );
}

// "Real facts" box for the car screens: crash stars, MPG and recalls from the government.
export function RealFacts({ carId, year = LATEST_MODEL_YEAR, recallsOpen = false }: { carId: string; year?: number; recallsOpen?: boolean }) {
  const { facts, loading } = useFacts(carId, year);
  const [open, setOpen] = useState(recallsOpen);
  const f: Facts = facts ?? { source: {} };
  const recalls = f.recalls ?? [];
  const offline = !loading && f.stars === undefined && f.mpg === undefined && f.recalls === undefined;

  return (
    <View style={{ marginTop: 18 }}>
      <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'baseline' }}>
        <Label>Real facts</Label>
        <Label style={{ fontSize: 10, color: C.muted }}>{f.saved ? `Saved ${f.saved} · ` : ''}NHTSA.gov + FuelEconomy.gov</Label>
      </View>
      {loading ? (
        <View style={s.wait}><ActivityIndicator color={C.ink} /><Body>Checking government data…</Body></View>
      ) : offline ? (
        <View style={s.wait}><Body>Can’t reach the government data right now. Check your internet and try again.</Body></View>
      ) : (
        <>
          <View style={s.row}>
            <Tile label="Crash test" note={f.stars ? `NHTSA overall${yearNote(f.source.safety, year)}` : 'Not rated yet'}>
              {f.stars ? <Stars n={f.stars} /> : <H size={22}>—</H>}
            </Tile>
            <Tile label={f.mpg?.fuel === 'EV' ? 'Electric' : 'Gas mileage'} note={f.mpg ? `${f.mpg.city} city · ${f.mpg.hwy} hwy${yearNote(f.source.mpg, year)}` : 'Not listed yet'}>
              <H size={24}>{f.mpg ? `${f.mpg.combined} ${f.mpg.fuel === 'EV' ? 'MPGe' : 'MPG'}` : '—'}</H>
            </Tile>
            <Tile label="Recalls" hi={recalls.length > 0} note={f.recalls ? `${f.source.recalls ?? year} model` : 'Not available'}>
              <H size={24}>{f.recalls ? (recalls.length ? recalls.length : 'None') : '—'}</H>
            </Tile>
          </View>
          {recalls.length > 0 && (
            <View style={s.banner}>
              <AlertIcon size={22} color={C.red} />
              <Body style={{ flex: 1, fontSize: 14 }}><Body bold style={{ fontSize: 14 }}>{recalls.length} recall{recalls.length === 1 ? '' : 's'} for the {f.source.recalls ?? year} model.</Body> Fixes are free at any dealer.</Body>
            </View>
          )}
          {recalls.length > 0 && (
            <Pressable onPress={() => { tap(); setOpen(!open); }} accessibilityRole="button" style={s.more}>
              <Body bold>{open ? 'Hide recalls' : `See ${recalls.length === 1 ? 'the recall' : `all ${recalls.length} recalls`}`}</Body>
              <Body bold>{open ? '−' : '+'}</Body>
            </Pressable>
          )}
          {open && recalls.map((r) => (
            <View key={r.id} style={s.recall}>
              <Label style={{ fontSize: 11 }}>{partName(r.part)}</Label>
              <Body style={{ fontSize: 13.5, marginTop: 4 }}><Body bold style={{ fontSize: 13.5 }}>The problem: </Body>{r.summary}</Body>
              {!!r.risk && <Body style={{ fontSize: 13, marginTop: 6 }}><Body bold style={{ fontSize: 13 }}>Why it matters: </Body>{r.risk}</Body>}
              {!!r.fix && <Body style={{ fontSize: 13, marginTop: 6 }}><Body bold style={{ fontSize: 13 }}>The fix: </Body>{r.fix}</Body>}
              <Body style={{ fontSize: 11.5, color: C.muted, marginTop: 6 }}>Recall #{r.id} · Fixed free at a dealer</Body>
            </View>
          ))}
          {recalls.length > 0 && (
            <Pressable onPress={() => Linking.openURL('https://www.nhtsa.gov/recalls')} accessibilityRole="link">
              <Body style={{ fontSize: 12, color: C.muted, marginTop: 8, textDecorationLine: 'underline' }}>Check a specific car by VIN at nhtsa.gov/recalls</Body>
            </Pressable>
          )}
        </>
      )}
    </View>
  );
}

const s = themed(() => StyleSheet.create({
  row: { flexDirection: 'row', gap: 6, marginTop: 6 },
  tile: { flex: 1, borderWidth: 1, borderColor: C.line, borderRadius: 12, padding: 8 },
  tileL: { fontSize: 9.5, color: C.muted },
  tileN: { fontSize: 10.5, lineHeight: 13, color: C.muted, fontFamily: F.body },
  wait: { flexDirection: 'row', gap: 10, alignItems: 'center', borderWidth: 2, borderColor: C.line, padding: 12, marginTop: 6 },
  more: { flexDirection: 'row', justifyContent: 'space-between', borderBottomWidth: 2, borderBottomColor: C.grey, paddingVertical: 10 },
  recall: { backgroundColor: C.card, borderWidth: 1, borderColor: C.line, borderRadius: 14, padding: 12, marginTop: 8 },
  banner: { flexDirection: 'row', gap: 10, alignItems: 'center', borderRadius: 14, borderWidth: 1, borderColor: C.red, backgroundColor: 'rgba(224,101,79,0.10)', padding: 12, marginTop: 10 },
}));

// One short line for result cards, like "31 MPG · 5★ safety · 1 recall".
export function FactLine({ carId, year = LATEST_MODEL_YEAR }: { carId: string; year?: number }) {
  const { facts, loading } = useFacts(carId, year);
  if (loading) return <Body style={{ fontSize: 12, opacity: 0.6 }}>Checking real data…</Body>;
  const parts = [
    facts?.mpg ? `${facts.mpg.combined} ${facts.mpg.fuel === 'EV' ? 'MPGe · electric' : 'MPG'}` : null,
    facts?.stars ? `${facts.stars}★ safety` : null,
    facts?.recalls ? (facts.recalls.length ? `${facts.recalls.length} recall${facts.recalls.length > 1 ? 's' : ''}` : 'No recalls') : null,
  ].filter(Boolean);
  return <Body style={{ fontSize: 12, opacity: 0.8 }}>{parts.length ? parts.join(' · ') : 'Price and facts: coming soon'}</Body>;
}
