// Your own profile photo (picture 131, Oct 24, 2026). Kept only on this phone (its own storage key, so it isn't
// saved again every time a setting changes). It never goes to our server.
import AsyncStorage from '@react-native-async-storage/async-storage';
import { useSyncExternalStore } from 'react';

const KEY = 'carvessa:photo:v1';
const MAX = 1_500_000; // a square photo is usually far smaller; bigger ones are refused, not saved
let photo: string | null = null;
let loaded = false;
const subs = new Set<() => void>();
const tell = () => subs.forEach((f) => f());

function load() {
  if (loaded) return;
  loaded = true;
  AsyncStorage.getItem(KEY).then((p) => { if (p) { photo = p; tell(); } }).catch(() => {});
}

/** Saves the photo (a data: address). Returns false when it's too big to keep. */
export function setProfilePhoto(p: string | null): boolean {
  if (p && p.length > MAX) return false;
  photo = p;
  tell();
  (p ? AsyncStorage.setItem(KEY, p) : AsyncStorage.removeItem(KEY)).catch(() => {});
  return true;
}

export function useProfilePhoto(): string | null {
  load();
  return useSyncExternalStore((f) => { subs.add(f); return () => { subs.delete(f); }; }, () => photo, () => photo);
}
