// The feature icon grid (Features A, picked Oct 9, 2026), shared by the Features screen and the
// coach's features question (picture 52 A, Oct 14, 2026). Tap once = want it. Tap again = must
// have (gold star). Tap a third time = off.
import { useState } from 'react';
import { StyleSheet, View } from 'react-native';
import Svg, { Path } from 'react-native-svg';

import { Pressable, Text } from '@/components/t';
import { tap } from '@/components/ui';
import { FEATURE_CATS, FEATURE_TILES, type FeatureTile } from '@/data/features';
import type { Answers } from '@/state/answers';
import { C, F, themed } from '@/theme';

export type Pick = 0 | 1 | 2; // off, want, must
export type Picks = Record<string, Pick>;

// Start from what they picked before.
export function picksFrom(a: { mustHaves: Answers['mustHaves']; wants?: Answers['wants'] }): Picks {
  const p: Picks = {};
  for (const t of FEATURE_TILES) {
    if (t.keys.some((k) => a.mustHaves.includes(k))) p[t.label] = 2;
    else if (t.keys.some((k) => a.wants?.includes(k))) p[t.label] = 1;
  }
  return p;
}
export const cycled = (picks: Picks, label: string): Picks => ({ ...picks, [label]: (((picks[label] ?? 0) + 1) % 3) as Pick });
export const mustTiles = (picks: Picks): FeatureTile[] => FEATURE_TILES.filter((t) => picks[t.label] === 2);
export const wantTiles = (picks: Picks): FeatureTile[] => FEATURE_TILES.filter((t) => picks[t.label] === 1);
// What goes into the saved answers.
export const picksToAnswers = (picks: Picks) => ({ mustHaves: mustTiles(picks).flatMap((t) => t.keys), wants: wantTiles(picks).flatMap((t) => t.keys) });

function Star() {
  return <Svg width={11} height={11} viewBox="0 0 24 24" fill={C.onAccent}><Path d="M12 2l3 6.5 7 .8-5.2 4.8 1.5 7-6.3-3.6-6.3 3.6 1.5-7L2 9.3l7-.8z" /></Svg>;
}

export function FeatureGrid({ picks, onChange, width, small }: { picks: Picks; onChange: (p: Picks) => void; width: number; small?: boolean }) {
  const [cat, setCat] = useState<(typeof FEATURE_CATS)[number]>('All');
  const gap = small ? 6 : 8;
  const tileW = (width - gap * 2) / 3;
  return (
    <View style={{ gap: small ? 8 : 10 }}>
      <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: 6 }}>
        {FEATURE_CATS.map((c) => (
          <Pressable key={c} onPress={() => { tap(); setCat(c); }} accessibilityRole="button" accessibilityState={{ selected: cat === c }}
            style={[s.cat, cat === c && { backgroundColor: C.fill, borderColor: C.fill }]}>
            <Text style={[s.catText, cat === c && { color: C.onAccent }]}>{c}</Text>
          </Pressable>
        ))}
      </View>
      <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap }}>
        {FEATURE_TILES.filter((t) => cat === 'All' || t.cat === cat).map((t) => {
          const p = picks[t.label] ?? 0;
          return (
            <Pressable key={t.label} onPress={() => { tap(); onChange(cycled(picks, t.label)); }} accessibilityRole="button"
              accessibilityLabel={`${t.label}, ${p === 2 ? 'must have' : p === 1 ? 'picked' : 'not picked'}`}
              style={({ pressed }) => [s.tile, { width: tileW, height: small ? 76 : 86 }, p > 0 && s.tileOn, pressed && { opacity: 0.8 }]}>
              <Svg width={small ? 24 : 26} height={small ? 24 : 26} viewBox="0 0 24 24" fill="none" stroke={p > 0 ? C.yellow : C.ink} strokeWidth={1.8} strokeLinecap="round" strokeLinejoin="round"><Path d={t.icon} /></Svg>
              <Text style={s.tileText}>{t.label}</Text>
              {p === 2 && <View style={s.star}><Star /></View>}
              {t.top && <Text style={s.top3}>TOP PICK</Text>}
            </Pressable>
          );
        })}
      </View>
    </View>
  );
}

const s = themed(() => StyleSheet.create({
  cat: { borderRadius: 20, borderWidth: 1, borderColor: C.line, backgroundColor: C.card, paddingHorizontal: 12, paddingVertical: 6 },
  catText: { fontFamily: F.bodyBold, fontSize: 13, color: C.ink },
  tile: { borderRadius: 14, backgroundColor: C.card, borderWidth: 1, borderColor: C.line, alignItems: 'center', justifyContent: 'center', gap: 5, padding: 4 },
  tileOn: { backgroundColor: C.hero, borderColor: C.yellow },
  tileText: { fontFamily: F.bodyBold, fontSize: 12.5, lineHeight: 14, color: C.ink, textAlign: 'center' },
  star: { position: 'absolute', right: 6, top: 6, width: 18, height: 18, borderRadius: 9, backgroundColor: C.fill, alignItems: 'center', justifyContent: 'center' },
  top3: { position: 'absolute', left: 7, top: 6, fontFamily: F.bodyBold, fontSize: 8.5, letterSpacing: 0.3, color: C.yellow },
}));
