// Spanish (picture 50 B, picked Oct 14, 2026). The app is written in English. When Spanish is on,
// every piece of text shown by our Text, TextInput and Pressable (components/t.tsx) is looked up
// in es.ts: first the exact words, then the patterns (for text with numbers or names in it).
// Text with no Spanish yet stays in English, so nothing ever shows up blank.
// The language comes from Me or the ES button on Login, or from the phone's language at first.
import { ES, ES_PATTERNS } from '@/i18n/es';

export type Lang = 'en' | 'es';
export let lang: Lang = 'en';
let cache = new Map<string, string>();

// Text we had no Spanish for (used by our test tool to find what's left to translate).
export const missing = new Set<string>();

export function applyLang(l: Lang) {
  if (l === lang) return;
  lang = l;
  cache = new Map();
}

export function phoneLang(): Lang {
  try {
    return /^es\b/i.test(Intl.DateTimeFormat().resolvedOptions().locale) ? 'es' : 'en';
  } catch {
    return 'en';
  }
}

// Spanish for these exact words, or null if we don't have it.
function find(core: string): string | null {
  const hit = ES[core];
  if (hit !== undefined) return hit;
  for (const [re, out] of ES_PATTERNS) {
    if (re.test(core)) return core.replace(re, (...m) => {
      // $1, $2 … put back what matched; {1}, {2} put it back translated (e.g. "1 recall").
      const groups = m.slice(1, -2) as string[];
      // One pass, so a dollar amount inside a translated group ("$1,470") is never read as "$1".
      return out.replace(/\{(\d)\}|\$(\d)/g, (_x: string, t?: string, r?: string) => (t ? tr(groups[Number(t) - 1] ?? '') : groups[Number(r) - 1] ?? ''));
    });
  }
  // The same words with a period at the end.
  if (core.length > 2 && core.endsWith('.')) {
    const bare = find(core.slice(0, -1));
    if (bare !== null) return /[.!?]$/.test(bare) ? bare : bare + '.';
  }
  // A label made of several sentences ("Hustle. Car that pays"): translate each one.
  const parts = core.replace(/([.!?]) (?=\S)/g, '$1\u0000').split('\u0000');
  if (parts.length > 1) {
    const got = parts.map((x) => find(x));
    if (got.some((x) => x !== null)) return got.map((x, i) => x ?? parts[i]).join(' ');
  }
  // A list ("Must have: Heated seats · Color: Red" or "Sunroof, Navigation"): translate each part.
  for (const sep of [' · ', ', ']) {
    if (!core.includes(sep)) continue;
    const bits = core.split(sep);
    const got = bits.map((x) => find(x));
    if (got.some((x) => x !== null)) return got.map((x, i) => x ?? bits[i]).join(sep);
  }
  return null;
}

function lookup(core: string, record = true): string {
  const got = find(core);
  if (got !== null) return got;
  if (record && /[a-z]{2}/i.test(core)) missing.add(core);
  return core;
}

// Translate one piece of text, keeping its spaces at the start and end.
export function tr(text: string, record = true): string {
  if (lang === 'en' || !text || !/[a-z]/i.test(text)) return text;
  const got = cache.get(text);
  if (got !== undefined) return got;
  const m = text.match(/^(\s*)([\s\S]*?)(\s*)$/);
  const out = m ? m[1] + lookup(m[2], record) + m[3] : text;
  if (out !== text || !record) cache.set(text, out);
  return out;
}

// A line made of words plus numbers or names ("What will the ", name, " really cost me?"):
// translate the whole line first so Spanish word order works, else each piece.
export function trLine(pieces: (string | number)[]): string[] {
  const whole = pieces.join('');
  if (lang === 'en') return pieces.map(String);
  const m = whole.match(/^(\s*)([\s\S]*?)(\s*)$/);
  const got = m ? find(m[2]) : null;
  if (got !== null) return [m![1] + got + m![3]];
  if (/[a-z]{2}/i.test(whole)) missing.add(whole.trim());
  return pieces.map((x) => (typeof x === 'string' ? tr(x, false) : String(x)));
}

// For text that isn't inside our Text (pop-ups, read out loud, the opening).
export const t = tr;

// Voice for reading out loud.
export const speechLang = () => (lang === 'es' ? 'es-US' : 'en-US');

// Lets our test tool read what's still in English on the web version.
(globalThis as { __i18nMissing?: Set<string> }).__i18nMissing = missing;
