// The home screen widgets need the widget part of the Android app file (Nov 5, 2026 build or later).
// Older app files get our updates too, so we check first: loading the widget package without it would crash.
import { NativeModules, Platform, TurboModuleRegistry } from 'react-native';

export function hasWidgets(): boolean {
  if (Platform.OS !== 'android') return false;
  try {
    return TurboModuleRegistry.get('AndroidWidget') != null || NativeModules.AndroidWidget != null;
  } catch {
    return false;
  }
}
