// Warning light · Set D · Coach chat ("Pick from a list"). Snapping a photo comes with the AI coach later.
import { router, useLocalSearchParams } from 'expo-router';
import { useEffect, useRef, useState } from 'react';
import { Linking, Platform, ScrollView, StyleSheet, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import Svg, { Path } from 'react-native-svg';

import { BackIcon, CoachIcon } from '@/components/icons';
import { Body, Btn, H, Label, SquareBtn, tap } from '@/components/ui';
import { LEVEL, LIGHTS } from '@/data/lights';
import { useSaved } from '@/state/saved';
import { calm, C, F, PAD, themed } from '@/theme';
import { sheet, SkyHeader } from '@/components/sky';
import { Pressable, Text } from '@/components/t';

const mapsSearch = (q: string) =>
  Platform.OS === 'ios' ? `http://maps.apple.com/?q=${encodeURIComponent(q)}` : `https://www.google.com/maps/search/${encodeURIComponent(q)}`;

function Bubble({ me, children }: { me?: boolean; children: React.ReactNode }) {
  return (
    <View style={[s.bub, me ? s.me : s.them]}>
      <Text style={me ? s.meText : s.themText}>{children}</Text>
    </View>
  );
}
function LightIcon({ d, color, size = 34 }: { d: string; color: string; size?: number }) {
  return (
    <Svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke={color} strokeWidth={1.9} strokeLinecap="round" strokeLinejoin="round">
      <Path d={d} />
    </Svg>
  );
}

export default function WarningLight() {
  const { myCar } = useSaved();
  // The 'Light on?' widget opens this screen on the light they tapped (?light=oil).
  const { light: asked } = useLocalSearchParams<{ light?: string }>();
  const [id, setId] = useState<string | null>(asked ?? null);
  const [seenAsk, setSeenAsk] = useState(asked);
  if (asked !== seenAsk) { setSeenAsk(asked); if (asked) setId(asked); }
  // Opened on a light: show its help (it's below the list of lights).
  useEffect(() => {
    if (!asked) return;
    const t = setTimeout(() => scroll.current?.scrollToEnd({ animated: true }), 450);
    return () => clearTimeout(t);
  }, [asked]);
  const scroll = useRef<ScrollView>(null);
  const light = LIGHTS.find((l) => l.id === id);
  const lv = light ? LEVEL[light.level] : null;
  const car = myCar ? `${myCar.year} ${myCar.make} ${myCar.model}` : 'your car';

  return (
    <SafeAreaView edges={calm ? [] : ['top']} style={{ flex: 1, backgroundColor: C.bg }}>
      {calm ? <SkyHeader title="Warning light" back={() => router.back()} /> : (
        <View style={s.top}>
          <SquareBtn label="Back" onPress={() => router.back()}><BackIcon /></SquareBtn>
          <View style={{ flexDirection: 'row', alignItems: 'center', gap: 6 }}><CoachIcon size={18} /><Label>Warning light</Label></View>
          <View style={{ width: 44 }} />
        </View>
      )}
      <View style={calm ? sheet.page : { flex: 1 }}>
      <ScrollView ref={scroll} contentContainerStyle={{ paddingHorizontal: PAD, paddingBottom: 40, gap: 8 }}>
        <Pressable onPress={() => { tap(); router.push({ pathname: '/light-help', params: { kind: 'ask', id: 'start' } }); }} accessibilityRole="button" style={askLink.box}>
          <Text style={askLink.t}>Not sure which one? Ask in your own words or send a photo ›</Text>
        </Pressable>
        <Bubble me>A light just came on in my dash.</Bubble>
        <Bubble>No worries. Tap the light that looks like yours.</Bubble>
        <View style={s.grid}>
          {LIGHTS.map((l) => (
            <Pressable key={l.id} onPress={() => { tap(); setId(l.id); setTimeout(() => scroll.current?.scrollToEnd({ animated: true }), 80); }}
              accessibilityRole="button" accessibilityLabel={l.name} accessibilityState={{ selected: id === l.id }}
              style={[s.tile, id === l.id && { borderColor: C.yellow, backgroundColor: C.accentSoft }]}>
              <View style={s.dash}><LightIcon d={l.icon} color={l.color} /></View>
              <Body bold style={{ fontSize: 12, textAlign: 'center', color: id === l.id ? C.ink : C.ink }}>{l.name}</Body>
            </Pressable>
          ))}
        </View>

        {light && lv && (
          <>
            <Bubble me>What does the “{light.name}” light mean?</Bubble>
            {light.level === 'stop' && (
              <View style={s.danger}><Body bold style={{ color: C.ink }}>Safety first: pull over somewhere safe and turn the engine off.</Body></View>
            )}
            <View style={s.card}>
              <View style={{ flexDirection: 'row', gap: 12, alignItems: 'center' }}>
                <View style={[s.dash, { width: 56, height: 56 }]}><LightIcon d={light.icon} color={light.color} size={40} /></View>
                <View style={{ flex: 1 }}>
                  <H size={24}>{light.name}</H>
                  <View style={[s.level, { backgroundColor: lv.color }]}><Label style={{ fontSize: 10.5, color: light.level === 'soon' ? '#14161A' : '#FFFFFF' }}>{lv.label}</Label></View>
                </View>
              </View>
              <Body style={{ marginTop: 10, fontSize: 15.5 }}>{light.means}</Body>
              {light.id === 'tire' && (
                <View style={s.psi}>
                  <Label style={{ color: C.yellow }}>For {car}</Label>
                  <Body style={{ color: C.ink, marginTop: 4 }}>The right air pressure (PSI) is on the sticker inside the driver’s door. Use that number, not the one on the tire.</Body>
                </View>
              )}
              {light.todo.map((t, i) => (
                <View key={t} style={s.step}>
                  <View style={s.stepN}><H size={15} style={{ color: C.onAccent }}>{i + 1}</H></View>
                  <Body style={{ flex: 1, fontSize: 14.5 }}>{t}</Body>
                </View>
              ))}
            </View>
            {/* Picture 109 A: step-by-step help for every light (free account). */}
            <Btn kind="yellow" label="Talk it through, step by step" onPress={() => { tap(); router.push({ pathname: '/light-help', params: { id: light.id } }); }} />
            {light.id === 'tire' && <Btn label="Find air near me" onPress={() => Linking.openURL(mapsSearch('air pump gas station'))} />}
            {light.id === 'fuel' && <Btn label="Find gas near me" onPress={() => Linking.openURL(mapsSearch('gas station'))} />}
            {light.level !== 'info' && light.id !== 'tire' && <Btn label="Find a repair shop near me" onPress={() => Linking.openURL(mapsSearch('auto repair shop'))} />}
            <Body style={{ fontSize: 11.5, color: C.muted }}>General guidance only. Your owner’s manual explains every light for your car. If you feel unsafe, pull over and call for help.</Body>
          </>
        )}
      </ScrollView>
      </View>
    </SafeAreaView>
  );
}

const s = themed(() => StyleSheet.create({
  top: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', paddingHorizontal: PAD, paddingTop: 10, paddingBottom: 8 },
  bub: { maxWidth: '86%', paddingHorizontal: 13, paddingVertical: 10 },
  them: { alignSelf: 'flex-start', backgroundColor: C.grey },
  me: { alignSelf: 'flex-end', backgroundColor: C.hero },
  themText: { fontFamily: F.body, fontSize: 15, lineHeight: 21, color: C.ink },
  meText: { fontFamily: F.bodyBold, fontSize: 15, lineHeight: 21, color: C.yellow },
  grid: { flexDirection: 'row', flexWrap: 'wrap', gap: 6 },
  tile: { width: '31.5%', borderWidth: 1, borderColor: C.line, borderRadius: 12, padding: 8, alignItems: 'center', gap: 6 },
  dash: { width: 48, height: 48, backgroundColor: '#151515', alignItems: 'center', justifyContent: 'center' },
  danger: { backgroundColor: C.red, padding: 12 },
  card: { borderWidth: 1, borderColor: C.line, borderRadius: 12, padding: 14 },
  level: { alignSelf: 'flex-start', paddingHorizontal: 8, paddingVertical: 3, marginTop: 4 },
  psi: { backgroundColor: C.hero, padding: 12, marginTop: 10 },
  step: { flexDirection: 'row', gap: 10, alignItems: 'flex-start', paddingTop: 10 },
  stepN: { width: 24, height: 24, backgroundColor: C.fill, alignItems: 'center', justifyContent: 'center' },
}));

// Link to the open chat, "Ask about my car" (Oct 20, 2026).
const askLink = themed(() => StyleSheet.create({
  box: { backgroundColor: C.fill, borderRadius: 14, paddingHorizontal: 14, paddingVertical: 11, marginTop: 4 },
  t: { fontFamily: F.bodyBold, fontSize: 14, color: C.onAccent },
}));
