// Fee check (picture 151 panels 2 + 4, Oct 26, 2026): type the dealer's price and fees from the sticker or their
// website; we compare the fees with most dealers in the shopper's state and add the tax that most dealer prices
// leave out. Works for everyone (no cars-for-sale feed needed). All ESTIMATES; friendly words only.
import { useState } from 'react';
import { StyleSheet, Switch, View } from 'react-native';

import { tap } from '@/components/ui';
import { aboutDollars, feeCheck } from '@/data/fee-check';
import { money } from '@/data/prices';
import { C, F, themed } from '@/theme';
import { Pressable, Text, TextInput } from '@/components/t';

const AMBER = '#B7791F';
const num = (s: string) => { const n = Number(s.replace(/[^\d]/g, '')); return s.trim() && Number.isFinite(n) ? n : null; };
const show = (n: number | null) => (n == null ? '' : n.toLocaleString('en-US'));

export function FeeCheck({ price: start, open: startOpen, allIn }: { price?: number; open?: boolean; allIn?: boolean }) {
  const [open, setOpen] = useState(!!startOpen);
  const [price, setPrice] = useState(show(start ?? null));
  const [fees, setFees] = useState('');
  const [includes, setIncludes] = useState(!!allIn);
  const p = num(price);
  const f = num(fees);
  const o = p ? feeCheck(p, f, includes) : null;
  const most = o?.state ? `most ${o.state} dealers` : 'most dealers';

  const summary = !o ? 'Type the dealer’s price and fees to see what you’d really pay.'
    : o.fees == null ? `Type the dealer’s fees to compare. ${o.state ? `Most ${o.state} dealers` : 'Most dealers'} charge about ${money(o.usual)}.`
    : o.high ? `About ${aboutDollars(o.extra)} more than ${most} charge. Tap to see.`
    : `About normal for ${o.state ?? 'most dealers'}.`;

  return (
    <View style={[s.box, o?.high && s.boxHigh]}>
      <Pressable onPress={() => { tap(); setOpen(!open); }} accessibilityRole="button" accessibilityState={{ expanded: open }} style={s.head}>
        <View style={[s.icon, { backgroundColor: (o?.high ? AMBER : C.green) + '22' }]}><Text style={[s.iconText, { color: o?.high ? AMBER : C.green }]}>$</Text></View>
        <View style={{ flex: 1 }}>
          <Text style={s.title}>{o?.fees ? `Fee check: ${money(o.fees)} in dealer fees` : 'Fee check'}</Text>
          <Text style={s.small}>{summary}</Text>
        </View>
        <Text style={[s.title, { color: C.yellow }]}>{open ? '⌃' : '›'}</Text>
      </Pressable>
      {open && (
        <View style={{ marginTop: 6 }}>
          <View style={{ flexDirection: 'row', gap: 10 }}>
            <View style={{ flex: 1 }}>
              <Text style={s.label}>Dealer’s price</Text>
              <TextInput value={price} onChangeText={setPrice} placeholder="$8,989" placeholderTextColor={C.muted} keyboardType="number-pad" style={s.input} accessibilityLabel="Dealer's price in dollars" />
            </View>
            <View style={{ flex: 1 }}>
              <Text style={s.label}>Dealer fees</Text>
              <TextInput value={fees} onChangeText={setFees} placeholder={o ? money(o.usual) : '$799'} placeholderTextColor={C.muted} keyboardType="number-pad" style={s.input} accessibilityLabel="Dealer fees in dollars, all added together" />
            </View>
          </View>
          <Text style={s.hint}>Add up every dealer fee you see: doc, service, filing, prep. Not the tax.</Text>
          <View style={s.switchRow}>
            <Text style={[s.small, { flex: 1, color: C.ink }]}>Their price already includes these fees</Text>
            <Switch value={includes} onValueChange={(v) => { tap(); setIncludes(v); }} accessibilityLabel="Their price already includes these fees" />
          </View>
          {o && (
            <View style={s.lines}>
              <Line label="Car price" value={money(o.carPrice)} />
              <Line label={o.fees == null ? 'Dealer fees (not typed yet)' : 'Dealer fees'} sub={`${o.state ? `Most ${o.state} dealers` : 'Most dealers'}: about ${money(o.usual)}`}
                value={o.fees == null ? `≈ ${money(o.usual)}` : money(o.fees)} amber={o.high} />
              <Line label={o.rate ? `${o.state ?? 'Typical'} ${o.taxName} (${o.rate}%)` : 'Car tax'} sub="Most dealer prices leave this out" value={`≈ ${money(o.tax)}`} />
              <Line label="Title and tag" value={`≈ ${money(o.title)}`} />
              <Line label="Out the door" value={`≈ ${money(o.total)}`} total />
            </View>
          )}
          {o?.high && (
            <View style={s.tip}>
              <Text style={[s.title, { color: C.onAccent, fontSize: 13.5 }]}>A friendly question</Text>
              <Text style={[s.small, { color: C.ink }]}>“Are any of these fees flexible, or can you take them off the price?” Dealers hear this every day. It’s OK to ask.</Text>
            </View>
          )}
          <Text style={s.hint}>{o?.state ? 'Estimates. The dealer’s paperwork has the final numbers. Ask for the out-the-door price in writing.' : 'Estimates with typical U.S. numbers. Add your ZIP code in the coach to use your state.'}</Text>
        </View>
      )}
    </View>
  );
}

function Line({ label, sub, value, amber, total }: { label: string; sub?: string; value: string; amber?: boolean; total?: boolean }) {
  return (
    <View style={[s.line, total && { borderBottomWidth: 0 }]}>
      <View style={{ flex: 1 }}>
        <Text style={[total ? s.title : s.lineLabel]}>{label}</Text>
        {sub ? <Text style={s.lineSub}>{sub}</Text> : null}
      </View>
      <Text style={[total ? s.total : s.lineValue, amber && { color: AMBER }]}>{value}</Text>
    </View>
  );
}

const s = themed(() => StyleSheet.create({
  box: { backgroundColor: C.card, borderWidth: 1, borderColor: C.line, borderRadius: 16, padding: 12, marginTop: 10 },
  boxHigh: { borderColor: AMBER, borderWidth: 1.5 },
  head: { flexDirection: 'row', alignItems: 'center', gap: 10 },
  icon: { width: 30, height: 30, borderRadius: 9, alignItems: 'center', justifyContent: 'center' },
  iconText: { fontFamily: F.bodyBold, fontSize: 15 },
  title: { fontFamily: F.bodyBold, fontSize: 15, color: C.ink },
  small: { fontFamily: F.body, fontSize: 12.5, lineHeight: 17, color: C.muted, marginTop: 2 },
  label: { fontFamily: F.bodyBold, fontSize: 13, color: C.ink, marginTop: 8 },
  input: { height: 46, borderRadius: 12, borderWidth: 1, borderColor: C.line, backgroundColor: C.bg, paddingHorizontal: 12, fontFamily: F.body, fontSize: 16, color: C.ink, marginTop: 4 },
  hint: { fontFamily: F.body, fontSize: 11.5, lineHeight: 16, color: C.muted, marginTop: 6 },
  switchRow: { flexDirection: 'row', alignItems: 'center', gap: 8, marginTop: 6 },
  lines: { marginTop: 6 },
  line: { flexDirection: 'row', alignItems: 'center', gap: 8, paddingVertical: 7, borderBottomWidth: 1, borderColor: C.line },
  lineLabel: { fontFamily: F.body, fontSize: 13.5, color: C.ink },
  lineSub: { fontFamily: F.body, fontSize: 11, color: C.muted },
  lineValue: { fontFamily: F.bodyBold, fontSize: 14, color: C.ink },
  total: { fontFamily: F.head, fontSize: 18, color: C.ink },
  tip: { backgroundColor: C.fill, borderRadius: 12, padding: 10, marginTop: 8 },
}));
