// Real cars for sale near you (Oct 15, 2026, step 1 of the map + list, picture 59 "like the demo").
// The app asks our Supabase function `listings`, which asks Auto.dev. Until Auto.dev says yes in
// writing, only test accounts get cars; everyone else gets "Coming soon" (picture 62).
// Drive times are estimates made on the server (straight line × 1.3, 30 to 55 mph).
import { Linking, Platform } from 'react-native';

import { FunctionsFetchError, FunctionsHttpError } from '@supabase/supabase-js';

import { BUDGETS, CARS, type Car } from '@/data/cars';
import { supabase } from '@/lib/supabase';
import { monthlyCap, paymentFor, topMatches, type Answers } from '@/state/answers';
import { onPullClear } from '@/lib/refresh';

export type Listing = {
  vin: string; kind: string; fuel: string; year: number; make: string; model: string; trim: string; color: string;
  price: number; miles: number | null; used: boolean; cpo: boolean;
  dealer: string; city: string; state: string; lat: number; lon: number;
  link: string; photo: string | null; photos: number;
  accidents: number | null; owners: number | null;
  road: number; min: number;
};
export type Origin = { lat: number; lon: number; place: string; zip: string };
export type Found =
  | { kind: 'cars'; origin: Origin; cars: Listing[] }
  | { kind: 'soon' }
  | { kind: 'zip' } // we couldn't find that ZIP
  | { kind: 'busy' } // too many searches today
  | { kind: 'offline' };

export type Ask = { zip?: string; lat?: number; lon?: number; models: Pick<Car, 'make' | 'model'>[]; maxPrice?: number; kind?: string | null };

// Every car we've shown, so the car page can open it by VIN.
const byVin = new Map<string, Listing>();
export const getListing = (vin: string) => byVin.get(vin);

/** "Tell me more › No accidents": hide cars with a reported accident. Unknown history stays (the dealer page or a report can tell). */
export const skipAccidents = (a: Answers) => a.more?.accidents === 'No accidents';
export const withoutAccidents = (found: Found): Found => (found.kind === 'cars' ? { ...found, cars: found.cars.filter((c) => !c.accidents) } : found);
export const forAnswers = (found: Found, a: Answers) => (skipAccidents(a) ? withoutAccidents(found) : found);

export async function findListings(a: Ask): Promise<Found> {
  const body = { zip: a.zip, lat: a.lat, lon: a.lon, maxPrice: a.maxPrice, kind: a.kind ?? undefined, models: a.models.map((c) => ({ make: c.make, model: c.model })) };
  let { data, error } = await supabase.functions.invoke('listings', { body });
  // Weak signal: try once more before showing "Can't load cars".
  if (error instanceof FunctionsFetchError) {
    await new Promise((r) => setTimeout(r, 1500));
    ({ data, error } = await supabase.functions.invoke('listings', { body }));
  }
  if (error) {
    if (error instanceof FunctionsFetchError) return { kind: 'offline' };
    if (error instanceof FunctionsHttpError) {
      const status = error.context?.status;
      if (status === 400) return { kind: 'zip' };
      if (status === 429) return { kind: 'busy' };
    }
    return { kind: 'offline' };
  }
  if (data?.soon) return { kind: 'soon' };
  const cars: Listing[] = Array.isArray(data?.cars) ? data.cars : [];
  for (const c of cars) byVin.set(c.vin, c);
  return { kind: 'cars', origin: data.origin, cars };
}

// One exact car by its VIN (picture 151): the car someone just scanned at a dealer. Same tester-only rule.
export type OneCar = { kind: 'car'; car: Listing } | { kind: 'none'; gone?: string } | { kind: 'soon' } | { kind: 'offline' };
const oneCache = new Map<string, OneCar>();
onPullClear(() => oneCache.clear());
export async function findByVin(vin: string, where: { zip?: string; lat?: number; lon?: number }): Promise<OneCar> {
  const key = `${vin}|${where.zip ?? ''}|${where.lat ?? ''},${where.lon ?? ''}`;
  if (oneCache.has(key)) return oneCache.get(key)!;
  const { data, error } = await supabase.functions.invoke('listings', { body: { vin, ...where } });
  if (error) return { kind: 'offline' };
  if (data?.soon) return { kind: 'soon' };
  const out: OneCar = data?.car ? { kind: 'car', car: data.car as Listing } : { kind: 'none', gone: data?.gone };
  if (out.kind === 'car') byVin.set(out.car.vin, out.car);
  oneCache.set(key, out);
  return out;
}

// What to look for: the coach's top 3, or popular SUVs and sedans before the coach.
export function shopModels(a: Answers, ids?: string[]): Car[] {
  if (ids?.length) return CARS.filter((c) => ids.includes(c.id)).slice(0, 4);
  if (a.goal || a.budget) return topMatches(a, 3).map((m) => m.car);
  return ['rav4', 'crv', 'camry', 'civic'].map((id) => CARS.find((c) => c.id === id)).filter((c): c is Car => !!c);
}
const MAX = [15000, 25000, 40000, 60000, 100000];
// Highest price to search: the coach budget, or (for a car loan) the price whose payment
// estimate matches the monthly payment they picked.
export function budgetMax(a: Answers): number | undefined {
  const cap = monthlyCap(a);
  if (cap) {
    let lo = 3000, hi = 200000;
    while (hi - lo > 250) { const mid = (lo + hi) / 2; if (paymentFor(a, mid) <= cap) lo = mid; else hi = mid; }
    return Math.round(lo / 500) * 500;
  }
  return MAX[BUDGETS.indexOf(a.budget ?? '')] as number | undefined;
}

export const listingName = (l: Listing) => `${l.year} ${l.make} ${l.model}${l.trim ? ` ${l.trim}` : ''}`;
export const shortK = (n: number) => `$${(n / 1000).toFixed(1).replace(/\.0$/, '')}K`;

// Cars at the same dealer share one pin.
export type Group = { key: string; lat: number; lon: number; cars: Listing[] };
export function groups(cars: Listing[]): Group[] {
  const m = new Map<string, Group>();
  for (const c of cars) {
    const key = `${c.lat.toFixed(2)},${c.lon.toFixed(2)}`;
    if (!m.has(key)) m.set(key, { key, lat: c.lat, lon: c.lon, cars: [] });
    m.get(key)!.cars.push(c);
  }
  return [...m.values()];
}
export const pinLabel = (g: Group) => {
  const lo = Math.min(...g.cars.map((c) => c.price));
  return g.cars.length > 1 ? `${g.cars.length} cars · from ${shortK(lo)}` : shortK(lo);
};

// Road miles you can drive in this many minutes (the same speed rule the server uses), then
// straight-line miles for the circle on the map.
export function straightMilesFor(min: number) {
  let road = 1;
  while (road < 200 && (road / Math.min(55, 30 + 0.8 * road)) * 60 < min) road++;
  return road / 1.3;
}

// The dealer's own page in the phone's map app (picture 148 A): stars, reviews, phone, address and hours are there.
// Android's geo: link opens whatever map app the person uses; iPhone opens Apple Maps. Free, and always up to date.
export function openDealerInMaps(l: Pick<Listing, 'dealer' | 'city' | 'state' | 'lat' | 'lon'>) {
  const q = encodeURIComponent([l.dealer, l.city, l.state].filter(Boolean).join(', '));
  const web = `https://www.google.com/maps/search/?api=1&query=${q}`;
  const url = Platform.OS === 'ios' ? `http://maps.apple.com/?q=${q}&sll=${l.lat},${l.lon}`
    : Platform.OS === 'android' ? `geo:${l.lat},${l.lon}?q=${q}` : web;
  Linking.openURL(url).catch(() => Linking.openURL(web).catch(() => {}));
}

// How many cars like this one (same brand and model) this dealer has, from the cars we've loaded.
export function dealerCount(l: Listing) {
  let n = 0;
  for (const c of byVin.values()) if (c.dealer === l.dealer && c.city === l.city && c.make === l.make && c.model === l.model) n++;
  return Math.max(1, n);
}

export function openDirections(l: { lat: number; lon: number; dealer?: string }) {
  const url = Platform.OS === 'ios'
    ? `http://maps.apple.com/?daddr=${l.lat},${l.lon}${l.dealer ? `&q=${encodeURIComponent(l.dealer)}` : ''}`
    : `https://www.google.com/maps/dir/?api=1&destination=${l.lat},${l.lon}`;
  Linking.openURL(url).catch(() => {});
}

/** Every dealer photo of a listing (Loudjier, Nov 12, 2026: "I need all the pictures. User can swipe").
 *  Listing photos are numbered (…VIN-1.jpg, -2.jpg…), so the gallery needs no extra data call. Max 40. */
export function listingPhotos(l: Pick<Listing, 'photo' | 'photos'>): string[] {
  if (!l.photo) return [];
  const m = l.photo.match(/^(.*-)1(\.(?:jpe?g|png|webp))(\?.*)?$/i);
  if (!m || l.photos <= 1) return [l.photo];
  return Array.from({ length: Math.min(l.photos, 40) }, (_, i) => `${m[1]}${i + 1}${m[2]}${m[3] ?? ''}`);
}
