// App start: the normal app (expo-router), plus the home screen widgets' task (Android app files that have it).
import 'expo-router/entry';
import { hasWidgets } from './src/lib/widget-native';

if (hasWidgets()) {
  const { registerWidgetTaskHandler } = require('react-native-android-widget');
  const { widgetTaskHandler } = require('./src/widgets/task-handler');
  registerWidgetTaskHandler(widgetTaskHandler);
}
