// Keeps a bottom bar (a writing box) above the phone keyboard. Android draws apps edge to edge now
// (Expo SDK 57): the window no longer shrinks for the keyboard, and on Loudjier's phone the plain
// Keyboard events didn't fire (Oct 20, 2026), so we read the keyboard from Reanimated, which follows
// the phone's own keyboard inset frame by frame. The bar is lifted by the part of the keyboard that
// reaches above the bar's normal spot (the tab bar and phone edge below it are already "free").
import { useEffect, useRef } from 'react';
import { Dimensions, type View } from 'react-native';
import { useAnimatedKeyboard, useAnimatedReaction, useAnimatedStyle, useSharedValue } from 'react-native-reanimated';
import { scheduleOnRN } from 'react-native-worklets';

export function useKeyboardLift(onShow?: () => void) {
  const ref = useRef<View>(null);
  const keyboard = useAnimatedKeyboard();
  const gap = useSharedValue(0); // space from the bar's bottom edge to the bottom of the screen
  const after = useRef(onShow);
  useEffect(() => { after.current = onShow; });

  // Measure where the bar sits while the keyboard is closed.
  const measure = () => {
    ref.current?.measureInWindow((_x, y, _w, h) => {
      if (keyboard.height.value < 1 && h > 0) gap.value = Math.max(0, Dimensions.get('window').height - (y + h));
    });
  };
  const opened = () => after.current?.();
  useAnimatedReaction(() => keyboard.height.value > gap.value, (open, was) => {
    if (open && !was) scheduleOnRN(opened);
  });
  const style = useAnimatedStyle(() => ({ marginBottom: Math.max(0, keyboard.height.value - gap.value) }));
  return [ref, style, measure] as const;
}
