// The old "Find near me" page is now part of the one car page (picture 71 A). Old links land here.
import { Redirect, useLocalSearchParams } from 'expo-router';

export default function NearMe() {
  const { id, year } = useLocalSearchParams<{ id: string; year?: string }>();
  return <Redirect href={{ pathname: '/car/[id]', params: { id, ...(year ? { year } : {}) } }} />;
}
