import { useEffect, useState } from 'react';
import { Image, ScrollView, StyleSheet, useWindowDimensions, View } from 'react-native';
import { SafeAreaView, useSafeAreaInsets } from 'react-native-safe-area-context';

import { CarCard } from '@/components/car-card';
import { AlertIcon, ArrowIcon, BulbIcon, CarIcon, ChatIcon, InfoIcon, SoundIcon, SunIcon, WrenchIcon } from '@/components/icons';
import { IconBox, type Tint } from '@/components/account-ui';
import { UndoBar } from '@/components/undo-bar';
import { CarSheet } from '@/components/car-sheet';
import { MilesCard, PlanCard } from '@/components/plan-cards';
import { estMiles } from '@/data/car-plan';
import { Ring } from '@/components/ring';
import { Sky, useSky } from '@/components/sky';
import { Image as ExpoImage } from 'expo-image';

import { CarCutout, hasCutout, paintsFor, PhotoCredit, ScanCutout } from '@/components/car-photo';
import { Body, Btn, H, Label, tap } from '@/components/ui';
import { CARS, carForMine } from '@/data/cars';
import { scanLook, type ScanLook } from '@/data/scan-looks';
import { recallsForMyCar } from '@/data/gov';
import { byMiles, checksFor, type Check, factsFor, MONTHS } from '@/data/car-tips';
import { carName, MAX_CARS } from '@/data/my-cars';
import { useAnswers } from '@/state/answers';
import { nextDue } from '@/data/upkeep';
