// Photos of cars people DRIVE that aren't in our shopping list (picture 205): one photo per body style, used for every year
// that looks the same outside. Real photos from Wikimedia Commons with free licenses, background removed, plates hidden.
// Add Atlanta's most common older cars here over time (Loudjier, Nov 6, 2026).
type Look = { make: string; model: string; from: number; to: number; year: number; src: number; credit: string };

const LOOKS: Look[] = [
  { make: 'nissan', model: 'pathfinder', from: 2013, to: 2016, year: 2013, src: require('../../assets/cutouts/look-pathfinder-2013.webp'),
    credit: 'Photo: Rutger van der Maar, CC BY 2.0 (background removed)' },
];

const squash = (s: string) => s.toLowerCase().replace(/[^a-z0-9]/g, '');

/** A same-look photo for their car, or undefined. Without a year, any look of that model counts. */
export function lookFor(make: string, model: string, year?: number): Look | undefined {
  const mk = squash(make), md = squash(model);
  return LOOKS.find((l) => mk === squash(l.make) && md.startsWith(squash(l.model)) && (!year || (year >= l.from && year <= l.to)));
}
