// Your own photos of a car (picture 145, Oct 25, 2026; more than one since picture 268, Nov 18, 2026).
// Kept only on this phone, never sent to our server. Keyed by VIN for scanned cars and by year + make + model for a
// car in My Garage. The first photo of a car uses its key; extra photos use key#2 … key#6.
// Each photo is saved under its own storage item (Android refuses one item over ~2 MB, and photos add up fast);
// a small index remembers which photos exist. Older app versions kept every photo in one item (v1): moved over once.
import AsyncStorage from '@react-native-async-storage/async-storage';
import { useSyncExternalStore } from 'react';

const V1 = 'carvessa:carphotos:v1';
const IDX = 'carvessa:carphotos:v2';
const ONE = 'carvessa:carphoto:'; // + photo key
const MAX_ONE = 1_500_000; // a phone photo at our quality is far smaller; bigger ones are refused, not saved
const MAX_ALL = 40; // keep the 40 newest photos on this phone
export const MAX_PER_CAR = 6;

let index: Record<string, number> = {}; // photo key → when it was saved
let photos: Record<string, string> = {}; // photo key → the photo (data: address or file)
let loaded = false;
let version = 0;
const subs = new Set<() => void>();
const tell = () => { version++; subs.forEach((f) => f()); };

export const vinKey = (vin: string) => `vin:${vin.trim().toUpperCase()}`;
export const carKey = (c: { year: number; make: string; model: string }) => `car:${c.year}|${c.make.trim().toLowerCase()}|${c.model.trim().toLowerCase()}`;
/** The keys a car's photos live under, in order: the first photo, then the extras. */
export const slotKeys = (key: string) => [key, ...Array.from({ length: MAX_PER_CAR - 1 }, (_, i) => `${key}#${i + 2}`)];

async function readAll() {
  const raw = await AsyncStorage.getItem(IDX);
  if (raw) {
    const idx: Record<string, number> = JSON.parse(raw);
    const got = await AsyncStorage.multiGet(Object.keys(idx).map((k) => ONE + k));
    const ph: Record<string, string> = {};
    got.forEach(([k, v]) => { if (v) ph[k.slice(ONE.length)] = v; });
    index = { ...Object.fromEntries(Object.keys(ph).map((k) => [k, idx[k]])), ...index };
    photos = { ...ph, ...photos };
    return;
  }
  // Older app versions: every photo in one item.
  const old = await AsyncStorage.getItem(V1);
  if (!old) return;
  const o: Record<string, { p: string; at: number }> = JSON.parse(old);
  for (const [k, v] of Object.entries(o)) {
    if (!(k in photos)) { photos[k] = v.p; index[k] = v.at; }
  }
  await save(Object.keys(o));
  AsyncStorage.removeItem(V1).catch(() => {});
}

function load() {
  if (loaded) return;
  loaded = true;
  readAll().then(tell).catch(() => {});
}

async function save(changed: string[]) {
  const put = changed.filter((k) => photos[k]).map((k) => [ONE + k, photos[k]] as [string, string]);
  const gone = changed.filter((k) => !photos[k]).map((k) => ONE + k);
  if (put.length) await AsyncStorage.multiSet(put);
  if (gone.length) await AsyncStorage.multiRemove(gone);
  await AsyncStorage.setItem(IDX, JSON.stringify(index));
}

// Keep the newest MAX_ALL photos; returns the keys that were dropped.
function trim(): string[] {
  const keep = Object.entries(index).sort((a, b) => b[1] - a[1]).slice(0, MAX_ALL).map(([k]) => k);
  const drop = Object.keys(index).filter((k) => !keep.includes(k));
  for (const k of drop) { delete index[k]; delete photos[k]; }
  return drop;
}

function commit(changed: string[]) {
  const dropped = trim();
  tell();
  save([...changed, ...dropped]).catch(() => {});
}

/** Saves (or removes, with null) the photo for these keys. Returns false when it's too big to keep. */
export function setCarPhoto(keys: string[], p: string | null): boolean {
  if (p && p.length > MAX_ONE) return false;
  const at = Date.now();
  for (const k of keys) {
    if (p) { photos[k] = p; index[k] = at; } else { delete photos[k]; delete index[k]; }
  }
  commit(keys);
  return true;
}

/** Adds one more photo of this car (first free slot). 'big' = too big to keep, 'full' = already MAX_PER_CAR photos. */
export function addCarPhoto(key: string, p: string): 'ok' | 'big' | 'full' {
  if (p.length > MAX_ONE) return 'big';
  const free = slotKeys(key).find((k) => !photos[k]);
  if (!free) return 'full';
  photos[free] = p; index[free] = Date.now();
  commit([free]);
  return 'ok';
}

/** Removes photo number n (0 = the first) of this car; the photos after it move up so there are no gaps. */
export function removeCarPhoto(key: string, n: number) {
  const slots = slotKeys(key);
  const list = slots.map((k) => photos[k]).filter((x): x is string => !!x);
  if (n < 0 || n >= list.length) return;
  list.splice(n, 1);
  const at = Date.now();
  slots.forEach((k, i) => {
    if (list[i]) { photos[k] = list[i]; index[k] = index[k] ?? at; } else { delete photos[k]; delete index[k]; }
  });
  commit(slots);
}

const sub = (f: () => void) => { subs.add(f); return () => { subs.delete(f); }; };

export function useCarPhoto(key: string | null): string | null {
  load();
  const get = () => (key ? photos[key] ?? null : null);
  return useSyncExternalStore(sub, get, get);
}

// Same list object until something changes, so React doesn't redraw for nothing.
const lists = new Map<string, { v: number; list: string[] }>();
/** Every photo of this car, in order (the first photo, then the extras). */
export function useCarPhotos(key: string | null): string[] {
  load();
  const get = () => {
    if (!key) return EMPTY;
    const c = lists.get(key);
    if (c && c.v === version) return c.list;
    const list = slotKeys(key).map((k) => photos[k]).filter((x): x is string => !!x);
    const same = c && c.list.length === list.length && c.list.every((x, i) => x === list[i]);
    const out = same ? c!.list : list;
    lists.set(key, { v: version, list: out });
    return out;
  };
  return useSyncExternalStore(sub, get, get);
}
const EMPTY: string[] = [];

/** The year + make + model match between a scanned car and a car in My Garage (model can be longer on either side). */
export function sameCar(a: { year: number; make: string; model: string }, b: { year: number; make: string; model: string }): boolean {
  const n = (s: string) => s.trim().toLowerCase().replace(/^chevrolet$/, 'chevy');
  const ma = n(a.model), mb = n(b.model);
  return a.year === b.year && n(a.make) === n(b.make) && (ma === mb || ma.startsWith(mb) || mb.startsWith(ma));
}
