import { carForMine } from '@/data/cars';
import { factsFor, checksFor } from '@/data/car-tips';
import { dailyOf, estMiles, nextDue as nextPaymentDate, oilLeft, tradeRange } from '@/data/car-plan';
import type { Car } from '@/data/cars';
import { fiveYearCost } from '@/data/costs';
import { savedFacts } from '@/data/gov';
import { daysUntil, parseUsDate } from './more';
import { carName } from '@/data/my-cars';
import { tr } from '@/i18n';
import type { MyCar } from '@/state/saved';

export const SNAP_KEY = 'carvessa:widget:v1';
export const TIP_KEY = 'carvessa:widget-tip:v1';
export const GARAGE_KEY = 'carvessa:widget-garage:v1';

export type WidgetCar = {
  name: string; // "2018 Chevy Trax"
  short: string; // nickname or model: "Trax"
  make: string;
  id?: string; // our car id (picture), when we have the car
  year: number;
  paint?: string;
  recalls: number | null; // open recalls on this model year (NHTSA), null = not known yet
  oilIn: number | null; // miles until the next oil change (estimate)
  payDate?: string; // "Nov 15"
  payAmount?: number;
  worth?: [number, number]; // trade-in estimate range
  // Second set (pictures 190–191):
  miles?: number; // estimated miles today
  regDue?: string; // "Jan 12"
  regDays?: number; // days until the tag renewal (below 0 = late)
  payDays?: number; // days until the next payment
  paid?: [number, number]; // payments made, of all payments
  vin?: string;
  insurer?: string;
  roadside?: string; // roadside help phone number they added
  value?: number[]; // trade-in middle estimate, 12 months ago → now
  cost?: { pay: number; gas: number; ins: number; upkeep: number }; // this month, estimates
};
/** The car they want next (W): a saved car, else the coach's #1. */
export type NextCar = { name: string; id: string; year: number; price: number; isNew: boolean; monthly?: number; over?: number };
export type WidgetWeather = { tempF: number; word: string; sky: string; isDay: boolean; at: number; tip: string };
export type WidgetSnap = {
  at: number;
  lang: 'en' | 'es';
  member: boolean;
  cars: WidgetCar[];
  active: number;
  tips: string[]; // facts and checks for the active car (from our checked car guide)
  spot?: { lat: number; lon: number; place: string };
  weather?: WidgetWeather;
  next?: NextCar;
  driver?: boolean; // their coach goal is driving for apps
};

const MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

/** One car as the widgets show it. `recalls` comes from the app's NHTSA check (null while unknown). */
export function widgetCar(c: MyCar, recalls: number | null, now: number): WidgetCar {
  const ours = carForMine(c.make, c.model);
  const miles = estMiles(c, now) ?? c.miles;
  const pay = c.loan && c.loan.left > 0 ? nextPaymentDate(c.loan, new Date(now)) : null;
  const worth = ours ? tradeRange(ours, c.year, miles ?? undefined) : null;
  const reg = parseUsDate(c.regDue);
  const mid = (r: [number, number] | null) => (r ? Math.round((r[0] + r[1]) / 2) : 0);
  const perMonth = Math.round(dailyOf(c) * 30.4);
  const value = ours && miles ? Array.from({ length: 12 }, (_, k) => mid(tradeRange(ours, c.year, Math.max(0, miles - (11 - k) * perMonth)))).filter(Boolean) : [];
  const loanLeft = c.loan && c.loan.left > 0;
  const total = c.loan?.total ?? (loanLeft ? Math.max(c.loan!.left, 72) : undefined);
  return {
    name: carName(c),
    short: c.nick || c.model,
    make: c.make,
    id: ours?.id,
    year: c.year,
    paint: c.color,
    recalls,
    oilIn: oilLeft(c, now),
    payDate: pay ? `${MON[pay.getMonth()]} ${pay.getDate()}` : undefined,
    payAmount: pay ? Math.round(c.loan!.payment) : undefined,
    worth: worth ?? undefined,
    miles: miles ?? undefined,
    regDue: reg ? `${MON[reg.getMonth()]} ${reg.getDate()}` : undefined,
    regDays: reg ? daysUntil(reg, now) : undefined,
    payDays: pay ? daysUntil(pay, now) : undefined,
    paid: loanLeft && total ? [Math.max(0, total - c.loan!.left), total] : undefined,
    vin: c.vin,
    insurer: c.insurer,
    roadside: c.roadside,
    value: value.length >= 2 ? value : undefined,
    cost: costOf(c, ours, worth, perMonth, now),
  };
}

/** What the car costs this month (estimates): their payment, gas from EPA MPG and their miles, insurance and
 * upkeep from our 5-year cost guide (the same math as the car page). */
function costOf(c: MyCar, ours: Car | null | undefined, worth: [number, number] | null, perMonth: number, now: number) {
  const value = worth ? (worth[0] + worth[1]) / 2 : 0;
  if (!value) return undefined;
  const mpg = ours ? savedFacts(ours.id, c.year)?.mpg?.combined : undefined;
  const age = Math.max(0, new Date(now).getFullYear() - c.year);
  const r = fiveYearCost({ price: value, isNew: false, ageYears: age, mpg, electric: ours?.green === 'ev', milesPerYear: perMonth * 12, gasPrice: 3.3, kwhPrice: 0.17, down: value, apr: 0, months: 60, taxPct: 0 });
  const part = (label: string) => Math.round((r.parts.find((x) => x.label === label)?.amount ?? 0) / 60);
  return { pay: c.loan && c.loan.left > 0 ? Math.round(c.loan.payment) : 0, gas: part(ours?.green === 'ev' ? 'Charging' : 'Gas'), ins: part('Insurance'), upkeep: part('Upkeep and repairs') };
}

/** Today's tip for the weather card: cold = tire pressure, heat = battery, rain = wipers. Our words, no numbers made up. */
export function weatherTip(tempF: number, sky: string, short: string): string {
  return tr(weatherTipEn(tempF, sky, short));
}
function weatherTipEn(tempF: number, sky: string, short: string): string {
  if (Number.isFinite(tempF) && tempF <= 45) return `Cold air can turn on the tire light. Check your ${short}'s tire pressure this week.`;
  if (Number.isFinite(tempF) && tempF >= 90) return `Heat is hard on batteries. If your ${short} starts slowly, get the battery tested.`;
  if (sky === 'rain' || sky === 'storm') return 'Wet roads: leave more room to stop. Streaky wipers? Time for new blades.';
  if (sky === 'snow') return 'Snow or ice: go slow, and clear every window before you drive.';
  return `Good day to check your ${short}'s tire pressure and washer fluid.`;
}

/** Facts and checks for the tip widget: the car's own facts first, then this month's checks. */
export function tipsFor(c: MyCar | null, month: number): string[] {
  // Each piece is translated on its own (our Spanish list has the guide's lines one by one), in the app's language.
  const facts = (c ? factsFor(c) : []).map((f) => {
    const i = f.indexOf(': ');
    return i > 0 && i < 60 ? `${tr(f.slice(0, i))}: ${tr(f.slice(i + 2))}` : tr(f);
  });
  const checks = checksFor(month).map((k) => `${tr(k.title)}. ${tr(k.text)}`);
  return [...facts, ...checks].filter(Boolean).slice(0, 12);
}

export async function readSnap(): Promise<WidgetSnap | null> {
  try {
    const raw = await AsyncStorage.getItem(SNAP_KEY);
    const s = raw ? (JSON.parse(raw) as WidgetSnap) : null;
    return s && Array.isArray(s.cars) ? s : null;
  } catch {
    return null;
  }
}
export const writeSnap = (s: WidgetSnap) => AsyncStorage.setItem(SNAP_KEY, JSON.stringify(s)).catch(() => {});

export async function readNum(key: string): Promise<number> {
  try { return Number(await AsyncStorage.getItem(key)) || 0; } catch { return 0; }
}
export const writeNum = (key: string, n: number) => AsyncStorage.setItem(key, String(n)).catch(() => {});

/** Money as "$9K" / "$310". */
export const money = (n: number) => (n >= 1000 ? `$${Math.round(n / 100) / 10}K`.replace('.0K', 'K') : `$${Math.round(n)}`);
export const miles = (n: number) => n.toLocaleString('en-US');
