/** Typical U.S. numbers when we don't know the state. */
export const US: StateCost = S('typical U.S.', 7, 476);
export const TITLE_REG = 100;

// First 3 digits of a ZIP code → state.
const RANGES: [number, number, string][] = [
  [10, 27, 'MA'], [28, 29, 'RI'], [30, 38, 'NH'], [39, 49, 'ME'], [50, 54, 'VT'], [55, 55, 'MA'], [56, 59, 'VT'], [60, 69, 'CT'],
  [70, 89, 'NJ'], [100, 149, 'NY'], [150, 196, 'PA'], [197, 199, 'DE'], [200, 200, 'DC'], [201, 201, 'VA'], [202, 205, 'DC'],
  [206, 219, 'MD'], [220, 246, 'VA'], [247, 268, 'WV'], [270, 289, 'NC'], [290, 299, 'SC'], [300, 319, 'GA'], [320, 349, 'FL'],
  [350, 369, 'AL'], [370, 385, 'TN'], [386, 397, 'MS'], [398, 399, 'GA'], [400, 427, 'KY'], [430, 459, 'OH'], [460, 479, 'IN'],
  [480, 499, 'MI'], [500, 528, 'IA'], [530, 549, 'WI'], [550, 567, 'MN'], [569, 569, 'DC'], [570, 577, 'SD'], [580, 588, 'ND'],
  [590, 599, 'MT'], [600, 629, 'IL'], [630, 658, 'MO'], [660, 679, 'KS'], [680, 693, 'NE'], [700, 714, 'LA'], [716, 729, 'AR'],
  [730, 732, 'OK'], [733, 733, 'TX'], [734, 749, 'OK'], [750, 799, 'TX'], [800, 816, 'CO'], [820, 831, 'WY'], [832, 838, 'ID'],
  [840, 847, 'UT'], [850, 865, 'AZ'], [870, 884, 'NM'], [885, 885, 'TX'], [889, 898, 'NV'], [900, 961, 'CA'], [967, 968, 'HI'],
  [970, 979, 'OR'], [980, 994, 'WA'], [995, 999, 'AK'],
];
export function stateFromZip(zip?: string | null): string | null {
  if (!zip || !/^\d{5}$/.test(zip)) return null;
  const p = Number(zip.slice(0, 3));
  return RANGES.find(([a, b]) => p >= a && p <= b)?.[2] ?? null;
}

// The shopper's state (from their ZIP), set by the answers provider. Used when no state is passed.
let home: string | null = null;
export const setHomeState = (st: string | null) => { home = st; };
export const homeState = () => home;
export const costsFor = (st: string | null = home): StateCost => (st && STATES[st]) || US;

/** Tax in dollars for this price in this state (South Carolina's fee stops at $500). */
export function carTax(price: number, st: string | null = home) {
  const c = costsFor(st);
  const t = Math.round((price * c.tax) / 100);
  return c.cap ? Math.min(t, c.cap) : t;
}
/** Dealer doc fee + title and registration, about. */
export const carFees = (st: string | null = home) => costsFor(st).doc + TITLE_REG;
export const outTheDoorIn = (price: number, st: string | null = home) => Math.round(price + carTax(price, st) + carFees(st));
