// A gold drawing of a car's body type (picture 145): shown on the scanner's turntable when we don't have a
// picture of that model yet. Never another car's photo, so it can't look like the wrong car.
import Svg, { Circle, Defs, LinearGradient, Path, Stop } from 'react-native-svg';

import type { Body } from '@/data/check';

// Body outline, window, and the two wheel centers, in a 220 x 90 box.
const SHAPES: Record<'sedan' | 'suv' | 'truck' | 'van' | 'hatch', { body: string; win: string; wheels: [number, number] }> = {
  sedan: { body: 'M14 66h180a10 10 0 0 0 10-10v-8l-26-8-22-24H78L52 40H22l-10 6v12a8 8 0 0 0 2 8z', win: 'M82 22h42l18 18H62z', wheels: [58, 158] },
  suv: { body: 'M12 66h186a8 8 0 0 0 8-8V40l-16-6-20-20H62L42 34H20l-8 8v18a6 6 0 0 0 0 6z', win: 'M66 20h96l16 16H52z', wheels: [56, 162] },
  truck: { body: 'M10 66h196a6 6 0 0 0 6-6V42h-84V34l-14-20H76L58 36H22l-10 8v16a6 6 0 0 0-2 6z', win: 'M80 20h30l12 16H64z', wheels: [52, 168] },
  van: { body: 'M12 66h190a8 8 0 0 0 8-8V28l-18-16H52L24 34l-12 8v18a6 6 0 0 0 0 6z', win: 'M58 18h124l12 14H40z', wheels: [56, 166] },
  hatch: { body: 'M30 66h152a8 8 0 0 0 8-8v-8l-16-8-24-26H86L62 40H40l-10 6v14a6 6 0 0 0 0 6z', win: 'M90 20h40l20 20H70z', wheels: [66, 152] },
};
const KIND: Record<Body, keyof typeof SHAPES> = { Sedan: 'sedan', Coupe: 'sedan', Convertible: 'sedan', Wagon: 'suv', SUV: 'suv', Truck: 'truck', Minivan: 'van', Van: 'van', Hatchback: 'hatch' };

export function BodyShape({ body, width }: { body: Body; width: number }) {
  const s = SHAPES[KIND[body]];
  return (
    <Svg width={width} height={width * (90 / 220)} viewBox="0 0 220 90" accessibilityLabel={body}>
      <Defs>
        <LinearGradient id="gold" x1="0" y1="0" x2="0" y2="1"><Stop offset="0" stopColor="#F3D27A" /><Stop offset="1" stopColor="#B98A2E" /></LinearGradient>
      </Defs>
      <Path d={s.body} fill="url(#gold)" />
      <Path d={s.win} fill="#0F1A2A" opacity={0.55} />
      {s.wheels.map((x) => <Circle key={x} cx={x} cy={66} r={14} fill="#0F1A2A" stroke="#F3D27A" strokeWidth={3} />)}
    </Svg>
  );
}
