// AI answers in the help chats (pictures 116 A + 117 A). The app asks the server function `car-help-ai` only
// after our safety words and matching found nothing, or when someone adds a photo. Any problem (AI not turned
// on yet, daily limit, no internet) returns null and the chat keeps its own no-AI answer.
import { lang } from '@/i18n';
import { supabase } from '@/lib/supabase';

export type AiAnswer = { answer: string; topic: { kind: 'light' | 'weird'; id: string } | null; unsure: boolean; urgent: boolean };

// Off for the rest of the session once the server says AI isn't turned on, so we don't keep asking.
let off = false;

export async function askAI(req: { text?: string; image?: string; mime?: string; chat?: string; car?: string; said?: string[] }): Promise<AiAnswer | null> {
  if (off) return null;
  try {
    const { data, error } = await supabase.functions.invoke('car-help-ai', { body: { ...req, lang } });
    if (error) {
      const status = (error as { context?: { status?: number } }).context?.status;
      if (status === 503 || status === 404) off = true;
      return null;
    }
    if (!data?.answer) return null;
    const [kind, id] = String(data.topic ?? '').split(':');
    return {
      answer: String(data.answer),
      topic: (kind === 'light' || kind === 'weird') && id ? { kind, id } : null,
      unsure: !!data.unsure,
      urgent: !!data.urgent,
    };
  } catch {
    return null;
  }
}
