import * as Haptics from 'expo-haptics';
import { router } from 'expo-router';
import { Platform, StyleSheet, TextProps, View, ViewStyle } from 'react-native';

import { Wordmark } from '@/components/brand';
import { C, calm, F, pickedBg, pickedInk, themed } from '@/theme';
import { Pressable, Text } from '@/components/t';

export function tap() {
  if (Platform.OS !== 'web') Haptics.selectionAsync().catch(() => {});
}

export function H({ style, size = 44, ...p }: TextProps & { size?: number }) {
  return <Text {...p} style={[{ fontFamily: F.head, fontSize: size, lineHeight: size * 0.95, textTransform: 'uppercase', color: C.ink }, style]} />;
}
export function Label({ style, ...p }: TextProps) {
  return <Text {...p} style={[{ fontFamily: F.head, fontSize: 12, letterSpacing: 1.6, textTransform: 'uppercase', color: C.ink }, style]} />;
}
export function Body({ style, bold, ...p }: TextProps & { bold?: boolean }) {
  return <Text {...p} style={[{ fontFamily: bold ? F.bodyBold : F.body, fontSize: 15, lineHeight: 21, color: C.ink }, style]} />;
}

// The Carvessa logo (D): "CAR" + gold headlight V + "essa". No box behind it (picture 67 B,
// Oct 15, 2026). On a picture (the Home city scene) pass `onPhoto`: white CAR, bright gold, soft glow.
// Tapping it goes Home (pass home={false} where that makes no sense, like the opening screen).
// dark: always the night colors (for screens that stay dark, like Login and the paint showroom).
// sky: on the Sunset Calm sky (design C): 'dark' sky (evening, night) = white CAR + warm gold, 'light' sky
// (morning, day) = dark green CAR + deep gold. No shadow needed on the plain sky.
export function Logo({ size = 17, home = true, dark = false, onPhoto = false, sky }: { size?: number; home?: boolean; dark?: boolean; onPhoto?: boolean; sky?: 'light' | 'dark' }) {
  const night = dark || onPhoto;
  const ink = sky ? (sky === 'dark' ? '#FFFFFF' : '#1D2B24') : night ? '#FFFFFF' : C.ink;
  const gold = sky ? (sky === 'dark' ? '#E3C27A' : '#86652B') : night ? '#CDB38B' : C.logoGold;
  const word = (
    <View style={{ paddingVertical: 8 }}>
      <Wordmark size={size} ink={ink} gold={gold} glow={onPhoto && !sky} />
    </View>
  );
  if (!home) return <View accessible accessibilityRole="header" accessibilityLabel="Carvessa">{word}</View>;
  return (
    <Pressable accessibilityRole="link" accessibilityLabel="Carvessa, go home" hitSlop={8}
      onPress={() => { tap(); router.navigate('/home'); }} style={({ pressed }) => ({ opacity: pressed ? 0.8 : 1, alignSelf: 'flex-start' })}>
      {word}
    </Pressable>
  );
}

type BtnKind = 'dark' | 'yellow' | 'outline' | 'outlineDark';
export function Btn({ label, onPress, kind = 'dark', icon, iconRight, style, small }: { label: string; onPress?: () => void; kind?: BtnKind; icon?: React.ReactNode; iconRight?: React.ReactNode; style?: ViewStyle; small?: boolean }) {
  const bg = kind === 'dark' ? C.hero : kind === 'yellow' ? C.fill : 'transparent';
  // outlineDark sits on a dark photo (Login), so it stays white in both looks.
  const fg = kind === 'dark' ? C.yellow : kind === 'yellow' ? C.onAccent : kind === 'outlineDark' ? '#FFFFFF' : C.ink;
  const border = kind === 'outline' ? C.line : kind === 'outlineDark' ? 'rgba(255,255,255,0.7)' : kind === 'dark' ? C.line : bg;
  return (
    <Pressable
      accessibilityRole="button"
      accessibilityLabel={label}
      onPress={() => { tap(); onPress?.(); }}
      style={({ pressed }) => [s.btn, { backgroundColor: bg, borderColor: border, height: small ? 48 : 56, opacity: pressed ? 0.8 : 1 }, calm && { borderRadius: 999 }, style]}>
      {icon}
      <Text style={{ fontFamily: F.head, fontSize: small ? 16 : 19, letterSpacing: 1, textTransform: 'uppercase', color: fg }}>{label}</Text>
      {iconRight}
    </Pressable>
  );
}

export function Chip({ label, on, onPress }: { label: string; on?: boolean; onPress?: () => void }) {
  return (
    <Pressable
      accessibilityRole="button"
      accessibilityState={{ selected: !!on }}
      onPress={() => { tap(); onPress?.(); }}
      style={({ pressed }) => [s.chip, calm && s.chipCalm, on && { backgroundColor: pickedBg(), borderColor: pickedBg() }, pressed && { opacity: 0.7 }]}>
      <Text style={{ fontFamily: F.bodyBold, fontSize: 14, color: on ? pickedInk() : C.ink }}>{label}</Text>
    </Pressable>
  );
}

export function Tag({ label, dark }: { label: string; dark?: boolean }) {
  return (
    <View style={{ alignSelf: 'flex-start', backgroundColor: dark ? C.hero : C.fill, paddingHorizontal: calm ? 9 : 7, paddingVertical: 3, borderRadius: calm ? 999 : 0 }}>
      <Label style={{ fontSize: 10.5, color: dark ? C.yellow : C.onAccent }}>{label}</Label>
    </View>
  );
}

export function SquareBtn({ children, onPress, label, dark }: { children: React.ReactNode; onPress?: () => void; label: string; dark?: boolean }) {
  return (
    <Pressable accessibilityRole="button" accessibilityLabel={label} onPress={() => { tap(); onPress?.(); }} hitSlop={6}
      style={({ pressed }) => [s.sq, { borderColor: dark ? C.ink : C.line, opacity: pressed ? 0.6 : 1 }]}>
      {children}
    </Pressable>
  );
}

export function FitBar({ pct }: { pct: number }) {
  return (
    <View style={{ flexDirection: 'row', alignItems: 'center', gap: 8 }}>
      <View style={{ flex: 1, height: 6, backgroundColor: C.line }}>
        <View style={{ width: `${pct}%`, height: '100%', backgroundColor: calm ? C.yellow : C.hero }} />
      </View>
      <H size={20}>{pct}%</H>
    </View>
  );
}

const s = themed(() => StyleSheet.create({
  btn: { flexDirection: 'row', alignItems: 'center', justifyContent: 'center', gap: 10, borderWidth: 1.5, borderRadius: 14 },
  chip: { borderWidth: 1, borderColor: C.line, borderRadius: 12, paddingHorizontal: 12, paddingVertical: 9, backgroundColor: C.bg },
  // Sunset Calm: round mint chips.
  chipCalm: { borderRadius: 999, paddingHorizontal: 14, backgroundColor: C.hero, borderColor: C.hero },
  sq: { width: 44, height: 44, borderWidth: 1.5, borderRadius: 12, alignItems: 'center', justifyContent: 'center' },
}));
