import { AccessibilityInfo, Animated, Easing, Modal, PanResponder, ScrollView, Share, StyleSheet, View } from 'react-native';
import Svg, { Circle, Defs, G, Line, Polygon, RadialGradient, Stop, LinearGradient as SvgLinear } from 'react-native-svg';

