export type Mode = 'night' | 'sun' | 'gray';
const known = (id: string) => CARS.some((c) => c.id === id);
const carOf = (id: string) => CARS.find((c) => c.id === id) as Car;
/** Short name for the side labels: 'RAV4', but 'Ram 1500' when the model is only a number. */
const shortOf = (c: Car) => (/^\d/.test(c.model) ? `${c.make} ${c.model}` : c.model);
/** The same year as the website's examples (2022 used) when the car was sold then, else its newest year. */
export function yearFor(c: Car) { const ys = yearsOf(c); return ys.includes(2022) ? 2022 : ys[0]; }
export function payOf(a: Answers, c: Car) {
  const y = yearFor(c), p = priceFor(c, y);
  return p ? { y, price: p.amount, isNew: p.isNew, pay: paymentFor(a, p.amount, p.isNew) } : { y, price: 0, isNew: false, pay: 0 };
}
const WHY: Record<string, string> = { saved: 'Most saved', compared: 'Most compared', looked: 'Most looked at' };
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

/** The list for the shopper's ZIP (area list from 20 shoppers up, else U.S. best sellers). */
export function usePopular(): PopList {
  const { answers } = useAnswers();
  const zip = answers.zip && /^\d{5}$/.test(answers.zip) ? answers.zip : '';
  const [rows, setRows] = useState<Awaited<ReturnType<typeof fetchPopular>>>([]);
  useEffect(() => { let on = true; fetchPopular(zip).then((r) => on && setRows(r)); return () => { on = false; }; }, [zip]);
  return useMemo(() => toList(rows, zip, known), [rows, zip]);
}

/** Night by the ZIP's sunset; in daytime the live weather picks Sunny or gray. No internet = Sunny. */
/** True before sunrise and after sunset where they are. */
export function stageNight(when: Date, lat: number, lon: number) {
  const t = sunTimes(when, lat, lon);
  if (!t) return false;
  const n = when.getTime();
  return n < t.rise || n > t.set;
}

export function useStageMode(): { mode: Mode; weather: Weather | null; night: boolean } {
  // Night until the real sunrise and from the real sunset (Loudjier, Nov 17, 2026, 7 AM screenshot: 'Not sunny').
  // The app's sky switches 20 minutes early; this stage waits for the sun, like a weather app.
  const { spot, now } = useSunPlace();
  const night = stageNight(now, spot.lat, spot.lon);
  const [w, setW] = useState<Weather | null>(null);
  useEffect(() => {
    let on = true;
    getWeather(spot.lat, spot.lon).then((x) => on && setW(x)).catch(() => {});
    const t = setInterval(() => getWeather(spot.lat, spot.lon).then((x) => on && setW(x)).catch(() => {}), 30 * 60 * 1000);
    return () => { on = false; clearInterval(t); };
  }, [spot.lat, spot.lon]);
  const sky = w?.sky ?? 'clear';
  return { mode: night ? 'night' : sky === 'clear' || sky === 'partly' ? 'sun' : 'gray', weather: w, night };
}

function useStill() {
  const [still, setStill] = useState(false);
  useEffect(() => { AccessibilityInfo.isReduceMotionEnabled().then(setStill).catch(() => {}); }, []);
  return still;
}
function useLoop(ms: number, on: boolean, back = true) {
  const [v] = useState(() => new Animated.Value(0));
  useEffect(() => {
    if (!on) { v.setValue(0.5); return; }
    const a = Animated.loop(back
      ? Animated.sequence([Animated.timing(v, { toValue: 1, duration: ms / 2, easing: Easing.inOut(Easing.sin), useNativeDriver: true }), Animated.timing(v, { toValue: 0, duration: ms / 2, easing: Easing.inOut(Easing.sin), useNativeDriver: true })])
      : Animated.timing(v, { toValue: 1, duration: ms, easing: Easing.linear, useNativeDriver: true }));
    a.start();
    return () => a.stop();
  }, [ms, on, back, v]);
  return v;
}

export const LOOKS = {
  night: { bg: ['#1B2E63', '#0B1532', '#070D22'] as const, ink: '#FFFFFF', sub: 'rgba(255,255,255,0.72)', kick: '#F4C24E', cone: '#FFE6AA', ring: '#F4C24E', chipBg: 'rgba(255,255,255,0.14)', chipInk: '#FFFFFF', card: 'rgba(255,255,255,0.07)', line: 'rgba(255,255,255,0.08)', rank: '#C9D3E2', good: '#7FE0A8', goodBg: 'rgba(127,224,168,0.14)' },
  sun: { bg: ['#7EC3F2', '#BFE3F8', '#FFF4E2'] as const, ink: '#10151B', sub: 'rgba(16,21,27,0.7)', kick: '#9A5A00', cone: '#FFF0C8', ring: '#D69628', chipBg: 'rgba(255,255,255,0.8)', chipInk: '#8A5600', card: 'rgba(255,255,255,0.88)', line: '#EEE3CF', rank: '#8A95A6', good: '#147A4B', goodBg: '#E3F5EA' },
  gray: { bg: ['#8FA3BC', '#B9C6D6', '#E2E8EF'] as const, ink: '#10151B', sub: 'rgba(16,21,27,0.7)', kick: '#33507A', cone: '#FFFFFF', ring: '#33507A', chipBg: 'rgba(255,255,255,0.8)', chipInk: '#33507A', card: 'rgba(255,255,255,0.9)', line: '#E2E8EF', rank: '#8A95A6', good: '#147A4B', goodBg: '#E3F5EA' },
};

const STARS = Array.from({ length: 22 }, (_, i) => ({ x: ((i * 37) % 100) / 100, y: ((i * 53) % 46) / 100, s: i % 3 === 0 ? 2.4 : 1.6 }));
const DROPS = Array.from({ length: 22 }, (_, i) => ({ x: ((i * 41) % 100) / 100, y: ((i * 23) % 100) / 100 }));

/** The scene behind the cars: stars, sun with turning rays and clouds, or clouds with rain. */
function Weatherscape({ mode, width, height, still }: { mode: Mode; width: number; height: number; still: boolean }) {
  const tw = useLoop(3000, !still && mode === 'night');
  const rot = useLoop(40000, !still && mode === 'sun', false);
  const drift = useLoop(30000, !still && mode !== 'night');
  const fall = useLoop(900, !still && mode === 'gray', false);
  if (mode === 'night') {
    return <Animated.View style={[StyleSheet.absoluteFill, { opacity: tw.interpolate({ inputRange: [0, 1], outputRange: [1, 0.45] }) }]} pointerEvents="none">
      {STARS.map((s, i) => <View key={i} style={{ position: 'absolute', left: s.x * width, top: s.y * height, width: s.s, height: s.s, borderRadius: 2, backgroundColor: '#FFFFFF', opacity: 0.35 + (i % 4) * 0.15 }} />)}
    </Animated.View>;
  }
  const cloud = (top: number, w: number, from: number, o: number, gray: boolean) => (
    <Animated.View style={{ position: 'absolute', top, left: from, width: w, height: w * 0.32, transform: [{ translateX: drift.interpolate({ inputRange: [0, 1], outputRange: [0, 60] }) }], opacity: o }}>
      <View style={{ position: 'absolute', bottom: 0, left: 0, right: 0, height: w * 0.22, borderRadius: 99, backgroundColor: gray ? '#7F93AD' : '#FFFFFF' }} />
      <View style={{ position: 'absolute', bottom: w * 0.08, left: w * 0.18, width: w * 0.36, height: w * 0.36, borderRadius: 99, backgroundColor: gray ? '#7F93AD' : '#FFFFFF' }} />
      <View style={{ position: 'absolute', bottom: w * 0.06, left: w * 0.46, width: w * 0.28, height: w * 0.28, borderRadius: 99, backgroundColor: gray ? '#7F93AD' : '#FFFFFF' }} />
    </Animated.View>
  );
  if (mode === 'sun') {
    return <View style={StyleSheet.absoluteFill} pointerEvents="none">
      <Animated.View style={{ position: 'absolute', right: -170, top: -150, width: 420, height: 420, transform: [{ rotate: rot.interpolate({ inputRange: [0, 1], outputRange: ['0deg', '360deg'] }) }] }}>
        <Svg width={420} height={420}><G opacity={0.32}>{Array.from({ length: 20 }, (_, i) => {
          const a = (i / 20) * Math.PI * 2; return <Line key={i} x1={210} y1={210} x2={210 + Math.cos(a) * 210} y2={210 + Math.sin(a) * 210} stroke="#FFE9A8" strokeWidth={14} strokeLinecap="round" />;
        })}</G></Svg>
      </Animated.View>
      <Svg width={220} height={220} style={{ position: 'absolute', right: -60, top: -50 }}>
        <Defs><RadialGradient id="sun" cx="50%" cy="50%" r="50%"><Stop offset="0" stopColor="#FFF6C8" /><Stop offset="0.35" stopColor="#FFF0B0" /><Stop offset="0.6" stopColor="#FFD678" stopOpacity="0.6" /><Stop offset="1" stopColor="#FFD678" stopOpacity="0" /></RadialGradient></Defs>
        <Circle cx={110} cy={110} r={110} fill="url(#sun)" />
      </Svg>
      {cloud(height * 0.42, 86, -70, 0.85, false)}
      {cloud(height * 0.3, 64, width * 0.5, 0.7, false)}
    </View>;
  }
  return <View style={StyleSheet.absoluteFill} pointerEvents="none">
    {cloud(height * 0.18, 170, -40, 0.7, true)}
    {cloud(height * 0.3, 130, width * 0.55, 0.55, true)}
    <Animated.View style={{ position: 'absolute', left: 0, top: 0, width, height: height * 2, transform: [{ translateY: still ? -height / 2 : fall.interpolate({ inputRange: [0, 1], outputRange: [-height, 0] }) }] }}>
      {[0, 1].map((half) => DROPS.map((d, i) => <View key={`${half}-${i}`} style={{ position: 'absolute', left: d.x * width, top: half * height + d.y * height, width: 1.5, height: 12, borderRadius: 1, backgroundColor: 'rgba(255,255,255,0.65)', transform: [{ rotate: '12deg' }] }} />))}
    </Animated.View>
  </View>;
}

/** The stage: soft light cone, glowing ring, #1 big in the middle, #2 and #3 at the sides. */
/** The stage: soft light cone, glowing ring, the car in the spotlight big in the middle, the one before and after at the
 * sides. Swipe left or right (or tap ‹ ›) to move the next or previous car into the light (Loudjier, Nov 17, 2026). */
function Stage({ list, mode, width, height, still, local, idx, onIdx, onList }: { list: PopCar[]; mode: Mode; width: number; height: number; still: boolean; local: boolean; idx: number; onIdx: (i: number) => void; onList: () => void }) {
  const L = LOOKS[mode];
  const sway = useLoop(6000, !still);
  const glow = useLoop(2800, !still);
  const [enter] = useState(() => new Animated.Value(still ? 1 : 0));
  const [drag] = useState(() => new Animated.Value(0));
  const ids = list.slice(0, 3).map((c) => c.id).join();
  useEffect(() => {
    if (still) { enter.setValue(1); return; }
    enter.setValue(0);
    Animated.timing(enter, { toValue: 1, duration: 1300, easing: Easing.out(Easing.cubic), useNativeDriver: true }).start();
  }, [ids, still, enter]);
  // Move one car: slide the scene out, switch, slide the new scene in from the other side.
  const busy = useRef(false);
  const go = (dir: 1 | -1) => {
    const to = idx + dir;
    if (busy.current || to < 0 || to >= list.length) { Animated.spring(drag, { toValue: 0, useNativeDriver: true }).start(); return; }
    tap();
    busy.current = true;
    const w = width * 0.55;
    Animated.timing(drag, { toValue: -dir * w, duration: still ? 0 : 160, easing: Easing.in(Easing.quad), useNativeDriver: true }).start(() => {
      onIdx(to);
      drag.setValue(dir * w);
      Animated.timing(drag, { toValue: 0, duration: still ? 0 : 300, easing: Easing.out(Easing.cubic), useNativeDriver: true }).start(() => { busy.current = false; });
    });
  };
  // The finger only records a swipe; the effect below moves the car (the same pattern as drive-slider.tsx).
  const [swipe, setSwipe] = useState<{ dir: 1 | -1 | 0; n: number }>({ dir: 0, n: 0 });
  const [pan] = useState(() => PanResponder.create({
    onMoveShouldSetPanResponder: (_e, g) => Math.abs(g.dx) > 12 && Math.abs(g.dx) > Math.abs(g.dy) * 1.5,
    onPanResponderTerminationRequest: () => false,
    onPanResponderMove: (_e, g) => drag.setValue(g.dx * 0.7),
    onPanResponderRelease: (_e, g) => setSwipe((x) => ({ dir: g.dx < -50 || g.vx < -0.5 ? 1 : g.dx > 50 || g.vx > 0.5 ? -1 : 0, n: x.n + 1 })),
    onPanResponderTerminate: () => setSwipe((x) => ({ dir: 0, n: x.n + 1 })),
  }));
  useEffect(() => {
    if (!swipe.n) return;
    if (swipe.dir) go(swipe.dir); else Animated.spring(drag, { toValue: 0, useNativeDriver: true }).start();
  }, [swipe]); // eslint-disable-line react-hooks/exhaustive-deps
  const a = list[idx], b = list[idx - 1], c = list[idx + 1];
  const big = Math.min(250, width * 0.66), side = Math.min(150, width * 0.4);
  const ringW = big * 0.92;
  const sideX = drag.interpolate({ inputRange: [-200, 200], outputRange: [-120, 120] });
  const fade = drag.interpolate({ inputRange: [-160, 0, 160], outputRange: [0.35, 1, 0.35], extrapolate: 'clamp' });
  const arrow = (dir: 1 | -1, on: boolean) => on ? (
    <Pressable onPress={() => go(dir)} accessibilityRole="button" accessibilityLabel={dir > 0 ? 'Next car' : 'Previous car'} hitSlop={10}
      style={[st.arrow, dir > 0 ? { right: 0 } : { left: 0 }, { backgroundColor: mode === 'night' ? 'rgba(255,255,255,0.14)' : 'rgba(255,255,255,0.85)' }]}>
      <Text style={[st.arrowT, { color: mode === 'night' ? '#FFFFFF' : '#1F5FBF' }]}>{dir > 0 ? '›' : '‹'}</Text>
    </Pressable>
  ) : null;
  return (
    <View style={{ height: height + 18, width, marginTop: 4 }} {...pan.panHandlers}>
      <Animated.View pointerEvents="none" style={{ position: 'absolute', left: width / 2 - 120, top: -26, width: 240, height: height - 10, transform: [{ rotate: sway.interpolate({ inputRange: [0, 1], outputRange: ['-4deg', '4deg'] }) }] }}>
        <Svg width={240} height={height - 10}>
          <Defs><SvgLinear id="cone" x1="0" y1="0" x2="0" y2="1"><Stop offset="0" stopColor={L.cone} stopOpacity="0" /><Stop offset="1" stopColor={L.cone} stopOpacity={mode === 'night' ? 0.17 : 0.45} /></SvgLinear></Defs>
          <Polygon points={`96,0 144,0 240,${height - 10} 0,${height - 10}`} fill="url(#cone)" />
        </Svg>
      </Animated.View>
      <View pointerEvents="none" style={{ position: 'absolute', left: -10, right: -10, top: height - 94, height: 80, borderRadius: 999, backgroundColor: mode === 'night' ? 'rgba(110,150,255,0.12)' : 'rgba(255,255,255,0.35)' }} />
      <Animated.View pointerEvents="none" style={{ position: 'absolute', left: (width - ringW) / 2, top: height - 26 - ringW * 0.2, width: ringW, height: ringW * 0.2, borderRadius: 999, borderWidth: 2, borderColor: L.ring, opacity: glow.interpolate({ inputRange: [0, 1], outputRange: [0.55, 1] }), shadowColor: L.ring, shadowOpacity: 0.7, shadowRadius: 14, shadowOffset: { width: 0, height: 0 } }} />
      {b && <Animated.View pointerEvents="none" style={{ position: 'absolute', left: -side * 0.22, top: height - 64 - side * 0.5, width: side, opacity: enter.interpolate({ inputRange: [0, 1], outputRange: [0, 0.82] }), transform: [{ translateX: Animated.add(enter.interpolate({ inputRange: [0, 1], outputRange: [-120, 0] }), sideX) }] }}>
        <CarCutout id={b.id} year={yearFor(carOf(b.id))} height={side * 0.5} label={carName(carOf(b.id), yearFor(carOf(b.id)))} flat />
      </Animated.View>}
      {c && <Animated.View pointerEvents="none" style={{ position: 'absolute', right: -side * 0.22, top: height - 64 - side * 0.5, width: side, opacity: enter.interpolate({ inputRange: [0, 1], outputRange: [0, 0.82] }), transform: [{ translateX: Animated.add(enter.interpolate({ inputRange: [0, 1], outputRange: [120, 0] }), sideX) }] }}>
        <CarCutout id={c.id} year={yearFor(carOf(c.id))} height={side * 0.5} label={carName(carOf(c.id), yearFor(carOf(c.id)))} flat />
      </Animated.View>}
      {a && <Animated.View pointerEvents="none" style={{ position: 'absolute', left: (width - big) / 2, top: height - 34 - big * 0.52, width: big, opacity: Animated.multiply(enter, fade), transform: [{ translateX: drag }, { translateY: enter.interpolate({ inputRange: [0, 1], outputRange: [34, 0] }) }, { scale: enter.interpolate({ inputRange: [0, 1], outputRange: [0.92, 1] }) }] }}>
        <CarCutout id={a.id} year={yearFor(carOf(a.id))} height={big * 0.52} label={carName(carOf(a.id), yearFor(carOf(a.id)))} flat />
      </Animated.View>}
      <Pressable onPress={() => { tap(); onList(); }} accessibilityRole="button" accessibilityLabel="See the whole list" hitSlop={8}
        style={[st.rk1, { borderColor: L.ring + '88', backgroundColor: mode === 'night' ? 'rgba(244,194,78,0.14)' : 'rgba(255,255,255,0.8)', left: width / 2 - 76 }]}><Text style={[st.rk1T, { color: mode === 'night' ? '#F4C24E' : L.kick }]}>{local ? `#${idx + 1} THIS WEEK  ▾` : `#${idx + 1} IN 2025  ▾`}</Text></Pressable>
      {b && <Text style={[st.rkS, { left: 6, color: mode === 'night' ? '#C9D3E2' : '#4A5568' }]} numberOfLines={1}>{`#${idx} ${shortOf(carOf(b.id))}`}</Text>}
      {c && <Text style={[st.rkS, { right: 6, color: mode === 'night' ? '#E7B48A' : '#9A5A2B', textAlign: 'right' }]} numberOfLines={1}>{`#${idx + 2} ${shortOf(carOf(c.id))}`}</Text>}
      {/* Tap the car in the light = open its page (Loudjier, Nov 17, 2026: "when I click on the car nothing happens").
          Swipes still move cars: the stage only takes over once the finger moves sideways. */}
      {a && <Pressable onPress={() => { tap(); router.push({ pathname: '/car/[id]', params: { id: a.id, year: String(yearFor(carOf(a.id))) } }); }}
        accessibilityRole="button" accessibilityLabel={`Open ${carName(carOf(a.id), yearFor(carOf(a.id)))}`}
        style={{ position: 'absolute', left: (width - big) / 2, top: height - 34 - big * 0.52, width: big, height: big * 0.52 + 20 }} />}
      {arrow(-1, idx > 0)}{arrow(1, idx < list.length - 1)}
      <View pointerEvents="none" style={st.dots}>{list.map((p, k) => <View key={p.id} style={[st.dot, { backgroundColor: k === idx ? (mode === 'night' ? '#F4C24E' : '#1F5FBF') : mode === 'night' ? 'rgba(255,255,255,0.3)' : 'rgba(16,21,27,0.2)' }, k === idx && { width: 16 }]} />)}</View>
    </View>
  );
}

export function popularShareText(list: PopList, a: Answers) {
  const top = list.cars.slice(0, 3).map((p, i) => { const c = carOf(p.id); const q = payOf(a, c); return `${i + 1}. ${carName(c, q.y)} · about ${money(q.pay)}/mo`; });
  return `${list.local ? `${list.area}’s top cars this week` : 'Best-selling cars in the U.S.'} on Carvessa:\n${top.join('\n')}\nPayments are estimates. carvessa.app`;
}

/** The whole stage block: header, weather chip, stage, #1 name, and the plan line. `full` = the Top 10 screen. */
export function PopularStage({ width, full, list }: { width: number; full?: boolean; list: PopList }) {
  const { answers } = useAnswers();
  const { mode, weather, night } = useStageMode();
  const still = useStill();
  const L = LOOKS[mode];
  const cap = monthlyCap(answers);
  const zip = answers.zip && /^\d{5}$/.test(answers.zip) ? answers.zip : '';
  // Which car is in the spotlight; a new list (filter, new week) starts again at #1.
  const ids = list.cars.map((p) => p.id).join();
  const [pick, setPick] = useState({ ids, i: 0 });
  const idx = pick.ids === ids ? pick.i : 0;
  const setIdx = (i: number) => setPick({ ids, i });
  const [sheet, setSheet] = useState(false);
  const top = list.cars[Math.min(idx, Math.max(0, list.cars.length - 1))];
  const wk = weekStart();
  const fits = cap ? list.cars.filter((p) => payOf(answers, carOf(p.id)).pay <= cap).length : 0;
  const stageH = full ? 270 : 240;
  const inner = width - 36;
  const first = top ? carOf(top.id) : null, fq = first ? payOf(answers, first) : null;
  const share = () => { tap(); Share.share({ message: popularShareText(list, answers) }).catch(() => {}); };
  return (
    <View style={{ width, overflow: 'hidden', borderRadius: full ? 0 : 28 }}>
      <LinearGradient colors={L.bg} start={{ x: 0.5, y: 0 }} end={{ x: 0.5, y: 1 }} style={StyleSheet.absoluteFill} />
      <Weatherscape mode={mode} width={width} height={stageH + 160} still={still} />
      <View style={{ padding: 18, paddingTop: full ? 8 : 18 }}>
        <View style={st.hdr}>
          <View style={{ flex: 1, paddingRight: 8 }}>
            <Text style={[st.kick, { color: L.kick }]}>{list.local ? `NEW WEEK · ${MONTHS[wk.getMonth()].toUpperCase()} ${wk.getDate()}` : '2025 SALES · U.S.'}</Text>
            <Text style={[st.h2, { color: L.ink }]} accessibilityRole="header">{list.local ? `Popular in ${list.area}` : 'Best sellers in the U.S.'}</Text>
            <Text style={[st.src, { color: L.sub }]}>{list.local ? 'From what shoppers here open, save and compare on Carvessa' : 'From automakers’ 2025 sales reports'}</Text>
          </View>
          <Pressable onPress={share} accessibilityRole="button" accessibilityLabel="Share this list" style={[st.shr, { backgroundColor: L.chipBg }]}>
            <Text style={[st.shrT, { color: mode === 'night' ? '#FFFFFF' : '#1F5FBF' }]}>Share ↗</Text>
          </Pressable>
        </View>
        {weather && Number.isFinite(weather.tempF) ? (
          <View style={[st.wx, { backgroundColor: L.chipBg }]}><Text style={[st.wxT, { color: L.chipInk }]}>{`${Math.round(weather.tempF)}° · ${skyWord(weather.sky, night)}${zip ? ` · ${zip}` : ''}`}</Text></View>
        ) : null}
        {list.cars.length ? <Stage list={list.cars} mode={mode} width={inner} height={stageH} still={still} local={list.local} idx={Math.min(idx, Math.max(0, list.cars.length - 1))} onIdx={setIdx} onList={() => setSheet(true)} /> : null}
        {first && fq ? (
          <Pressable onPress={() => { tap(); router.push({ pathname: '/car/[id]', params: { id: first.id, year: String(fq.y) } }); }} accessibilityRole="button" style={{ alignItems: 'center', marginTop: -2 }}>
            <Text style={[st.name, { color: L.ink }]}>{carName(first, fq.y)}</Text>
            <Text style={[st.pay, { color: L.sub }]}>{`≈ ${money(fq.pay)}/mo · ${money(fq.price)} ${fq.isNew ? 'new' : 'used'} est.`}</Text>
            {top?.why || top?.move === 'up' ? (
              <View style={[st.why, { backgroundColor: L.goodBg }]}><Text style={[st.whyT, { color: L.good }]}>{[top.move === 'up' ? `↑ ${top.by}` : '', top.why ? WHY[top.why] : ''].filter(Boolean).join(' · ')}</Text></View>
            ) : null}
          </Pressable>
        ) : null}
        {!list.local ? (
          <Text style={[st.note, { color: L.sub }]}>{`${list.area === 'Atlanta' ? 'Atlanta' : 'Your area'}’s own list starts when enough shoppers there use Carvessa. Save cars you like to help build it.`}</Text>
        ) : null}
        {cap ? (
          <Pressable onPress={() => { tap(); router.navigate({ pathname: '/search', params: { monthly: String(cap) } }); }} accessibilityRole="button"
            style={[st.plan, { backgroundColor: L.goodBg }]}>
            <Text style={[st.planT, { color: mode === 'night' ? '#BDF0D2' : '#14593A' }]}>{`${fits} of the top ${list.cars.length} fit your $${cap} plan`}</Text>
            <Text style={[st.planT, { color: L.good, fontWeight: '800' }]}>See ›</Text>
          </Pressable>
        ) : null}
      </View>
      <ListSheet open={sheet} list={list} idx={idx} mode={mode} onPick={(i) => { setIdx(i); setSheet(false); }} onClose={() => setSheet(false)} />
    </View>
  );
}

/** The whole list in a sheet, opened by tapping the rank badge (Loudjier, Nov 17, 2026). Tap a car = it moves into
 * the spotlight; "Details" opens its page. */
function ListSheet({ open, list, idx, mode, onPick, onClose }: { open: boolean; list: PopList; idx: number; mode: Mode; onPick: (i: number) => void; onClose: () => void }) {
  const { answers } = useAnswers();
  if (!open) return null;
  const night = mode === 'night';
  const bg = night ? '#111C3D' : '#FFFFFF', ink = night ? '#FFFFFF' : '#10151B', sub = night ? 'rgba(255,255,255,0.7)' : '#5B6575', line = night ? 'rgba(255,255,255,0.08)' : '#E7ECF3';
  return (
    <Modal transparent animationType="slide" visible onRequestClose={onClose}>
      <View style={{ flex: 1, justifyContent: 'flex-end', backgroundColor: 'rgba(8,14,30,0.5)' }}>
        <Pressable style={StyleSheet.absoluteFill} onPress={onClose} accessibilityLabel="Close the list" />
        <View style={{ backgroundColor: bg, borderTopLeftRadius: 28, borderTopRightRadius: 28, paddingHorizontal: 18, paddingTop: 12, paddingBottom: 30, maxHeight: '82%' }}>
          <View style={{ alignSelf: 'center', width: 44, height: 5, borderRadius: 9, backgroundColor: night ? 'rgba(255,255,255,0.25)' : '#D6DDE8', marginBottom: 12 }} />
          <Text style={{ fontSize: 20, fontWeight: '800', color: ink }} accessibilityRole="header">{list.local ? `Popular in ${list.area}` : 'Best sellers in the U.S.'}</Text>
          <Text style={{ fontSize: 12.5, color: sub, marginTop: 3, marginBottom: 10 }}>Tap a car to put it in the spotlight</Text>
          <ScrollView>
            {list.cars.map((p, i) => {
              const c = carOf(p.id), q = payOf(answers, c), on = i === idx;
              return (
                <Pressable key={p.id} onPress={() => { tap(); onPick(i); }} accessibilityRole="button" accessibilityState={{ selected: on }} accessibilityLabel={`Number ${p.rank}, ${carName(c, q.y)}`}
                  style={{ flexDirection: 'row', alignItems: 'center', gap: 10, paddingVertical: 8, paddingHorizontal: 8, borderRadius: 16, marginBottom: 4, borderWidth: on ? 2 : 1, borderColor: on ? (night ? '#F4C24E' : '#1F5FBF') : line }}>
                  <Text style={{ width: 22, textAlign: 'center', fontSize: 16, fontWeight: '800', color: on ? (night ? '#F4C24E' : '#1F5FBF') : sub }}>{String(p.rank)}</Text>
                  <CarThumb id={c.id} year={q.y} width={68} height={44} label={carName(c, q.y)} />
                  <View style={{ flex: 1 }}>
                    <Text style={{ fontSize: 14, fontWeight: '800', color: ink }} numberOfLines={1}>{carName(c, q.y)}</Text>
                    <Text style={{ fontSize: 12, color: sub }} numberOfLines={1}>{`≈ ${money(q.pay)}/mo · ${money(q.price)} est.`}</Text>
                  </View>
                  <Pressable onPress={() => { tap(); onClose(); router.push({ pathname: '/car/[id]', params: { id: c.id, year: String(q.y) } }); }} accessibilityRole="button" hitSlop={8}
                    style={{ borderRadius: 99, paddingHorizontal: 10, paddingVertical: 6, backgroundColor: night ? 'rgba(255,255,255,0.1)' : '#E3ECFA' }}>
                    <Text style={{ fontSize: 12, fontWeight: '800', color: night ? '#FFFFFF' : '#1F5FBF' }}>Details</Text>
                  </Pressable>
                </Pressable>
              );
            })}
          </ScrollView>
        </View>
      </View>
    </Modal>
  );
}

/** One row of the list (#4 and down). */
export function PopularRow({ p, mode, answers }: { p: PopCar; mode: Mode; answers: Answers }) {
  const L = LOOKS[mode];
  const c = carOf(p.id), q = payOf(answers, c);
  const mv = p.move === 'up' ? `↑ ${p.by}` : p.move === 'down' ? `↓ ${p.by}` : p.move === 'new' ? 'New' : '–';
  return (
    <Pressable onPress={() => { tap(); router.push({ pathname: '/car/[id]', params: { id: c.id, year: String(q.y) } }); }} accessibilityRole="button" accessibilityLabel={`Number ${p.rank}, ${carName(c, q.y)}`}
      style={[st.row, { backgroundColor: L.card, borderColor: L.line }]}>
      <Text style={[st.rowN, { color: L.rank }]}>{String(p.rank)}</Text>
      <CarThumb id={c.id} year={q.y} width={70} height={46} label={carName(c, q.y)} />
      <View style={{ flex: 1 }}>
        <Text style={[st.rowName, { color: L.ink }]} numberOfLines={1}>{carName(c, q.y)}</Text>
        <Text style={[st.rowSub, { color: L.sub }]} numberOfLines={1}>{`≈ ${money(q.pay)}/mo${p.why ? ` · ${WHY[p.why]}` : ''}`}</Text>
      </View>
      {<View style={[st.mv, { backgroundColor: p.move === 'up' || p.move === 'new' ? L.goodBg : L.line }]}><Text style={[st.mvT, { color: p.move === 'up' || p.move === 'new' ? L.good : L.rank }]}>{mv}</Text></View>}
    </Pressable>
  );
}

