// Budget in Search (picture 122 A, Loudjier Oct 21, 2026: "122 build A"): a "Price | Monthly" switch.
// Monthly shows cars whose payment ESTIMATE fits, using the coach's credit and money down (or Good
// credit and $1,750 down until they answer), 72 months and their state's tax and fees.
import type { Car } from '@/data/cars';
import { priceFor } from '@/data/prices';
import { paymentFor, type Answers } from '@/state/answers';

export const MONTHLY_CHIPS = [300, 400, 500, 600, 700];
export const DOWN_CHOICES = ['$0', 'Under $1,000', '$1,000 – $2,500', '$2,500 – $5,000', '$5,000+'];
export const CREDIT_CHOICES = ['Rebuilding', 'Fair', 'Good', 'Great'] as const;
/** A car this much over their monthly number still shows, under "Just over". */
export const JUST_OVER = 50;

/** Their loan answers, with the defaults we show until they pick. */
export const loanOf = (a: Answers): Answers => ({ ...a, credit: a.credit ?? 'Good', down: a.down ?? '$1,000 – $2,500' });

export type MonthlyPick = { year: number; pay: number; over: number };
/** The newest year (years are newest first) whose payment fits, else the cheapest year if it's just over. */
export function monthlyPick(a: Answers, car: Car, years: number[], cap: number): MonthlyPick | null {
  const loan = loanOf(a);
  const pays: MonthlyPick[] = [];
  for (const y of years) {
    const p = priceFor(car, y);
    if (p) pays.push({ year: y, pay: paymentFor(loan, p.amount, p.isNew), over: 0 });
  }
  const fit = pays.find((x) => x.pay <= cap);
  if (fit) return fit;
  const low = pays.reduce<MonthlyPick | null>((m, x) => (!m || x.pay < m.pay ? x : m), null);
  return low && low.pay - cap <= JUST_OVER ? { ...low, over: low.pay - cap } : null;
}
