// "You're pre-approved" (picture 167 screen 15, Oct 30, 2026): Loudjier's Capital One story.
// They type in what their lender gave them (rate, up to, months, good until). It becomes their shopping
// number, car payments use their real rate, cars show "Fits your pre-approval", and after they buy it
// becomes My loan. Typed by them: we never pull credit or get data from a lender.
import { router } from 'expo-router';
import { useState } from 'react';
import { KeyboardAvoidingView, Platform, ScrollView, StyleSheet, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

import { BigBtn, Card } from '@/components/account-ui';
import { notify } from '@/components/notify';
import { sheet, SkyHeader } from '@/components/sky';
import { Text, TextInput } from '@/components/t';
import { Body, Label, tap } from '@/components/ui';
import { type PreApproval, shoppingNumber, useAnswers } from '@/state/answers';
import { useSaved } from '@/state/saved';
import { C, calm, F, PAD, themed } from '@/theme';

const num = (t: string) => Number(t.replace(/[^\d.]/g, '')) || 0;
const usd = (n: number) => `$${Math.round(n).toLocaleString('en-US')}`;

function Field({ label, value, onChange, placeholder, kind = 'number' }: { label: string; value: string; onChange: (v: string) => void; placeholder: string; kind?: 'number' | 'decimal' | 'text' }) {
  return (
    <View style={{ flex: 1 }}>
      <Label style={s.fl}>{label}</Label>
      <TextInput value={value} onChangeText={onChange} placeholder={placeholder} placeholderTextColor={C.muted} accessibilityLabel={label}
        keyboardType={kind === 'number' ? 'number-pad' : kind === 'decimal' ? 'decimal-pad' : 'default'} style={s.input} autoCorrect={false} />
    </View>
  );
}

export default function PreApprovedScreen() {
  const { answers, setAnswers } = useAnswers();
  const { myCar } = useSaved();
  const p = answers.pre;
  const [apr, setApr] = useState(p ? String(p.apr) : '');
  const [upTo, setUpTo] = useState(p ? String(p.upTo) : '');
  const [months, setMonths] = useState(p ? String(p.months) : '72');
  const [until, setUntil] = useState(p?.until ?? '');
  const [lender, setLender] = useState(p?.lender ?? '');
  const next: PreApproval = { apr: num(apr), upTo: Math.round(num(upTo)), months: Math.round(num(months)), until: until.trim() || undefined, lender: lender.trim() || undefined };
  const ok = next.apr > 0 && next.apr < 40 && next.upTo >= 1000 && next.months >= 12 && next.months <= 96 && (!next.until || /^\d{1,2}\/\d{1,2}\/\d{4}$/.test(next.until));
  const back = () => router.back();
  const save = () => {
    if (!ok) return notify('Check your numbers', 'Add the rate, the amount (“up to”) and the months. The date looks like 12/10/2026.');
    tap();
    setAnswers({ ...answers, pre: next, pay: answers.pay ?? 'Car loan' });
    router.push(answers.goal ? { pathname: '/results', params: { upgrade: '0' } } : '/search');
  };
  return (
    <SafeAreaView edges={calm ? [] : ['top']} style={{ flex: 1, backgroundColor: C.bg }}>
      <SkyHeader title={p ? 'You’re pre-approved' : 'Got pre-approved?'} sub="Type in what your lender gave you" back={back} />
      <KeyboardAvoidingView behavior={Platform.OS === 'ios' ? 'padding' : undefined} style={calm ? sheet.page : { flex: 1 }}>
        <ScrollView contentContainerStyle={{ paddingHorizontal: PAD, paddingBottom: 40, paddingTop: 6 }} keyboardShouldPersistTaps="handled">
          <Body style={[s.small, { fontSize: 13.5, color: C.ink, marginBottom: 6 }]}>Walk in like a cash buyer: you know your rate and your payment before the dealer starts talking numbers.</Body>
          <Card style={{ paddingVertical: 12 }}>
            <View style={s.two}>
              <Field label="RATE (APR %)" value={apr} onChange={setApr} placeholder="6.4" kind="decimal" />
              <Field label="UP TO $" value={upTo} onChange={setUpTo} placeholder="26,000" />
            </View>
            <View style={s.two}>
              <Field label="MONTHS" value={months} onChange={setMonths} placeholder="72" />
              <Field label="GOOD UNTIL" value={until} onChange={setUntil} placeholder="12/10/2026" kind="text" />
            </View>
            <View style={s.two}><Field label="LENDER (OPTIONAL)" value={lender} onChange={setLender} placeholder="My credit union" kind="text" /></View>
          </Card>
          {ok && (
            <View style={s.good}>
              <Text style={s.goodB}>{`Your shopping number: ≈ ${usd(shoppingNumber(next))} a month`}</Text>
              <Text style={s.goodT}>{`If you borrow the full ${usd(next.upTo)} (estimate). Car payments in Carvessa now use your ${next.apr}% rate, and cars that fit show “✓ Fits your pre-approval.”`}</Text>
            </View>
          )}
          {ok && (
            <Card style={{ marginTop: 10, paddingVertical: 12 }}>
              <Body bold>At the dealer</Body>
              <Body style={s.small}>{`“I’m pre-approved at ${next.apr}%. Can you beat it?” If not, use yours. You can always say no.`}</Body>
            </Card>
          )}
          <View style={{ gap: 8, marginTop: 14 }}>
            <BigBtn label="Save and show my cars" onPress={save} />
            {p && myCar && !myCar.loan && <BigBtn label="I bought my car: make it My loan" kind="soft" onPress={() => { tap(); router.push('/loan'); }} />}
            {p && <BigBtn label="Remove my pre-approval" kind="plain" onPress={() => { tap(); setAnswers({ ...answers, pre: undefined }); back(); }} />}
          </View>
          <Body style={[s.small, { marginTop: 14 }]}>Kept on your phone. We never pull your credit and never ask for your Social Security number.</Body>
        </ScrollView>
      </KeyboardAvoidingView>
    </SafeAreaView>
  );
}

const s = themed(() => StyleSheet.create({
  fl: { fontSize: 10.5, color: C.muted, marginBottom: 4, marginTop: 10 },
  input: { height: 48, borderWidth: 1.5, borderColor: C.line, borderRadius: 12, paddingHorizontal: 12, fontFamily: F.bodyBold, fontSize: 16, color: C.ink, backgroundColor: C.card },
  two: { flexDirection: 'row', gap: 8 },
  small: { fontSize: 12, color: C.muted, marginTop: 6, lineHeight: 17, fontFamily: F.body },
  good: { backgroundColor: 'rgba(31,157,85,0.12)', borderRadius: 14, padding: 12, marginTop: 10 },
  goodB: { fontFamily: F.bodyBold, fontSize: 15, color: C.green },
  goodT: { fontFamily: F.body, fontSize: 12.5, color: C.ink, marginTop: 3, lineHeight: 18 },
}));
