// The pull-down spinner for any screen (see lib/refresh.ts). Usage: <ScrollView refreshControl={pull} … /> with
// const pull = usePullRefresh(). `also` runs too, for screens with their own data (like Check a car).
import { useEffect, useRef, useState } from 'react';
import { RefreshControl } from 'react-native';

import { tap } from '@/components/ui';
import { pullRefresh } from '@/lib/refresh';
import { C } from '@/theme';

export function usePullRefresh(also?: () => unknown) {
  const [on, setOn] = useState(false);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
  useEffect(() => () => { if (timer.current) clearTimeout(timer.current); }, []);
  const go = () => {
    tap();
    setOn(true);
    pullRefresh();
    Promise.resolve(also?.()).catch(() => {}).finally(() => {
      // Keep the spinner up a moment so people see something happened.
      timer.current = setTimeout(() => setOn(false), 900);
    });
  };
  return <RefreshControl refreshing={on} onRefresh={go} tintColor={C.yellow} colors={[C.yellow]} progressBackgroundColor={C.card} />;
}
