// Home "Best for…" rows (pictures 110 A + 111, Loudjier: "A it is… best safety, best for family…", Oct 19, 2026).
// Each row is a short swipe list of our own picks (not ads). When we know someone's plan (budget or monthly
// payment, new/used, kind of car), each row shows the cars that fit it first, at the year that fits.
import { BUDGETS, CARS, type Car, carIsKind, type Goal, yearsOf } from '@/data/cars';
import { savedFacts } from '@/data/gov';
import { bandOf, money, priceFor } from '@/data/prices';
import { KIND_LABEL, monthlyCap, moreMatches, paymentFor, topMatches, type Answers } from '@/state/answers';

export type Pick = { car: Car; year: number; line: string; tag?: string; fits?: boolean };
export type Row = { key: string; title: string; sub: string; goal?: Goal; picks: Pick[]; total?: number }; // total: every car in the row ("See all N")

/** The year to show for a car: the newest that fits their plan, else 2022 (a typical used year), else the newest. */
function yearFor(a: Answers, car: Car): { year: number; fits?: boolean } {
  let years = yearsOf(car);
  if (a.newUsed === 'New only') years = years.filter((y) => priceFor(car, y)?.isNew);
  if (a.newUsed === 'Used only') years = years.filter((y) => !priceFor(car, y)?.isNew);
  if (!years.length) years = yearsOf(car);
  const cap = monthlyCap(a);
  const budget = BUDGETS.indexOf(a.budget ?? '');
  if (cap || budget >= 0) {
    const fits = (y: number) => {
      const p = priceFor(car, y);
      if (!p) return false;
      return cap ? paymentFor(a, p.amount, p.isNew) <= cap : bandOf(p.amount) <= budget;
    };
    const ok = years.find(fits);
    if (ok) return { year: ok, fits: true };
    return { year: years[years.length - 1], fits: false };
  }
  return { year: years.includes(2022) ? 2022 : years[0] };
}

function lineFor(a: Answers, car: Car, year: number): string {
  const p = priceFor(car, year);
  const cap = monthlyCap(a);
  return !p ? '' : cap ? `≈ ${money(paymentFor(a, p.amount, p.isNew))}/mo est.` : p.isNew ? `From ${money(p.amount)}` : `${money(p.amount)} used · est.`;
}

function pick(a: Answers, car: Car, extra?: (y: number) => string | undefined): Pick {
  const { year, fits } = yearFor(a, car);
  const p = priceFor(car, year);
  const line = p ? lineFor(a, car, year) : '';
  const tag = extra?.(year) ?? (fits === true ? 'Fits your plan' : fits === false ? 'Over your plan' : undefined);
  return { car, year, line, tag, fits };
}

/** Plan known: cars that fit come first; a wanted kind (SUV, Sedan…) is preferred when the row has enough of them. */
function order(a: Answers, list: Pick[], limit = 8): Pick[] {
  const kind = KIND_LABEL[a.kind ?? ''];
  const same = kind ? list.filter((p) => carIsKind(p.car, kind)) : [];
  const base = same.length >= 3 ? same : list;
  return [...base].sort((x, y) => Number(y.fits === true) - Number(x.fits === true)).slice(0, limit);
}

const stars = (c: Car, y: number) => savedFacts(c.id, y)?.stars ?? 0;
const recalls = (c: Car, y: number) => savedFacts(c.id, y)?.recalls?.length ?? 9;
const mpg = (c: Car, y: number) => savedFacts(c.id, y)?.mpg?.combined ?? 0;
const notLux = (c: Car) => !c.goals.includes('Luxury');

export function homeRows(a: Answers, limit = 8): Row[] {
  const P = (c: Car, extra?: (y: number) => string | undefined) => pick(a, c, extra);
  const rows: Row[] = [
    { key: 'safety', title: 'Best for safety', sub: '5★ crash test and few recalls (NHTSA)',
      picks: CARS.filter(notLux).map((c) => P(c, (y) => (stars(c, y) === 5 ? '5★ safety' : undefined)))
        .filter((p) => stars(p.car, p.year) === 5).sort((x, y) => recalls(x.car, x.year) - recalls(y.car, y.year)) },
    { key: 'family', goal: 'Family', title: 'Best for families', sub: 'Lots of room and easy car seats',
      picks: CARS.filter((c) => notLux(c) && (c.seats >= 7 || (c.goals.includes('Family') && c.body === 'SUV'))).sort((x, y) => y.seats - x.seats).map((c) => P(c, () => `Fits ${c.seats}`)) },
    { key: 'first', goal: 'Save money', title: 'Best first cars', sub: 'Cheap to buy, insure and fix',
      picks: CARS.filter((c) => c.goals.includes('Save money') && ['Sedan', 'Hatchback', 'SUV'].includes(c.body) && c.green !== 'ev')
        .map((c) => P(c)).sort((x, y) => (priceFor(x.car, x.year)?.amount ?? 1e9) - (priceFor(y.car, y.year)?.amount ?? 1e9)) },
    { key: 'apps', goal: 'Drive for apps', title: 'Best for app drivers', sub: 'Uber and Lyft friendly, low cost per mile',
      picks: CARS.filter((c) => c.goals.includes('Drive for apps')).map((c) => P(c)) },
    { key: 'gas', title: 'Best on gas', sub: 'Hybrids and electric (EPA mileage)',
      picks: CARS.filter((c) => notLux(c) && (c.green || mpg(c, 2022) >= 35)).map((c) => P(c, (y) => (c.green === 'ev' ? 'Electric' : mpg(c, y) ? `${mpg(c, y)} MPG` : 'Saves gas')))
        // At the year shown it must really save gas (a 23 MPG gas-only year of a car that also comes as a hybrid doesn't count).
        .filter((p) => p.car.green === 'ev' || mpg(p.car, p.year) >= 33 || (!mpg(p.car, p.year) && !!p.car.green))
        .sort((x, y) => mpg(y.car, y.year) - mpg(x.car, x.year)) },
    { key: 'trips', goal: 'Adventure', title: 'Best for weekend trips', sub: 'All-wheel drive and room for gear',
      picks: CARS.filter((c) => notLux(c) && c.goals.includes('Adventure') && c.body !== 'Truck').map((c) => P(c)) },
    { key: 'work', goal: 'Side hustle', title: 'Best for work and side hustles', sub: 'Trucks that haul and tow',
      picks: CARS.filter((c) => c.goals.includes('Side hustle')).map((c) => P(c)) },
  ];
  if (a.goal === 'Luxury') rows.push({ key: 'lux', goal: 'Luxury', title: 'Best luxury picks', sub: 'Comfort, quiet and the latest tech', picks: CARS.filter((c) => c.goals.includes('Luxury')).map((c) => P(c)) });
  // A wanted kind narrows the swipe row, but "See all" (limit Infinity) keeps every car in the row.
  const out = rows.map((r) => ({ ...r, total: r.picks.length, picks: limit === Infinity ? [...r.picks].sort((x, y) => Number(y.fits === true) - Number(x.fits === true)) : order(a, r.picks, limit) }))
    .filter((r) => r.picks.length >= 2);
  // The row that matches their coach goal goes first.
  const i = out.findIndex((r) => r.goal && r.goal === a.goal);
  if (i > 0) out.unshift(...out.splice(i, 1));
  return out;
}

/** One row with every car, for its "See all" page (picture 129 A). */
export function fullRow(a: Answers, key: string): Row | undefined {
  return homeRows(a, Infinity).find((r) => r.key === key);
}

/** Brands we have cars for, most cars first. */
export function topBrands(): string[] {
  const n: Record<string, number> = {};
  for (const c of CARS) n[c.make] = (n[c.make] ?? 0) + 1;
  return Object.keys(n).sort((x, y) => n[y] - n[x]);
}

/** "Fits your plan": the coach's top 3, then the next good matches (only after the coach). */
export function planRow(a: Answers): Row | null {
  if (!a.goal) return null;
  const list = [...topMatches(a, 3), ...moreMatches(a, 5)];
  if (list.length < 2) return null;
  return {
    key: 'plan', title: 'Fits your plan',
    sub: monthlyCap(a) ? 'Payment estimates with your credit and money down' : 'In your budget, at the year that fits',
    picks: list.map((m) => ({ car: m.car, year: m.year, line: lineFor(a, m.car, m.year), tag: `${m.fit}% match`, fits: true })),
  };
}

/** "You looked at": car pages opened on this phone, newest first. */
export function recentRow(a: Answers, recent: { id: string; year: number }[]): Row | null {
  const picks = recent.flatMap((r) => {
    const car = CARS.find((c) => c.id === r.id);
    return car ? [{ car, year: r.year, line: lineFor(a, car, r.year) }] : [];
  });
  return picks.length ? { key: 'recent', title: 'You looked at', sub: '', picks } : null;
}
