const TABLE = new Map(C.map(([code, meaning, plain, soon]) => [code, { code, meaning, plain, soon }]));

/** Every code written in the text ("p2135", "P0420 and P0171"). */
export function codesIn(text: string): string[] {
  return [...new Set((text.toUpperCase().match(/\b[PBCU][0-3][0-9A-F]{3}\b/g) ?? []))];
}
export const codeInfo = (code: string): CodeInfo | null => TABLE.get(code.toUpperCase()) ?? null;

const SYSTEM: Record<string, string> = { P: 'the engine or transmission', B: 'the body (like air bags, seats or doors)', C: 'the chassis (like brakes, ABS or steering)', U: 'the car’s computer network' };

/** Our answer for one code, as chat bubbles. */
export function codeAnswer(code: string): { say: string[]; warn: boolean } {
  const info = codeInfo(code);
  if (info) {
    return {
      warn: info.soon === 'today',
      say: [
        `${info.code}: ${info.meaning}.`,
        info.plain,
        info.soon === 'today'
          ? 'Get it checked today if you can, and drive gently. If the car loses power, shakes, or the check engine light flashes, pull over when it’s safe.'
          : 'It’s usually OK to drive for now. Get it checked soon so it doesn’t turn into a bigger repair.',
      ],
    };
  }
  const kind = SYSTEM[code[0]] ?? 'the car';
  const maker = code[1] === '1' || code[1] === '3';
  return {
    warn: false,
    say: [
      `${code} is a code for ${kind}.`,
      maker ? 'Codes with a 1 or 3 as the second character mean different things on different brands, so the shop or your brand’s dealer needs to look it up for your car.' : 'We don’t have this one in our list yet. Many parts stores and shops can look it up and test it.',
    ],
  };
}
