// Pros and cons: our notes, plus points taken from the real government data.
export function prosCons(id: string, f: Facts | null) {
  const n = NOTES[id] ?? { pros: [], cons: [] };
  const pros = [...n.pros], cons = [...n.cons];
  if (f?.stars === 5) pros.unshift('5-star NHTSA crash test');
  if (f?.mpg && f.mpg.fuel !== 'EV' && f.mpg.combined >= 30) pros.push(`Great gas mileage: ${f.mpg.combined} MPG`);
  if (f?.mpg && f.mpg.fuel !== 'EV' && f.mpg.combined <= 20) cons.push(`Low gas mileage: ${f.mpg.combined} MPG`);
  if (f?.recalls && f.recalls.length === 0) pros.push('No recalls for this year');
  if (f?.recalls && f.recalls.length >= 5) cons.push(`${f.recalls.length} recalls for this year. Make sure they were fixed.`);
  return { pros: pros.slice(0, 5), cons: cons.slice(0, 4) };
}

