// The full "About this car" guide on the car page (picture 119 A, Loudjier Oct 20, 2026: "Build A",
// everything open): why people buy it, how it drives, who it's for (and who should skip it), which
// version to get, the app-driver note (only for app drivers), used years, monthly costs, and what to
// ask the dealer. Text is in data/guide*.ts; costs are our own 5-year math, always labeled estimates.
import { router } from 'expo-router';
import { StyleSheet, View } from 'react-native';

import { CarIcon, CashIcon, HeartIcon, MapIcon, ShieldCheckIcon, SoundIcon, StarIcon, SunIcon, TagIcon, WrenchIcon, BulbIcon, ArrowIcon } from '@/components/icons';
import { Pressable, Text } from '@/components/t';
import { tap } from '@/components/ui';
import { quickFiveYear, round } from '@/data/costs';
import type { Car } from '@/data/cars';
import { COMMON_ASK, GUIDE, GUIDE_UI, type GuideIcon } from '@/data/guide';
import { money, priceFor } from '@/data/prices';
import { costsFor, homeState } from '@/data/state-costs';
import { useFacts } from '@/data/use-facts';
import { VersionTabs } from '@/components/versions';
import { useAnswers } from '@/state/answers';
import { C, F, isDarkLook, look, themed } from '@/theme';
import { ageOf } from '@/data/year';

type IconC = (p: { size?: number; color?: string }) => React.ReactElement;
const ICONS: Record<GuideIcon, IconC> = {
  cash: CashIcon, gas: CashIcon, space: CarIcon, safe: ShieldCheckIcon, last: WrenchIcon, tech: BulbIcon, fun: StarIcon,
  value: TagIcon, quiet: SoundIcon, family: HeartIcon, road: MapIcon, weather: SunIcon, power: CarIcon,
};
// Soft tile colors per kind of reason (same family as the account tiles).
const TINT: Record<GuideIcon, 'blue' | 'green' | 'amber' | 'purple'> = {
  cash: 'green', gas: 'amber', space: 'blue', safe: 'green', last: 'purple', tech: 'blue', fun: 'purple',
  value: 'green', quiet: 'blue', family: 'blue', road: 'amber', weather: 'amber', power: 'purple',
};
function tint(t: 'blue' | 'green' | 'amber' | 'purple' | 'red') {
  const night = isDarkLook(look);
  const day = { blue: ['#E3ECFA', '#1F5FBF'], green: ['#E3F1E8', '#1C6B40'], amber: ['#FFF1D6', '#7A5000'], purple: ['#F1E8FB', '#6B3FA0'], red: ['#FBE6E3', '#A3382A'] }[t];
  const dark = { blue: ['rgba(156,192,247,0.14)', '#9CC0F7'], green: ['rgba(127,220,164,0.14)', '#8FE0B0'], amber: ['rgba(242,196,107,0.14)', '#F2C46B'], purple: ['rgba(196,160,240,0.16)', '#CDB0F2'], red: ['rgba(240,140,120,0.16)', '#F2A39A'] }[t];
  const [bg, fg] = night ? dark : day;
  return { bg, fg };
}

function Head({ children, sub }: { children: string; sub?: string }) {
  return (
    <View style={s.head}>
      <Text style={s.h} accessibilityRole="header">{children}</Text>
      {sub ? <Text style={s.sub}>{sub}</Text> : null}
    </View>
  );
}

function Costs({ car, year }: { car: Car; year: number }) {
  const { facts } = useFacts(car.id, year);
  const p = priceFor(car, year);
  if (!p) return null;
  const ev = car.green === 'ev' || facts?.mpg?.fuel === 'EV';
  const five = quickFiveYear(p.amount, p.isNew, ageOf(year), facts?.mpg?.combined, ev, costsFor().tax);
  const part = (label: string) => (five.parts.find((x) => x.label === label)?.amount ?? 0) / 60;
  const st = homeState();
  const rows: [string, number][] = [
    [ev ? GUIDE_UI.charge[0] : GUIDE_UI.gas[0], part(ev ? 'Charging' : 'Gas')],
    [GUIDE_UI.insurance[0], part('Insurance')],
    [GUIDE_UI.upkeep[0], part('Upkeep and repairs')],
  ];
  return (
    <>
      <Head sub={st ? `Estimates for a ${year} in ${costsFor(st).name}` : `Estimates for a ${year}`}>{GUIDE_UI.costs[0]}</Head>
      <View style={s.box}>
        <View style={s.costRow}><Text style={s.sub}>{GUIDE_UI.perMonth[0]}</Text></View>
        {rows.map(([k, v], i) => (
          <View key={k} style={[s.costRow, i > 0 && s.rule]}>
            <Text style={s.body}>{k}</Text>
            <Text style={s.bold}>{`≈ ${money(round(v))}`}</Text>
          </View>
        ))}
        <Pressable onPress={() => { tap(); router.push({ pathname: '/cost/[id]', params: { id: car.id, year: String(year) } }); }} accessibilityRole="button" style={s.more}>
          <Text style={s.moreT}>{GUIDE_UI.fullCost[0]}</Text>
          <ArrowIcon size={16} color={C.onAccent} />
        </Pressable>
      </View>
    </>
  );
}

export function CarGuide({ car, year }: { car: Car; year: number }) {
  const { answers } = useAnswers();
  const g = GUIDE[car.id];
  if (!g) return null;
  const yes = tint('green');
  const no = tint('red');
  return (
    <View>
      <Head>{GUIDE_UI.why[0]}</Head>
      {g.why.map((w) => {
        const Icon = ICONS[w.icon];
        const t = tint(TINT[w.icon]);
        return (
          <View key={w.title[0]} style={s.why}>
            <View style={[s.ic, { backgroundColor: t.bg }]}><Icon size={18} color={t.fg} /></View>
            <View style={{ flex: 1 }}>
              <Text style={s.bold}>{w.title[0]}</Text>
              <Text style={s.small}>{w.text[0]}</Text>
            </View>
          </View>
        );
      })}

      <Head>{GUIDE_UI.drive[0]}</Head>
      <Text style={s.body}>{g.drive[0]}</Text>

      <Head>{GUIDE_UI.right[0]}</Head>
      <View style={[s.side, { backgroundColor: yes.bg }]}>
        <Text style={[s.bold, { color: yes.fg }]}>{GUIDE_UI.great[0]}</Text>
        {g.greatIf.map((x) => <Text key={x[0]} style={[s.small, s.item]}>{`•  `}<Text style={s.small}>{x[0]}</Text></Text>)}
      </View>
      <View style={[s.side, { backgroundColor: no.bg }]}>
        <Text style={[s.bold, { color: no.fg }]}>{GUIDE_UI.skip[0]}</Text>
        {g.skipIf.map((x) => <Text key={x[0]} style={[s.small, s.item]}>{`•  `}<Text style={s.small}>{x[0]}</Text></Text>)}
      </View>

      <Head sub={g.trimNote[0]}>{GUIDE_UI.version[0]}</Head>
      {/* Picture 237 (Nov 13, 2026): one switch, then Compare versions and Buy this version. */}
      <VersionTabs car={car} year={year} guide={g} />

      {g.apps && answers.goal === 'Drive for apps' ? (
        <>
          <Head>{GUIDE_UI.apps[0]}</Head>
          <Text style={s.body}>{g.apps[0]}</Text>
        </>
      ) : null}

      <Head sub={GUIDE_UI.yearsSub[0]}>{GUIDE_UI.years[0]}</Head>
      <View style={s.box}>
        {g.years.map((y, i) => (
          <View key={y.years} style={[s.year, i > 0 && s.rule]}>
            <View style={[s.dot, { backgroundColor: y.tone === 'good' ? tint('green').fg : tint('amber').fg }]} />
            <View style={{ flex: 1 }}>
              <Text style={s.bold}>{y.years}</Text>
              <Text style={s.small}>{y.text[0]}</Text>
            </View>
          </View>
        ))}
      </View>

      <Costs car={car} year={year} />

      <Head>{GUIDE_UI.ask[0]}</Head>
      <View style={[s.box, { backgroundColor: tint('amber').bg, borderColor: 'transparent' }]}>
        {[...g.ask, ...COMMON_ASK].map((q, i) => (
          <Text key={q[0]} style={[s.small, { color: C.ink, marginTop: i ? 6 : 0 }]}>{`${i + 1}. `}<Text style={[s.small, { color: C.ink }]}>{q[0]}</Text></Text>
        ))}
      </View>
      <Text style={[s.sub, { marginTop: 10 }]}>{GUIDE_UI.note[0]}</Text>
    </View>
  );
}

const s = themed(() => StyleSheet.create({
  head: { marginTop: 20, marginBottom: 8 },
  h: { fontFamily: F.bodyBold, fontSize: 18, color: C.ink },
  sub: { fontFamily: F.body, fontSize: 12.5, color: C.muted, marginTop: 2 },
  body: { fontFamily: F.body, fontSize: 15, lineHeight: 22, color: C.ink },
  bold: { fontFamily: F.bodyBold, fontSize: 14.5, color: C.ink },
  small: { fontFamily: F.body, fontSize: 13.5, lineHeight: 19, color: C.muted },
  why: { flexDirection: 'row', gap: 12, alignItems: 'flex-start', backgroundColor: C.card, borderRadius: 16, padding: 12, marginTop: 8, borderWidth: 1, borderColor: C.line },
  ic: { width: 36, height: 36, borderRadius: 11, alignItems: 'center', justifyContent: 'center' },
  side: { borderRadius: 16, padding: 12, marginTop: 8 },
  item: { marginTop: 4, color: C.ink },
  trimLink: { alignSelf: 'flex-start', marginTop: 4 },
  trimLinkT: { fontFamily: F.bodyBold, fontSize: 13.5 },
  trim: { borderWidth: 1.5, borderColor: C.line, backgroundColor: C.card, borderRadius: 14, padding: 12, marginTop: 8, gap: 3 },
  pill: { borderRadius: 999, paddingHorizontal: 9, paddingVertical: 3 },
  pillT: { fontFamily: F.bodyBold, fontSize: 11 },
  box: { backgroundColor: C.card, borderRadius: 16, paddingHorizontal: 14, paddingVertical: 10, borderWidth: 1, borderColor: C.line },
  year: { flexDirection: 'row', gap: 10, paddingVertical: 9 },
  dot: { width: 10, height: 10, borderRadius: 5, marginTop: 5 },
  rule: { borderTopWidth: 1, borderTopColor: C.line },
  costRow: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', paddingVertical: 8 },
  more: { flexDirection: 'row', alignItems: 'center', justifyContent: 'center', gap: 6, backgroundColor: C.fill, borderRadius: 12, paddingVertical: 11, marginTop: 8, marginBottom: 4 },
  moreT: { fontFamily: F.bodyBold, fontSize: 14, color: C.onAccent },
}));
