// Picture 237 · 2C (Nov 13, 2026): two versions face to face with a gold VS. Each card shows our checked note for
// that version; tap a name in the row above to swap a side. Our take says which one most people should get.
import { router, useLocalSearchParams } from 'expo-router';
import { ScrollView, StyleSheet, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

import { sheet, SkyHeader } from '@/components/sky';
import { Pressable, Text } from '@/components/t';
import { tap } from '@/components/ui';
import { VStage } from '@/components/versions';
import { CARS } from '@/data/cars';
import { GUIDE } from '@/data/guide';
import { tr as tr2 } from '@/i18n';
import { C, F, isDarkLook, look, PAD, themed } from '@/theme';

export default function VersionsPage() {
  const q = useLocalSearchParams<{ id: string; year?: string; a?: string; b?: string }>();
  const car = CARS.find((c) => c.id === q.id);
  const g = car ? GUIDE[car.id] : undefined;
  const year = Number(q.year) || new Date().getFullYear();
  if (!car || !g || g.trims.length < 2) {
    return (
      <SafeAreaView edges={[]} style={{ flex: 1, backgroundColor: C.bg }}>
        <SkyHeader title="Compare versions" back={() => router.back()} />
        <View style={[sheet.page, { padding: PAD }]}><Text style={s.note}>This car has only one version to look at.</Text></View>
      </SafeAreaView>
    );
  }
  const names = g.trims.map((t) => t.name);
  const a = g.trims.find((t) => t.name === q.a) ?? g.trims[0];
  const b = g.trims.find((t) => t.name === q.b && t.name !== a.name) ?? g.trims.find((t) => t.name !== a.name)!;
  const set = (side: 'a' | 'b', name: string) => {
    tap();
    const next = side === 'a' ? { a: name, b: name === b.name ? a.name : b.name } : { a: name === a.name ? b.name : a.name, b: name };
    router.setParams(next);
  };
  const best = [a, b].find((t) => t.best);
  const rest = best ? (best === a ? b : a) : undefined;
  const night = isDarkLook(look);
  const label = `${car.make} ${car.model}`;

  const side = (t: typeof a, side: 'a' | 'b') => (
    <View style={s.card}>
      <VStage id={car.id} year={year} height={104} label={`${label} ${t.name}`} />
      <View style={{ padding: 10 }}>
        <Text style={s.name} numberOfLines={2}>{t.name}</Text>
        {t.best && <View style={[s.best, { backgroundColor: night ? '#9CC0F7' : '#1F5FBF' }]}><Text style={[s.bestT, { color: night ? '#0D1626' : '#fff' }]}>Best value</Text></View>}
        <Text style={s.small}>{t.text[0]}</Text>
      </View>
      <Pressable onPress={() => { tap(); router.push({ pathname: '/buy-road', params: { id: car.id, year: String(year), trim: t.name } }); }}
        accessibilityRole="button" accessibilityLabel={`${tr2('Buy')} ${t.name}`} style={[s.buy, side === 'b' ? s.pri : s.sec]}>
        <Text style={[s.buyT, { color: side === 'b' ? (night ? '#0D1626' : '#fff') : C.onAccent }]} numberOfLines={1}>{`Buy ${t.name}`}</Text>
      </Pressable>
    </View>
  );

  return (
    <SafeAreaView edges={[]} style={{ flex: 1, backgroundColor: C.bg }}>
      <SkyHeader title="Compare versions" back={() => router.back()} />
      <ScrollView style={sheet.page} contentContainerStyle={{ padding: PAD, paddingBottom: 110 }}>
        <Text style={s.title}>{`${a.name} vs ${b.name}`}</Text>
        <Text style={s.sub}>{`${year} ${label}`}</Text>
        {names.length > 2 && (['a', 'b'] as const).map((side) => (
          <View key={side} style={s.pickRow}>
            <Text style={s.pickL}>{side === 'a' ? 'Left' : 'Right'}</Text>
            <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={{ gap: 6 }}>
              {names.map((n) => {
                const on = (side === 'a' ? a.name : b.name) === n;
                return (
                  <Pressable key={n} onPress={() => set(side, n)} accessibilityRole="button" accessibilityState={{ selected: on }} style={[s.chip, on && s.chipOn]}>
                    <Text style={[s.chipT, on && { color: C.onAccent }]} numberOfLines={1}>{n}</Text>
                  </Pressable>
                );
              })}
            </ScrollView>
          </View>
        ))}
        <View style={s.split}>
          {side(a, 'a')}
          {side(b, 'b')}
          <View style={s.vs} pointerEvents="none"><Text style={s.vsT}>VS</Text></View>
        </View>
        <View style={s.take}>
          <Text style={s.takeT}>
            <Text style={[s.takeT, { fontFamily: F.bodyBold }]}>Our take: </Text>
            {best && rest ? `${best.name} is the best value for most people. Pick ${rest.name} if this fits you: ${tr2(rest.text[0]).toLowerCase()}`
              : `Both are good. Pick the one whose note fits how you drive, then compare real prices at the dealer.`}
          </Text>
        </View>
        <Text style={s.foot}>Each version’s exact price and full feature list come from the dealer. Ask for the out-the-door price of the version you want.</Text>
      </ScrollView>
    </SafeAreaView>
  );
}
const s = themed(() => StyleSheet.create({
  title: { fontFamily: F.head, fontSize: 22, color: C.ink },
  sub: { fontFamily: F.body, fontSize: 13, color: C.muted, marginTop: 2 },
  note: { fontFamily: F.body, fontSize: 15, color: C.ink },
  pickRow: { flexDirection: 'row', alignItems: 'center', gap: 8, marginTop: 10 },
  pickL: { fontFamily: F.bodyBold, fontSize: 12.5, color: C.muted, width: 40 },
  chip: { borderRadius: 999, paddingHorizontal: 12, paddingVertical: 7, backgroundColor: C.card, borderWidth: 1, borderColor: C.line },
  chipOn: { backgroundColor: C.fill, borderColor: C.fill },
  chipT: { fontFamily: F.bodyBold, fontSize: 13, color: C.ink },
  split: { flexDirection: 'row', gap: 10, marginTop: 14 },
  card: { flex: 1, backgroundColor: C.card, borderRadius: 18, overflow: 'hidden', borderWidth: 1, borderColor: C.line, justifyContent: 'space-between' },
  name: { fontFamily: F.head, fontSize: 17, color: C.ink },
  best: { alignSelf: 'flex-start', borderRadius: 999, paddingHorizontal: 8, paddingVertical: 2, marginTop: 4 },
  bestT: { fontFamily: F.bodyBold, fontSize: 11 },
  small: { fontFamily: F.body, fontSize: 13, lineHeight: 18, color: C.muted, marginTop: 6 },
  buy: { margin: 10, marginTop: 0, borderRadius: 999, paddingVertical: 10, alignItems: 'center' },
  pri: { backgroundColor: isDarkLook(look) ? '#9CC0F7' : '#1F5FBF' },
  sec: { backgroundColor: C.fill },
  buyT: { fontFamily: F.bodyBold, fontSize: 13.5 },
  vs: { position: 'absolute', left: '50%', top: 82, marginLeft: -21, width: 42, height: 42, borderRadius: 21, backgroundColor: '#9A7535', borderWidth: 3, borderColor: C.bg, alignItems: 'center', justifyContent: 'center' },
  vsT: { fontFamily: F.logo, fontSize: 11.5, color: '#fff' },
  take: { marginTop: 14, backgroundColor: C.goodBg, borderRadius: 14, padding: 12 },
  takeT: { fontFamily: F.body, fontSize: 14, lineHeight: 20, color: C.goodInk },
  foot: { fontFamily: F.body, fontSize: 12, lineHeight: 17, color: C.muted, marginTop: 10 },
}));
