// Cars for sale near you (picture 59 "like the demo", picked Oct 15, 2026; step 1 of the map + list).
// Map on top, list below, closest drive first. Slide "How far will you drive?" (picture 64 B), tap a
// price on the map for the route and a small card (64 C), drag the map and "Search this area" (64 D).
// Real-life screens from picture 62: loading, no results, no internet, Coming soon.
// Real cars only for test accounts until Auto.dev says yes in writing (see data/listings.ts).
import { router, useLocalSearchParams } from 'expo-router';
import { useEffect, useMemo, useState } from 'react';
import { FlatList, Image, KeyboardAvoidingView, Platform, StyleSheet, useWindowDimensions, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import Svg, { Circle, Path } from 'react-native-svg';

import { BodyRow, KINDS, type Kind } from '@/components/body-tiles';
import { ColorChips } from '@/components/color-pick';
import { colorFamily, type ColorFamily } from '@/data/colors';
import { DriveSlider } from '@/components/drive-slider';
import { BackIcon, NoSignalIcon } from '@/components/icons';
import { notify } from '@/components/notify';
import { MAX_Z, MIN_Z, milesToPx, TileMap, type LatLon } from '@/components/tile-map';
import { Body, Btn, Chip, H, Label, SquareBtn, tap } from '@/components/ui';
import { PriceTag } from '@/components/price-box';
import { carForListing, listingTag } from '@/data/fair-price';
import { zipToPlace } from '@/data/dealers';
import {
  budgetMax, findListings, forAnswers, groups, listingName, openDirections, pinLabel, shopModels, straightMilesFor,
  type Found, type Listing,
} from '@/data/listings';
import { money } from '@/data/prices';
import { supabase } from '@/lib/supabase';
import { trimMatches } from '@/data/trims';
import { UseMyLocation } from '@/components/use-location';
