import { usePullRefresh } from '@/components/pull-refresh';

type Where = { zip: string } | { lat: number; lon: number };
const whereKey = (w: Where) => ('zip' in w ? w.zip : `${w.lat.toFixed(3)},${w.lon.toFixed(3)}`);
const miles = (a: LatLon, b: LatLon) => {
  const r = Math.PI / 180;
  const x = Math.sin(((b.lat - a.lat) * r) / 2) ** 2 + Math.cos(a.lat * r) * Math.cos(b.lat * r) * Math.sin(((b.lon - a.lon) * r) / 2) ** 2;
  return 7917.6 * Math.asin(Math.sqrt(x));
};

export function DrivePill({ car, small }: { car: Listing; small?: boolean }) {
  return (
    <View style={[s.drive, small && { paddingVertical: 1 }]}>
      <Text style={[s.driveText, small && { fontSize: 11.5 }]}>{car.min} min · {car.road} mi</Text>
    </View>
  );
}

function ZipAsk({ onZip, onSpot, bad }: { onZip: (z: string) => void; onSpot: (s: Spot) => void; bad?: string }) {
  const [z, setZ] = useState(bad ?? '');
  const ok = /^\d{5}$/.test(z);
  return (
    <View style={s.panel}>
      <Label style={{ color: C.yellow }}>Drive times</Label>
      <H size={28} style={{ marginTop: 2 }}>Where do you start from?</H>
      <Body style={{ color: C.muted, marginTop: 4 }}>
        {bad ? `We couldn’t find ZIP ${bad}. Check it and try again.` : 'Your ZIP code shows how far each car is. We don’t track where you go.'}
      </Body>
      <UseMyLocation onSpot={onSpot} needZip style={{ marginTop: 12 }} />
      <TextInput value={z} onChangeText={(t) => setZ(t.replace(/\D/g, '').slice(0, 5))} keyboardType="number-pad" maxLength={5}
        placeholder="ZIP code" placeholderTextColor={C.muted} style={s.zip} accessibilityLabel="ZIP code" returnKeyType="search"
        onSubmitEditing={() => ok && onZip(z)} />
      <Btn kind="yellow" label="Show cars near me" onPress={() => ok && onZip(z)} style={{ marginTop: 12, opacity: ok ? 1 : 0.5 }} />
    </View>
  );
}

function Skeleton() {
  return (
    <View style={{ paddingHorizontal: PAD, gap: 10, marginTop: 12 }} accessibilityLabel="Loading cars">
      {[0, 1, 2].map((i) => (
        <View key={i} style={[s.card, { opacity: 1 - i * 0.2 }]}>
          <View style={[s.photo, { backgroundColor: C.line }]} />
          <View style={{ flex: 1, gap: 8 }}>
            <View style={{ height: 12, width: '80%', borderRadius: 6, backgroundColor: C.line }} />
            <View style={{ height: 18, width: '45%', borderRadius: 6, backgroundColor: C.line }} />
            <View style={{ height: 10, width: '60%', borderRadius: 6, backgroundColor: C.line }} />
          </View>
        </View>
      ))}
    </View>
  );
}

function CarRow({ car, on }: { car: Listing; on?: boolean }) {
  const tag = listingTag(car);
  return (
    <Pressable onPress={() => { tap(); router.push({ pathname: '/listing/[vin]', params: { vin: car.vin } }); }} accessibilityRole="button"
      accessibilityLabel={`${listingName(car)}, ${money(car.price)}, about ${car.min} minutes away`}
      style={({ pressed }) => [s.card, on && { borderColor: C.yellow, borderWidth: 2 }, pressed && { opacity: 0.8 }]}>
      {car.photo ? <Image source={{ uri: car.photo }} style={s.photo} resizeMode="cover" /> : <View style={[s.photo, { backgroundColor: C.line }]} />}
      <View style={{ flex: 1, minWidth: 0 }}>
        <Text style={s.name} numberOfLines={1}>{listingName(car)}</Text>
        <View style={{ flexDirection: 'row', alignItems: 'center', gap: 8 }}>
          <Text style={s.price}>{money(car.price)}</Text>
          {tag ? <PriceTag tag={tag.tag} /> : null}
        </View>
        <Text style={s.sub} numberOfLines={1}>{[car.miles != null ? `${car.miles.toLocaleString('en-US')} mi` : '', car.dealer].filter(Boolean).join(' · ')}</Text>
        <DrivePill car={car} small />
      </View>
    </Pressable>
  );
}

export default function Shop() {
  const { answers, setAnswers } = useAnswers();
  const { session } = useAuth();
  const { ids, trim: trimParam } = useLocalSearchParams<{ ids?: string; trim?: string }>();
  // A version picked on the car page guide ("Find this version for sale"); ✕ clears it.
  const [trim, setTrim] = useState<string | null>(null);
  const [seenTrim, setSeenTrim] = useState<string | undefined>(undefined);
  if (trimParam !== seenTrim) { setSeenTrim(trimParam); setTrim(trimParam || null); }
  const { width, height } = useWindowDimensions();
  const models = useMemo(() => shopModels(answers, ids ? String(ids).split(',') : undefined), [answers, ids]);
  const maxPrice = budgetMax(answers);
  const zip = answers.zip && /^\d{5}$/.test(answers.zip) ? answers.zip : '';

  const [where, setWhere] = useState<Where | null>(zip ? { zip } : null);
  const [gotZip, setGotZip] = useState(zip);
  if (zip !== gotZip) { setGotZip(zip); setWhere(zip ? { zip } : null); }

  // Map middle for the ZIP (so the map shows while the cars load).
  const [home, setHome] = useState<{ zip: string; at: LatLon } | null>(null);
  useEffect(() => {
    if (!zip) return;
    let on = true;
    zipToPlace(zip).then((p) => on && setHome({ zip, at: { lat: p.lat, lon: p.lon } })).catch(() => {});
    return () => { on = false; };
  }, [zip]);

  // A kind of car from the photo tiles (picture 68 B + E): every car of that kind, any model.
  const [kind, setKind] = useState<Kind | null>(null);

  // The cars. `got.key` says which search they belong to; a different key means "loading".
  const askKey = where ? `${whereKey(where)}|${kind ?? models.map((m) => m.id).join(',')}|${maxPrice ?? ''}` : '';
  const [got, setGot] = useState<{ key: string; found: Found } | null>(null);
  const [retry, setRetry] = useState(0);
  const pull = usePullRefresh(() => setRetry((n) => n + 1));
  useEffect(() => {
    if (!where) return;
    let on = true;
    findListings({ ...where, models, maxPrice, kind }).then((found) => on && setGot({ key: `${askKey}#${retry}`, found }))
      .catch(() => on && setGot({ key: `${askKey}#${retry}`, found: { kind: 'offline' } }));
    return () => { on = false; };
  }, [askKey, retry]); // eslint-disable-line react-hooks/exhaustive-deps
  const found = got?.key === `${askKey}#${retry}` ? got.found : null;
  const origin = found?.kind === 'cars' ? found.origin : null;

  const [maxMin, setMaxMin] = useState(40);
  const [only, setOnly] = useState<string | null>(null); // a model id, or all
  const [sel, setSel] = useState<{ key: string; i: number } | null>(null);
  const [mapOpen, setMapOpen] = useState(true);
  const [moved, setMoved] = useState<{ at: LatLon; z: number } | null>(null);

  const foundAll = useMemo(() => { const f = found && forAnswers(found, answers); return f?.kind === 'cars' ? f.cars : []; }, [found, answers]);
  const hidden = found?.kind === 'cars' ? found.cars.length - foundAll.length : 0;
  // Color filter (picture 75 D): only cars in the colors they tapped.
  const [colors, setColors] = useState<ColorFamily[]>([]);
  const all = useMemo(() => foundAll.filter((c) => (!colors.length || colors.includes(colorFamily(c.color))) && (!trim || trimMatches(c.trim, trim))), [foundAll, colors, trim]);
  const ofModel = only && !kind ? all.filter((c) => { const m = models.find((x) => x.id === only); return m && carForListing(c)?.id === m.id; }) : all;
  const shown = ofModel.filter((c) => c.min <= maxMin);
  const pins = groups(shown);
  const selGroup = sel ? pins.find((g) => g.key === sel.key) ?? null : null;
  const selCar = selGroup ? selGroup.cars[Math.min(sel!.i, selGroup.cars.length - 1)] : null;
  const farther = ofModel.filter((c) => c.min > maxMin).sort((a, b) => a.min - b.min);
  const nextStep = farther.length ? Math.min(60, Math.ceil(farther[0].min / 5) * 5) : null;
  const nextAdds = nextStep ? farther.filter((c) => c.min <= nextStep).length : 0;

  const center: LatLon | null = origin ? { lat: origin.lat, lon: origin.lon } : home?.zip === zip ? home.at : null;
  const mapH = mapOpen ? Math.round(Math.max(300, Math.min(height * 0.46, 460))) : 0;
  const areaFar = moved && center ? miles(moved.at, center) > 4 : false;

  const setZip = (z: string) => { tap(); setAnswers({ ...answers, zip: z }); setSel(null); setMoved(null); setWhere({ zip: z }); };
  // "Use my location": search from where they are; the ZIP is kept for next time.
  const useSpot = (sp: Spot) => { if (sp.zip) { setGotZip(sp.zip); setAnswers({ ...answers, zip: sp.zip }); } setSel(null); setMoved(null); setWhere({ lat: sp.lat, lon: sp.lon }); };
  const searchArea = () => { if (!moved) return; tap(); setSel(null); setWhere({ lat: moved.at.lat, lon: moved.at.lon }); setMoved(null); };
  const back = () => (router.canGoBack() ? router.back() : router.navigate('/search'));
  // "Tell me when it's ready" (picture 66 B, Oct 15, 2026): guests just type an email, no account.
  const [notifyEmail, setNotifyEmail] = useState('');
  const [onList, setOnList] = useState(false);
  const tellMe = async () => {
    const email = (session?.user.email ?? notifyEmail).trim();
    if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) { notify('Check your email', 'That email doesn’t look right. Check it and try again.'); return; }
    tap();
    const { error } = await supabase.from('waitlist').insert({ email, source: 'app' });
    if (error && error.code !== '23505') notify('Something went wrong', 'Please try again.');
    else setOnList(true);
  };

  const placeLine = origin
    ? ('zip' in (where ?? {}) ? `From ${origin.zip} · ${origin.place}` : `From the map · near ${origin.place}`)
    : zip ? `From ${zip}` : '';

  const header = (
    <View style={{ paddingHorizontal: PAD, paddingTop: 12 }}>
      <View style={s.count}>
        <H size={26}>{shown.length} {shown.length === 1 ? 'car' : 'cars'}</H>
        <Text style={s.within}>within {maxMin} min</Text>
      </View>
      {placeLine ? <Body style={{ color: C.muted, fontSize: 13 }}>{placeLine}</Body> : null}
      <View style={{ marginTop: 10 }}>
        <BodyRow value={kind} onChange={(k) => { setKind(k); setOnly(null); setSel(null); }} first={models.map((m) => m.model).join(', ')} />
      </View>
      <Text style={s.howFar}>How far will you drive?</Text>
      <DriveSlider value={maxMin} onChange={(v) => { setMaxMin(v); setSel(null); }} />
      <Text style={s.more} accessibilityLiveRegion="polite">
        {nextStep ? `Go to ${nextStep} min: +${nextAdds} more` : all.length ? 'You see every car we found.' : ''}
      </Text>
      {models.length > 1 && !kind && (
        <View style={s.chips}>
          <Chip label="All" on={!only} onPress={() => { setOnly(null); setSel(null); }} />
          {models.map((m) => <Chip key={m.id} label={m.model} on={only === m.id} onPress={() => { setOnly(only === m.id ? null : m.id); setSel(null); }} />)}
        </View>
      )}
      <ColorChips colors={foundAll.map((c) => c.color)} value={colors} onChange={(v) => { setColors(v); setSel(null); }} />
      {trim ? (
        <View style={s.chips}>
          <Chip label={`Version: ${trim} ✕`} on onPress={() => { setTrim(null); setSel(null); }} />
        </View>
      ) : null}
      {hidden > 0 && <Text style={[s.sub, { marginBottom: 4 }]}>{`Hiding ${hidden} with a reported accident (your “Tell me more” answer)`}</Text>}
      <View style={s.listTop}>
        <Label style={{ color: C.muted }}>Closest first</Label>
        <Pressable onPress={() => { tap(); setMapOpen(!mapOpen); }} accessibilityRole="button" hitSlop={8}>
          <Text style={s.link}>{mapOpen ? 'Hide map' : 'Show map'}</Text>
        </Pressable>
      </View>
      {'lat' in (where ?? {}) && zip ? (
        <Pressable onPress={() => setZip(zip)} accessibilityRole="button" style={{ marginBottom: 8 }}>
          <Text style={s.link}>← Back to cars near {zip}</Text>
        </Pressable>
      ) : null}
    </View>
  );

  const empty = (
    <View style={[s.panel, { marginTop: 4 }]}>
      <H size={24}>{all.length ? `No cars within ${maxMin} min` : 'No cars found here'}</H>
      <Body style={{ color: C.muted, marginTop: 4 }}>{all.length ? 'Try one of these:' : 'Try a bigger area or all models.'}</Body>
      {nextStep ? <Btn kind="outline" small label={`Go to ${nextStep} min · +${nextAdds} cars`} onPress={() => setMaxMin(nextStep)} style={{ marginTop: 10 }} /> : null}
      {only ? <Btn kind="outline" small label="Show all models" onPress={() => setOnly(null)} style={{ marginTop: 8 }} /> : null}
      {colors.length ? <Btn kind="outline" small label="Show every color" onPress={() => setColors([])} style={{ marginTop: 8 }} /> : null}
    </View>
  );

  let body: React.ReactNode;
  if (!zip && !where) body = <ZipAsk onZip={setZip} onSpot={useSpot} />;
  else if (!found) body = <Skeleton />;
  else if (found.kind === 'zip') body = <ZipAsk onZip={setZip} onSpot={useSpot} bad={zip} />;
  else if (found.kind === 'soon') {
    body = (
      <View style={s.panel}>
        <Label style={{ color: C.yellow }}>Coming soon</Label>
        <H size={30} style={{ marginTop: 2 }}>Real cars for sale near you</H>
        <Body style={{ color: C.muted, marginTop: 6 }}>Prices, photos, history and drive times from dealers around you. We’re finishing it now.</Body>
        {onList ? (
          <View style={s.done} accessibilityLiveRegion="polite"><Text style={s.doneText}>✓ You’re on the list. We’ll email you once.</Text></View>
        ) : (
          <>
            {!session?.user.email && (
              <TextInput value={notifyEmail} onChangeText={setNotifyEmail} placeholder="Your email" placeholderTextColor={C.muted}
                keyboardType="email-address" autoCapitalize="none" autoCorrect={false} autoComplete="email" style={s.email}
                accessibilityLabel="Your email" returnKeyType="send" onSubmitEditing={tellMe} />
            )}
            <Btn kind="yellow" label="Tell me when it’s ready" onPress={tellMe} style={{ marginTop: 12 }} />
            <Text style={s.small}>One email when it’s ready. No account, no password.</Text>
          </>
        )}
      </View>
    );
  } else if (found.kind === 'offline' || found.kind === 'busy') {
    body = (
      <View style={s.panel}>
        <NoSignalIcon size={30} color={C.muted} />
        <H size={26}>{found.kind === 'busy' ? 'Lots of searches today' : 'Can’t load cars right now'}</H>
        <Body style={{ color: C.muted, marginTop: 4 }}>
          {found.kind === 'busy' ? 'Please try again tomorrow. Your saved cars and the coach still work.' : 'Check your internet. Your saved cars, recalls and coach answers still work.'}
        </Body>
        {found.kind === 'offline' && <Btn kind="yellow" label="Try again" onPress={() => setRetry(retry + 1)} style={{ marginTop: 14 }} />}
        <Btn kind="outline" label="See my saved cars" onPress={() => router.navigate('/garage')} style={{ marginTop: 8 }} />
      </View>
    );
  }

  const ringPx = (z: number) => (center ? milesToPx(straightMilesFor(maxMin), center, z) : 0);

  return (
    <SafeAreaView edges={['top']} style={{ flex: 1, backgroundColor: C.bg }}>
      <KeyboardAvoidingView style={{ flex: 1 }} behavior={Platform.OS === 'ios' ? 'padding' : undefined}>
        {mapOpen && (
          <View style={{ height: mapH }}>
            {center ? (
              <TileMap width={width} height={mapH} center={center} zoom={9} controlsTop={Math.max(64, mapH - 108)}
                onMoved={(at, z) => setMoved({ at, z: Math.max(MIN_Z, Math.min(MAX_Z, z)) })}>
                {(proj, z) => {
                  const o = proj(center.lat, center.lon);
                  const r = found?.kind === 'cars' ? ringPx(z) : 0;
                  const sp = selCar ? proj(selCar.lat, selCar.lon) : null;
                  const mid = sp ? { x: (o.x + sp.x) / 2 + 22, y: (o.y + sp.y) / 2 - 14 } : null;
                  return (
                    <>
                      <Svg width={width} height={mapH} style={StyleSheet.absoluteFill} pointerEvents="none">
                        {r > 0 && <Circle cx={o.x} cy={o.y} r={r} fill={C.yellow} fillOpacity={0.07} stroke={C.yellow} strokeWidth={2} strokeDasharray="7 6" />}
                        {sp && mid && <Path d={`M${o.x},${o.y} Q${mid.x},${mid.y} ${sp.x},${sp.y}`} stroke={C.yellow} strokeWidth={5} fill="none" strokeLinecap="round" />}
                      </Svg>
                      {r > 0 && <View pointerEvents="none" style={[s.ringTag, { left: o.x - 30, top: o.y - r - 10 }]}><Text style={s.ringText}>{maxMin} min</Text></View>}
                      {sp && mid && selCar && <View pointerEvents="none" style={[s.routeTag, { left: mid.x - 50, top: mid.y - 12 }]}><Text style={s.routeText}>{selCar.min} min · {selCar.road} mi</Text></View>}
                      {pins.map((g) => {
                        const p = proj(g.lat, g.lon);
                        if (p.x < -60 || p.x > width + 60 || p.y < 76 || p.y > mapH + 30) return null;
                        const on = g.key === sel?.key;
                        return (
                          <View key={g.key} pointerEvents="box-none" style={{ position: 'absolute', left: p.x - 80, top: p.y - 34, width: 160, alignItems: 'center', zIndex: on ? 2 : 1 }}>
                            <Pressable onPress={() => { tap(); setSel(on ? null : { key: g.key, i: 0 }); }} accessibilityRole="button"
                              accessibilityLabel={`${g.cars[0].dealer}: ${pinLabel(g)}`} style={[s.pin, on && s.pinOn]}>
                              <Text style={[s.pinText, on && { color: theme === 'midnight' ? '#111111' : '#FFFFFF' }]}>{pinLabel(g)}</Text>
                            </Pressable>
                          </View>
                        );
                      })}
                      <View pointerEvents="none" style={[s.me, { left: o.x - 9, top: o.y - 9 }]} />
                    </>
                  );
                }}
              </TileMap>
            ) : <View style={{ flex: 1, backgroundColor: C.hero }} />}

            {/* Top bar over the map */}
            <View style={s.bar} pointerEvents="box-none">
              <SquareBtn label="Back" onPress={back}><BackIcon /></SquareBtn>
              <View style={s.pill}>
                <Text style={s.pillText} numberOfLines={1}>{kind ? KINDS.find((k) => k.kind === kind)!.label : models.map((m) => m.model).join(', ')}{maxPrice ? ` · under ${money(maxPrice)}` : ''}</Text>
              </View>
            </View>
            {!found && where && center && (
              <View style={s.finding} pointerEvents="none"><Text style={s.findingText}>Finding cars near {'zip' in where ? where.zip : 'here'}…</Text></View>
            )}
            {areaFar && found?.kind === 'cars' && !selCar && (
              <Pressable onPress={searchArea} accessibilityRole="button" style={s.area}><Text style={s.areaText}>↻ Search this area</Text></Pressable>
            )}

            {/* Tapped a pin: route + small card */}
            {selCar && selGroup && (
              <View style={s.peek}>
                <Pressable onPress={() => setSel(null)} accessibilityRole="button" accessibilityLabel="Close" hitSlop={10} style={s.x}><Text style={{ color: C.muted, fontSize: 18 }}>✕</Text></Pressable>
                <View style={{ flexDirection: 'row', gap: 10 }}>
                  {selCar.photo ? <Image source={{ uri: selCar.photo }} style={s.peekPhoto} /> : <View style={[s.peekPhoto, { backgroundColor: C.line }]} />}
                  <View style={{ flex: 1, minWidth: 0, paddingRight: 18 }}>
                    <Text style={s.name} numberOfLines={1}>{listingName(selCar)}</Text>
                    <Text style={s.price}>{money(selCar.price)}</Text>
                    <Text style={s.sub} numberOfLines={1}>{selCar.dealer}</Text>
                    {selGroup.cars.length > 1 && (
                      <View style={s.nav}>
                        <Pressable onPress={() => setSel({ key: selGroup.key, i: (sel!.i + selGroup.cars.length - 1) % selGroup.cars.length })} accessibilityRole="button" accessibilityLabel="Previous car" style={s.navBtn}><Text style={s.navT}>‹</Text></Pressable>
                        <Text style={s.sub}>{(sel!.i % selGroup.cars.length) + 1} of {selGroup.cars.length} here</Text>
                        <Pressable onPress={() => setSel({ key: selGroup.key, i: (sel!.i + 1) % selGroup.cars.length })} accessibilityRole="button" accessibilityLabel="Next car" style={s.navBtn}><Text style={s.navT}>›</Text></Pressable>
                      </View>
                    )}
                  </View>
                </View>
                <View style={{ flexDirection: 'row', gap: 8, marginTop: 8 }}>
                  <Btn kind="yellow" small label="See car" onPress={() => router.push({ pathname: '/listing/[vin]', params: { vin: selCar.vin } })} style={{ flex: 1, height: 44 }} />
                  <Btn kind="outline" small label="Directions" onPress={() => openDirections(selCar)} style={{ flex: 1, height: 44 }} />
                </View>
              </View>
            )}
          </View>
        )}
        {!mapOpen && (
          <View style={[s.bar, { position: 'relative', top: 0 }]}>
            <SquareBtn label="Back" onPress={back}><BackIcon /></SquareBtn>
            <H size={24} style={{ flex: 1 }}>Cars for sale</H>
          </View>
        )}

        {found?.kind === 'cars' ? (
          <FlatList refreshControl={pull}
            data={shown}
            keyExtractor={(c) => c.vin}
            renderItem={({ item }) => <View style={{ paddingHorizontal: PAD }}><CarRow car={item} on={item.vin === selCar?.vin} /></View>}
            ItemSeparatorComponent={() => <View style={{ height: 10 }} />}
            ListHeaderComponent={header}
            ListEmptyComponent={empty}
            ListFooterComponent={shown.length ? <Text style={s.fine}>Prices, miles and history come from each dealer’s listing. Drive times are estimates.</Text> : null}
            contentContainerStyle={{ paddingBottom: 30 }}
            keyboardShouldPersistTaps="handled"
          />
        ) : (
          <FlatList refreshControl={pull} data={[]} renderItem={null} ListHeaderComponent={<View style={{ paddingTop: 8 }}>{body}</View>} keyboardShouldPersistTaps="handled" />
        )}
      </KeyboardAvoidingView>
    </SafeAreaView>
  );
}

