// Picture 238 A (Nov 13, 2026, Loudjier: "Build A"): one Filters page for Search and every "See all" page.
// Only filters we have real data for: our cars (make, body, fuel, seats, features), NHTSA stars, EPA mileage and
// our own price estimates. Mileage, colors and deal rating belong to real cars for sale (the map page).
import { CARS, carIsKind, featureAt, type Car, type Kind } from '@/data/cars';
import { savedFacts } from '@/data/gov';
import { priceFor } from '@/data/prices';

export type Fuel = 'Gas' | 'Hybrid' | 'Electric';
export const FUELS: Fuel[] = ['Gas', 'Hybrid', 'Electric'];
export const MUSTS = ['4x4 / AWD', 'Apple CarPlay', 'Android Auto', 'Heated seats', 'Remote start', 'Third row', 'Towing', 'Adaptive cruise'];
export const SEATS = [5, 7, 8] as const;
export const PRICE_STEPS = [10000, 15000, 20000, 25000, 30000, 35000, 40000, 50000, 60000, 80000, 100000];

export type Filters = {
  newUsed?: 'New' | 'Used';
  makes: string[];
  yearMin?: number;
  yearMax?: number;
  priceMin?: number;
  priceMax?: number;
  bodies: Kind[];
  fuels: Fuel[];
  seats?: number; // at least
  must: string[];
  safe5?: boolean;
  mpg33?: boolean;
};
export const NO_FILTERS: Filters = { makes: [], bodies: [], fuels: [], must: [] };

export const MAKES = [...new Set(CARS.map((c) => c.make))].sort();
export const BODIES: Kind[] = (['SUV', 'Sedan', 'Truck', 'Minivan', 'Hatchback', 'Sports'] as Kind[]).filter((k) => CARS.some((c) => carIsKind(c, k)));
export const bodyLabel = (k: Kind) => (k === 'Sports' ? 'Sports car' : k);

/** How many filters are on (the number on the button). */
export function filterCount(f: Filters): number {
  return (f.newUsed ? 1 : 0) + f.makes.length + (f.yearMin || f.yearMax ? 1 : 0) + (f.priceMin || f.priceMax ? 1 : 0)
    + f.bodies.length + f.fuels.length + (f.seats ? 1 : 0) + f.must.length + (f.safe5 ? 1 : 0) + (f.mpg33 ? 1 : 0);
}

/** The filters that don't depend on the year (brand, body, fuel, seats). */
export function carOk(car: Car, f: Filters): boolean {
  if (f.makes.length && !f.makes.includes(car.make)) return false;
  if (f.bodies.length && !f.bodies.some((k) => carIsKind(car, k))) return false;
  if (f.fuels.length) {
    const ok = f.fuels.some((x) => (x === 'Electric' ? car.green === 'ev' : x === 'Hybrid' ? car.green === 'hybrid' : car.green !== 'ev'));
    if (!ok) return false;
  }
  if (f.seats && car.seats < f.seats) return false;
  return true;
}

/** A must-have counts when it comes on the car or on some versions (never "check" or missing). */
const has = (car: Car, year: number, m: string) => { const st = featureAt(car, year, m); return st === 'inc' || st === 'trim'; };

/** The filters that depend on the model year (new/used, years, price, features, safety, mileage). */
export function yearOk(car: Car, year: number, f: Filters): boolean {
  if (f.yearMin && year < f.yearMin) return false;
  if (f.yearMax && year > f.yearMax) return false;
  const p = priceFor(car, year);
  if (f.newUsed && (!p || (f.newUsed === 'New') !== p.isNew)) return false;
  if ((f.priceMin || f.priceMax) && !p) return false;
  if (p && f.priceMin && p.amount < f.priceMin) return false;
  if (p && f.priceMax && p.amount > f.priceMax) return false;
  if (f.must.some((m) => !has(car, year, m))) return false;
  if (f.safe5 && savedFacts(car.id, year)?.stars !== 5) return false;
  if (f.mpg33 && car.green !== 'ev' && (savedFacts(car.id, year)?.mpg?.combined ?? 0) < 33) return false;
  return true;
}

export const passes = (car: Car, year: number, f: Filters) => carOk(car, f) && yearOk(car, year, f);

/** One line per filter that is on, for the chips under the buttons (tap ✕ to remove). */
export function filterChips(f: Filters): { label: string; remove: (f: Filters) => Filters }[] {
  const out: { label: string; remove: (f: Filters) => Filters }[] = [];
  const k = (n: number) => (n >= 1000 ? `$${Math.round(n / 1000)}K` : `$${n}`);
  if (f.newUsed) out.push({ label: f.newUsed === 'New' ? 'New' : 'Used', remove: (x) => ({ ...x, newUsed: undefined }) });
  f.makes.forEach((m) => out.push({ label: m, remove: (x) => ({ ...x, makes: x.makes.filter((y) => y !== m) }) }));
  if (f.yearMin || f.yearMax) out.push({ label: f.yearMin && f.yearMax ? `${f.yearMin}–${f.yearMax}` : f.yearMin ? `${f.yearMin} or newer` : `${f.yearMax} or older`, remove: (x) => ({ ...x, yearMin: undefined, yearMax: undefined }) });
  if (f.priceMin || f.priceMax) out.push({ label: f.priceMin && f.priceMax ? `${k(f.priceMin)}–${k(f.priceMax)}` : f.priceMax ? `Under ${k(f.priceMax)}` : `Over ${k(f.priceMin!)}`, remove: (x) => ({ ...x, priceMin: undefined, priceMax: undefined }) });
  f.bodies.forEach((b) => out.push({ label: bodyLabel(b), remove: (x) => ({ ...x, bodies: x.bodies.filter((y) => y !== b) }) }));
  f.fuels.forEach((b) => out.push({ label: b, remove: (x) => ({ ...x, fuels: x.fuels.filter((y) => y !== b) }) }));
  if (f.seats) out.push({ label: `${f.seats}+ seats`, remove: (x) => ({ ...x, seats: undefined }) });
  f.must.forEach((m) => out.push({ label: m, remove: (x) => ({ ...x, must: x.must.filter((y) => y !== m) }) }));
  if (f.safe5) out.push({ label: '5★ safety', remove: (x) => ({ ...x, safe5: undefined }) });
  if (f.mpg33) out.push({ label: 'Over 33 MPG', remove: (x) => ({ ...x, mpg33: undefined }) });
  return out;
}
